INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('JimmyLv/BibiGPT-v1/agent-browser', 'community', 'JimmyLv', 'BibiGPT-v1', 'JimmyLv/BibiGPT-v1', 'agent-browser', 5926, 798, 70, '2026-03-07T12:42:58Z', '2026-03-07T12:47:59.515Z', 'c9d2e56a35fe8a2a7e73065e5b091d5f27ecd941ae977c87e6548c9ec8ad6c1a', '{"id":"JimmyLv/BibiGPT-v1/agent-browser","name":"agent-browser","description":{"en":"The agent-browser skill automates browser tasks for developers, allowing them to navigate, snapshot, and interact with web pages. It supports various platforms like Bilibili, YouTube, and Dropbox.","zh":"agent-browser是一种浏览器自动化工具，支持导航、快照和交互操作。通过agent-browser open、snapshot和interact命令，轻松完成浏览器自动化任务","ja":"agent-browserはブラウザ自動化ツールで、ナビゲーション、スナップショット、インタラクションをサポート。agent-browser open、snapshot、interactコマンドを使用してブラウザ自動化タスクを簡単に実行","ko":"agent-browser는 브라우저 자동화 도구로, 네비게이션, 스냅샷, 상호작용을 지원한다. agent-browser open, snapshot, interact 명령을 사용하여 브라우저 자동화 작업을 쉽게 수행","es":"Agent-browser es una herramienta de automatización de navegador que permite ejecutar comandos como ''open'' y ''snapshot'' para interactuar con elementos web.","fr":"Agent-browser est un outil d''automatisation de navigateur qui permet d''exécuter des commandes comme ''open'' et ''snapshot'' pour interagir avec des éléments web.","de":"Agent-browser ist ein Tool zur Automatisierung von Browsern, mit dem Befehle wie ''open'' und ''snapshot'' ausgeführt werden können, um mit Web-Elementen zu interagieren.","pt":"O agent-browser é uma ferramenta de automação de navegador que permite interagir com elementos da web","ru":"Agent-browser - это инструмент автоматизации браузера, который позволяет взаимодействовать с веб-элементами","ar":"agent-browser هو أداة تحكم متصفح الويب التي تمكن من التفاعل مع عناصر الويب"},"seo":{"title":{"en":"agent-browser: Browser Automation Setup Guide | AI Agent ...","zh":"agent-browser_SETUP GUIDE：一键式浏览器自动化","ja":"agent-browser セットアップガイド：ブラウザ自動化を簡単に","ko":"agent-browser 설정 가이드: 브라우저 자동화 MADE EASY","es":"Guía de configuración de agent-browser para automatizació...","fr":"Guide de mise en route de agent-browser pour l''automatisa...","de":"Einrichtungsanleitung für agent-browser zur Browserautoma...","pt":"Guia de Configuração do agent-browser para Automação de N...","ru":"Руководство по Настройке agent-browser для Автоматизации ...","ar":"دليل إعداد agent-browser لتحكم متصفح الويب"},"description":{"en":"Discover how to automate browser tasks with agent-browser. Learn to navigate, snapshot, and interact with web pages using commands like ''agent-browser open'' ...","zh":"使用agent-browser实现浏览器自动化，轻松完成导航、快照和交互操作","ja":"agent-browserでブラウザ自動化を実現。ナビゲーション、スナップショット、インタラクションを簡単に","ko":"agent-browser로 브라우저 자동화를 구현하여 네비게이션, 스냅샷, 상호작용을 쉽게 수행","es":"Aprende a configurar y utilizar agent-browser para automatizar tareas en navegadores con comandos como ''open'' y ''snapshot''","fr":"Découvrez comment configurer et utiliser agent-browser pour automatiser des tâches dans les navigateurs avec des commandes comme ''open'' et ''snapshot''","de":"Erfahren Sie, wie Sie agent-browser konfigurieren und verwenden, um Aufgaben in Browsern mit Befehlen wie ''open'' und ''snapshot'' zu automatisieren","pt":"Aprenda a usar o agent-browser para automação de navegador com navegadores como Bilibili e YouTube","ru":"Узнайте, как использовать agent-browser для автоматизации браузера с браузерами seperti Bilibili и YouTube","ar":"تعرف على كيفية استخدام agent-browser لتحكم متصفح الويب مع متصفحات مثل Bilibili و YouTube"},"definition":{"en":"agent-browser is a browser automation tool that enables developers to automate tasks using commands like ''agent-browser open'' and ''agent-browser snapshot'', supporting multiple platforms and file formats","zh":"agent-browser是一种浏览器自动化工具，用于实现一键式浏览器操作","ja":"agent-browserはブラウザ自動化ツールで、ブラウザ操作を簡単に実現","ko":"agent-browser는 브라우저 자동화 도구로, 브라우저 작업을 쉽게 자동화","es":"Agent-browser es una herramienta de automatización de navegador que utiliza comandos de línea de comandos para interactuar con elementos web.","fr":"Agent-browser est un outil d''automatisation de navigateur qui utilise des commandes de ligne de commande pour interagir avec des éléments web.","de":"Agent-browser ist ein Tool zur Automatisierung von Browsern, das Befehle der Kommandozeile verwendet, um mit Web-Elementen zu interagieren.","pt":"O agent-browser é uma ferramenta de automação de navegador que executa tarefas como navegação e interação com elementos da web","ru":"Agent-browser - это инструмент автоматизации браузера, который выполняет задачи, такие как навигация и взаимодействие с веб-элементами","ar":"agent-browser هو أداة تحكم متصفح الويب التي تنفذ مهام مثل التنقل والتفاعل مع عناصر الويب"},"features":{"en":["Navigates to web pages using ''agent-browser open <url>'' command","Captures snapshots of web pages using ''agent-browser snapshot -i'' command","Interacts with web pages using element references like ''@e1'' and ''@e2''","Supports multiple platforms including Bilibili, YouTube, and Dropbox","Automates tasks using a core workflow of navigate, snapshot, interact, and re-snapshot"],"zh":["支持导航、快照和交互操作","使用agent-browser open命令打开指定URL","使用snapshot命令获取元素引用","使用interact命令进行点击、填充和选择操作"],"ja":["ナビゲーション、スナップショット、インタラクションをサポート","agent-browser openコマンドで指定のURLを開く","snapshotコマンドで要素参照を取得","interactコマンドでクリック、入力、選択操作を実行"],"ko":["네비게이션, 스냅샷, 상호작용을 지원","agent-browser open 명령으로 지정한 URLを開기","snapshot 명령으로 요소 참조를 가져오기","interact 명령으로 클릭, 입력, 선택 작업을 수행"],"es":["Automatización de navegadores con comandos como ''open'' y ''snapshot''","Interacción con elementos web utilizando referencias como ''@e1'' y ''@e2''","Compatibilidad con navegadores como Bilibili, YouTube y Dropbox","Soporte para la ejecución de comandos en línea de comandos","Capacidad para tomar instantáneas de elementos web y obtener referencias"],"fr":["Automatisation de navigateurs avec des commandes comme ''open'' et ''snapshot''","Interaction avec des éléments web en utilisant des références comme ''@e1'' et ''@e2''","Compatibilité avec des navigateurs comme Bilibili, YouTube et Dropbox","Prise en charge de l''exécution de commandes en ligne de commande","Capacité à prendre des instantanés d''éléments web et à obtenir des références"],"de":["Automatisierung von Browsern mit Befehlen wie ''open'' und ''snapshot''","Interaktion mit Web-Elementen unter Verwendung von Referenzen wie ''@e1'' und ''@e2''","Kompatibilität mit Browsern wie Bilibili, YouTube und Dropbox","Unterstützung für die Ausführung von Befehlen in der Kommandozeile","Fähigkeit, Momentaufnahmen von Web-Elementen zu erstellen und Referenzen zu erhalten"],"pt":["Navegação automática com comandos como ''agent-browser open <url>''","Captura de elementos da web com ''agent-browser snapshot -i''","Interação com elementos da web usando referências como ''@e1'', ''@e2''","Atualização de referências após mudanças no DOM","Suporte a navegadores como Bilibili e YouTube","Integração com ferramentas de AI como ChatGPT"],"ru":["Автоматическая навигация с командами как ''agent-browser open <url>''","Снятие элементов веб-страницы с ''agent-browser snapshot -i''","Взаимодействие с веб-элементами с использованием ссылок как ''@e1'', ''@e2''","Обновление ссылок после изменений в DOM","Поддержка браузеров как Bilibili и YouTube","Интеграция с инструментами ИИ как ChatGPT"],"ar":["تنقل تلقائي باستخدام أوامر مثل ''agent-browser open <url>''","التقاط عناصر الويب باستخدام ''agent-browser snapshot -i''","التفاعل مع عناصر الويب باستخدام المراجع مثل ''@e1'', ''@e2''","تحديث المراجع بعد التغييرات في DOM","دعم متصفحات مثل Bilibili و YouTube","التكامل مع أدوات الذكاء الاصطناعي مثل ChatGPT"]},"keywords":{"en":["how to use agent-browser","agent-browser alternative","agent-browser setup guide","browser automation with agent-browser","agent-browser vs selenium","what is agent-browser","agent-browser install","agent-browser tutorial","agent-browser for web scraping","agent-browser for automated testing"],"zh":["agent-browser","浏览器自动化","一键式浏览器操作","AIエージェント","浏览器自动化工具","agent-browser open","snapshot","interact"],"ja":["agent-browser","ブラウザ自動化","一键式ブラウザ操作","AIエージェント","ブラウザ自動化ツール","agent-browser open","snapshot","interact"],"ko":["agent-browser","브라우저 자동화","한 번에 브라우저 작업","AI 에이전트","브라우저 자동화 도구","agent-browser open","snapshot","interact"],"es":["agent-browser","automatización de navegador","comandos de línea de comandos","interacción con elementos web","referencias web","Bilibili","YouTube","Dropbox","automatización de tareas"],"fr":["agent-browser","automatisation de navigateur","commandes de ligne de commande","interaction avec des éléments web","références web","Bilibili","YouTube","Dropbox","automatisation de tâches"],"de":["agent-browser","Automatisierung von Browsern","Befehle der Kommandozeile","Interaktion mit Web-Elementen","Web-Referenzen","Bilibili","YouTube","Dropbox","Automatisierung von Aufgaben"],"pt":["agent-browser","automação de navegador","navegação automática","captura de elementos da web","interação com elementos da web","ferramentas de AI","ChatGPT","Bilibili","YouTube"],"ru":["agent-browser","автоматизация браузера","автоматическая навигация","снятие элементов веб-страницы","взаимодействие с веб-элементами","инструменты ИИ","ChatGPT","Bilibili","YouTube"],"ar":["agent-browser","تحكم متصفح الويب","تنقل تلقائي","التقاط عناصر الويب","التفاعل مع عناصر الويب","أدوات الذكاء الاصطناعي","ChatGPT","Bilibili","YouTube"]}},"owner":"JimmyLv","repo":"BibiGPT-v1","repoPath":"JimmyLv/BibiGPT-v1","stars":5926,"forks":798,"updatedAt":"2026-03-07T12:42:58Z","topics":["bilibili","chatgpt","gpt","gpt-3","openai","youtube"],"category":"community","skillMd":{"name":"agent-browser","description":"Browser automation CLI for AI agents. Use when the user needs to interact with websites, including navigating pages, filling forms, clicking buttons, taking screenshots, extracting data, testing web apps, or automating any browser task. Triggers include requests to open a website, fill out a form, click a button, take a screenshot, scrape data from a page, test this web app, login to a site, automate browser actions, or any task requiring programmatic web interaction.","bodyPreview":"# Browser Automation with agent-browser\n\n## Core Workflow\n\nEvery browser automation follows this pattern:\n\n1. **Navigate**: `agent-browser open <url>`\n2. **Snapshot**: `agent-browser snapshot -i` (get element refs like `@e1`, `@e2`)\n3. **Interact**: Use refs to click, fill, select\n4. **Re-snapshot**: After navigation or DOM changes, get fresh refs\n\n```bash\nagent-browser open https://example.com/form\nagent-browser snapshot -i\n# Output: @e1 [input type=\"email\"], @e2 [input type=\"password\"], @e3 [b","body":"# Browser Automation with agent-browser\n\n## Core Workflow\n\nEvery browser automation follows this pattern:\n\n1. **Navigate**: `agent-browser open <url>`\n2. **Snapshot**: `agent-browser snapshot -i` (get element refs like `@e1`, `@e2`)\n3. **Interact**: Use refs to click, fill, select\n4. **Re-snapshot**: After navigation or DOM changes, get fresh refs\n\n```bash\nagent-browser open https://example.com/form\nagent-browser snapshot -i\n# Output: @e1 [input type=\"email\"], @e2 [input type=\"password\"], @e3 [button] \"Submit\"\n\nagent-browser fill @e1 \"user@example.com\"\nagent-browser fill @e2 \"password123\"\nagent-browser click @e3\nagent-browser wait --load networkidle\nagent-browser snapshot -i  # Check result\n```\n\n## Command Chaining\n\nCommands can be chained with `&&` in a single shell invocation. The browser persists between commands via a background daemon, so chaining is safe and more efficient than separate calls.\n\n```bash\n# Chain open + wait + snapshot in one call\nagent-browser open https://example.com && agent-browser wait --load networkidle && agent-browser snapshot -i\n\n# Chain multiple interactions\nagent-browser fill @e1 \"user@example.com\" && agent-browser fill @e2 \"password123\" && agent-browser click @e3\n\n# Navigate and capture\nagent-browser open https://example.com && agent-browser wait --load networkidle && agent-browser screenshot page.png\n```\n\n**When to chain:** Use `&&` when you don''t need to read the output of an intermediate command before proceeding (e.g., open + wait + screenshot). Run commands separately when you need to parse the output first (e.g., snapshot to discover refs, then interact using those refs).\n\n## Essential Commands\n\n```bash\n# Navigation\nagent-browser open <url>              # Navigate (aliases: goto, navigate)\nagent-browser close                   # Close browser\n\n# Snapshot\nagent-browser snapshot -i             # Interactive elements with refs (recommended)\nagent-browser snapshot -i -C          # Include cursor-interactive elements (divs with onclick, cursor:pointer)\nagent-browser snapshot -s \"#selector\" # Scope to CSS selector\n\n# Interaction (use @refs from snapshot)\nagent-browser click @e1               # Click element\nagent-browser click @e1 --new-tab     # Click and open in new tab\nagent-browser fill @e2 \"text\"         # Clear and type text\nagent-browser type @e2 \"text\"         # Type without clearing\nagent-browser select @e1 \"option\"     # Select dropdown option\nagent-browser check @e1               # Check checkbox\nagent-browser press Enter             # Press key\nagent-browser keyboard type \"text\"    # Type at current focus (no selector)\nagent-browser keyboard inserttext \"text\"  # Insert without key events\nagent-browser scroll down 500         # Scroll page\nagent-browser scroll down 500 --selector \"div.content\"  # Scroll within a specific container\n\n# Get information\nagent-browser get text @e1            # Get element text\nagent-browser get url                 # Get current URL\nagent-browser get title               # Get page title\n\n# Wait\nagent-browser wait @e1                # Wait for element\nagent-browser wait --load networkidle # Wait for network idle\nagent-browser wait --url \"**/page\"    # Wait for URL pattern\nagent-browser wait 2000               # Wait milliseconds\n\n# Downloads\nagent-browser download @e1 ./file.pdf          # Click element to trigger download\nagent-browser wait --download ./output.zip     # Wait for any download to complete\nagent-browser --download-path ./downloads open <url>  # Set default download directory\n\n# Capture\nagent-browser screenshot              # Screenshot to temp dir\nagent-browser screenshot --full       # Full page screenshot\nagent-browser screenshot --annotate   # Annotated screenshot with numbered element labels\nagent-browser pdf output.pdf          # Save as PDF\n\n# Diff (compare page states)\nagent-browser diff snapshot                          # Compare current vs last snapshot\nagent-browser diff snapshot --baseline before.txt    # Compare current vs saved file\nagent-browser diff screenshot --baseline before.png  # Visual pixel diff\nagent-browser diff url <url1> <url2>                 # Compare two pages\nagent-browser diff url <url1> <url2> --wait-until networkidle  # Custom wait strategy\nagent-browser diff url <url1> <url2> --selector \"#main\"  # Scope to element\n```\n\n## Common Patterns\n\n### Form Submission\n\n```bash\nagent-browser open https://example.com/signup\nagent-browser snapshot -i\nagent-browser fill @e1 \"Jane Doe\"\nagent-browser fill @e2 \"jane@example.com\"\nagent-browser select @e3 \"California\"\nagent-browser check @e4\nagent-browser click @e5\nagent-browser wait --load networkidle\n```\n\n### Authentication with Auth Vault (Recommended)\n\n```bash\n# Save credentials once (encrypted with AGENT_BROWSER_ENCRYPTION_KEY)\n# Recommended: pipe password via stdin to avoid shell history exposure\necho \"pass\" | agent-browser auth save github --url https://github.com/login --username user --password-stdin\n\n# Login using saved profile (LLM never sees password)\nagent-browser auth login github\n\n# List/show/delete profiles\nagent-browser auth list\nagent-browser auth show github\nagent-browser auth delete github\n```\n\n### Authentication with State Persistence\n\n```bash\n# Login once and save state\nagent-browser open https://app.example.com/login\nagent-browser snapshot -i\nagent-browser fill @e1 \"$USERNAME\"\nagent-browser fill @e2 \"$PASSWORD\"\nagent-browser click @e3\nagent-browser wait --url \"**/dashboard\"\nagent-browser state save auth.json\n\n# Reuse in future sessions\nagent-browser state load auth.json\nagent-browser open https://app.example.com/dashboard\n```\n\n### Session Persistence\n\n```bash\n# Auto-save/restore cookies and localStorage across browser restarts\nagent-browser --session-name myapp open https://app.example.com/login\n# ... login flow ...\nagent-browser close  # State auto-saved to ~/.agent-browser/sessions/\n\n# Next time, state is auto-loaded\nagent-browser --session-name myapp open https://app.example.com/dashboard\n\n# Encrypt state at rest\nexport AGENT_BROWSER_ENCRYPTION_KEY=$(openssl rand -hex 32)\nagent-browser --session-name secure open https://app.example.com\n\n# Manage saved states\nagent-browser state list\nagent-browser state show myapp-default.json\nagent-browser state clear myapp\nagent-browser state clean --older-than 7\n```\n\n### Data Extraction\n\n```bash\nagent-browser open https://example.com/products\nagent-browser snapshot -i\nagent-browser get text @e5           # Get specific element text\nagent-browser get text body > page.txt  # Get all page text\n\n# JSON output for parsing\nagent-browser snapshot -i --json\nagent-browser get text @e1 --json\n```\n\n### Parallel Sessions\n\n```bash\nagent-browser --session site1 open https://site-a.com\nagent-browser --session site2 open https://site-b.com\n\nagent-browser --session site1 snapshot -i\nagent-browser --session site2 snapshot -i\n\nagent-browser session list\n```\n\n### Connect to Existing Chrome\n\n```bash\n# Auto-discover running Chrome with remote debugging enabled\nagent-browser --auto-connect open https://example.com\nagent-browser --auto-connect snapshot\n\n# Or with explicit CDP port\nagent-browser --cdp 9222 snapshot\n```\n\n### Color Scheme (Dark Mode)\n\n```bash\n# Persistent dark mode via flag (applies to all pages and new tabs)\nagent-browser --color-scheme dark open https://example.com\n\n# Or via environment variable\nAGENT_BROWSER_COLOR_SCHEME=dark agent-browser open https://example.com\n\n# Or set during session (persists for subsequent commands)\nagent-browser set media dark\n```\n\n### Visual Browser (Debugging)\n\n```bash\nagent-browser --headed open https://example.com\nagent-browser highlight @e1          # Highlight element\nagent-browser record start demo.webm # Record session\nagent-browser profiler start         # Start Chrome DevTools profiling\nagent-browser profiler stop trace.json # Stop and save profile (path optional)\n```\n\nUse `AGENT_BROWSER_HEADED=1` to enable headed mode via environment variable. Browser extensions work in both headed and headless mode.\n\n### Local Files (PDFs, HTML)\n\n```bash\n# Open local files with file:// URLs\nagent-browser --allow-file-access open file:///path/to/document.pdf\nagent-browser --allow-file-access open file:///path/to/page.html\nagent-browser screenshot output.png\n```\n\n### iOS Simulator (Mobile Safari)\n\n```bash\n# List available iOS simulators\nagent-browser device list\n\n# Launch Safari on a specific device\nagent-browser -p ios --device \"iPhone 16 Pro\" open https://example.com\n\n# Same workflow as desktop - snapshot, interact, re-snapshot\nagent-browser -p ios snapshot -i\nagent-browser -p ios tap @e1          # Tap (alias for click)\nagent-browser -p ios fill @e2 \"text\"\nagent-browser -p ios swipe up         # Mobile-specific gesture\n\n# Take screenshot\nagent-browser -p ios screenshot mobile.png\n\n# Close session (shuts down simulator)\nagent-browser -p ios close\n```\n\n**Requirements:** macOS with Xcode, Appium (`npm install -g appium && appium driver install xcuitest`)\n\n**Real devices:** Works with physical iOS devices if pre-configured. Use `--device \"<UDID>\"` where UDID is from `xcrun xctrace list devices`.\n\n## Security\n\nAll security features are opt-in. By default, agent-browser imposes no restrictions on navigation, actions, or output.\n\n### Content Boundaries (Recommended for AI Agents)\n\nEnable `--content-boundaries` to wrap page-sourced output in markers that help LLMs distinguish tool output from untrusted page content:\n\n```bash\nexport AGENT_BROWSER_CONTENT_BOUNDARIES=1\nagent-browser snapshot\n# Output:\n# --- AGENT_BROWSER_PAGE_CONTENT nonce=<hex> origin=https://example.com ---\n# [accessibility tree]\n# --- END_AGENT_BROWSER_PAGE_CONTENT nonce=<hex> ---\n```\n\n### Domain Allowlist\n\nRestrict navigation to trusted domains. Wildcards like `*.example.com` also match the bare domain `example.com`. Sub-resource requests, WebSocket, and EventSource connections to non-allowed domains are also blocked. Include CDN domains your target pages depend on:\n\n```bash\nexport AGENT_BROWSER_ALLOWED_DOMAINS=\"example.com,*.example.com\"\nagent-browser open https://example.com        # OK\nagent-browser open https://malicious.com       # Blocked\n```\n\n### Action Policy\n\nUse a policy file to gate destructive actions:\n\n```bash\nexport AGENT_BROWSER_ACTION_POLICY=./policy.json\n```\n\nExample `policy.json`:\n\n```json\n{ \"default\": \"deny\", \"allow\": [\"navigate\", \"snapshot\", \"click\", \"scroll\", \"wait\", \"get\"] }\n```\n\nAuth vault operations (`auth login`, etc.) bypass action policy but domain allowlist still applies.\n\n### Output Limits\n\nPrevent context flooding from large pages:\n\n```bash\nexport AGENT_BROWSER_MAX_OUTPUT=50000\n```\n\n## Diffing (Verifying Changes)\n\nUse `diff snapshot` after performing an action to verify it had the intended effect. This compares the current accessibility tree against the last snapshot taken in the session.\n\n```bash\n# Typical workflow: snapshot -> action -> diff\nagent-browser snapshot -i          # Take baseline snapshot\nagent-browser click @e2            # Perform action\nagent-browser diff snapshot        # See what changed (auto-compares to last snapshot)\n```\n\nFor visual regression testing or monitoring:\n\n```bash\n# Save a baseline screenshot, then compare later\nagent-browser screenshot baseline.png\n# ... time passes or changes are made ...\nagent-browser diff screenshot --baseline baseline.png\n\n# Compare staging vs production\nagent-browser diff url https://staging.example.com https://prod.example.com --screenshot\n```\n\n`diff snapshot` output uses `+` for additions and `-` for removals, similar to git diff. `diff screenshot` produces a diff image with changed pixels highlighted in red, plus a mismatch percentage.\n\n## Timeouts and Slow Pages\n\nThe default Playwright timeout is 25 seconds for local browsers. This can be overridden with the `AGENT_BROWSER_DEFAULT_TIMEOUT` environment variable (value in milliseconds). For slow websites or large pages, use explicit waits instead of relying on the default timeout:\n\n```bash\n# Wait for network activity to settle (best for slow pages)\nagent-browser wait --load networkidle\n\n# Wait for a specific element to appear\nagent-browser wait \"#content\"\nagent-browser wait @e1\n\n# Wait for a specific URL pattern (useful after redirects)\nagent-browser wait --url \"**/dashboard\"\n\n# Wait for a JavaScript condition\nagent-browser wait --fn \"document.readyState === ''complete''\"\n\n# Wait a fixed duration (milliseconds) as a last resort\nagent-browser wait 5000\n```\n\nWhen dealing with consistently slow websites, use `wait --load networkidle` after `open` to ensure the page is fully loaded before taking a snapshot. If a specific element is slow to render, wait for it directly with `wait <selector>` or `wait @ref`.\n\n## Session Management and Cleanup\n\nWhen running multiple agents or automations concurrently, always use named sessions to avoid conflicts:\n\n```bash\n# Each agent gets its own isolated session\nagent-browser --session agent1 open site-a.com\nagent-browser --session agent2 open site-b.com\n\n# Check active sessions\nagent-browser session list\n```\n\nAlways close your browser session when done to avoid leaked processes:\n\n```bash\nagent-browser close                    # Close default session\nagent-browser --session agent1 close   # Close specific session\n```\n\nIf a previous session was not closed properly, the daemon may still be running. Use `agent-browser close` to clean it up before starting new work.\n\n## Ref Lifecycle (Important)\n\nRefs (`@e1`, `@e2`, etc.) are invalidated when the page changes. Always re-snapshot after:\n\n- Clicking links or buttons that navigate\n- Form submissions\n- Dynamic content loading (dropdowns, modals)\n\n```bash\nagent-browser click @e5              # Navigates to new page\nagent-browser snapshot -i            # MUST re-snapshot\nagent-browser click @e1              # Use new refs\n```\n\n## Annotated Screenshots (Vision Mode)\n\nUse `--annotate` to take a screenshot with numbered labels overlaid on interactive elements. Each label `[N]` maps to ref `@eN`. This also caches refs, so you can interact with elements immediately without a separate snapshot.\n\n```bash\nagent-browser screenshot --annotate\n# Output includes the image path and a legend:\n#   [1] @e1 button \"Submit\"\n#   [2] @e2 link \"Home\"\n#   [3] @e3 textbox \"Email\"\nagent-browser click @e2              # Click using ref from annotated screenshot\n```\n\nUse annotated screenshots when:\n\n- The page has unlabeled icon buttons or visual-only elements\n- You need to verify visual layout or styling\n- Canvas or chart elements are present (invisible to text snapshots)\n- You need spatial reasoning about element positions\n\n## Semantic Locators (Alternative to Refs)\n\nWhen refs are unavailable or unreliable, use semantic locators:\n\n```bash\nagent-browser find text \"Sign In\" click\nagent-browser find label \"Email\" fill \"user@test.com\"\nagent-browser find role button click --name \"Submit\"\nagent-browser find placeholder \"Search\" type \"query\"\nagent-browser find testid \"submit-btn\" click\n```\n\n## JavaScript Evaluation (eval)\n\nUse `eval` to run JavaScript in the browser context. **Shell quoting can corrupt complex expressions** -- use `--stdin` or `-b` to avoid issues.\n\n```bash\n# Simple expressions work with regular quoting\nagent-browser eval ''document.title''\nagent-browser eval ''document.querySelectorAll(\"img\").length''\n\n# Complex JS: use --stdin with heredoc (RECOMMENDED)\nagent-browser eval --stdin <<''EVALEOF''\nJSON.stringify(\n  Array.from(document.querySelectorAll(\"img\"))\n    .filter(i => !i.alt)\n    .map(i => ({ src: i.src.split(\"/\").pop(), width: i.width }))\n)\nEVALEOF\n\n# Alternative: base64 encoding (avoids all shell escaping issues)\nagent-browser eval -b \"$(echo -n ''Array.from(document.querySelectorAll(\"a\")).map(a => a.href)'' | base64)\"\n```\n\n**Why this matters:** When the shell processes your command, inner double quotes, `!` characters (history expansion), backticks, and `$()` can all corrupt the JavaScript before it reaches agent-browser. The `--stdin` and `-b` flags bypass shell interpretation entirely.\n\n**Rules of thumb:**\n\n- Single-line, no nested quotes -> regular `eval ''expression''` with single quotes is fine\n- Nested quotes, arrow functions, template literals, or multiline -> use `eval --stdin <<''EVALEOF''`\n- Programmatic/generated scripts -> use `eval -b` with base64\n\n## Configuration File\n\nCreate `agent-browser.json` in the project root for persistent settings:\n\n```json\n{\n  \"headed\": true,\n  \"proxy\": \"http://localhost:8080\",\n  \"profile\": \"./browser-data\"\n}\n```\n\nPriority (lowest to highest): `~/.agent-browser/config.json` < `./agent-browser.json` < env vars < CLI flags. Use `--config <path>` or `AGENT_BROWSER_CONFIG` env var for a custom config file (exits with error if missing/invalid). All CLI options map to camelCase keys (e.g., `--executable-path` -> `\"executablePath\"`). Boolean flags accept `true`/`false` values (e.g., `--headed false` overrides config). Extensions from user and project configs are merged, not replaced.\n\n## Deep-Dive Documentation\n\n| Reference                                                            | When to Use                                               |\n| -------------------------------------------------------------------- | --------------------------------------------------------- |\n| [references/commands.md](references/commands.md)                     | Full command reference with all options                   |\n| [references/snapshot-refs.md](references/snapshot-refs.md)           | Ref lifecycle, invalidation rules, troubleshooting        |\n| [references/session-management.md](references/session-management.md) | Parallel sessions, state persistence, concurrent scraping |\n| [references/authentication.md](references/authentication.md)         | Login flows, OAuth, 2FA handling, state reuse             |\n| [references/video-recording.md](references/video-recording.md)       | Recording workflows for debugging and documentation       |\n| [references/profiling.md](references/profiling.md)                   | Chrome DevTools profiling for performance analysis        |\n| [references/proxy-support.md](references/proxy-support.md)           | Proxy configuration, geo-testing, rotating proxies        |\n\n## Experimental: Native Mode\n\nagent-browser has an experimental native Rust daemon that communicates with Chrome directly via CDP, bypassing Node.js and Playwright entirely. It is opt-in and not recommended for production use yet.\n\n```bash\n# Enable via flag\nagent-browser --native open example.com\n\n# Enable via environment variable (avoids passing --native every time)\nexport AGENT_BROWSER_NATIVE=1\nagent-browser open example.com\n```\n\nThe native daemon supports Chromium and Safari (via WebDriver). Firefox and WebKit are not yet supported. All core commands (navigate, snapshot, click, fill, screenshot, cookies, storage, tabs, eval, etc.) work identically in native mode. Use `agent-browser close` before switching between native and default mode within the same session.\n\n## Ready-to-Use Templates\n\n| Template                                                                 | Description                         |\n| ------------------------------------------------------------------------ | ----------------------------------- |\n| [templates/form-automation.sh](templates/form-automation.sh)             | Form filling with validation        |\n| [templates/authenticated-session.sh](templates/authenticated-session.sh) | Login once, reuse state             |\n| [templates/capture-workflow.sh](templates/capture-workflow.sh)           | Content extraction with screenshots |\n\n```bash\n./templates/form-automation.sh https://example.com/form\n./templates/authenticated-session.sh https://app.example.com/login\n./templates/capture-workflow.sh https://example.com ./output\n```\n"},"lastSynced":"2026-03-07T12:47:59.515Z","agentAnalysis":{"suitability":{"en":"Perfect for Web Automation Agents needing advanced browser interaction capabilities.","zh":"非常适合需要高级浏览器交互能力的Web自动化代理。","ja":"Web自動化エージェントが高度なブラウザの相互作用機能を必要とする場合に最適です。","ko":"고급 브라우저 상호 작용 기능이 필요한 웹 자동화 에이전트에 적합합니다.","es":"Perfecto para agentes de automatización web que necesitan capacidades de interacción avanzada con el navegador.","fr":"Parfait pour les agents d''automatisation web nécessitant des capacités d''interaction avancée avec le navigateur.","de":"Perfekt für Web-Automationsagenten, die erweiterte Browser-Interaktionsfunktionen benötigen.","pt":"Perfeito para Agentes de Automação da Web que precisam de capacidades de interação avançada do navegador.","ru":"Идеально для веб-агентов автоматизации, требующих продвинутых возможностей взаимодействия с браузером.","ar":"مثالي لعميل التutomatiون على الويب الذي يحتاج إلى قدرات تفاعل متقدمة للمتصفح."},"recommendation":{"en":"Empowers agents to automate browser tasks using protocols like HTTP and HTTPS, supporting platforms such as Bilibili, YouTube, and Dropbox, and enabling interactions like clicking, filling, and selecting elements using references like @e1, @e2.","zh":"赋予代理使用HTTP和HTTPS等协议自动化浏览器任务的能力，支持Bilibili、YouTube和Dropbox等平台，并能够使用@e1、@e2等引用进行点击、填充和选择元素等交互。","ja":"エージェントがHTTPとHTTPSなどのプロトコルを使用してブラウザのタスクを自動化する機能を提供し、Bilibili、YouTube、Dropboxなどのプラットフォームをサポートし、@e1、@e2などの参照を使用して要素のクリック、入力、選択などの相互作用を可能にします。","ko":"에이전트가 HTTP와 HTTPS 등의 프로토콜을 사용하여 브라우저 작업을 자동화 할 수 있는 기능을 제공하며, Bilibili, YouTube, Dropbox 등의 플랫폼을 지원하며, @e1, @e2 등의 참조를 사용하여 요소의 클릭, 입력, 선택 등의 상호 작용을 가능하게 합니다.","es":"Habilita a los agentes a automatizar tareas del navegador utilizando protocolos como HTTP y HTTPS, con soporte para plataformas como Bilibili, YouTube y Dropbox, y permitiendo interacciones como hacer clic, rellenar y seleccionar elementos utilizando referencias como @e1, @e2.","fr":"Permet aux agents d''automatiser les tâches du navigateur en utilisant des protocoles tels que HTTP et HTTPS, en prenant en charge des plateformes comme Bilibili, YouTube et Dropbox, et en permettant des interactions comme le clic, le remplissage et la sélection d''éléments à l''aide de références comme @e1, @e2.","de":"Ermöglicht es Agenten, Browseraufgaben mithilfe von Protokollen wie HTTP und HTTPS zu automatisieren, und unterstützt Plattformen wie Bilibili, YouTube und Dropbox, und ermöglicht Interaktionen wie Klicken, Ausfüllen und Auswählen von Elementen unter Verwendung von Referenzen wie @e1, @e2.","pt":"Habilita agentes a automatizar tarefas do navegador usando protocolos como HTTP e HTTPS, suportando plataformas como Bilibili, YouTube e Dropbox, e permitindo interações como clicar, preencher e selecionar elementos usando referências como @e1, @e2.","ru":"Наделяет агентов возможностью автоматизировать задачи браузера с использованием протоколов HTTP и HTTPS, поддерживая платформы, такие как Bilibili, YouTube и Dropbox, и позволяя взаимодействия, такие как клик, заполнение и выбор элементов с использованием ссылок, таких как @e1, @e2.","ar":"يمنح الوكلاء القدرة على توفير مهام المتصفح باستخدام بروتوكولات مثل HTTP و HTTPS ، ودعم منصات مثل Bilibili و YouTube و Dropbox ، وتمكين التفاعلات مثل النقر وملء واختيار العناصر باستخدام مراجع مثل @e1 ، @e2."},"useCases":{"en":["Automating web page navigation and snapshotting","Generating interactions with web elements using references","Debugging web page issues using snapshot comparisons"],"zh":["自动化网页导航和快照","使用引用生成网页元素的交互","使用快照比较调试网页问题"],"ja":["Webページのナビゲーションとスナップショットの自動化","参照を使用してWeb要素の相互作用を生成する","スナップショットの比較を使用してWebページの問題をデバッグする"],"ko":["웹 페이지 탐색 및 스냅샷 자동화","참조를 사용하여 웹 요소의 상호 작용 생성","스냅샷 비교를 사용하여 웹 페이지 문제 디버깅"],"es":["Automatizar la navegación y la captura de páginas web","Generar interacciones con elementos web utilizando referencias","Depurar problemas de páginas web mediante comparaciones de capturas"],"fr":["Automatiser la navigation et la capture de pages web","Générer des interactions avec des éléments web à l''aide de références","Déboguer les problèmes de pages web à l''aide de comparaisons de captures"],"de":["Automatisierung der Webseitennavigation und -Momentaufnahme","Erzeugen von Interaktionen mit Web-Elementen unter Verwendung von Referenzen","Fehlerbehebung bei Webseitenproblemen mithilfe von Momentaufnahmevergleichen"],"pt":["Automatizar navegação de página da web e captura de tela","Gerar interações com elementos da web usando referências","Depurar problemas de página da web usando comparações de captura de tela"],"ru":["Автоматизация навигации по веб-страницам и создание снимков","Генерирование взаимодействий с веб-элементами с помощью ссылок","Отладка проблем веб-страниц с помощью сравнения снимков"],"ar":["توفير التنقل في صفحات الويب والتقاط الشاشة","توليد التفاعلات مع عناصر الويب باستخدام المراجع","تصحيح الأخطاء في صفحات الويب باستخدام مقارنة لقطات الشاشة"]},"limitations":{"en":["Requires accurate element references for interaction","Limited to supported platforms","Needs re-snapshotting after navigation or DOM changes"],"zh":["需要准确的元素引用来进行交互","仅限支持的平台","导航或DOM更改后需要重新快照"],"ja":["相互作用を行うために正確な要素参照が必要","サポートされているプラットフォームのみ","ナビゲーションまたはDOMの変更後には再スナップショットが必要"],"ko":["상호 작용을进行하기 위해 정확한 요소 참조가 필요","지원되는 플랫폼만","탐색 또는 DOM 변경 후에는 다시 스냅샷이 필요"],"es":["Requiere referencias de elementos precisas para la interacción","Limitado a plataformas compatibles","Requiere una nueva captura después de la navegación o los cambios en el DOM"],"fr":["Nécessite des références d''éléments précises pour l''interaction","Limité aux plateformes prises en charge","Nécessite une nouvelle capture après la navigation ou les modifications du DOM"],"de":["Benötigt genaue Elementreferenzen für die Interaktion","Begrenzt auf unterstützte Plattformen","Benötigt eine erneute Momentaufnahme nach der Navigation oder Änderungen im DOM"],"pt":["Exige referências de elementos precisas para interação","Limitado às plataformas suportadas","Necessita re-captura após navegação ou alterações no DOM"],"ru":["Требует точных ссылок на элементы для взаимодействия","Ограничен поддерживаемыми платформами","Требует повторной съемки после навигации или изменений DOM"],"ar":["يتطلب مراجع دقيقة للعناصر للتفاعل","محدود بالمنصات المدعومة","يحتاج إلى إعادة التقاط بعد التنقل أو التغييرات في DOM"]},"version":4},"contentHash":"c9d2e56a35fe8a2a7e73065e5b091d5f27ecd941ae977c87e6548c9ec8ad6c1a","qualityScore":70}');
