INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('JimmyLv/BibiGPT-v1/agent-browser', 'agent-browser', 'JimmyLv', 'BibiGPT-v1', 'community', 'agent-browser JimmyLv BibiGPT-v1 community bilibili chatgpt gpt gpt-3 openai youtube The agent-browser skill automates browser tasks for developers, allowing them to navigate, snapshot, and interact with web pages. It supports various platforms like Bilibili, YouTube, and Dropbox. agent-browser是一种浏览器自动化工具，支持导航、快照和交互操作。通过agent-browser open、snapshot和interact命令，轻松完成浏览器自动化任务 agent-browserはブラウザ自動化ツールで、ナビゲーション、スナップショット、インタラクションをサポート。agent-browser open、snapshot、interactコマンドを使用してブラウザ自動化タスクを簡単に実行 agent-browser는 브라우저 자동화 도구로, 네비게이션, 스냅샷, 상호작용을 지원한다. agent-browser open, snapshot, interact 명령을 사용하여 브라우저 자동화 작업을 쉽게 수행 Agent-browser es una herramienta de automatización de navegador que permite ejecutar comandos como ''open'' y ''snapshot'' para interactuar con elementos web. Agent-browser est un outil d''automatisation de navigateur qui permet d''exécuter des commandes comme ''open'' et ''snapshot'' pour interagir avec des éléments web. Agent-browser ist ein Tool zur Automatisierung von Browsern, mit dem Befehle wie ''open'' und ''snapshot'' ausgeführt werden können, um mit Web-Elementen zu interagieren. O agent-browser é uma ferramenta de automação de navegador que permite interagir com elementos da web Agent-browser - это инструмент автоматизации браузера, который позволяет взаимодействовать с веб-элементами agent-browser هو أداة تحكم متصفح الويب التي تمكن من التفاعل مع عناصر الويب how to use agent-browser agent-browser alternative agent-browser setup guide browser automation with agent-browser agent-browser vs selenium what is agent-browser agent-browser install agent-browser tutorial agent-browser for web scraping agent-browser for automated testing agent-browser 浏览器自动化 一键式浏览器操作 AIエージェント 浏览器自动化工具 agent-browser open snapshot interact Navigates to web pages using ''agent-browser open <url>'' command Captures snapshots of web pages using ''agent-browser snapshot -i'' command Interacts with web pages using element references like ''@e1'' and ''@e2'' Supports multiple platforms including Bilibili, YouTube, and Dropbox Automates tasks using a core workflow of navigate, snapshot, interact, and re-snapshot agent-browser is a browser automation tool that enables developers to automate tasks using commands like ''agent-browser open'' and ''agent-browser snapshot'', supporting multiple platforms and file formats');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('catlog22/Claude-Code-Workflow/team-coordinate', 'community', 'catlog22', 'Claude-Code-Workflow', 'catlog22/Claude-Code-Workflow', 'team-coordinate', 1411, 114, 70, '2026-03-04T23:14:02Z', '2026-03-06T06:26:11.869Z', 'e4c7b7a2b0e0c3477c2fbe3a76d2fe2da9faa2d566a986e1de9b82bd42470661', '{"id":"catlog22/Claude-Code-Workflow/team-coordinate","name":"team-coordinate","description":{"en":"The team-coordinate skill provides a universal team coordination framework, analyzing tasks and generating role-specs for automated workflow execution, benefiting development teams.","zh":"Team Coordinate 是一个 JSON 驱动的多代理协调开发框架，具有智能 CLI 编排和自动化工作流执行","ja":"Team Coordinate は JSON ドリブンのマルチエージェント開発フレームワークで、AI エージェント CLI オーケストレーションと自動化ワークフロー実行を備えています","ko":"Team Coordinate는 JSON 기반의 다중 에이전트 개발 프레임워크로 지능형 CLI 오케스트레이션 및 자동화 워크플로우 실행을 지원합니다","es":"Team Coordinate es un marco de desarrollo de equipo impulsado por JSON con arquitectura de contexto y ejecución de flujo de trabajo automatizada. Permite la coordinación de tareas y la generación dinámica de roles de trabajo","fr":"Team Coordinate est un cadre de développement d''équipe basé sur JSON avec architecture de contexte et exécution de workflow automatisée. Il permet la coordination de tâches et la génération dynamique de rôles de travail","de":"Team Coordinate ist ein JSON-basiertes Entwicklungsfamework für Teams mit Kontextarchitektur und automatisierter Workflow-Ausführung. Es ermöglicht die Koordination von Aufgaben und die dynamische Generierung von Arbeitsrollen","pt":"O Team Coordinate é um framework de desenvolvimento de equipes JSON-driven com CLI inteligente e arquitetura de contexto para automação de fluxo de trabalho","ru":"Team Coordinate - это фреймворк для координации команд с JSON-driven и интеллектуальной CLI для автоматизации рабочих процессов","ar":"أداة تنسيق الفريق هي إطار عمل لتنسيق فريق التطوير مع CLI ذكية وقاعدة JSON لآليّة سير العمل"},"seo":{"title":{"en":"team-coordinate: Intelligent CLI Orchestration Setup Guid...","zh":"Team Coordinate 设置指南：JSON 驱动的智能 CLI 编排","ja":"Team Coordinate セットアップガイド：JSON ドリブンの AI エージェント CLI オーケストレ...","ko":"Team Coordinate 설정 가이드: JSON 기반의 지능형 CLI 오케스트레이션","es":"Guía de configuración de Team Coordinate: Marco de desarr...","fr":"Guide de mise en place de Team Coordinate : Cadre de déve...","de":"Einrichtungsleitfaden für Team Coordinate: Entwicklungsfa...","pt":"Guia de Configuração do Team Coordinate: Framework de Des...","ru":"ИИ Агенты: Настройка Team Coordinate - Фреймворк для Коор...","ar":"دليل إعداد أداة تنسيق الفريق: إطار عمل لتنسيق فريق التطوير"},"description":{"en":"Unlock efficient team coordination with team-coordinate''s JSON-driven framework and automated workflow execution - get started now!","zh":"了解 Team Coordinate 的 JSON 驱动的多代理协调开发框架，智能 CLI 编排和自动化工作流执行","ja":"Team Coordinate の JSON ドリブンのマルチエージェント開発フレームワーク、AI エージェント CLI オーケストレーション、および自動化ワークフロー実行について学びます","ko":"Team Coordinate의 JSON 기반의 다중 에이전트 개발 프레임워크, 지능형 CLI 오케스트레이션 및 자동화 워크플로우 실행에 대해 알아보세요","es":"Aprende a configurar Team Coordinate, un marco de desarrollo de equipo impulsado por JSON con arquitectura de contexto y ejecución de flujo de trabajo automa...","fr":"Découvrez comment configurer Team Coordinate, un cadre de développement d''équipe basé sur JSON avec architecture de contexte et exécution de workflow automat...","de":"Erfahren Sie, wie Sie Team Coordinate einrichten, ein JSON-basiertes Entwicklungsfamework für Teams mit Kontextarchitektur und automatisierter Workflow-Ausfü...","pt":"Aprenda a configurar o Team Coordinate, um framework de desenvolvimento de equipes JSON-driven com CLI inteligente e arquitetura de contexto","ru":"Узнайте, как настроить Team Coordinate, фреймворк для координации команд с JSON-driven и интеллектуальной CLI","ar":"تعرف على كيفية إعداد أداة تنسيق الفريق، إطار عمل لتنسيق فريق التطوير مع CLI ذكية وقاعدة JSON"},"definition":{"en":"team-coordinate is a JSON-driven multi-agent cadence-team development framework with intelligent CLI orchestration and context-first architecture.","zh":"Team Coordinate 是一种 JSON 驱动的多代理协调开发框架","ja":"Team Coordinate は JSON ドリブンのマルチエージェント開発フレームワークです","ko":"Team Coordinate는 JSON 기반의 다중 에이전트 개발 프레임워크입니다","es":"Team Coordinate es un marco de desarrollo de equipo que utiliza JSON para coordinar tareas y generar roles de trabajo de forma dinámica","fr":"Team Coordinate est un cadre de développement d''équipe qui utilise JSON pour coordonner des tâches et générer des rôles de travail de manière dynamique","de":"Team Coordinate ist ein Entwicklungsfamework für Teams, das JSON verwendet, um Aufgaben zu koordinieren und Arbeitsrollen dynamisch zu generieren","pt":"O Team Coordinate é um framework de desenvolvimento de equipes que utiliza JSON e CLI para automatizar fluxos de trabalho","ru":"Team Coordinate - это фреймворк для координации команд, который использует JSON и CLI для автоматизации рабочих процессов","ar":"أداة تنسيق الفريق هي إطار عمل لتنسيق فريق التطوير يستخدم JSON و CLI لآليّة سير العمل"},"features":{"en":["JSON-driven multi-agent framework for flexible team coordination","Intelligent CLI orchestration using Gemini, Qwen, and Codex","Context-first architecture for efficient workflow execution","Automated workflow execution and task dispatch","Dynamically generated worker roles as lightweight role-spec files"],"zh":["JSON 驱动的多代理协调开发框架","智能 CLI 编排（Gemini/Qwen/Codex）","上下文优先架构","自动化工作流执行"],"ja":["JSON ドリブンのマルチエージェント開発フレームワーク","AI エージェント CLI オーケストレーション（Gemini/Qwen/Codex）","コンテキスト優先アーキテクチャ","自動化ワークフロー実行"],"ko":["JSON 기반의 다중 에이전트 개발 프레임워크","지능형 CLI 오케스트레이션（Gemini/Qwen/Codex）","컨텍스트 우선 아키텍처","자동화 워크플로우 실행"],"es":["Arquitectura de contexto para una mejor coordinación de tareas","Ejecución de flujo de trabajo automatizada con CLI de Gemini/Qwen/Codex","Generación dinámica de roles de trabajo como archivos de especificación de roles ligeros","Coordinación de tareas y asignación de roles de trabajo mediante JSON","Integración con herramientas de línea de comandos como CLI de Gemini/Qwen/Codex"],"fr":["Architecture de contexte pour une meilleure coordination de tâches","Exécution de workflow automatisée avec CLI Gemini/Qwen/Codex","Génération dynamique de rôles de travail comme fichiers de spécification de rôles légers","Coordination de tâches et affectation de rôles de travail via JSON","Intégration avec des outils de ligne de commande tels que CLI Gemini/Qwen/Codex"],"de":["Kontextarchitektur für eine bessere Aufgabenkoordination","Automatisierte Workflow-Ausführung mit Gemini/Qwen/Codex-CLI","Dynamische Generierung von Arbeitsrollen als leichtgewichtige Rollenspezifikationsdateien","Aufgabenkoordination und Rollenzuweisung über JSON","Integration mit Kommandozeilenwerkzeugen wie Gemini/Qwen/Codex-CLI"],"pt":["Arquitetura de contexto para gerenciamento de fluxo de trabalho","CLI inteligente com suporte a Gemini, Qwen e Codex","Desenvolvimento de equipes JSON-driven para automação de fluxo de trabalho","Geração dinâmica de arquivos de especificação de papel para trabalhadores","Execução automatizada de fluxo de trabalho com suporte a múltiplos agentes"],"ru":["Архитектура контекста для управления рабочими процессами","Интеллектуальная CLI с поддержкой Gemini, Qwen и Codex","Разработка команд с JSON-driven для автоматизации рабочих процессов","Динамическая генерация файлов спецификации ролей для работников","Автоматическая выполнение рабочих процессов с поддержкой нескольких агентов"],"ar":["هندسة سياقية لإدارة سير العمل","واجهة سطر أوامر ذكية مع دعم لجيميني، كوين وكودكس","تطوير فريق التطوير مع JSON-driven لآليّة سير العمل","توليد ديناميكي لملفات مواصفات الدور للعاملين","تنفيذ آلي لآليّة سير العمل مع دعم لعدة وكلاء"]},"keywords":{"en":["how to use team-coordinate","team-coordinate setup guide","team-coordinate vs claude","team-coordinate install","what is team-coordinate","team-coordinate alternative","JSON-driven workflow automation","intelligent CLI orchestration tools","context-first architecture benefits"],"zh":["Team Coordinate","JSON 驱动的多代理协调","智能 CLI 编排","自动化工作流执行","Gemini","Qwen","Codex","上下文优先架构"],"ja":["Team Coordinate","JSON ドリブンのマルチエージェント","AI エージェント CLI オーケストレーション","自動化ワークフロー実行","Gemini","Qwen","Codex","コンテキスト優先アーキテクチャ"],"ko":["Team Coordinate","JSON 기반의 다중 에이전트","지능형 CLI 오케스트레이션","자동화 워크플로우 실행","Gemini","Qwen","Codex","컨텍스트 우선 아키텍처"],"es":["Team Coordinate","desarrollo de equipo","JSON","arquitectura de contexto","CLI de Gemini/Qwen/Codex","automatización de flujo de trabajo","generación dinámica de roles de trabajo","herramientas de desarrollo de equipo","coordinación de tareas","Agente de IA para desarrollo de equipo"],"fr":["Team Coordinate","développement d''équipe","JSON","architecture de contexte","CLI Gemini/Qwen/Codex","automatisation de workflow","génération dynamique de rôles de travail","outils de développement d''équipe","coordination de tâches","Outil d''IA pour développement d''équipe"],"de":["Team Coordinate","Entwicklungsfamework für Teams","JSON","Kontextarchitektur","Gemini/Qwen/Codex-CLI","Automatisierung von Workflow","dynamische Generierung von Arbeitsrollen","Entwicklungstools für Teams","Aufgabenkoordination","KI-Tool für Team-Entwicklung"],"pt":["team coordinate","desenvolvimento de equipes","framework de desenvolvimento","JSON-driven","CLI inteligente","automação de fluxo de trabalho","gerenciamento de fluxo de trabalho","arquitetura de contexto"],"ru":["team coordinate","координация команд","фреймворк для разработки","JSON-driven","интеллектуальная CLI","автоматизация рабочих процессов","управление рабочими процессами","архитектура контекста"],"ar":["أداة تنسيق الفريق","تنسيق فريق التطوير","إطار عمل لتنسيق فريق التطوير","JSON-driven","واجهة سطر أوامر ذكية","آليّة سير العمل","إدارة سير العمل","هندسة سياقية"]}},"owner":"catlog22","repo":"Claude-Code-Workflow","repoPath":"catlog22/Claude-Code-Workflow","stars":1411,"forks":114,"updatedAt":"2026-03-04T23:14:02Z","topics":["claude","claude-code","cli-tools","codex","context-management","gemini-cli","json-driven","qwen-code","task-orchestration","workflow-automation"],"category":"community","skillMd":{"name":"team-coordinate","description":"Universal team coordination skill with dynamic role generation. Uses team-worker agent architecture with role-spec files. Only coordinator is built-in -- all worker roles are generated at runtime as role-specs and spawned via team-worker agent. Beat/cadence model for orchestration. Triggers on Team Coordinate .","bodyPreview":"# Team Coordinate \n\nUniversal team coordination skill: analyze task -> generate role-specs -> dispatch -> execute -> deliver. Only the **coordinator** is built-in. All worker roles are **dynamically generated** as lightweight role-spec files and spawned via the `team-worker` agent.\n\n\n## Architecture\n\n```\n+---------------------------------------------------+\n|  Skill(skill=\"team-coordinate\")                 |\n|  args=\"task description\"                           |\n+-------------------+------------","body":"# Team Coordinate \n\nUniversal team coordination skill: analyze task -> generate role-specs -> dispatch -> execute -> deliver. Only the **coordinator** is built-in. All worker roles are **dynamically generated** as lightweight role-spec files and spawned via the `team-worker` agent.\n\n\n## Architecture\n\n```\n+---------------------------------------------------+\n|  Skill(skill=\"team-coordinate\")                 |\n|  args=\"task description\"                           |\n+-------------------+-------------------------------+\n                    |\n         Orchestration Mode (auto -> coordinator)\n                    |\n              Coordinator (built-in)\n              Phase 0-5 orchestration\n                    |\n    +-------+-------+-------+-------+\n    v       v       v       v       v\n [team-worker agents, each loaded with a dynamic role-spec]\n  (roles generated at runtime from task analysis)\n\n  CLI Tools (callable by any worker):\n    ccw cli --mode analysis  - analysis and exploration\n    ccw cli --mode write     - code generation and modification\n```\n\n## Role Router\n\nThis skill is **coordinator-only**. Workers do NOT invoke this skill -- they are spawned as `team-worker` agents directly.\n\n### Input Parsing\n\nParse `$ARGUMENTS`. No `--role` needed -- always routes to coordinator.\n\n### Role Registry\n\nOnly coordinator is statically registered. All other roles are dynamic, stored as role-specs in session.\n\n| Role | File | Type |\n|------|------|------|\n| coordinator | [roles/coordinator/role.md](roles/coordinator/role.md) | built-in orchestrator |\n| (dynamic) | `<session>/role-specs/<role-name>.md` | runtime-generated role-spec |\n\n### CLI Tool Usage\n\nWorkers can use CLI tools for analysis and code operations:\n\n| Tool | Purpose |\n|------|---------|\n| ccw cli --mode analysis | Analysis, exploration, pattern discovery |\n| ccw cli --mode write | Code generation, modification, refactoring |\n\n### Dispatch\n\nAlways route to coordinator. Coordinator reads `roles/coordinator/role.md` and executes its phases.\n\n### Orchestration Mode\n\nUser just provides task description.\n\n**Invocation**: `Skill(skill=\"team-coordinate\", args=\"task description\")`\n\n**Lifecycle**:\n```\nUser provides task description\n  -> coordinator Phase 1: task analysis (detect capabilities, build dependency graph)\n  -> coordinator Phase 2: generate role-specs + initialize session\n  -> coordinator Phase 3: create task chain from dependency graph\n  -> coordinator Phase 4: spawn first batch workers (background) -> STOP\n  -> Worker executes -> SendMessage callback -> coordinator advances next step\n  -> Loop until pipeline complete -> Phase 5 report + completion action\n```\n\n**User Commands** (wake paused coordinator):\n\n| Command | Action |\n|---------|--------|\n| `check` / `status` | Output execution status graph, no advancement |\n| `resume` / `continue` | Check worker states, advance next step |\n\n---\n\n## Coordinator Spawn Template\n\n### v2 Worker Spawn (all roles)\n\nWhen coordinator spawns workers, use `team-worker` agent with role-spec path:\n\n```\nAgent({\n  subagent_type: \"team-worker\",\n  description: \"Spawn <role> worker\",\n  team_name: <team-name>,\n  name: \"<role>\",\n  run_in_background: true,\n  prompt: `## Role Assignment\nrole: <role>\nrole_spec: <session-folder>/role-specs/<role>.md\nsession: <session-folder>\nsession_id: <session-id>\nteam_name: <team-name>\nrequirement: <task-description>\ninner_loop: <true|false>\n\nRead role_spec file to load Phase 2-4 domain instructions.\nExecute built-in Phase 1 (task discovery) -> role-spec Phase 2-4 -> built-in Phase 5 (report).`\n})\n```\n\n**Inner Loop roles** (role has 2+ serial same-prefix tasks): Set `inner_loop: true`. The team-worker agent handles the loop internally.\n\n**Single-task roles**: Set `inner_loop: false`.\n\n---\n\n## Completion Action\n\nWhen pipeline completes (all tasks done), coordinator presents an interactive choice:\n\n```\nAskUserQuestion({\n  questions: [{\n    question: \"Team pipeline complete. What would you like to do?\",\n    header: \"Completion\",\n    multiSelect: false,\n    options: [\n      { label: \"Archive & Clean (Recommended)\", description: \"Archive session, clean up team\" },\n      { label: \"Keep Active\", description: \"Keep session for follow-up work\" },\n      { label: \"Export Results\", description: \"Export deliverables to target directory, then clean\" }\n    ]\n  }]\n})\n```\n\n### Action Handlers\n\n| Choice | Steps |\n|--------|-------|\n| Archive & Clean | Update session status=\"completed\" -> TeamDelete -> output final summary with artifact paths |\n| Keep Active | Update session status=\"paused\" -> output: \"Resume with: Skill(skill=''team-coordinate'', args=''resume'')\" |\n| Export Results | AskUserQuestion(target path) -> copy artifacts to target -> Archive & Clean |\n\n---\n\n## Cadence Control\n\n**Beat model**: Event-driven, each beat = coordinator wake -> process -> spawn -> STOP.\n\n```\nBeat Cycle (single beat)\n======================================================================\n  Event                   Coordinator              Workers\n----------------------------------------------------------------------\n  callback/resume --> +- handleCallback -+\n                      |  mark completed   |\n                      |  check pipeline   |\n                      +- handleSpawnNext -+\n                      |  find ready tasks |\n                      |  spawn workers ---+--> [team-worker A] Phase 1-5\n                      |  (parallel OK)  --+--> [team-worker B] Phase 1-5\n                      +- STOP (idle) -----+         |\n                                                     |\n  callback <-----------------------------------------+\n  (next beat)              SendMessage + TaskUpdate(completed)\n======================================================================\n\n  Fast-Advance (skips coordinator for simple linear successors)\n======================================================================\n  [Worker A] Phase 5 complete\n    +- 1 ready task? simple successor? --> spawn team-worker B directly\n    +- complex case? --> SendMessage to coordinator\n======================================================================\n```\n\n**Pipelines are dynamic**: Unlike static pipeline definitions, team-coordinate pipelines are generated per-task from the dependency graph.\n\n---\n\n## Session Directory\n\n```\n.workflow/.team/TC-<slug>-<date>/\n+-- team-session.json           # Session state + dynamic role registry\n+-- task-analysis.json          # Phase 1 output: capabilities, dependency graph\n+-- role-specs/                 # Dynamic role-spec definitions (generated Phase 2)\n|   +-- <role-1>.md             # Lightweight: frontmatter + Phase 2-4 only\n|   +-- <role-2>.md\n+-- artifacts/                  # All MD deliverables from workers\n|   +-- <artifact>.md\n+-- .msg/                       # Team message bus + state\n|   +-- messages.jsonl          # Message log\n|   +-- meta.json               # Session metadata + cross-role state\n+-- wisdom/                     # Cross-task knowledge\n|   +-- learnings.md\n|   +-- decisions.md\n|   +-- issues.md\n+-- explorations/               # Shared explore cache\n|   +-- cache-index.json\n|   +-- explore-<angle>.json\n+-- discussions/                # Inline discuss records\n|   +-- <round>.md\n```\n\n### team-session.json Schema\n\n```json\n{\n  \"session_id\": \"TC-<slug>-<date>\",\n  \"task_description\": \"<original user input>\",\n  \"status\": \"active | paused | completed\",\n  \"team_name\": \"<team-name>\",\n  \"roles\": [\n    {\n      \"name\": \"<role-name>\",\n      \"prefix\": \"<PREFIX>\",\n      \"responsibility_type\": \"<type>\",\n      \"inner_loop\": false,\n      \"role_spec\": \"role-specs/<role-name>.md\"\n    }\n  ],\n  \"pipeline\": {\n    \"dependency_graph\": {},\n    \"tasks_total\": 0,\n    \"tasks_completed\": 0\n  },\n  \"active_workers\": [],\n  \"completed_tasks\": [],\n  \"completion_action\": \"interactive\",\n  \"created_at\": \"<timestamp>\"\n}\n```\n\n---\n\n## Session Resume\n\nCoordinator supports `resume` / `continue` for interrupted sessions:\n\n1. Scan `.workflow/.team/TC-*/team-session.json` for active/paused sessions\n2. Multiple matches -> AskUserQuestion for selection\n3. Audit TaskList -> reconcile session state <-> task status\n4. Reset in_progress -> pending (interrupted tasks)\n5. Rebuild team and spawn needed workers only\n6. Create missing tasks with correct blockedBy\n7. Kick first executable task -> Phase 4 coordination loop\n\n---\n\n## Error Handling\n\n| Scenario | Resolution |\n|----------|------------|\n| Unknown command | Error with available command list |\n| Dynamic role-spec not found | Error, coordinator may need to regenerate |\n| Command file not found | Fallback to inline execution |\n| CLI tool fails | Worker proceeds with direct implementation, logs warning |\n| Explore cache corrupt | Clear cache, re-explore |\n| Fast-advance spawns wrong task | Coordinator reconciles on next callback |\n| capability_gap reported | Coordinator generates new role-spec via handleAdapt |\n| Completion action fails | Default to Keep Active, log warning |\n"},"lastSynced":"2026-03-06T06:26:11.869Z","agentAnalysis":{"suitability":{"en":"Ideal for Autonomous Agents like AutoGPT and LangChain requiring dynamic team coordination and automated workflow execution.","zh":"适用于AutoGPT和LangChain等自动化代理，需要动态团队协调和自动化工作流执行。","ja":"AutoGPTやLangChainなどの自律エージェントに適しており、動的なチームの調整と自動化されたワークフローの実行が必要です。","ko":"AutoGPT 및 LangChain과 같은 자율 에이전트에 적합하며, 동적 팀 조정 및 자동화된 워크플로우 실행이 필요합니다.","es":"Ideal para Agentes Autónomos como AutoGPT y LangChain que requieren coordinación de equipo dinámica y ejecución de flujo de trabajo automatizada.","fr":"Idéal pour les agents autonomes tels que AutoGPT et LangChain nécessitant une coordination d''équipe dynamique et une exécution de workflow automatisée.","de":"Ideal für autonome Agenten wie AutoGPT und LangChain, die eine dynamische Teamkoordination und eine automatisierte Workflow-Ausführung erfordern.","pt":"Ideal para Agentes Autônomos como AutoGPT e LangChain que requerem coordenação de equipe dinâmica e execução de fluxo de trabalho automatizada.","ru":"Идеально подходит для автономных агентов, таких как AutoGPT и LangChain, требующих динамической координации команд и автоматизированной выполнения рабочих процессов.","ar":"مثالي للوكلاء المستقلين مثل AutoGPT و LangChain الذين يتطلبون تنسيق فريق ديناميكي وتحكم في سير العمل التلقائي."},"recommendation":{"en":"Empowers agents to analyze tasks, generate role-specs, and dispatch worker roles via the `team-worker` agent, utilizing lightweight role-spec files for efficient workflow management and leveraging protocols for seamless execution and delivery.","zh":"赋予代理分析任务、生成角色规格并通过`team-worker`代理分发工人角色，利用轻量级角色规格文件进行高效的工作流管理，并利用协议实现无缝的执行和交付。","ja":"エージェントにタスクを分析し、ロール仕様を生成し、`team-worker`エージェントを介してワーカーロールを配布する能力を与え、軽量のロール仕様ファイルを使用して効率的なワークフローマネジメントを行い、プロトコルを利用してシームレスな実行と納品を行う。","ko":"에이전트가 작업을 분석하고 역할 규격을 생성하며 `team-worker` 에이전트를 통해 작업자 역할을 배포할 수 있도록 하며, 가벼운 역할 규격 파일을 사용하여 효율적인 워크플로우 관리를进行하며, 프로토콜을 활용하여 무결점의 실행 및 전달을 수행합니다.","es":"Habilita a los agentes a analizar tareas, generar especificaciones de roles y enviar roles de trabajador a través del agente `team-worker`, utilizando archivos de especificaciones de roles ligeros para una gestión de flujo de trabajo eficiente y aprovechando protocolos para una ejecución y entrega sin problemas.","fr":"Permet aux agents d''analyser les tâches, de générer des spécifications de rôle et d''envoyer des rôles de travailleur via l''agent `team-worker`, en utilisant des fichiers de spécifications de rôle légers pour une gestion de workflow efficace et en exploitant des protocoles pour une exécution et une livraison sans problème.","de":"Ermöglicht es Agenten, Aufgaben zu analysieren, Rollenspezifikationen zu generieren und Arbeitnehmerrollen über den `team-worker`-Agenten zu senden, indem sie leichtgewichtige Rollenspezifikationsdateien für eine effiziente Workflow-Verwaltung verwenden und Protokolle für eine reibungslose Ausführung und Lieferung nutzen.","pt":"Habilita os agentes a analisar tarefas, gerar especificações de funções e enviar funções de trabalhador via o agente `team-worker`, utilizando arquivos de especificações de funções leves para gestão de fluxo de trabalho eficiente e aproveitando protocolos para execução e entrega sem problemas.","ru":"Предоставляет агентам возможность анализировать задачи, создавать спецификации ролей и отправлять роли рабочих через агент `team-worker`, используя легкие файлы спецификаций ролей для эффективного управления рабочим процессом и используя протоколы для бесперебойной выполнения и доставки.","ar":"تمكن الوكلاء من تحليل المهام وتوليد مواصفات الأدوار وإرسال أدوار العمال من خلال وكلاء `team-worker` ، باستخدام ملفات مواصفات الأدوار الخفيفة للإدارة الفعالة لسير العمل واستخدام البروتوكولات للتنفيذ والتسليم دون مشاكل."},"useCases":{"en":["Automating development workflows","Generating dynamic role-specs for task execution","Dispatching and executing tasks with the `team-worker` agent","Delivering project outcomes through coordinated team efforts"],"zh":["自动化开发工作流","为任务执行生成动态角色规格","使用`team-worker`代理分发和执行任务","通过协调的团队努力交付项目成果"],"ja":["開発ワークフローの自動化","タスク実行のための動的なロール仕様の生成","`team-worker`エージェントを使用したタスクの配布と実行","調整されたチームの努力によるプロジェクト成果の納品"],"ko":["개발 워크플로우의 자동화","작업 실행을 위한 동적 역할 규격의 생성","`team-worker` 에이전트를 사용한 작업의 배포 및 실행","조정된 팀의 노력에 의한 프로젝트 결과의 전달"],"es":["Automatización de flujos de trabajo de desarrollo","Generación de especificaciones de roles dinámicos para la ejecución de tareas","Envío y ejecución de tareas con el agente `team-worker`","Entrega de resultados de proyecto a través de esfuerzos de equipo coordinados"],"fr":["Automatisation des flux de travail de développement","Génération de spécifications de rôle dynamiques pour l''exécution de tâches","Envoi et exécution de tâches avec l''agent `team-worker`","Livraison de résultats de projet via des efforts d''équipe coordonnés"],"de":["Automatisierung von Entwicklungs-Workflows","Generierung von dynamischen Rollenspezifikationen für die Aufgabenausführung","Senden und Ausführen von Aufgaben mit dem `team-worker`-Agenten","Lieferung von Projektergebnissen durch koordinierte Teamanstrengungen"],"pt":["Automatizar fluxos de trabalho de desenvolvimento","Gerar especificações de funções dinâmicas para execução de tarefas","Enviar e executar tarefas com o agente `team-worker`","Entregar resultados de projetos por meio de esforços de equipe coordenados"],"ru":["Автоматизировать рабочие потоки разработки","Генерировать динамические спецификации ролей для выполнения задач","Отправлять и выполнять задачи с помощью агента `team-worker`","Доставлять результаты проектов посредством скоординированных усилий команды"],"ar":["توفير سير عمل تطوير آلي","توليد مواصفات أدوار ديناميكية لتنفيذ المهام","إرسال وتنفيذ المهام مع وكلاء `team-worker`","تسليم نتائج المشاريع من خلال جهود الفريق المنسقة"]},"limitations":{"en":["Requires coordinator role to be built-in","Dynamically generated worker roles may need additional configuration"],"zh":["需要内置协调者角色","动态生成的工人角色可能需要额外的配置"],"ja":["コーディネーターロールが組み込まれている必要がある","動的に生成されたワーカーロールには追加の構成が必要になる場合がある"],"ko":["조정자 역할이 내장되어 있어야 함","동적으로 생성된 작업자 역할에는 추가적인 구성이 필요할 수 있음"],"es":["Requiere que el rol de coordinador esté integrado","Los roles de trabajador generados dinámicamente pueden necesitar configuración adicional"],"fr":["Nécessite que le rôle de coordinateur soit intégré","Les rôles de travailleur générés dynamiquement peuvent nécessiter une configuration supplémentaire"],"de":["Erfordert, dass die Koordinator-Rolle integriert ist","Dynamisch generierte Arbeitnehmerrollen können eine zusätzliche Konfiguration erfordern"],"pt":["Requer que o papel de coordenador seja integrado","Papéis de trabalhador gerados dinamicamente podem precisar de configuração adicional"],"ru":["Требует, чтобы роль координатора была встроена","Динамически сгенерированные роли рабочих могут потребовать дополнительной настройки"],"ar":["يتطلب أن يكون دور المنسق متضمّنًا","أدوار العمال المولدة ديناميكيًا قد تحتاج إلى تكوين إضافي"]},"version":4},"contentHash":"e4c7b7a2b0e0c3477c2fbe3a76d2fe2da9faa2d566a986e1de9b82bd42470661","qualityScore":70}');
