INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('catlog22/Claude-Code-Workflow/team-coordinate', 'team-coordinate', 'catlog22', 'Claude-Code-Workflow', 'community', 'team-coordinate catlog22 Claude-Code-Workflow community claude claude-code cli-tools codex context-management gemini-cli json-driven qwen-code task-orchestration workflow-automation The team-coordinate skill provides a universal team coordination framework, analyzing tasks and generating role-specs for automated workflow execution, benefiting development teams. Team Coordinate 是一个 JSON 驱动的多代理协调开发框架，具有智能 CLI 编排和自动化工作流执行 Team Coordinate は JSON ドリブンのマルチエージェント開発フレームワークで、AI エージェント CLI オーケストレーションと自動化ワークフロー実行を備えています Team Coordinate는 JSON 기반의 다중 에이전트 개발 프레임워크로 지능형 CLI 오케스트레이션 및 자동화 워크플로우 실행을 지원합니다 Team Coordinate es un marco de desarrollo de equipo impulsado por JSON con arquitectura de contexto y ejecución de flujo de trabajo automatizada. Permite la coordinación de tareas y la generación dinámica de roles de trabajo Team Coordinate est un cadre de développement d''équipe basé sur JSON avec architecture de contexte et exécution de workflow automatisée. Il permet la coordination de tâches et la génération dynamique de rôles de travail Team Coordinate ist ein JSON-basiertes Entwicklungsfamework für Teams mit Kontextarchitektur und automatisierter Workflow-Ausführung. Es ermöglicht die Koordination von Aufgaben und die dynamische Generierung von Arbeitsrollen O Team Coordinate é um framework de desenvolvimento de equipes JSON-driven com CLI inteligente e arquitetura de contexto para automação de fluxo de trabalho Team Coordinate - это фреймворк для координации команд с JSON-driven и интеллектуальной CLI для автоматизации рабочих процессов أداة تنسيق الفريق هي إطار عمل لتنسيق فريق التطوير مع CLI ذكية وقاعدة JSON لآليّة سير العمل how to use team-coordinate team-coordinate setup guide team-coordinate vs claude team-coordinate install what is team-coordinate team-coordinate alternative JSON-driven workflow automation intelligent CLI orchestration tools context-first architecture benefits Team Coordinate JSON 驱动的多代理协调 智能 CLI 编排 自动化工作流执行 Gemini Qwen Codex 上下文优先架构 JSON-driven multi-agent framework for flexible team coordination Intelligent CLI orchestration using Gemini, Qwen, and Codex Context-first architecture for efficient workflow execution Automated workflow execution and task dispatch Dynamically generated worker roles as lightweight role-spec files team-coordinate is a JSON-driven multi-agent cadence-team development framework with intelligent CLI orchestration and context-first architecture.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('inkeep/agents/write-docs', 'community', 'inkeep', 'agents', 'inkeep/agents', 'write-docs', 968, 102, 70, '2026-03-01T12:44:11Z', '2026-03-06T06:26:11.723Z', '21e6ac40ada8ce49cc35e2ef26f2be272a26c568016f655ec62f0b7a76f019c7', '{"id":"inkeep/agents/write-docs","name":"write-docs","description":{"en":"The write-docs skill creates clear, consistent documentation for AI agents and multi-agent workflows, benefiting developers and customers alike.","zh":"write-docs技能用于创建和管理AIエージェント文档，支持二向同步和TypeScript SDK","ja":"AIエージェントのドキュメントを作成し、管理するためのwrite-docsスキルは、2ウェイス同期とTypeScript SDKをサポート","ko":"write-docs 기능은 AI 에이전트 문서를 생성하고 관리하며 2차원 동기화와 TypeScript SDK를 지원합니다","es":"write-docs permite crear documentación clara y consistente para Agentes de Inteligencia Artificial, siguiendo patrones y estructuras establecidas","fr":"write-docs permet de créer une documentation claire et cohérente pour les Agents d''Intelligence Artificielle, suivant des modèles et des structures établis","de":"write-docs ermöglicht die Erstellung klarer und konsistenter Dokumentationen für Künstliche Intelligenz-Agenten, unter Verwendung etablierter Muster und Strukturen","pt":"O Write-Docs é uma ferramenta para criar documentação clara e consistente para agentes de IA, com sincronização bidirecional e SDK em TypeScript.","ru":"Write-Docs - это инструмент для создания четкой и последовательной документации для ИИ Агентов, с двухсторонней синхронизацией и SDK на TypeScript.","ar":"Write-Docs هو أداة لإنشاء توثيق واضح ومتماسك للوكلاء الذكية، مع التزامن ثنائي الاتجاه و SDK باللغة TypeScript."},"seo":{"title":{"en":"write-docs: Documentation Setup Guide for AI Agents","zh":"AIエージェント文档创建与管理最佳实践","ja":"AIエージェントのドキュメント作成と管理のためのセットアップガイド","ko":"AI 에이전트 문서 작성 및 관리를 위한 최고의 방법","es":"Guía de configuración de write-docs para Agentes de Intel...","fr":"Guide de mi