INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('inkeep/agents/write-docs', 'write-docs', 'inkeep', 'agents', 'community', 'write-docs inkeep agents community agent agent-builder agent-framework agents-sdk ai ai-agent ai-agents aiagentframework developer-sdk inkeep llms low-code mcp mcp-server mulit-agent no-code self-hosted typescript workflow workflows The write-docs skill creates clear, consistent documentation for AI agents and multi-agent workflows, benefiting developers and customers alike. write-docs技能用于创建和管理AIエージェント文档，支持二向同步和TypeScript SDK AIエージェントのドキュメントを作成し、管理するためのwrite-docsスキルは、2ウェイス同期とTypeScript SDKをサポート write-docs 기능은 AI 에이전트 문서를 생성하고 관리하며 2차원 동기화와 TypeScript SDK를 지원합니다 write-docs permite crear documentación clara y consistente para Agentes de Inteligencia Artificial, siguiendo patrones y estructuras establecidas write-docs permet de créer une documentation claire et cohérente pour les Agents d''Intelligence Artificielle, suivant des modèles et des structures établis write-docs ermöglicht die Erstellung klarer und konsistenter Dokumentationen für Künstliche Intelligenz-Agenten, unter Verwendung etablierter Muster und Strukturen O Write-Docs é uma ferramenta para criar documentação clara e consistente para agentes de IA, com sincronização bidirecional e SDK em TypeScript. Write-Docs - это инструмент для создания четкой и последовательной документации для ИИ Агентов, с двухсторонней синхронизацией и SDK на TypeScript. Write-Docs هو أداة لإنشاء توثيق واضح ومتماسك للوكلاء الذكية، مع التزامن ثنائي الاتجاه و SDK باللغة TypeScript. how to use write-docs write-docs alternative write-docs setup guide what is write-docs write-docs vs agent-builder write-docs install write-docs for AI agents no-code documentation tools TypeScript SDK for documentation AIエージェント文档创建 二向同步 TypeScript SDK AIエージェント管理 文档结构 多语言文档创建 write-docs技能 Creates documentation for customer-facing features, APIs, SDKs, and CLI Supports no-code visual builder and TypeScript SDK for 2-way sync Enables restructuring and reorganizing of docs, including moves, renames, and redirects Updates pages in agents-docs/content/, snippets, and public-facing READMEs Manages reference artifacts like .env.example files write-docs is a skill for creating and managing documentation for AI agents, following established patterns and structure for the Inkeep docs site.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('K-Dense-AI/claude-scientific-writer/research-lookup', 'community', 'K-Dense-AI', 'claude-scientific-writer', 'K-Dense-AI/claude-scientific-writer', 'research-lookup', 866, 95, 70, '2026-02-25T00:46:09Z', '2026-03-06T06:27:16.169Z', 'ed983e74963584d4410fda87d3375067d59b5a9913be5846dfd533951d11ac9b', '{"id":"K-Dense-AI/claude-scientific-writer/research-lookup","name":"research-lookup","description":{"en":"The research-lookup skill provides real-time research information lookup for AI agents, utilizing intelligent backend routing and comprehensive research reports. It benefits developers and researchers seeking efficient information retrieval","zh":"研究查找技能提供实时研究信息查找，具有智能后端路由和多源研究报告","ja":"研究情報検索スキルは、リアルタイムの研究情報検索を提供し、intellegent backend routingとマルチソースの研究レポートを備えています","ko":"연구 정보 조회 스킬은 실시간 연구 정보 조회를 제공하며,智能 백엔드 라우팅 및 다중 소스 연구 레ポート를 지원합니다","es":"research-lookup es una herramienta de búsqueda de información científica en tiempo real que utiliza enrutamiento inteligente de backend y API de chat paralelo para proporcionar informes de investigación completos","fr":"research-lookup est un outil de recherche d''informations scientifiques en temps réel qui utilise un routage de backend intelligent et une API de chat parallèle pour fournir des rapports de recherche complets","de":"research-lookup ist ein Tool für die Echtzeit-Recherche wissenschaftlicher Informationen, das intelligente Backend-Weiterleitung und parallele Chat-API nutzt, um umfassende Forschungsberichte bereitzustellen","pt":"O Research-Lookup é uma ferramenta de busca de informações científicas em tempo real que utiliza roteamento de backend inteligente para fornecer relatórios de pesquisa abrangentes.","ru":"Research-Lookup - это инструмент для поиска научной информации в режиме реального времени, который использует интеллектуальную маршрутизацию бэкенда для предоставления всесторонних отчетов о pesquisa.","ar":"Research-Lookup هي أداة للبحث عن المعلومات العلمية في الوقت الفعلي التي تستخدم التوجيه الخلفي الذكي لتوفير تقارير بحث شاملة"},"seo":{"title":{"en":"research-lookup: Intelligent Research Information Lookup ...","zh":"研究查找技能配置指南 - 智能后端路由","ja":"研究情報検索スキルセットアップガイド - intellegent backend routing","ko":"연구 정보 조회 스킬 설정 가이드 -智能 백엔드 라우팅","es":"Guía de Configuración para research-lookup: Búsqueda de I...","fr":"Guide de Configuration pour research-lookup: Recherche d''...","de":"Einrichtungsleitfaden für research-lookup: Intelligente W...","pt":"Guia de Configuração do Research-Lookup: Busca de Informa...","ru":"Настройка Research-Lookup: Интеллектуальный Поиск Научной...","ar":"دليل إعداد Research-Lookup: بحث ذكي لمعلومات البحث العلمي"},"description":{"en":"Unlock real-time research capabilities with research-lookup. Discover how to integrate Parallel Chat API and Perplexity sonar-pro-search for comprehensive re...","zh":"了解研究查找技能的技术细节，包括并行聊天API和Perplexity sonar-pro-search","ja":"研究情報検索スキルの技術的詳細を学ぶ - Parallel Chat APIとPerplexity sonar-pro-search","ko":"연구 정보 조회 스킬의 기술적 세부 정보를 알아보세요 - Parallel Chat API 및 Perplexity sonar-pro-search","es":"Descubre cómo funciona research-lookup, una herramienta de búsqueda de información científica en tiempo real con enrutamiento inteligente de backend y API de...","fr":"Découvrez comment fonctionne research-lookup, un outil de recherche d''informations scientifiques en temps réel avec routage de backend intelligent et API de ...","de":"Erfahren Sie, wie research-lookup funktioniert, ein Tool für die Echtzeit-Recherche wissenschaftlicher Informationen mit intelligenter Backend-Weiterleitung ...","pt":"Aprenda a configurar o Research-Lookup, uma ferramenta de busca de informações científicas em tempo real com roteamento de backend inteligente","ru":"Узнайте, как настроить Research-Lookup, инструмент для поиска научной информации в режиме реального времени с интеллектуальным маршрутизацией бэкенда","ar":"تعرف على كيفية إعداد Research-Lookup، أداة للبحث عن المعلومات العلمية في الوقت الفعلي مع التوجيه الخلفي الذكي"},"definition":{"en":"research-lookup is a general-purpose scientific writer skill that enables real-time research information lookup with intelligent backend routing","zh":"研究查找技能是一种提供实时研究信息查找的AI技能，具有智能后端路由","ja":"研究情報検索スキルは、リアルタイムの研究情報検索を提供するAIスキルで、intellegent backend routingを備えています","ko":"연구 정보 조회 스킬은 실시간 연구 정보 조회를 제공하는 AI 스킬로,智能 백엔드 라우팅을 지원합니다","es":"research-lookup es una herramienta de búsqueda de información científica que utiliza tecnologías de inteligencia artificial para proporcionar resultados de búsqueda precisos y relevantes","fr":"research-lookup est un outil de recherche d''informations scientifiques qui utilise des technologies d''intelligence artificielle pour fournir des résultats de recherche précis et pertinents","de":"research-lookup ist ein Tool für die wissenschaftliche Informationsrecherche, das künstliche Intelligenz-Technologien nutzt, um präzise und relevante Suchergebnisse bereitzustellen","pt":"O que é Research-Lookup? É uma ferramenta de busca de informações científicas em tempo real que utiliza tecnologias de inteligência artificial","ru":"Что такое Research-Lookup? Это инструмент для поиска научной информации в режиме реального времени, который использует технологии искусственного интеллекта","ar":"ما هو Research-Lookup؟ هو أداة للبحث عن المعلومات العلمية في الوقت الفعلي التي تستخدم تقنيات الذكاء الاصطناعي"},"features":{"en":["Utilizes Parallel Chat API for comprehensive, multi-source research reports","Employs Perplexity sonar-pro-search for academic-specific paper searches","Integrates with OpenRouter for scholarly database access","Provides inline citations via OpenAI-compatible Chat API","Supports real-time research queries through intelligent backend routing","Offers access to research reports via https://api.parallel.ai"],"zh":["并行聊天API（core模型）","Perplexity sonar-pro-search（通过OpenRouter）","智能后端路由","多源研究报告","实时研究信息查找"],"ja":["Parallel Chat API（coreモデル）","Perplexity sonar-pro-search（OpenRouter経由）","intellegent backend routing","マルチソースの研究レポート","リアルタイムの研究情報検索"],"ko":["Parallel Chat API（core 모델）","Perplexity sonar-pro-search（OpenRouter를 통해）","智能 백엔드 라우팅","다중 소스 연구 레ポート","실시간 연구 정보 조회"],"es":["Enrutamiento inteligente de backend para consultas de investigación generales","API de chat paralelo para informes de investigación completos","Compatibilidad con OpenAI para resultados de búsqueda precisos","Búsqueda de artículos académicos con Perplexity sonar-pro-search","Acceso a bases de datos académicas a través de OpenRouter","Informes de investigación con citas en línea para mayor precisión"],"fr":["Routage de backend intelligent pour les requêtes de recherche générales","API de chat parallèle pour les rapports de recherche complets","Compatibilité avec OpenAI pour des résultats de recherche précis","Recherche d''articles académiques avec Perplexity sonar-pro-search","Accès aux bases de données académiques via OpenRouter","Rapports de recherche avec des citations en ligne pour une plus grande précision"],"de":["Intelligente Backend-Weiterleitung für allgemeine Forschungsanfragen","Parallele Chat-API für umfassende Forschungsberichte","Kompatibilität mit OpenAI für präzise Suchergebnisse","Akademische Artikel-Suche mit Perplexity sonar-pro-search","Zugriff auf akademische Datenbanken über OpenRouter","Forschungsberichte mit Online-Zitaten für höhere Genauigkeit"],"pt":["Busca de informações científicas em tempo real","Roteamento de backend inteligente","Parallel Chat API para consultas gerais","Perplexity sonar-pro-search para buscas acadêmicas","Suporte a múltiplas fontes de pesquisa","Relatórios de pesquisa abrangentes com citações inline"],"ru":["Поиск научной информации в режиме реального времени","Интеллектуальная маршрутизацией бэкенда","Parallel Chat API для общих запросов","Perplexity sonar-pro-search для академических поисков","Поддержка нескольких источников pesquisa","Всесторонние отчеты о pesquisa с inline цитатами"],"ar":["بحث المعلومات العلمية في الوقت الفعلي","التوجيه الخلفي الذكي","Parallel Chat API للاستفسارات العامة","Perplexity sonar-pro-search للبحث الأكاديمي","دعم مصادر البحث المتعددة","تقارير بحث شاملة مع الاستشهادات داخل النص"]},"keywords":{"en":["how to use research-lookup","research-lookup alternative","research-lookup setup guide","what is research-lookup","research-lookup vs Claude","research-lookup install","intelligent research information lookup","Parallel Chat API integration","Perplexity sonar-pro-search tutorial"],"zh":["AIエージェント","研究查找技能","智能后端路由","并行聊天API","Perplexity sonar-pro-search","研究信息查找","AI工具"],"ja":["AIエージェント","研究情報検索スキル","intellegent backend routing","Parallel Chat API","Perplexity sonar-pro-search","研究情報検索","AIツール"],"ko":["AI 에이전트","연구 정보 조회 스킬","智能 백엔드 라우팅","Parallel Chat API","Perplexity sonar-pro-search","연구 정보 조회","AI 도구"],"es":["herramientas de búsqueda científica","inteligencia artificial para la investigación","API de chat para la investigación","búsqueda de artículos académicos","OpenAI para la investigación","Perplexity sonar-pro-search","OpenRouter para la investigación","informes de investigación en tiempo real","Agente de investigación inteligente","Herramientas de investigación AI"],"fr":["outils de recherche scientifique","intelligence artificielle pour la recherche","API de chat pour la recherche","recherche d''articles académiques","OpenAI pour la recherche","Perplexity sonar-pro-search","OpenRouter pour la recherche","rapports de recherche en temps réel","Agent de recherche intelligent","Outils de recherche IA"],"de":["Tools für die wissenschaftliche Recherche","künstliche Intelligenz für die Forschung","Chat-API für die Forschung","Akademische Artikel-Suche","OpenAI für die Forschung","Perplexity sonar-pro-search","OpenRouter für die Forschung","Forschungsberichte in Echtzeit","Intelligenter Forschungsagent","Forschungs-Tools mit KI"],"pt":["Research-Lookup","busca de informações científicas","roteamento de backend inteligente","Parallel Chat API","Perplexity sonar-pro-search","ferramentas de pesquisa","ИИ Агенты","tecnologias de inteligência artificial"],"ru":["Research-Lookup","поиск научной информации","интеллектуальная маршрутизацией бэкенда","Parallel Chat API","Perplexity sonar-pro-search","инструменты для pesquisa","ИИ Агенты","технологии искусственного интеллекта"],"ar":["Research-Lookup","بحث المعلومات العلمية","التوجيه الخلفي الذكي","Parallel Chat API","Perplexity sonar-pro-search","أدوات البحث","وكلاء الذكاء الاصطناعي","تقنيات الذكاء الاصطناعي"]}},"owner":"K-Dense-AI","repo":"claude-scientific-writer","repoPath":"K-Dense-AI/claude-scientific-writer","stars":866,"forks":95,"updatedAt":"2026-02-25T00:46:09Z","topics":["ai-agents","anthropic","claude","skills","tools","writer"],"category":"community","skillMd":{"name":"research-lookup","description":"Look up current research information using the Parallel Chat API (primary) or Perplexity sonar-pro-search (academic paper searches). Automatically routes queries to the best backend. Use for finding papers, gathering research data, and verifying scientific information.","bodyPreview":"# Research Information Lookup\n\n## Overview\n\nThis skill provides real-time research information lookup with **intelligent backend routing**:\n\n- **Parallel Chat API** (`core` model): Default backend for all general research queries. Provides comprehensive, multi-source research reports with inline citations via the OpenAI-compatible Chat API at `https://api.parallel.ai`.\n- **Perplexity sonar-pro-search** (via OpenRouter): Used only for academic-specific paper searches where scholarly database acce","body":"# Research Information Lookup\n\n## Overview\n\nThis skill provides real-time research information lookup with **intelligent backend routing**:\n\n- **Parallel Chat API** (`core` model): Default backend for all general research queries. Provides comprehensive, multi-source research reports with inline citations via the OpenAI-compatible Chat API at `https://api.parallel.ai`.\n- **Perplexity sonar-pro-search** (via OpenRouter): Used only for academic-specific paper searches where scholarly database access is critical.\n\nThe skill automatically detects query type and routes to the optimal backend.\n\n## When to Use This Skill\n\nUse this skill when you need:\n\n- **Current Research Information**: Latest studies, papers, and findings\n- **Literature Verification**: Check facts, statistics, or claims against current research\n- **Background Research**: Gather context and supporting evidence for scientific writing\n- **Citation Sources**: Find relevant papers and studies to cite\n- **Technical Documentation**: Look up specifications, protocols, or methodologies\n- **Market/Industry Data**: Current statistics, trends, competitive intelligence\n- **Recent Developments**: Emerging trends, breakthroughs, announcements\n\n## Visual Enhancement with Scientific Schematics\n\n**When creating documents with this skill, always consider adding scientific diagrams and schematics to enhance visual communication.**\n\nIf your document does not already contain schematics or diagrams:\n- Use the **scientific-schematics** skill to generate AI-powered publication-quality diagrams\n- Simply describe your desired diagram in natural language\n\n```bash\npython scripts/generate_schematic.py \"your diagram description\" -o figures/output.png\n```\n\n---\n\n## Automatic Backend Selection\n\nThe skill automatically routes queries to the best backend based on content:\n\n### Routing Logic\n\n```\nQuery arrives\n    |\n    +-- Contains academic keywords? (papers, DOI, journal, peer-reviewed, etc.)\n    |       YES --> Perplexity sonar-pro-search (academic search mode)\n    |\n    +-- Everything else (general research, market data, technical info, analysis)\n            --> Parallel Chat API (core model)\n```\n\n### Academic Keywords (Routes to Perplexity)\n\nQueries containing these terms are routed to Perplexity for academic-focused search:\n\n- Paper finding: `find papers`, `find articles`, `research papers on`, `published studies`\n- Citations: `cite`, `citation`, `doi`, `pubmed`, `pmid`\n- Academic sources: `peer-reviewed`, `journal article`, `scholarly`, `arxiv`, `preprint`\n- Review types: `systematic review`, `meta-analysis`, `literature search`\n- Paper quality: `foundational papers`, `seminal papers`, `landmark papers`, `highly cited`\n\n### Everything Else (Routes to Parallel)\n\nAll other queries go to the Parallel Chat API (core model), including:\n\n- General research questions\n- Market and industry analysis\n- Technical information and documentation\n- Current events and recent developments\n- Comparative analysis\n- Statistical data retrieval\n- Complex analytical queries\n\n### Manual Override\n\nYou can force a specific backend:\n\n```bash\n# Force Parallel Deep Research\npython research_lookup.py \"your query\" --force-backend parallel\n\n# Force Perplexity academic search\npython research_lookup.py \"your query\" --force-backend perplexity\n```\n\n---\n\n## Core Capabilities\n\n### 1. General Research Queries (Parallel Chat API)\n\n**Default backend.** Provides comprehensive, multi-source research with citations via the Chat API (`core` model).\n\n```\nQuery Examples:\n- \"Recent advances in CRISPR gene editing 2025\"\n- \"Compare mRNA vaccines vs traditional vaccines for cancer treatment\"\n- \"AI adoption in healthcare industry statistics\"\n- \"Global renewable energy market trends and projections\"\n- \"Explain the mechanism underlying gut microbiome and depression\"\n```\n\n**Response includes:**\n- Comprehensive research report in markdown\n- Inline citations from authoritative web sources\n- Structured sections with key findings\n- Multiple perspectives and data points\n- Source URLs for verification\n\n### 2. Academic Paper Search (Perplexity sonar-pro-search)\n\n**Used for academic-specific queries.** Prioritizes scholarly databases and peer-reviewed sources.\n\n```\nQuery Examples:\n- \"Find papers on transformer attention mechanisms in NeurIPS 2024\"\n- \"Foundational papers on quantum error correction\"\n- \"Systematic review of immunotherapy in non-small cell lung cancer\"\n- \"Cite the original BERT paper and its most influential follow-ups\"\n- \"Published studies on CRISPR off-target effects in clinical trials\"\n```\n\n**Response includes:**\n- Summary of key findings from academic literature\n- 5-8 high-quality citations with authors, titles, journals, years, DOIs\n- Citation counts and venue tier indicators\n- Key statistics and methodology highlights\n- Research gaps and future directions\n\n### 3. Technical and Methodological Information\n\n```\nQuery Examples:\n- \"Western blot protocol for protein detection\"\n- \"Statistical power analysis for clinical trials\"\n- \"Machine learning model evaluation metrics comparison\"\n```\n\n### 4. Statistical and Market Data\n\n```\nQuery Examples:\n- \"Prevalence of diabetes in US population 2025\"\n- \"Global AI market size and growth projections\"\n- \"COVID-19 vaccination rates by country\"\n```\n\n---\n\n## Paper Quality and Popularity Prioritization\n\n**CRITICAL**: When searching for papers, ALWAYS prioritize high-quality, influential papers.\n\n### Citation-Based Ranking\n\n| Paper Age | Citation Threshold | Classification |\n|-----------|-------------------|----------------|\n| 0-3 years | 20+ citations | Noteworthy |\n| 0-3 years | 100+ citations | Highly Influential |\n| 3-7 years | 100+ citations | Significant |\n| 3-7 years | 500+ citations | Landmark Paper |\n| 7+ years | 500+ citations | Seminal Work |\n| 7+ years | 1000+ citations | Foundational |\n\n### Venue Quality Tiers\n\n**Tier 1 - Premier Venues** (Always prefer):\n- **General Science**: Nature, Science, Cell, PNAS\n- **Medicine**: NEJM, Lancet, JAMA, BMJ\n- **Field-Specific**: Nature Medicine, Nature Biotechnology, Nature Methods\n- **Top CS/AI**: NeurIPS, ICML, ICLR, ACL, CVPR\n\n**Tier 2 - High-Impact Specialized** (Strong preference):\n- Journals with Impact Factor > 10\n- Top conferences in subfields (EMNLP, NAACL, ECCV, MICCAI)\n\n**Tier 3 - Respected Specialized** (Include when relevant):\n- Journals with Impact Factor 5-10\n\n---\n\n## Technical Integration\n\n### Environment Variables\n\n```bash\n# Primary backend (Parallel Chat API) - REQUIRED\nexport PARALLEL_API_KEY=\"your_parallel_api_key\"\n\n# Academic search backend (Perplexity) - REQUIRED for academic queries\nexport OPENROUTER_API_KEY=\"your_openrouter_api_key\"\n```\n\n### API Specifications\n\n**Parallel Chat API:**\n- Endpoint: `https://api.parallel.ai` (OpenAI SDK compatible)\n- Model: `core` (60s-5min latency, complex multi-source synthesis)\n- Output: Markdown text with inline citations\n- Citations: Research basis with URLs, reasoning, and confidence levels\n- Rate limits: 300 req/min\n- Python package: `openai`\n\n**Perplexity sonar-pro-search:**\n- Model: `perplexity/sonar-pro-search` (via OpenRouter)\n- Search mode: Academic (prioritizes peer-reviewed sources)\n- Search context: High (comprehensive research)\n- Response time: 5-15 seconds\n\n### Command-Line Usage\n\n```bash\n# Auto-routed research (recommended) — ALWAYS save to sources/\npython research_lookup.py \"your query\" -o sources/research_YYYYMMDD_HHMMSS_<topic>.md\n\n# Force specific backend — ALWAYS save to sources/\npython research_lookup.py \"your query\" --force-backend parallel -o sources/research_<topic>.md\npython research_lookup.py \"your query\" --force-backend perplexity -o sources/papers_<topic>.md\n\n# JSON output — ALWAYS save to sources/\npython research_lookup.py \"your query\" --json -o sources/research_<topic>.json\n\n# Batch queries — ALWAYS save to sources/\npython research_lookup.py --batch \"query 1\" \"query 2\" \"query 3\" -o sources/batch_research_<topic>.md\n```\n\n---\n\n## MANDATORY: Save All Results to Sources Folder\n\n**Every research-lookup result MUST be saved to the project''s `sources/` folder.**\n\nThis is non-negotiable. Research results are expensive to obtain and critical for reproducibility.\n\n### Saving Rules\n\n| Backend | `-o` Flag Target | Filename Pattern |\n|---------|-----------------|------------------|\n| Parallel Deep Research | `sources/research_<topic>.md` | `research_YYYYMMDD_HHMMSS_<brief_topic>.md` |\n| Perplexity (academic) | `sources/papers_<topic>.md` | `papers_YYYYMMDD_HHMMSS_<brief_topic>.md` |\n| Batch queries | `sources/batch_<topic>.md` | `batch_research_YYYYMMDD_HHMMSS_<brief_topic>.md` |\n\n### How to Save\n\n**CRITICAL: Every call to `research_lookup.py` MUST include the `-o` flag pointing to the `sources/` folder.**\n\n**CRITICAL: Saved files MUST preserve all citations, source URLs, and DOIs.** The default text output automatically includes a `Sources` section (with title, date, URL for each source) and an `Additional References` section (with DOIs and academic URLs extracted from the response text). For maximum citation metadata, use `--json`.\n\n```bash\n# General research — save to sources/ (includes Sources + Additional References sections)\npython research_lookup.py \"Recent advances in CRISPR gene editing 2025\" \\\n  -o sources/research_20250217_143000_crispr_advances.md\n\n# Academic paper search — save to sources/ (includes paper citations with DOIs)\npython research_lookup.py \"Find papers on transformer attention mechanisms in NeurIPS 2024\" \\\n  -o sources/papers_20250217_143500_transformer_attention.md\n\n# JSON format for maximum citation metadata (full citation objects with URLs, DOIs, snippets)\npython research_lookup.py \"CRISPR clinical trials\" --json \\\n  -o sources/research_20250217_143000_crispr_trials.json\n\n# Forced backend — save to sources/\npython research_lookup.py \"AI regulation landscape\" --force-backend parallel \\\n  -o sources/research_20250217_144000_ai_regulation.md\n\n# Batch queries — save to sources/\npython research_lookup.py --batch \"mRNA vaccines efficacy\" \"mRNA vaccines safety\" \\\n  -o sources/batch_research_20250217_144500_mrna_vaccines.md\n```\n\n### Citation Preservation in Saved Files\n\nEach output format preserves citations differently:\n\n| Format | Citations Included | When to Use |\n|--------|-------------------|-------------|\n| Text (default) | `Sources (N):` section with `[title] (date) + URL` + `Additional References (N):` with DOIs and academic URLs | Standard use — human-readable with all citations |\n| JSON (`--json`) | Full citation objects: `url`, `title`, `date`, `snippet`, `doi`, `type` | When you need maximum citation metadata |\n\n**For Parallel backend**, saved files include: research report + Sources list (title, URL) + Additional References (DOIs, academic URLs).\n**For Perplexity backend**, saved files include: academic summary + Sources list (title, date, URL, snippet) + Additional References (DOIs, academic URLs).\n\n**Use `--json` when you need to:**\n- Parse citation metadata programmatically\n- Preserve full DOI and URL data for BibTeX generation\n- Maintain the structured citation objects for cross-referencing\n\n### Why Save Everything\n\n1. **Reproducibility**: Every citation and claim can be traced back to its raw research source\n2. **Context Window Recovery**: If context is compacted, saved results can be re-read without re-querying\n3. **Audit Trail**: The `sources/` folder documents exactly how all research information was gathered\n4. **Reuse Across Sections**: Multiple sections can reference the same saved research without duplicate queries\n5. **Cost Efficiency**: Check `sources/` for existing results before making new API calls\n6. **Peer Review Support**: Reviewers can verify the research backing every citation\n\n### Before Making a New Query, Check Sources First\n\nBefore calling `research_lookup.py`, check if a relevant result already exists:\n\n```bash\nls sources/  # Check existing saved results\n```\n\nIf a prior lookup covers the same topic, re-read the saved file instead of making a new API call.\n\n### Logging\n\nWhen saving research results, always log:\n\n```\n[HH:MM:SS] SAVED: Research lookup to sources/research_20250217_143000_crispr_advances.md (3,800 words, 8 citations)\n[HH:MM:SS] SAVED: Paper search to sources/papers_20250217_143500_transformer_attention.md (6 papers found)\n```\n\n---\n\n## Integration with Scientific Writing\n\nThis skill enhances scientific writing by providing:\n\n1. **Literature Review Support**: Gather current research for introduction and discussion — **save to `sources/`**\n2. **Methods Validation**: Verify protocols against current standards — **save to `sources/`**\n3. **Results Contextualization**: Compare findings with recent similar studies — **save to `sources/`**\n4. **Discussion Enhancement**: Support arguments with latest evidence — **save to `sources/`**\n5. **Citation Management**: Provide properly formatted citations — **save to `sources/`**\n\n## Complementary Tools\n\n| Task | Tool |\n|------|------|\n| General web search | `parallel-web` skill (`parallel_web.py search`) |\n| Citation verification | `parallel-web` skill (`parallel_web.py extract`) |\n| Deep research (any topic) | `research-lookup` or `parallel-web` skill |\n| Academic paper search | `research-lookup` (auto-routes to Perplexity) |\n| Google Scholar search | `citation-management` skill |\n| PubMed search | `citation-management` skill |\n| DOI to BibTeX | `citation-management` skill |\n| Metadata verification | `parallel-web` skill (`parallel_web.py search` or `extract`) |\n\n---\n\n## Error Handling and Limitations\n\n**Known Limitations:**\n- Parallel Chat API (core model): Complex queries may take up to 5 minutes\n- Perplexity: Information cutoff, may not access full text behind paywalls\n- Both: Cannot access proprietary or restricted databases\n\n**Fallback Behavior:**\n- If the selected backend''s API key is missing, tries the other backend\n- If both backends fail, returns structured error response\n- Rephrase queries for better results if initial response is insufficient\n\n---\n\n## Usage Examples\n\n### Example 1: General Research (Routes to Parallel)\n\n**Query**: \"Recent advances in transformer attention mechanisms 2025\"\n\n**Backend**: Parallel Chat API (core model)\n\n**Response**: Comprehensive markdown report with citations from authoritative sources, covering recent papers, key innovations, and performance benchmarks.\n\n### Example 2: Academic Paper Search (Routes to Perplexity)\n\n**Query**: \"Find papers on CRISPR off-target effects in clinical trials\"\n\n**Backend**: Perplexity sonar-pro-search (academic mode)\n\n**Response**: Curated list of 5-8 high-impact papers with full citations, DOIs, citation counts, and venue tier indicators.\n\n### Example 3: Comparative Analysis (Routes to Parallel)\n\n**Query**: \"Compare and contrast mRNA vaccines vs traditional vaccines for cancer treatment\"\n\n**Backend**: Parallel Chat API (core model)\n\n**Response**: Detailed comparative report with data from multiple sources, structured analysis, and cited evidence.\n\n### Example 4: Market Data (Routes to Parallel)\n\n**Query**: \"Global AI adoption in healthcare statistics 2025\"\n\n**Backend**: Parallel Chat API (core model)\n\n**Response**: Current market data, adoption rates, growth projections, and regional analysis with source citations.\n\n---\n\n## Summary\n\nThis skill serves as the primary research interface with intelligent dual-backend routing:\n\n- **Parallel Chat API** (default, `core` model): Comprehensive, multi-source research for any topic\n- **Perplexity sonar-pro-search**: Academic-specific paper searches only\n- **Automatic routing**: Detects academic queries and routes appropriately\n- **Manual override**: Force any backend when needed\n- **Complementary**: Works alongside `parallel-web` skill for web search and URL extraction\n"},"lastSynced":"2026-03-06T06:27:16.169Z","agentAnalysis":{"suitability":{"en":"Ideal for Knowledge Agents requiring real-time research information lookup with intelligent backend routing and comprehensive research reports.","zh":"适合需要实时研究信息查找、智能后端路由和综合研究报告的知识代理。","ja":"リアルタイムの研究情報の検索やインテリジェントなバックエンドルーティング、包括的な研究レポートが必要なナレッジエージェントに適しています。","ko":"실시간 연구 정보 조회 및 지능형 백엔드 라우팅, 포괄적인 연구 보고서가 필요한 지식 에이전트에 적합합니다.","es":"Ideal para Agentes de Conocimiento que requieren búsqueda de información de investigación en tiempo real con enrutamiento de backend inteligente e informes de investigación comprehensivos.","fr":"Idéal pour les Agents de Connaissance nécessitant une recherche d''information en temps réel avec un routage de backend intelligent et des rapports de recherche complets.","de":"Ideal für Wissensagenten, die Echtzeit-Rechercheinformationen mit intelligentem Back-end-Routing und umfassenden Forschungsberichten benötigen.","pt":"Ideal para Agentes de Conhecimento que exigem pesquisa de informações em tempo real com roteamento de backend inteligente e relatórios de pesquisa abrangentes.","ru":"Идеально для агентов знаний, требующих поиска информации в режиме реального времени с интеллектуальным маршрутизацией бэкэнда и комплексными исследовательскими отчетами.","ar":"مثالية لعمليات الوكيل المعرفي التي تتطلب بحث المعلومات في الوقت الفعلي مع التوجيه الخلفي المتقدم والتقارير البحثية الشاملة."},"recommendation":{"en":"Empowers agents to perform efficient information retrieval via the Parallel Chat API and Perplexity sonar-pro-search, leveraging OpenAI-compatible interfaces and inline citations for academic-specific paper searches.","zh":"通过 Parallel Chat API 和 Perplexity sonar-pro-search 启用代理执行高效的信息检索，利用 OpenAI 兼容接口和内联引用进行学术论文搜索。","ja":"Parallel Chat API と Perplexity sonar-pro-search を使用してエージェントが効率的な情報の取得を実行できるようにし、OpenAI 互換インターフェイスとインライン引用を使用して学術論文の検索を実行します。","ko":"Parallel Chat API 및 Perplexity sonar-pro-search를 통해 에이전트가 효율적인 정보 검색을 수행할 수 있도록 하며, OpenAI 호환 인터페이스 및 인라인 인용을 사용하여 학술 논문 검색을 수행합니다.","es":"Habilita a los agentes a realizar una recuperación de información eficiente a través de la Parallel Chat API y Perplexity sonar-pro-search, aprovechando interfaces compatibles con OpenAI y citas en línea para búsquedas de artículos académicos.","fr":"Permet aux agents d''effectuer une récupération d''informations efficace via l''API Parallel Chat et Perplexity sonar-pro-search, en exploitant les interfaces compatibles OpenAI et les citations en ligne pour les recherches d''articles académiques.","de":"Ermöglicht es Agenten, effiziente Informationsabruf durch die Parallel Chat API und Perplexity sonar-pro-search durchzuführen, indem OpenAI-kompatible Schnittstellen und Inline-Zitate für akademische Artikel-Suchen genutzt werden.","pt":"Permite que os agentes realizem uma recuperação eficiente de informações via a Parallel Chat API e Perplexity sonar-pro-search, aproveitando interfaces compatíveis com OpenAI e citações em linha para pesquisas de papel acadêmico.","ru":"Позволяет агентам выполнять эффективный поиск информации через Parallel Chat API и Perplexity sonar-pro-search, используя интерфейсы, совместимые с OpenAI, и цитаты в строке для поиска академических статей.","ar":"تمكن الوكلاء من أداء استرجاع المعلومات بكفاءة من خلال واجهة Parallel Chat API و Perplexity sonar-pro-search، مستفيدة من واجهات متوافقة مع OpenAI والاستشهادات المتضمنة للبحث الأكاديمي."},"useCases":{"en":["Automating research queries with multi-source reports","Generating comprehensive research summaries with inline citations","Conducting academic-specific paper searches via Perplexity sonar-pro-search"],"zh":["使用多源报告自动执行研究查询","使用内联引用生成综合研究摘要","通过 Perplexity sonar-pro-search 进行学术论文搜索"],"ja":["マルチソースレポートを使用して研究クエリを自動化する","インライン引用を使用して包括的な研究サマリーを生成する","Perplexity sonar-pro-search を使用して学術論文を検索する"],"ko":["다중 소스 보고서를 사용하여 연구 쿼리를 자동화하는 것","인라인 인용을 사용하여 포괄적인 연구 요약을 생성하는 것","Perplexity sonar-pro-search를 사용하여 학술 논문을 검색하는 것"],"es":["Automatizar consultas de investigación con informes de múltiples fuentes","Generar resúmenes de investigación comprehensivos con citas en línea","Realizar búsquedas de artículos académicos específicos a través de Perplexity sonar-pro-search"],"fr":["Automatiser les requêtes de recherche avec des rapports à sources multiples","Générer des résumés de recherche complets avec des citations en ligne","Effectuer des recherches d''articles académiques spécifiques via Perplexity sonar-pro-search"],"de":["Automatisierung von Forschungsanfragen mit Berichten aus mehreren Quellen","Erstellung umfassender Forschungszusammenfassungen mit Inline-Zitaten","Durchführung akademischer Artikel-Suchen über Perplexity sonar-pro-search"],"pt":["Automatizar consultas de pesquisa com relatórios de multi-fonte","Gerar resumos de pesquisa abrangentes com citações em linha","Realizar pesquisas de papel acadêmico específico via Perplexity sonar-pro-search"],"ru":["Автоматизировать запросы исследования с отчетами из нескольких источников","Генерировать комплексные резюме исследований с цитатами в строке","Проводить поиск академических статей через Perplexity sonar-pro-search"],"ar":["توفير استفسارات البحث بالكامل مع تقارير متعددة المصادر","توليد ملخصات بحث شاملة مع الاستشهادات المتضمنة","إجراء عمليات بحث محددة للأوراق الأكاديمية من خلال Perplexity sonar-pro-search"]},"limitations":{"en":["Requires access to the Parallel Chat API at https://api.parallel.ai","Limited to OpenAI-compatible interfaces","Academic-specific paper searches require access to scholarly databases via OpenRouter"],"zh":["需要访问 https://api.parallel.ai 的 Parallel Chat API","仅限 OpenAI 兼容接口","学术论文搜索需要通过 OpenRouter 访问学术数据库"],"ja":["https://api.parallel.ai の Parallel Chat API にアクセスする必要がある","OpenAI 互換インターフェイスのみ","学術論文の検索には OpenRouter を使用して学術データベースにアクセスする必要がある"],"ko":["https://api.parallel.ai 의 Parallel Chat API에 접근할 수 있어야 함","OpenAI 호환 인터페이스만 해당","학술 논문 검색에는 OpenRouter를 사용하여 학술 데이터베이스에 접근할 수 있어야 함"],"es":["Requiere acceso a la Parallel Chat API en https://api.parallel.ai","Limitado a interfaces compatibles con OpenAI","Las búsquedas de artículos académicos específicos requieren acceso a bases de datos académicas a través de OpenRouter"],"fr":["Nécessite un accès à l''API Parallel Chat à https://api.parallel.ai","Limité aux interfaces compatibles OpenAI","Les recherches d''articles académiques spécifiques nécessitent un accès aux bases de données universitaires via OpenRouter"],"de":["Erfordert Zugriff auf die Parallel Chat API unter https://api.parallel.ai","Begrenzt auf OpenAI-kompatible Schnittstellen","Akademische Artikel-Suchen erfordern Zugriff auf wissenschaftliche Datenbanken über OpenRouter"],"pt":["Exige acesso à Parallel Chat API em https://api.parallel.ai","Limitado a interfaces compatíveis com OpenAI","Pesquisas de papel acadêmico específico exigem acesso a bases de dados acadêmicas via OpenRouter"],"ru":["Требует доступа к Parallel Chat API по адресу https://api.parallel.ai","Ограничен интерфейсами, совместимыми с OpenAI","Поиск академических статей требует доступа к академическим базам данных через OpenRouter"],"ar":["يتطلب الوصول إلى واجهة Parallel Chat API على https://api.parallel.ai","محدود بالواجهات المتوافقة مع OpenAI","تتطلب عمليات البحث الأكاديمي المحددة الوصول إلى قواعد البيانات الأكاديمية عبر OpenRouter"]},"version":4},"contentHash":"ed983e74963584d4410fda87d3375067d59b5a9913be5846dfd533951d11ac9b","qualityScore":70}');
