INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('K-Dense-AI/claude-scientific-writer/research-lookup', 'research-lookup', 'K-Dense-AI', 'claude-scientific-writer', 'community', 'research-lookup K-Dense-AI claude-scientific-writer community ai-agents anthropic claude skills tools writer The research-lookup skill provides real-time research information lookup for AI agents, utilizing intelligent backend routing and comprehensive research reports. It benefits developers and researchers seeking efficient information retrieval 研究查找技能提供实时研究信息查找，具有智能后端路由和多源研究报告 研究情報検索スキルは、リアルタイムの研究情報検索を提供し、intellegent backend routingとマルチソースの研究レポートを備えています 연구 정보 조회 스킬은 실시간 연구 정보 조회를 제공하며,智能 백엔드 라우팅 및 다중 소스 연구 레ポート를 지원합니다 research-lookup es una herramienta de búsqueda de información científica en tiempo real que utiliza enrutamiento inteligente de backend y API de chat paralelo para proporcionar informes de investigación completos research-lookup est un outil de recherche d''informations scientifiques en temps réel qui utilise un routage de backend intelligent et une API de chat parallèle pour fournir des rapports de recherche complets research-lookup ist ein Tool für die Echtzeit-Recherche wissenschaftlicher Informationen, das intelligente Backend-Weiterleitung und parallele Chat-API nutzt, um umfassende Forschungsberichte bereitzustellen O Research-Lookup é uma ferramenta de busca de informações científicas em tempo real que utiliza roteamento de backend inteligente para fornecer relatórios de pesquisa abrangentes. Research-Lookup - это инструмент для поиска научной информации в режиме реального времени, который использует интеллектуальную маршрутизацию бэкенда для предоставления всесторонних отчетов о pesquisa. Research-Lookup هي أداة للبحث عن المعلومات العلمية في الوقت الفعلي التي تستخدم التوجيه الخلفي الذكي لتوفير تقارير بحث شاملة how to use research-lookup research-lookup alternative research-lookup setup guide what is research-lookup research-lookup vs Claude research-lookup install intelligent research information lookup Parallel Chat API integration Perplexity sonar-pro-search tutorial AIエージェント 研究查找技能 智能后端路由 并行聊天API Perplexity sonar-pro-search 研究信息查找 AI工具 Utilizes Parallel Chat API for comprehensive, multi-source research reports Employs Perplexity sonar-pro-search for academic-specific paper searches Integrates with OpenRouter for scholarly database access Provides inline citations via OpenAI-compatible Chat API Supports real-time research queries through intelligent backend routing Offers access to research reports via https://api.parallel.ai research-lookup is a general-purpose scientific writer skill that enables real-time research information lookup with intelligent backend routing');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('swimlane/ngx-ui/generate-swimlane-swim-solution', 'community', 'swimlane', 'ngx-ui', 'swimlane/ngx-ui', 'generate-swimlane-swim-solution', 735, 114, 70, '2026-02-27T18:17:34Z', '2026-03-06T06:27:29.235Z', '4950f8b91fa001e522b97b777edf93a06456aa608af3a9663cf44583f95ceb03', '{"id":"swimlane/ngx-ui/generate-swimlane-swim-solution","name":"generate-swimlane-swim-solution","description":{"en":"The generate-swimlane-swim-solution skill generates a standalone Lit-based solution for Angular using SwimlaneElement and custom Lit elements. It benefits developers who need to create custom widgets or small apps with Swimlane UI components.","zh":"生成Swimlane Lit Element解决方案，创建自定义小部件或应用程序，使用SwimlaneElement和Swimlane自定义Lit元素","ja":"Swimlane Lit Elementソリューションを生成して、カスタムウィジェットまたはアプリケーションを作成します。SwimlaneElementとSwimlaneのカスタムLit要素を使用します","ko":"Swimlane Lit Element 솔루션을 생성하여 사용자 지정 위젯 또는 애플리케이션을 생성합니다. SwimlaneElement와 Swimlane의 사용자 지정 Lit 요소를 사용합니다","es":"El generate-swimlane-swim-solution es una habilidad que permite generar soluciones personalizadas con Angular y Lit Element","fr":"Le generate-swimlane-swim-solution est une compétence qui permet de générer des solutions sur mesure avec Angular et Lit Element","de":"Das generate-swimlane-swim-solution ist eine Fähigkeit, die die Erstellung individueller Lösungen mit Angular und Lit Element ermöglicht","pt":"O generate-swimlane-swim-solution é uma biblioteca de componentes e estilos para Angular, permitindo a criação de soluções personalizadas","ru":"Generate Swimlane Swim Solution - это библиотека компонентов и стилей для Angular, позволяющая создавать индивидуальные решения","ar":"generate-swimlane-swim-solution هي مكتبة مكونات وأساليب ل Angular، مما يسمح بإنشاء حلول مخصصة"},"seo":{"title":{"en":"generate-swimlane-swim-solution: Lit Element Solution Set...","zh":"生成Swimlane Lit Element解决方案指南","ja":"Swimlane Lit Elementソリューション生成ガイド","ko":"Swimlane Lit Element 솔루션 생성 설정 가이드","es":"Guía de configuración de generate-swimlane-swim-solution ...","fr":"Guide de démarrage rapide pour generate-swimlane-swim-sol...","de":"Einrichtungsleitfaden für generate-swimlane-swim-solution","pt":"Guia de Configuração para generate-swimlane-swim-solution...","ru":"Настройка Generate Swimlane Swim Solution с помощью ИИ Аг...","ar":"دليل الإعداد لgenerate-swimlane-swim-solution باستخدام An..."},"description":{"en":"Discover how to generate a standalone Lit-based solution with SwimlaneElement and custom Lit elements. Learn how to apply the use-swim-ui skill for component...","zh":"使用AIエージェント生成Swimlane Lit Element解决方案，了解如何创建自定义小部件或应用程序","ja":"AIエージェントを使用してSwimlane Lit Elementソリューションを生成し、カスタムウィジェットまたはアプリケーションの作成方法を学びましょう","ko":"AI 도구를 사용하여 Swimlane Lit Element 솔루션을 생성하고 사용자 지정 위젯 또는 애플리케이션을 생성하는 방법을 알아보세요","es":"Aprende a utilizar generate-swimlane-swim-solution con Angular y Lit Element para crear soluciones personalizadas","fr":"Découvrez comment utiliser generate-swimlane-swim-solution avec Angular et Lit Element pour créer des solutions sur mesure","de":"Erfahren Sie, wie Sie generate-swimlane-swim-solution mit Angular und Lit Element verwenden, um individuelle Lösungen zu erstellen","pt":"Aprenda a criar soluções personalizadas com generate-swimlane-swim-solution e Angular, incluindo componentes e estilos personalizados","ru":"Создайте индивидуальные решения с Generate Swimlane Swim Solution и Angular, включая пользовательские компоненты и стили","ar":"تعلم كيفية إنشاء حلول مخصصة باستخدام generate-swimlane-swim-solution و Angular، بما في ذلك مكونات وأساليب مخصصة"},"definition":{"en":"generate-swimlane-swim-solution is a skill that generates a standalone Lit-based solution using SwimlaneElement and custom Lit elements for Angular applications.","zh":"生成Swimlane Lit Element解决方案是指使用AIエージェント创建自定义小部件或应用程序的过程","ja":"Swimlane Lit Elementソリューション生成とは、AIエージェントを使用してカスタムウィジェットまたはアプリケーションを作成するプロセスです","ko":"Swimlane Lit Element 솔루션 생성은 AI 도구를 사용하여 사용자 지정 위젯 또는 애플리케이션을 생성하는 프로세스입니다","es":"El generate-swimlane-swim-solution es una herramienta de AI que genera soluciones de interfaz de usuario personalizadas","fr":"Le generate-swimlane-swim-solution est un outil d''IA qui génère des solutions d''interface utilisateur sur mesure","de":"Das generate-swimlane-swim-solution ist ein AI-Tool, das individuelle Benutzeroberflächenlösungen generiert","pt":"O que é generate-swimlane-swim-solution? É uma biblioteca de componentes e estilos para Angular","ru":"Что такое Generate Swimlane Swim Solution? Это библиотека компонентов и стилей для Angular","ar":"ما هي generate-swimlane-swim-solution؟ هي مكتبة مكونات وأساليب ل Angular"},"features":{"en":["Generates a standalone Lit-based solution using SwimlaneElement","Utilizes custom Lit elements from the Swimlane UI component library","Applies the use-swim-ui skill for component lists and design rules","Supports Angular applications with custom widgets or small apps","Requires the use-swim-ui skill for property/event/slot API reference","Follows design rules and component source from use-swim-ui''s reference.md"],"zh":["使用SwimlaneElement和Swimlane自定义Lit元素","创建自定义小部件或应用程序","支持Angular组件和样式库","使用use-swim-ui技能生成解决方案"],"ja":["SwimlaneElementとSwimlaneのカスタムLit要素を使用","カスタムウィジェットまたはアプリケーションを作成","Angularコンポーネントとスタイルライブラリをサポート","use-swim-uiスキルを使用してソリューションを生成"],"ko":["SwimlaneElement와 Swimlane의 사용자 지정 Lit 요소를 사용","사용자 지정 위젯 또는 애플리케이션을 생성","Angular 컴포넌트 및 스타일 라이브러리를 지원","use-swim-ui 스킬을 사용하여 솔루션을 생성"],"es":["Generación de soluciones personalizadas con Angular","Uso de Lit Element para crear componentes personalizados","Compatibilidad con SwimlaneElement y elementos personalizados de Swimlane","Soporte para Hacktoberfest","Incorporación de estilos y componentes de interfaz de usuario"],"fr":["Génération de solutions sur mesure avec Angular","Utilisation de Lit Element pour créer des composants personnalisés","Compatibilité avec SwimlaneElement et éléments personnalisés de Swimlane","Prise en charge de Hacktoberfest","Intégration de styles et de composants d''interface utilisateur"],"de":["Erstellung individueller Lösungen mit Angular","Verwendung von Lit Element für die Erstellung von benutzerdefinierten Komponenten","Kompatibilität mit SwimlaneElement und benutzerdefinierten Swimlane-Elementen","Unterstützung für Hacktoberfest","Einbindung von Stilen und Benutzeroberflächenkomponenten"],"pt":["Utiliza SwimlaneElement como wrapper para Lit","Inclui componentes personalizados como swim-","Permite a criação de soluções standalone com Lit","Suporta uso de CDN e base de uso","Inclui design rules e API para propriedades e eventos"],"ru":["Использует SwimlaneElement как обертку для Lit","Включает пользовательские компоненты как swim-","Позволяет создавать индивидуальные решения с Lit","Поддерживает использование CDN и базы использования","Включает правила дизайна и API для свойств и событий"],"ar":["يستخدم SwimlaneElement كغلاف ل Lit","يتضمن مكونات مخصصة مثل swim-","يسمح بإنشاء حلول مخصصة مع Lit","يدعم استخدام CDN و قاعدة الاستخدام","يتضمن قواعد التصميم و واجهة برمجة التطبيقات لخصائص و أحداث"]},"keywords":{"en":["how to use generate-swimlane-swim-solution","generate-swimlane-swim-solution setup guide","generate-swimlane-swim-solution alternative","generate-swimlane-swim-solution vs angular material","generate-swimlane-swim-solution install","what is generate-swimlane-swim-solution","generate-swimlane-swim-solution tutorial","generate-swimlane-swim-solution for angular developers","generate-swimlane-swim-solution best practices"],"zh":["生成Swimlane Lit Element解决方案","AIエージェント","SwimlaneElement","Angular组件","样式库","use-swim-ui技能"],"ja":["Swimlane Lit Elementソリューション生成","AIエージェント","SwimlaneElement","Angularコンポーネント","スタイルライブラリ","use-swim-uiスキル"],"ko":["Swimlane Lit Element 솔루션 생성","AI 도구","SwimlaneElement","Angular 컴포넌트","스타일 라이브러리","use-swim-ui 스킬"],"es":["generate-swimlane-swim-solution","Angular","Lit Element","SwimlaneElement","componentes personalizados","Hacktoberfest","estilos de interfaz de usuario","herramientas de AI para desarrolladores","soluciones de interfaz de usuario personalizadas"],"fr":["generate-swimlane-swim-solution","Angular","Lit Element","SwimlaneElement","composants personnalisés","Hacktoberfest","styles d''interface utilisateur","outils d''IA pour les développeurs","solutions d''interface utilisateur sur mesure"],"de":["generate-swimlane-swim-solution","Angular","Lit Element","SwimlaneElement","benutzerdefinierte Komponenten","Hacktoberfest","Benutzeroberflächenstile","AI-Tools für Entwickler","individuelle Benutzeroberflächenlösungen"],"pt":["generate-swimlane-swim-solution","Angular","componentes personalizados","estilos personalizados","Lit","SwimlaneElement","CDN","desenvolvimento web"],"ru":["Generate Swimlane Swim Solution","Angular","пользовательские компоненты","пользовательские стили","Lit","SwimlaneElement","CDN","веб-разработка","ИИ Агенты"],"ar":["generate-swimlane-swim-solution","Angular","مكونات مخصصة","أساليب مخصصة","Lit","SwimlaneElement","CDN","تطوير ويب","ادوات الذكاء الاصطناعي"]}},"owner":"swimlane","repo":"ngx-ui","repoPath":"swimlane/ngx-ui","stars":735,"forks":114,"updatedAt":"2026-02-27T18:17:34Z","topics":["angular","component","css","dialog","directive","drawer","hacktoberfest","icons","library","select","split","styles","tabs","tree"],"category":"community","skillMd":{"name":"generate-swimlane-swim-solution","description":"Generate Swimlane Lit Element Solution (CDN). Requires the use-swim-ui skill for component list, API, CDN, and design rules.","bodyPreview":"# Generate Swimlane Lit Element Solution (CDN)\n\n**Prerequisite:** When executing this skill, you **must** apply the **use-swim-ui** skill: use it for the component list, CDN/base usage, design rules, and for property/event/slot API (use-swim-ui’s reference.md or component source). Do not generate the solution without that context.\n\nGenerate a **standalone Lit-based solution** (custom widget or small app) that uses **SwimlaneElement** (wrapper for Lit) and **Swimlane custom Lit elements** (`swim-","body":"# Generate Swimlane Lit Element Solution (CDN)\n\n**Prerequisite:** When executing this skill, you **must** apply the **use-swim-ui** skill: use it for the component list, CDN/base usage, design rules, and for property/event/slot API (use-swim-ui’s reference.md or component source). Do not generate the solution without that context.\n\nGenerate a **standalone Lit-based solution** (custom widget or small app) that uses **SwimlaneElement** (wrapper for Lit) and **Swimlane custom Lit elements** (`swim-*`) from `@swimlane/swim-ui`, with all dependencies loaded from **CDN**. Use **lit-elements as-is** — do not add additional styling for the elements (no custom colors, borders, shadows, typography on components); **only layout styling** (flex, grid, spacing, positioning) is allowed. The solution must be professional, consistent, accessible (WCAG), and free of memory leaks. You may use **HTML**, **vanilla JavaScript**, and **Swimlane Lit custom elements** only.\n\n**Base library**: All custom elements must extend **SwimlaneElement** and use its exports (`css`, `html`, `svg`, `unsafeCSS`) — not raw LitElement. For **component list**, **CDN/base usage**, and **design rules** (layout-only styling, tokens), apply the **use-swim-ui** skill; for full property/event/slot API see **use-swim-ui**’s [reference.md](../use-swim-ui/reference.md).\n\n- **SwimlaneElement**: [npm @swimlane/swimlane-element](https://www.npmjs.com/package/@swimlane/swimlane-element) · [GitHub swimlane/swimlane-element](https://github.com/swimlane/swimlane-element)\n\nExample (solution file):\n\n```js\nimport { SwimlaneElement, css, html, svg, unsafeCSS } from ''@swimlane/swimlane-element@2'';\nimport ''https://cdn.jsdelivr.net/gh/surya-pabbineedi/swim-ui@gh-pages/swim-ui.js?v=1'';\nimport { repeat } from ''lit-html@1/directives/repeat.js'';\n```\n\n## Input\n\n- **Goal/solution required**: Use the user''s description of the solution (e.g. \"dashboard widget\", \"form with validation\", \"alert configurator\"). **If the user does not provide a goal or solution to build, ask them:** e.g. *\"What solution or widget would you like to build? (e.g. dashboard widget, form with validation, alert configurator)\"* — and **do not generate any output** until they provide one.\n- **Updating an existing solution**: If the user refers to the **same solution again** or **points to a specific file** (e.g. an existing `.js` file in `projects/swimlane/swim-ui/demo/solutions`), **update that existing solution file** instead of creating a new one. Use the referenced file as the target to modify; preserve or refine behavior based on their new instructions.\n- If the user @-mentions a file or provides a spec, use that as the target (or as the file to update when applicable).\n- You may take **inspiration** from patterns at [Swimlane Platform Custom Widgets](https://swimlane.github.io/custom-widgets) (layout, UX, use cases), but **all UI elements must be Swimlane Lit custom elements** (`swim-*`) from `@swimlane/swim-ui` — do not copy non-Lit or framework-specific patterns from that site.\n\n## Output Location and Structure\n\n- **Output is a single `.js` file** (ES module) under **`projects/swimlane/swim-ui/demo/solutions`** with a **unique name**.\n- **Naming**: Derive a unique filename from the solution purpose, e.g. `<slug>-solution.js` (e.g. `alert-configurator-solution.js`, `dashboard-widget-solution.js`). Ensure the name does not conflict with existing files in that directory.\n- **When updating**: If the user pointed to an existing file or the same solution, write to **that existing file** (e.g. the same `projects/swimlane/swim-ui/demo/solutions/<name>.js`) instead of creating a new file.\n- The `.js` file is a **self-contained ES module** that imports from CDN (Lit and swim-ui), **exports a default class** extending `SwimlaneElement` (the main solution component), composes the UI with `swim-*` components, and can be loaded by the demo app or a minimal HTML page (e.g. `<script type=\"module\" src=\"...\">`). No build step required.\n- **Do not register** the solution class as a custom element (no `customElements.define(...)`) — custom element registration is handled by the Swimlane platform.\n\n## CDN Imports\n\nAll runtime dependencies must be loaded from CDN (no npm install or bundling). Follow **use-swim-ui** for SwimlaneElement base and swim-ui bundle URL; ensure the `lit` specifier is available (e.g. import map). Solution-specific:\n\n- In the solution file: import SwimlaneElement (or Lit) first, then the swim-ui bundle; use the same Lit instance.\n- For directives (e.g. `repeat`): `import { repeat } from ''https://esm.sh/lit-html@1/directives/repeat.js''` (or `lit-html@1/directives/repeat.js` with import map).\n- The solution class must **extend `SwimlaneElement`**, use `html`, `css`, `svg`, `unsafeCSS` from that package, and **export as default** — do not call `customElements.define()`.\n- In the command output, list every import with exact CDN URLs or import-map specifiers so the solution is copy-paste runnable.\n\n## Available Swimlane Lit Custom Elements\n\nUse **only** the `swim-*` elements listed in the **use-swim-ui** skill (component list and usage). Do not invent or assume other tag names. For properties, events, slots, and imperative APIs (e.g. drawer), use **use-swim-ui** and its [reference.md](../use-swim-ui/reference.md); or read `projects/swimlane/swim-ui/src/components/<name>/` for the source of truth.\n\n## Design and Consistency\n\nFollow the **use-swim-ui** skill for design rules (lit-elements as-is, layout-only styling, CSS variables, no hardcoded colors on components). In addition for solutions: use semantic HTML (`main`, `section`, `header`, `form`, `label`, etc.) and keep the DOM clear and minimal for maintainability and accessibility.\n\n\n## Accessibility (WCAG 2.1)\n\n- **Semantics**: Use the correct elements and ARIA roles (e.g. `role=\"button\"` only when not a `<button>`, `role=\"tablist\"` / `role=\"tab\"` / `role=\"tabpanel\"` where appropriate). Prefer native elements when they fit (e.g. `<button>`, `<input>`, `<label>`).\n- **ARIA**: Add `aria-label`, `aria-labelledby`, `aria-describedby`, `aria-expanded`, `aria-selected`, `aria-controls`, `aria-disabled`, `aria-invalid`, `aria-required` where they convey state or relationships. Keep `id` / `aria-controls` / `aria-labelledby` links valid and stable.\n- **Keyboard**: Full keyboard operation: Tab, Enter/Space to activate, Arrow keys where appropriate (e.g. lists, tabs), Escape to close overlays. No keyboard traps; focus moves logically (e.g. into/out of dialogs and drawers).\n- **Focus**: Visible focus indicator (e.g. `:focus-visible` with outline). When opening overlays, move focus as needed (e.g. to first focusable element or close button).\n- **Labels**: Every form control and interactive region has an accessible name (associated `<label>`, `aria-label`, or `aria-labelledby`).\n- **State**: Expose state to assistive tech (`aria-selected`, `aria-checked`, `aria-expanded`, `aria-disabled`, etc.) and keep it in sync with the UI.\n- **Contrast**: Use design tokens; ensure focus/active/disabled states meet contrast requirements.\n\n## No Memory Leaks\n\nIf the solution includes **custom Lit elements** (in addition to `swim-*`), or attaches **listeners/timers** in script:\n\n1. **Event listeners**\n   - Remove any listener added to **document**, **window**, or other elements (e.g. slotted content). Use the same bound reference for `addEventListener` and `removeEventListener`.\n   - Prefer storing the handler as a class field (e.g. `this._clickBound = () => this._onClick();`) so it can be removed in `disconnectedCallback()`.\n\n2. **Timers**\n   - Clear every `setTimeout`, `setInterval`, and recurring `requestAnimationFrame` in `disconnectedCallback()` (or when the relevant UI is torn down). Set stored timer ids to `undefined` after clearing.\n\n3. **Cleanup order**\n   - In `disconnectedCallback()`, remove listeners and clear timers **before** calling `super.disconnectedCallback()`.\n\n4. **No long-lived refs**\n   - Avoid holding references to DOM nodes or objects that are no longer in the document after the component is disconnected.\n\nIf the solution is **only** HTML and uses `swim-*` elements without adding its own listeners or timers, document that no extra cleanup is required beyond what the Swimlane components already do.\n\n## Allowed Technologies\n\n- **HTML5**: Structure, semantics, and minimal inline or linked CSS (prefer CSS variables).\n- **Vanilla JavaScript (ES module)**: Logic, event handlers, and dynamic updates. Use `type=\"module\"` and CDN imports.\n- **Swimlane Lit custom elements**: All UI components must be `swim-*` from `@swimlane/swim-ui` as listed in the **use-swim-ui** skill.\n- **Optional**: Custom Lit elements defined in the solution''s own script (e.g. a wrapper or app shell) must **extend SwimlaneElement** and use `css`, `html`, `svg`, `unsafeCSS` from `@swimlane/swimlane-element@2`; use directives (e.g. `repeat`) from `lit-html@1/directives/` as needed. **The main solution class must be the default export** — do not call `customElements.define()` (registration is handled by the Swimlane platform). Follow the same accessibility and no–memory-leak rules.\n\n## What Not to Do\n\n- Do **not** use Angular, React, Vue, or any other framework. Only **SwimlaneElement** (for any custom element you write) and Swimlane''s `swim-*` components. Do not use raw LitElement.\n- Do **not** add additional styling to `swim-*` elements (e.g. custom colors, borders, shadows, typography). Use lit-elements as-is; only layout-related CSS (flex, grid, spacing, positioning) is allowed.\n- Do **not** use components or patterns from other design systems or from the custom-widgets site that are not part of `@swimlane/swim-ui`. Use only the `swim-*` elements listed in this command.\n- Do **not** assume a build step (e.g. bundling or npm install) unless the user explicitly asks for it. Default is runnable in the browser via CDN.\n- Do **not** call `customElements.define()` to register the solution class — the Swimlane platform handles registration. Always **export default** the class instead.\n- Do **not** leave event listeners or timers attached after the component or page context is gone.\n\n## Steps\n\n1. **Apply use-swim-ui**: Use the **use-swim-ui** skill (and its reference.md) for the component list, CDN usage, design rules, and per-component properties/events/slots. Do not rely on memory alone for `swim-*` API.\n2. **Get the goal**: If the user did not provide a goal or solution to build, **ask** for one and stop. Do not generate output until they specify what to build.\n3. **Determine create vs update**: If the user points to an existing file (e.g. a `.js` file in `projects/swimlane/swim-ui/demo/solutions`) or refers to the same solution they had before, **update** that file. Otherwise, **create** a new `.js` file with a unique name in `projects/swimlane/swim-ui/demo/solutions`.\n4. **Clarify scope**: From the user''s request, determine the solution''s purpose (e.g. single widget, form, dashboard), which `swim-*` components are needed (from use-swim-ui), and whether to add any custom Lit element.\n5. **Choose CDN URLs**: Decide exact CDN URLs (or import-map specifiers) for **SwimlaneElement** (`@swimlane/swimlane-element@2`), any lit-html directives (e.g. `lit-html@1/directives/repeat.js`), and for **swim-ui** use the bundle at `https://cdn.jsdelivr.net/gh/surya-pabbineedi/swim-ui@gh-pages/swim-ui.js?v=1`. Ensure `lit` is provided (e.g. via import map) so the bundle resolves. Document the import URLs in a short comment at the top of the file if helpful.\n6. **Design structure**: Outline the structure (semantic sections, form groups, layout) and which Swimlane components go where (from **use-swim-ui** component list and reference.md). Reuse design tokens from the swim-ui demo for consistency (or inject minimal `:root` via the script if the solution is loaded standalone).\n7. **Implement**: Write the single `.js` file at `projects/swimlane/swim-ui/demo/solutions/<unique-name>.js`. The file must: import **SwimlaneElement**, `css`, `html`, `svg`, `unsafeCSS` from `@swimlane/swimlane-element@2`; import any needed directives (e.g. `repeat` from `lit-html@1/directives/repeat.js`); import swim-ui from CDN; **export a default class** extending **SwimlaneElement** (do not call `customElements.define()` — registration is handled by the Swimlane platform); compose the UI with `swim-*` elements and wire events using **use-swim-ui** API (properties, events, slots); ensure every interactive element is accessible; and have any custom element clean up in `disconnectedCallback()`. When updating an existing file, apply the user''s changes while keeping the same file path and unique name.\n8. **Verify**: Check that (a) all imports resolve (correct CDN URLs or import maps), (b) custom elements extend **SwimlaneElement** and use its exports, (c) only listed `swim-*` elements are used (per use-swim-ui), (d) labels/ARIA/keyboard/focus are in place, and (e) there are no listener/timer leaks.\n\nDeliver a **professional, consistent, accessible, leak-free** solution in **one `.js` file** under `projects/swimlane/swim-ui/demo/solutions` with a **unique name**, **exporting a default class** extending **SwimlaneElement** (from `@swimlane/swimlane-element@2`) — do **not** register it as a custom element (no `customElements.define()`), using **only** `swim-*` components from `@swimlane/swim-ui`, and loading **all dependencies from CDN**. When the user refers to the same solution or points to a file, **update** that file instead of creating a new one.\n"},"lastSynced":"2026-03-06T06:27:29.235Z","agentAnalysis":{"suitability":{"en":"Ideal for Frontend Agents specializing in Angular and Lit-based solutions, seeking to generate custom widgets or small apps with Swimlane UI components.","zh":"适合专注于Angular和Lit-based解决方案的前端代理，旨在生成自定义小部件或使用Swimlane UI组件的小应用程序。","ja":"AngularとLit-basedソリューションを専門とするフロントエンドエージェントに適しています。Swimlane UIコンポーネントを使用してカスタムウィジェットまたは小規模アプリケーションを生成することを目指しています。","ko":"Angular와 Lit-based 솔루션을 전문으로 하는 프론트엔드 에이전트에게 적합합니다. Swimlane UI 컴포넌트를 사용하여 사용자 정의 위젯 또는 작은 애플리케이션을 생성하려는 경우에 적합합니다.","es":"Ideal para agentes de frontend que se especializan en Angular y soluciones basadas en Lit, que buscan generar widgets personalizados o pequeñas aplicaciones con componentes de interfaz de usuario de Swimlane.","fr":"Idéal pour les agents de frontend qui se spécialisent dans Angular et les solutions basées sur Lit, qui cherchent à générer des widgets personnalisés ou de petites applications avec des composants d''interface utilisateur de Swimlane.","de":"Ideal für Frontend-Agents, die sich auf Angular und Lit-basierte Lösungen spezialisieren und benutzerdefinierte Widgets oder kleine Apps mit Swimlane-Benutzeroberflächenelementen erstellen möchten.","pt":"Ideal para Agentes Frontend especializados em Angular e soluções baseadas em Lit, que buscam gerar widgets personalizados ou pequenos aplicativos com componentes de interface do usuário da Swimlane.","ru":"Идеально для агентов Frontend, специализирующихся на Angular и решениях на основе Lit, которые хотят создавать пользовательские виджеты или небольшие приложения с помощью компонентов интерфейса пользователя Swimlane.","ar":"مثالي للوكلاء الأماميين المتخصصين في Angular وحلول Lit ، الذين يرغبون في生成 أدوات مخصصة أو تطبيقات صغيرة مع مكونات واجهة المستخدم من Swimlane."},"recommendation":{"en":"Empowers agents to create standalone Lit-based solutions using SwimlaneElement and custom Lit elements, leveraging CDN/base usage, design rules, and property/event/slot API from use-swim-ui, to develop tailored widgets or small applications with advanced UI capabilities.","zh":"赋予代理创建独立的Lit-based解决方案的能力，使用SwimlaneElement和自定义Lit元素，利用CDN/基础使用、设计规则和use-swim-ui的属性/事件/插槽API，开发具有高级UI功能的定制小部件或小应用程序。","ja":"エージェントが独立したLit-basedソリューションを作成できるようにします。SwimlaneElementとカスタムLit要素を使用し、CDN/基本使用、設計ルール、およびuse-swim-uiのプロパティ/イベント/スロットAPIを利用して、高度なUI機能を備えたカスタムウィジェットまたは小規模アプリケーションを開発します。","ko":"에이전트가 독립적인 Lit-based 솔루션을 생성할 수 있도록 합니다. SwimlaneElement와 사용자 정의 Lit 요소를 사용하며, CDN/기본 사용, 디자인 규칙 및 use-swim-ui의 속성/이벤트/슬롯 API를 활용하여 고급 UI 기능을 갖춘 사용자 정의 위젯 또는 작은 애플리케이션을 개발합니다.","es":"Habilita a los agentes a crear soluciones basadas en Lit de forma independiente utilizando SwimlaneElement y elementos personalizados de Lit, aprovechando el uso de CDN/base, reglas de diseño y API de propiedad/evento/ranura de use-swim-ui, para desarrollar widgets personalizados o aplicaciones pequeñas con capacidades de interfaz de usuario avanzadas.","fr":"Permet aux agents de créer des solutions basées sur Lit de manière autonome en utilisant SwimlaneElement et des éléments Lit personnalisés, en exploitant l''utilisation de CDN/base, les règles de conception et l''API de propriété/événement/emplacement de use-swim-ui, pour développer des widgets personnalisés ou de petites applications avec des capacités d''interface utilisateur avancées.","de":"Ermächtigt die Agenten, eigenständige Lit-basierte Lösungen mit SwimlaneElement und benutzerdefinierten Lit-Elementen zu erstellen, indem sie die CDN-Grundnutzung, die Designregeln und die Eigenschafts-/Ereignis-/Schlitz-API von use-swim-ui nutzen, um maßgeschneiderte Widgets oder kleine Anwendungen mit erweiterten Benutzeroberflächenfunktionen zu entwickeln.","pt":"Habilita os agentes a criar soluções baseadas em Lit autônomas usando SwimlaneElement e elementos Lit personalizados, aproveitando o uso de CDN/base, regras de design e API de propriedade/evento/slot do use-swim-ui, para desenvolver widgets personalizados ou pequenos aplicativos com capacidades de interface do usuário avançadas.","ru":"Наделяет агентов возможностью создавать автономные решения на осн