INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('swimlane/ngx-ui/generate-swimlane-swim-solution', 'generate-swimlane-swim-solution', 'swimlane', 'ngx-ui', 'community', 'generate-swimlane-swim-solution swimlane ngx-ui community angular component css dialog directive drawer hacktoberfest icons library select split styles tabs tree The generate-swimlane-swim-solution skill generates a standalone Lit-based solution for Angular using SwimlaneElement and custom Lit elements. It benefits developers who need to create custom widgets or small apps with Swimlane UI components. 生成Swimlane Lit Element解决方案，创建自定义小部件或应用程序，使用SwimlaneElement和Swimlane自定义Lit元素 Swimlane Lit Elementソリューションを生成して、カスタムウィジェットまたはアプリケーションを作成します。SwimlaneElementとSwimlaneのカスタムLit要素を使用します Swimlane Lit Element 솔루션을 생성하여 사용자 지정 위젯 또는 애플리케이션을 생성합니다. SwimlaneElement와 Swimlane의 사용자 지정 Lit 요소를 사용합니다 El generate-swimlane-swim-solution es una habilidad que permite generar soluciones personalizadas con Angular y Lit Element Le generate-swimlane-swim-solution est une compétence qui permet de générer des solutions sur mesure avec Angular et Lit Element Das generate-swimlane-swim-solution ist eine Fähigkeit, die die Erstellung individueller Lösungen mit Angular und Lit Element ermöglicht O generate-swimlane-swim-solution é uma biblioteca de componentes e estilos para Angular, permitindo a criação de soluções personalizadas Generate Swimlane Swim Solution - это библиотека компонентов и стилей для Angular, позволяющая создавать индивидуальные решения generate-swimlane-swim-solution هي مكتبة مكونات وأساليب ل Angular، مما يسمح بإنشاء حلول مخصصة how to use generate-swimlane-swim-solution generate-swimlane-swim-solution setup guide generate-swimlane-swim-solution alternative generate-swimlane-swim-solution vs angular material generate-swimlane-swim-solution install what is generate-swimlane-swim-solution generate-swimlane-swim-solution tutorial generate-swimlane-swim-solution for angular developers generate-swimlane-swim-solution best practices 生成Swimlane Lit Element解决方案 AIエージェント SwimlaneElement Angular组件 样式库 use-swim-ui技能 Generates a standalone Lit-based solution using SwimlaneElement Utilizes custom Lit elements from the Swimlane UI component library Applies the use-swim-ui skill for component lists and design rules Supports Angular applications with custom widgets or small apps Requires the use-swim-ui skill for property/event/slot API reference Follows design rules and component source from use-swim-ui''s reference.md generate-swimlane-swim-solution is a skill that generates a standalone Lit-based solution using SwimlaneElement and custom Lit elements for Angular applications.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('stellarlinkco/codex/babysit-pr', 'community', 'stellarlinkco', 'codex', 'stellarlinkco/codex', 'babysit-pr', 345, 16, 70, '2026-03-05T10:33:47Z', '2026-03-06T06:28:29.369Z', '165e7c05a4d5a7d1ba58afca15c3539f48b2b0cf0c3c251a0e644b2a1434ecf5', '{"id":"stellarlinkco/codex/babysit-pr","name":"babysit-pr","description":{"en":"babysit-pr is an open-source coding agent that automates PR management, ensuring persistent monitoring until merge, closure, or user intervention is required. It benefits developers by simplifying PR workflows.","zh":"babysit-pr 是一个开源的编码代理，用于自动化 PR 审核流程，确保代码质量和开发效率","ja":"babysit-pr はオープンソースのコードエージェントで、PR レビューを自動化してコード品質と開発効率を向上させる","ko":"babysit-pr는 오픈소스의 코드 에이전트로 PR 리뷰를 자동화하여 코드 품질과 개발 효율성을 향상시킵니다","es":"babysit-pr es un agente de código abierto que automatiza la revisión de código y el seguimiento de solicitudes de extracción hasta su resolución","fr":"babysit-pr est un agent de codage open source qui automatise la revue de code et le suivi des demandes d''extraction jusqu''à leur résolution","de":"babysit-pr ist ein Open-Source-Coding-Agent, der die Code-Review- und Pull-Request-Verfolgung bis zur Auflösung automatisiert","pt":"O babysit-pr é um agente de codificação de código aberto que automatiza o processo de PR com OpenAI. Ele persiste em babysitar um PR até que ocorra um dos resultados finais.","ru":"babysit-pr - это открытый агент кодирования, который автоматизирует процесс PR с ИИ Агентами. Он постоянно следит за PR до тех пор, пока не произойдет один из конечных результатов.","ar":"babysit-pr هو وسيط ترميز مفتوح المصدر يؤتمة عملية إدارة طلبات السحب مع أدوات ذكاء إصطناعي. وهو يصر على مراقبة طلب السحب حتى تحقق واحدة من النتائج النهائية."},"seo":{"title":{"en":"babysit-pr: Automated PR Management for AI Agents | AI Ag...","zh":"babysit-pr Setup Guide: 自动化 PR 审核流程","ja":"babysit-pr のセットアップガイド: PR レビューの自動化","ko":"babysit-pr 설정 가이드: PR 리뷰 자동화","es":"Guía de configuración de babysit-pr: Agente de código abi...","fr":"Guide de mise en place de babysit-pr: Agent de codage ope...","de":"Einrichtungsleitfaden für babysit-pr: Open-Source-Coding-...","pt":"Guia de Configuração do babysit-pr: Automação de PR com O...","ru":"Настройка babysit-pr: Автоматизация PR с ИИ Агентами","ar":"دليل إعداد babysit-pr: آليّة إدارة طلبات السحب مع أدوات ذ..."},"description":{"en":"Streamline your PR process with babysit-pr! Learn how to automate PR management, resolve merge conflicts, and optimize CI workflows. Get started now!","zh":"使用 babysit-pr 自动化 PR 审核流程，提高代码质量和开发效率","ja":"babysit-pr を使用して PR レビューを自動化し、コード品質と開発効率を向上させる","ko":"babysit-pr를 사용하여 PR 리뷰를 자동화하고 코드 품질 및 개발 효율성을 향상시키세요","es":"Aprende a configurar babysit-pr, un agente de código abierto para automatizar tareas de revisión de código y seguimiento de solicitudes de extracción","fr":"Découvrez comment configurer babysit-pr, un agent de codage open source pour automatiser les tâches de revue de code et de suivi des demandes d''extraction","de":"Erfahren Sie, wie Sie babysit-pr einrichten, einen Open-Source-Coding-Agent für die Automatisierung von Code-Review- und Pull-Request-Verfolgungsaufgaben","pt":"Aprenda a configurar o babysit-pr para automação de PR com OpenAI e melhore a eficiência do seu fluxo de trabalho de desenvolvimento","ru":"Узнайте, как настроить babysit-pr для автоматизации PR с ИИ Агентами и повысьте эффективность вашего рабочего процесса разработки","ar":"تعرف على كيفية إعداد babysit-pr لآليّة إدارة طلبات السحب مع أدوات ذكاء إصطناعي وتحسين كفاءة تدفق عملك التطويري"},"definition":{"en":"babysit-pr is an open-source AI agent that automates the process of babysitting a PR until it is merged, closed, or requires user assistance.","zh":"babysit-pr 是一个自动化 PR 审核流程的工具","ja":"babysit-pr は PR レビューを自動化するツール","ko":"babysit-pr는 PR 리뷰를 자동화하는 도구입니다","es":"babysit-pr es un agente de código abierto que gestiona y automatiza tareas de revisión de código y seguimiento de solicitudes de extracción","fr":"babysit-pr est un agent de codage open source qui gère et automatise les tâches de revue de code et de suivi des demandes d''extraction","de":"babysit-pr ist ein Open-Source-Coding-Agent, der Code-Review- und Pull-Request-Verfolgungsaufgaben verwaltet und automatisiert","pt":"O que é babysit-pr? É um agente de codificação de código aberto que automatiza o processo de PR com OpenAI","ru":"Что такое babysit-pr? Это открытый агент кодирования, который автоматизирует процесс PR с ИИ Агентами","ar":"ما هو babysit-pr? هو وسيط ترميز مفتوح المصدر يؤتمة عملية إدارة طلبات السحب مع أدوات ذكاء إصطناعي"},"features":{"en":["Monitors PRs persistently until terminal outcomes occur","Checks for successful CI, unaddressed review comments, and required review approval","Detects potential merge conflicts and reports conflict risk","Handles situations requiring user help, such as CI infrastructure issues","Ensures PRs are mergeable and not blocked by review approvals","Retries flaky failures until retry budget is exhausted"],"zh":["自动化 PR 审核流程","支持 CI/CD 流程","检测未解决的审查评论","检查合并冲突风险","确保代码质量和开发效率"],"ja":["PR レビューを自動化","CI/CD プロセスをサポート","未解決のレビュー コメントを検出","マージ コンフリクト リスクを確認","コード 品質と開発効率を向上させる"],"ko":["PR 리뷰를 자동화","CI/CD 프로세스를 지원","미해결 리뷰 댓글을 감지","병합 충돌 위험을 확인","코드 품질과 개발 효율성을 향상시키기"],"es":["Automatización de la revisión de código y seguimiento de solicitudes de extracción","Integración con sistemas de CI para verificar la éxito de las pruebas","Detección de comentarios de revisión no abordados y conflictos de fusión potenciales","Compatibilidad con OpenAI, Anthropics y Gemini","Seguimiento persistente hasta la resolución de la solicitud de extracción"],"fr":["Automatisation de la revue de code et du suivi des demandes d''extraction","Intégration avec les systèmes de CI pour vérifier la réussite des tests","Détection de commentaires de revue non abordés et de conflits de fusion potentiels","Compatibilité avec OpenAI, Anthropics et Gemini","Suivi persistant jusqu''à la résolution de la demande d''extraction"],"de":["Automatisierung der Code-Review- und Pull-Request-Verfolgung","Integration mit CI-Systemen zur Überprüfung des Erfolgs der Tests","Erkennung von unbeantworteten Review-Kommentaren und potenziellen Merge-Konflikten","Kompatibilität mit OpenAI, Anthropics und Gemini","Persistierende Verfolgung bis zur Auflösung der Pull-Request"],"pt":["Automação de PR com OpenAI","Persistência em babysitar um PR até que ocorra um dos resultados finais","Integração com CI para verificar a sucesso dos testes","Verificação de comentários de revisão e aprovação de revisão","Detecção de conflitos de merge potenciais"],"ru":["Автоматизация PR с ИИ Агентами","Постоянное наблюдение за PR до тех пор, пока не произойдет один из конечных результатов","Интеграция с CI для проверки успеха тестов","Проверка комментариев к ревью и одобрения ревью","Обнаружение потенциальных конфликтов слияния"],"ar":["آليّة إدارة طلبات السحب مع أدوات ذكاء إصطناعي","الاستمرار في مراقبة طلب السحب حتى تحقق واحدة من النتائج النهائية","التكامل مع CI للتحقق من نجاح الاختبارات","التحقق من تعليقات المراجعة وموافقة المراجعة","اكتشاف تضارب الدمج المحتمل"]},"keywords":{"en":["how to use babysit-pr","babysit-pr alternative","babysit-pr setup guide","what is babysit-pr","babysit-pr vs openai","babysit-pr install","automated pr management","ci workflow optimization","merge conflict resolution"],"zh":["babysit-pr","AI 代理","自动化 PR 审核","CI/CD","代码质量","开发效率","开源编码代理"],"ja":["babysit-pr","AI エージェント","PR レビューの自動化","CI/CD","コード品質","開発効率","オープンソースコードエージェント"],"ko":["babysit-pr","AI 에이전트","PR 리뷰 자동화","CI/CD","코드 품질","개발 효율성","오픈소스 코드 에이전트"],"es":["agente de código abierto","automatización de revisión de código","seguimiento de solicitudes de extracción","integración con CI","OpenAI","Anthropic","Gemini","desarrollo de software","herramientas de desarrollo"],"fr":["agent de codage open source","automatisation de la revue de code","suivi des demandes d''extraction","intégration avec les CI","OpenAI","Anthropic","Gemini","développement de logiciels","outils de développement"],"de":["Open-Source-Coding-Agent","Automatisierung der Code-Review","Verfolgung von Pull-Requests","Integration mit CI-Systemen","OpenAI","Anthropic","Gemini","Softwareentwicklung","Entwicklungstools"],"pt":["babysit-pr","automação de PR","OpenAI","desenvolvimento de software","fluxo de trabalho de desenvolvimento","CI","comentários de revisão","aprovação de revisão","conflitos de merge"],"ru":["babysit-pr","автоматизация PR","ИИ Агенты","разработка программного обеспечения","рабочий процесс разработки","CI","комментарии к ревью","одобрение ревью","конфликты слияния"],"ar":["babysit-pr","آليّة إدارة طلبات السحب","أدوات ذكاء إصطناعي","تطوير البرمجيات","تدفق عمل التطوير","CI","تعليقات المراجعة","موافقة المراجعة","تضارب الدمج"]}},"owner":"stellarlinkco","repo":"codex","repoPath":"stellarlinkco/codex","stars":345,"forks":16,"updatedAt":"2026-03-05T10:33:47Z","topics":[],"category":"community","skillMd":{"name":"babysit-pr","description":"Babysit a GitHub pull request after creation by continuously polling CI checks/workflow runs, new review comments, and mergeability state until the PR is ready to merge (or merged/closed). Diagnose failures, retry likely flaky failures up to 3 times, auto-fix/push branch-related issues when appropriate, and stop only when user help is required (for example CI infrastructure issues, exhausted flaky retries, or ambiguous/blocking situations). Use when the user asks Codex to monitor a PR, watch CI, handle review comments, or keep an eye on failures and feedback on an open PR.","bodyPreview":"# PR Babysitter\n\n## Objective\nBabysit a PR persistently until one of these terminal outcomes occurs:\n\n- The PR is merged or closed.\n- CI is successful, there are no unaddressed review comments surfaced by the watcher, required review approval is not blocking merge, and there are no potential merge conflicts (PR is mergeable / not reporting conflict risk).\n- A situation requires user help (for example CI infrastructure issues, repeated flaky failures after retry budget is exhausted, permission pr","body":"# PR Babysitter\n\n## Objective\nBabysit a PR persistently until one of these terminal outcomes occurs:\n\n- The PR is merged or closed.\n- CI is successful, there are no unaddressed review comments surfaced by the watcher, required review approval is not blocking merge, and there are no potential merge conflicts (PR is mergeable / not reporting conflict risk).\n- A situation requires user help (for example CI infrastructure issues, repeated flaky failures after retry budget is exhausted, permission problems, or ambiguity that cannot be resolved safely).\n\nDo not stop merely because a single snapshot returns `idle` while checks are still pending.\n\n## Inputs\nAccept any of the following:\n\n- No PR argument: infer the PR from the current branch (`--pr auto`)\n- PR number\n- PR URL\n\n## Core Workflow\n\n1. When the user asks to \"monitor\"/\"watch\"/\"babysit\" a PR, start with the watcher''s continuous mode (`--watch`) unless you are intentionally doing a one-shot diagnostic snapshot.\n2. Run the watcher script to snapshot PR/CI/review state (or consume each streamed snapshot from `--watch`).\n3. Inspect the `actions` list in the JSON response.\n4. If `diagnose_ci_failure` is present, inspect failed run logs and classify the failure.\n5. If the failure is likely caused by the current branch, patch code locally, commit, and push.\n6. If `process_review_comment` is present, inspect surfaced review items and decide whether to address them.\n7. If a review item is actionable and correct, patch code locally, commit, and push.\n8. If the failure is likely flaky/unrelated and `retry_failed_checks` is present, rerun failed jobs with `--retry-failed-now`.\n9. If both actionable review feedback and `retry_failed_checks` are present, prioritize review feedback first; a new commit will retrigger CI, so avoid rerunning flaky checks on the old SHA unless you intentionally defer the review change.\n10. On every loop, verify mergeability / merge-conflict status (for example via `gh pr view`) in addition to CI and review state.\n11. After any push or rerun action, immediately return to step 1 and continue polling on the updated SHA/state.\n12. If you had been using `--watch` before pausing to patch/commit/push, relaunch `--watch` yourself in the same turn immediately after the push (do not wait for the user to re-invoke the skill).\n13. Repeat polling until the PR is green + review-clean + mergeable, `stop_pr_closed` appears, or a user-help-required blocker is reached.\n14. Maintain terminal/session ownership: while babysitting is active, keep consuming watcher output in the same turn; do not leave a detached `--watch` process running and then end the turn as if monitoring were complete.\n\n## Commands\n\n### One-shot snapshot\n\n```bash\npython3 .codex/skills/babysit-pr/scripts/gh_pr_watch.py --pr auto --once\n```\n\n### Continuous watch (JSONL)\n\n```bash\npython3 .codex/skills/babysit-pr/scripts/gh_pr_watch.py --pr auto --watch\n```\n\n### Trigger flaky retry cycle (only when watcher indicates)\n\n```bash\npython3 .codex/skills/babysit-pr/scripts/gh_pr_watch.py --pr auto --retry-failed-now\n```\n\n### Explicit PR target\n\n```bash\npython3 .codex/skills/babysit-pr/scripts/gh_pr_watch.py --pr <number-or-url> --once\n```\n\n## CI Failure Classification\nUse `gh` commands to inspect failed runs before deciding to rerun.\n\n- `gh run view <run-id> --json jobs,name,workflowName,conclusion,status,url,headSha`\n- `gh run view <run-id> --log-failed`\n\nPrefer treating failures as branch-related when logs point to changed code (compile/test/lint/typecheck/snapshots/static analysis in touched areas).\n\nPrefer treating failures as flaky/unrelated when logs show transient infra/external issues (timeouts, runner provisioning failures, registry/network outages, GitHub Actions infra errors).\n\nIf classification is ambiguous, perform one manual diagnosis attempt before choosing rerun.\n\nRead `.codex/skills/babysit-pr/references/heuristics.md` for a concise checklist.\n\n## Review Comment Handling\nThe watcher surfaces review items from:\n\n- PR issue comments\n- Inline review comments\n- Review submissions (COMMENT / APPROVED / CHANGES_REQUESTED)\n\nIt intentionally surfaces Codex reviewer bot feedback (for example comments/reviews from `chatgpt-codex-connector[bot]`) in addition to human reviewer feedback. Most unrelated bot noise should still be ignored.\nFor safety, the watcher only auto-surfaces trusted human review authors (for example repo OWNER/MEMBER/COLLABORATOR, plus the authenticated operator) and approved review bots such as Codex.\nOn a fresh watcher state file, existing pending review feedback may be surfaced immediately (not only comments that arrive after monitoring starts). This is intentional so already-open review comments are not missed.\n\nWhen you agree with a comment and it is actionable:\n\n1. Patch code locally.\n2. Commit with `codex: address PR review feedback (#<n>)`.\n3. Push to the PR head branch.\n4. Resume watching on the new SHA immediately (do not stop after reporting the push).\n5. If monitoring was running in `--watch` mode, restart `--watch` immediately after the push in the same turn; do not wait for the user to ask again.\n\nIf you disagree or the comment is non-actionable/already addressed, record it as handled by continuing the watcher loop (the script de-duplicates surfaced items via state after surfacing them).\nIf a code review comment/thread is already marked as resolved in GitHub, treat it as non-actionable and safely ignore it unless new unresolved follow-up feedback appears.\n\n## Git Safety Rules\n\n- Work only on the PR head branch.\n- Avoid destructive git commands.\n- Do not switch branches unless necessary to recover context.\n- Before editing, check for unrelated uncommitted changes. If present, stop and ask the user.\n- After each successful fix, commit and `git push`, then re-run the watcher.\n- If you interrupted a live `--watch` session to make the fix, restart `--watch` immediately after the push in the same turn.\n- Do not run multiple concurrent `--watch` processes for the same PR/state file; keep one watcher session active and reuse it until it stops or you intentionally restart it.\n- A push is not a terminal outcome; continue the monitoring loop unless a strict stop condition is met.\n\nCommit message defaults:\n\n- `codex: fix CI failure on PR #<n>`\n- `codex: address PR review feedback (#<n>)`\n\n## Monitoring Loop Pattern\nUse this loop in a live Codex session:\n\n1. Run `--once`.\n2. Read `actions`.\n3. First check whether the PR is now merged or otherwise closed; if so, report that terminal state and stop polling immediately.\n4. Check CI summary, new review items, and mergeability/conflict status.\n5. Diagnose CI failures and classify branch-related vs flaky/unrelated.\n6. Process actionable review comments before flaky reruns when both are present; if a review fix requires a commit, push it and skip rerunning failed checks on the old SHA.\n7. Retry failed checks only when `retry_failed_checks` is present and you are not about to replace the current SHA with a review/CI fix commit.\n8. If you pushed a commit or triggered a rerun, report the action briefly and continue polling (do not stop).\n9. After a review-fix push, proactively restart continuous monitoring (`--watch`) in the same turn unless a strict stop condition has already been reached.\n10. If everything is passing, mergeable, not blocked on required review approval, and there are no unaddressed review items, report success and stop.\n11. If blocked on a user-help-required issue (infra outage, exhausted flaky retries, unclear reviewer request, permissions), report the blocker and stop.\n12. Otherwise sleep according to the polling cadence below and repeat.\n\nWhen the user explicitly asks to monitor/watch/babysit a PR, prefer `--watch` so polling continues autonomously in one command. Use repeated `--once` snapshots only for debugging, local testing, or when the user explicitly asks for a one-shot check.\nDo not stop to ask the user whether to continue polling; continue autonomously until a strict stop condition is met or the user explicitly interrupts.\nDo not hand control back to the user after a review-fix push just because a new SHA was created; restarting the watcher and re-entering the poll loop is part of the same babysitting task.\nIf a `--watch` process is still running and no strict stop condition has been reached, the babysitting task is still in progress; keep streaming/consuming watcher output instead of ending the turn.\n\n## Polling Cadence\nUse adaptive polling and continue monitoring even after CI turns green:\n\n- While CI is not green (pending/running/queued or failing): poll every 1 minute.\n- After CI turns green: start at every 1 minute, then back off exponentially when there is no change (for example 1m, 2m, 4m, 8m, 16m, 32m), capping at every 1 hour.\n- Reset the green-state polling interval back to 1 minute whenever anything changes (new commit/SHA, check status changes, new review comments, mergeability changes, review decision changes).\n- If CI stops being green again (new commit, rerun, or regression): return to 1-minute polling.\n- If any poll shows the PR is merged or otherwise closed: stop polling immediately and report the terminal state.\n\n## Stop Conditions (Strict)\nStop only when one of the following is true:\n\n- PR merged or closed (stop as soon as a poll/snapshot confirms this).\n- PR is ready to merge: CI succeeded, no surfaced unaddressed review comments, not blocked on required review approval, and no merge conflict risk.\n- User intervention is required and Codex cannot safely proceed alone.\n\nKeep polling when:\n\n- `actions` contains only `idle` but checks are still pending.\n- CI is still running/queued.\n- Review state is quiet but CI is not terminal.\n- CI is green but mergeability is unknown/pending.\n- CI is green and mergeable, but the PR is still open and you are waiting for possible new review comments or merge-conflict changes per the green-state cadence.\n- The PR is green but blocked on review approval (`REVIEW_REQUIRED` / similar); continue polling on the green-state cadence and surface any new review comments without asking for confirmation to keep watching.\n\n## Output Expectations\nProvide concise progress updates while monitoring and a final summary that includes:\n\n- During long unchanged monitoring periods, avoid emitting a full update on every poll; summarize only status changes plus occasional heartbeat updates.\n- Treat push confirmations, intermediate CI snapshots, and review-action updates as progress updates only; do not emit the final summary or end the babysitting session unless a strict stop condition is met.\n- A user request to \"monitor\" is not satisfied by a couple of sample polls; remain in the loop until a strict stop condition or an explicit user interruption.\n- A review-fix commit + push is not a completion event; immediately resume live monitoring (`--watch`) in the same turn and continue reporting progress updates.\n- When CI first transitions to all green for the current SHA, emit a one-time celebratory progress update (do not repeat it on every green poll). Preferred style: `🚀 CI is all green! 33/33 passed. Still on watch for review approval.`\n- Do not send the final summary while a watcher terminal is still running unless the watcher has emitted/confirmed a strict stop condition; otherwise continue with progress updates.\n\n- Final PR SHA\n- CI status summary\n- Mergeability / conflict status\n- Fixes pushed\n- Flaky retry cycles used\n- Remaining unresolved failures or review comments\n\n## References\n\n- Heuristics and decision tree: `.codex/skills/babysit-pr/references/heuristics.md`\n- GitHub CLI/API details used by the watcher: `.codex/skills/babysit-pr/references/github-api-notes.md`\n"},"lastSynced":"2026-03-06T06:28:29.369Z","agentAnalysis":{"suitability":{"en":"Perfect for GitHub Integration Agents needing automated PR management and monitoring capabilities.","zh":"适合需要自动化PR管理和监控能力的GitHub集成代理。","ja":"GitHub Integration Agentsが自動化されたPR管理と監視機能を必要とする場合に最適です。","ko":"자동화된 PR 관리 및 모니터링 기능이 필요한 GitHub 통합 에이전트에 적합합니다.","es":"Perfecto para Agentes de Integración de GitHub que necesitan capacidades de administración y monitoreo de PR automatizadas.","fr":"Parfait pour les Agents d''Intégration de GitHub nécessitant une gestion et un suivi automatiques des PR.","de":"Perfekt für GitHub-Integration-Agenten, die eine automatisierte PR-Verwaltung und Überwachungsfunktionen benötigen.","pt":"Perfeito para Agentes de Integração do GitHub que necessitam de gerenciamento e monitoramento automatizados de PR.","ru":"Идеально подходит для агентов интеграции GitHub, которым необходимы автоматизированные возможности управления и мониторинга PR.","ar":"مثالي للوكلاء المتكاملين مع GitHub الذين يحتاجون إلى إدارة ومراقبة 자동ية ل-PR."},"recommendation":{"en":"Empowers agents to persistently monitor pull requests until merge, closure, or user intervention is required, leveraging CI success checks, review comment analysis, and merge conflict detection via GitHub APIs and webhooks.","zh":"赋予代理持续监控拉取请求的能力，直到合并、关闭或需要用户干预，利用CI成功检查、审查评论分析和合并冲突检测通过GitHub APIs和Webhooks。","ja":"エージェントがマージ、クローズ、またはユーザー介入が必要になるまでプルリクエストを継続的に監視できるようにし、CIの成功チェック、レビューコメントの分析、GitHub APIおよびWebhook経由でのマージコンフリクトの検出を利用します。","ko":"에이전트가 병합, 닫기 또는 사용자 개입이 필요할 때까지 풀 요청을 지속적으로 모니터링할 수 있도록 하며, GitHub API 및 웹훅을 통해 CI 성공 체크, 리뷰 댓글 분석 및 병합 충돌 감지를 활용합니다.","es":"Habilita a los agentes a monitorear persistentemente las solicitudes de extracción hasta que se fusionen, cierren o se requiera intervención del usuario, aprovechando las comprobaciones de éxito de CI, el análisis de comentarios de revisión y la detección de conflictos de fusión a través de GitHub APIs y webhooks.","fr":"Permet aux agents de surveiller en permanence les demandes d''extraction jusqu''à ce qu''elles soient fusionnées, closes ou qu''une intervention utilisateur soit requise, en exploitant les vérifications de réussite de CI, l''analyse de commentaires de révision et la détection de conflits de fusion via les API et les webhooks de GitHub.","de":"Ermächtigt Agenten, Pull-Requests beharrlich bis zum Merge, zur Schließung oder bis eine Benutzereingriff erforderlich ist, zu überwachen, indem es CI-Erfolgskontrollen, Review-Kommentar-Analyse und Merge-Konflikt-Erkennung über GitHub-APIs und Webhooks nutzt.","pt":"Habilita os agentes a monitorar persistentemente solicitações de pull até a mesclagem, fechamento ou intervenção do usuário seja necessária, aproveitando verificações de sucesso do CI, análise de comentários de revisão e detecção de conflitos de mesclagem por meio das APIs e webhooks do GitHub.","ru":"Наделяет агентов возможностью постоянно отслеживать запросы на слияние до слияния, закрытия или необходимости вмешательства пользователя, используя проверки успешности CI, анализ комментариев к обзору и обнаружение конфликтов слияния через API и веб-хуки GitHub.","ar":"تمكّن الوكلاء من مراقبة استمرارية طلبات الدمج حتى الدمج أو الإغلاق أو مداخلة المستخدم المطلوبة، مستفيدة من فحوصات نجاح CI وتحليل تعليقات المراجعة واكتشاف تضارب الدمج عبر واجهات برمجة التطبيقات ومتصلات الويب الخاصة ب-GitHub."},"useCases":{"en":["Automating PR workflows for streamlined developer experience","Monitoring CI pipeline successes and failures for prompt intervention","Detecting and addressing potential merge conflicts before they block merges"],"zh":["自动化PR工作流以实现流畅的开发者体验","监控CI管道的成功和失败以进行及时干预","检测和解决潜在的合并冲突以避免阻塞合并"],"ja":["開発者のスムーズな体験を実現するためにPRワークフローを自動化する","タイムリーな介入のためにCIパイプラインの成功と失敗を監視する","マージをブロックするのを防ぐために潜在的なマージコンフリクトを検知して対応する"],"ko":["개발자의 원활한 경험을 위해 PR 워크플ロー 자동화","적절한 개입을 위해 CI 파이프라인 성공 및 실패 모니터링","병합을 차단하지 않도록 잠재적인 병합 충돌 감지 및 해결"],"es":["Automatizar flujos de trabajo de PR para una experiencia de desarrollador optimizada","Supervisar los éxitos y fracasos de la canalización de CI para una intervención oportuna","Detectar y abordar conflictos de fusión potenciales antes de que bloqueen las fusiones"],"fr":["Automatiser les flux de travail de PR pour une expérience de développeur optimisée","Superviser les réussites et les échecs de la canalisation de CI pour une intervention rapide","Détecter et résoudre les conflits de fusion potentiels avant qu''ils n''empêchent les fusions"],"de":["Automatisierung von PR-Workflows für eine optimierte Entwicklererfahrung","Überwachung der Erfolge und Misserfolge der CI-Pipeline für eine zeitnahe Intervention","Erkennung und Ansprechen potenzieller Merge-Konflikte, bevor sie Merges blockieren"],"pt":["Automatizar fluxos de trabalho de PR para experiência de desenvolvedor otimizada","Monitorar sucessos e falhas de pipelines de CI para intervenção imediata","Detectar e solucionar conflitos de mesclagem potenciais antes que bloqueiem as mesclagens"],"ru":["Автоматизировать рабочие процессы PR для оптимизации опыта разработчиков","Отслеживать успехи и неудачи конвейеров CI для оперативного вмешательства","Обнаруживать и решать потенциальные конфликты слияния до того, как они заблокируют слияния"],"ar":["أتمتة سير عمل PR لتحسين تجربة المطورين","مراقبة نجاحات وإخفاقات خطوط أنابيب CI للتدخل الفوري","اكتشاف ومعالجة تضارب الدمج المحتملة قبل حصولها على حجب الدمج"]},"limitations":{"en":["Requires GitHub API access and permissions","Limited to pull request management within GitHub repositories"],"zh":["需要GitHub API访问和权限","仅限于GitHub仓库内的拉取请求管理"],"ja":["GitHub APIへのアクセスと権限が必要","GitHubリポジトリ内のプルリクエスト管理に限定される"],"ko":["GitHub API 액세스 및 권한 필요","GitHub 리포지토리 내 풀 요청 관리에만 제한됨"],"es":["Requiere acceso y permisos a la API de GitHub","Limitado a la administración de solicitudes de extracción dentro de los repositorios de GitHub"],"fr":["Nécessite un accès et des autorisations à l''API de GitHub","Limité à la gestion des demandes d''extraction au sein des référentiels de GitHub"],"de":["Benötigt Zugriff und Berechtigungen auf die GitHub-API","Begrenzt auf die Verwaltung von Pull-Requests innerhalb von GitHub-Repositorys"],"pt":["Requer acesso e permissões à API do GitHub","Limitado à gestão de solicitações de pull dentro dos repositórios do GitHub"],"ru":["Требует доступа и разрешений к API GitHub","Ограничен управлением запросами на слияние внутри репозиториев GitHub"],"ar":["يتطلب الوصول والصلاحيات إلى واجهة برمجة التطبيقات الخاصة ب-GitHub","محدود بإدارة طلبات الدمج داخل مستودعات GitHub"]},"version":4},"contentHash":"165e7c05a4d5a7d1ba58afca15c3539f48b2b0cf0c3c251a0e644b2a1434ecf5","qualityScore":70}');
