INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('stellarlinkco/codex/babysit-pr', 'babysit-pr', 'stellarlinkco', 'codex', 'community', 'babysit-pr stellarlinkco codex community babysit-pr is an open-source coding agent that automates PR management, ensuring persistent monitoring until merge, closure, or user intervention is required. It benefits developers by simplifying PR workflows. babysit-pr 是一个开源的编码代理，用于自动化 PR 审核流程，确保代码质量和开发效率 babysit-pr はオープンソースのコードエージェントで、PR レビューを自動化してコード品質と開発効率を向上させる babysit-pr는 오픈소스의 코드 에이전트로 PR 리뷰를 자동화하여 코드 품질과 개발 효율성을 향상시킵니다 babysit-pr es un agente de código abierto que automatiza la revisión de código y el seguimiento de solicitudes de extracción hasta su resolución babysit-pr est un agent de codage open source qui automatise la revue de code et le suivi des demandes d''extraction jusqu''à leur résolution babysit-pr ist ein Open-Source-Coding-Agent, der die Code-Review- und Pull-Request-Verfolgung bis zur Auflösung automatisiert O babysit-pr é um agente de codificação de código aberto que automatiza o processo de PR com OpenAI. Ele persiste em babysitar um PR até que ocorra um dos resultados finais. babysit-pr - это открытый агент кодирования, который автоматизирует процесс PR с ИИ Агентами. Он постоянно следит за PR до тех пор, пока не произойдет один из конечных результатов. babysit-pr هو وسيط ترميز مفتوح المصدر يؤتمة عملية إدارة طلبات السحب مع أدوات ذكاء إصطناعي. وهو يصر على مراقبة طلب السحب حتى تحقق واحدة من النتائج النهائية. how to use babysit-pr babysit-pr alternative babysit-pr setup guide what is babysit-pr babysit-pr vs openai babysit-pr install automated pr management ci workflow optimization merge conflict resolution babysit-pr AI 代理 自动化 PR 审核 CI/CD 代码质量 开发效率 开源编码代理 Monitors PRs persistently until terminal outcomes occur Checks for successful CI, unaddressed review comments, and required review approval Detects potential merge conflicts and reports conflict risk Handles situations requiring user help, such as CI infrastructure issues Ensures PRs are mergeable and not blocked by review approvals Retries flaky failures until retry budget is exhausted babysit-pr is an open-source AI agent that automates the process of babysitting a PR until it is merged, closed, or requires user assistance.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('segmentio/action-destinations/implement-destination', 'community', 'segmentio', 'action-destinations', 'segmentio/action-destinations', 'implement-destination', 80, 305, 70, '2026-03-06T07:16:24Z', '2026-03-06T13:00:40.563Z', '4daa514558345b2aa2a87fec00168434b53108fa5671271144e53dca2f3aab0e', '{"id":"segmentio/action-destinations/implement-destination","name":"implement-destination","description":{"en":"The implement-destination skill generates complete Segment action-destination code from analysis documents and user-selected actions, benefiting developers building streaming destinations.","zh":"implement-destination技能是用于生成Segment行动目的地代码的工具，支持OpenAPI规范、网站文档和标准分析格式","ja":"implement-destinationスキルは、Segmentアクション目的地コードを生成するツールです。OpenAPI仕様、Webサイトドキュメント、標準分析形式をサポートしています","ko":"implement-destination 스킬은 Segment 액션 대상 코드를 생성하는 도구로, OpenAPI 사양, 웹 사이트 문서 및 표준 분석 형식을 지원합니다","es":"El skill implement-destination genera código de destino de acción completo en Segment a partir de documentos de análisis y acciones seleccionadas por el usuario.","fr":"Le skill implement-destination génère du code de destination d''action complet sur Segment à partir de documents d''analyse et d''actions sélectionnées par l''utilisateur.","de":"Der Skill implement-destination generiert vollständigen Aktionszielcode in Segment aus Analysedokumenten und vom Benutzer ausgewählten Aktionen.","pt":"O Implement-Destination é uma ferramenta que gera código completo para Segment a partir de documentos de análise, permitindo a criação de destinos de streaming personalizados","ru":"Implement-Destination - это инструмент, который генерирует полный код для Segment из документов анализа, позволяя создавать индивидуальные потоковые назначения","ar":"Implement-Destination هو أداة تولد كود كامل للقسم من وثائق التحليل، مما يسمح بإنشاء وجهات بث مخصصة"},"seo"