INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('segmentio/action-destinations/implement-destination', 'implement-destination', 'segmentio', 'action-destinations', 'community', 'implement-destination segmentio action-destinations community The implement-destination skill generates complete Segment action-destination code from analysis documents and user-selected actions, benefiting developers building streaming destinations. implement-destination技能是用于生成Segment行动目的地代码的工具，支持OpenAPI规范、网站文档和标准分析格式 implement-destinationスキルは、Segmentアクション目的地コードを生成するツールです。OpenAPI仕様、Webサイトドキュメント、標準分析形式をサポートしています implement-destination 스킬은 Segment 액션 대상 코드를 생성하는 도구로, OpenAPI 사양, 웹 사이트 문서 및 표준 분석 형식을 지원합니다 El skill implement-destination genera código de destino de acción completo en Segment a partir de documentos de análisis y acciones seleccionadas por el usuario. Le skill implement-destination génère du code de destination d''action complet sur Segment à partir de documents d''analyse et d''actions sélectionnées par l''utilisateur. Der Skill implement-destination generiert vollständigen Aktionszielcode in Segment aus Analysedokumenten und vom Benutzer ausgewählten Aktionen. O Implement-Destination é uma ferramenta que gera código completo para Segment a partir de documentos de análise, permitindo a criação de destinos de streaming personalizados Implement-Destination - это инструмент, который генерирует полный код для Segment из документов анализа, позволяя создавать индивидуальные потоковые назначения Implement-Destination هو أداة تولد كود كامل للقسم من وثائق التحليل، مما يسمح بإنشاء وجهات بث مخصصة how to use implement-destination implement-destination setup guide what is implement-destination implement-destination alternative implement-destination vs Segment implement-destination install OpenAPI specifications Standard Analysis Format AI工具 Segment行动目的地 代码生成器 OpenAPI规范 网站文档 标准分析格式 实现目标 代码生成 AIエージェント Generates complete Segment action-destination code from analysis documents Supports OpenAPI specifications via /openapi-analyze Analyzes website documentation via /web-analyze Works with any analysis document following the Standard Analysis Format Requires analysis documents to follow the format defined in .claude/skills/implement-destination/analysis-format.md Implement-destination is a skill that generates complete Segment action-destination code from analysis documents, supporting OpenAPI specifications and Standard Analysis Format.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('IstiN/dmtools/dmtools', 'community', 'IstiN', 'dmtools', 'IstiN/dmtools', 'dmtools', 33, 14, 70, '2026-03-02T15:56:45Z', '2026-03-06T06:38:29.345Z', '7dfffa48aa723baaec39e8c0e5c8d420555b432279a291bd9345bf607bcd5e8d', '{"id":"IstiN/dmtools/dmtools","name":"dmtools","description":{"en":"dmtools is an AI-powered development toolkit that integrates with multiple platforms, providing 96+ MCP tools for automation. It benefits developers by streamlining their workflow.","zh":"DMtools 是一个 AI 电子商务自动化工具，提供 96+ 的 MCP 工具，帮助开发者简化工作流程","ja":"DMtools は、AI エージェントによる電子商取引自動化ツールで、96 個以上の MCP ツールを提供して開発者のワークフローを簡素化","ko":"DMtools 는 AI 도구를 통한 전자상거래 자동화 도구로, 96개 이상의 MCP 도구를 제공하여 개발자의 워크플로우를 단순화합니다","es":"dmtools es un kit de herramientas de desarrollo de AI que integra con múltiples plataformas y ofrece 96+ herramientas MCP para automatización","fr":"dmtools est un kit de développement d''IA qui s''intègre à plusieurs plateformes et offre 96+ outils MCP pour l''automatisation","de":"dmtools ist ein AI-Entwicklungstoolkit, das in mehrere Plattformen integriert ist und 96+ MCP-Tools für die Automatisierung bietet","pt":"O dmtools é uma ferramenta de desenvolvimento baseada em IA que oferece integração com múltiplas plataformas e mais de 96 ferramentas de automação MCP.","ru":"dmtools - это набор инструментов разработки на основе ИИ, который предлагает интеграцию с несколькими платформами и более 96 инструментов автоматизации MCP.","ar":"dmtools هو مجموعة أدوات تطوير تعتمد على الذكاء الاصطناعي وتوفر إمكانية التكامل مع منصات متعددة وأكثر من 96 أداة تلقائية MCP."},"seo":{"title":{"en":"dmtools: Automated Setup Guide for AI Agents | AI Agent S...","zh":"DMtools 设置指南：AI 电子商务自动化工具","ja":"DMtools セットアップガイド：AI エージェントによる自動化ツール","ko":"DMtools 설정 가이드: AI 도구를 통한 자동화","es":"Guía de Configuración de dmtools: Herramientas de Gestión...","fr":"