INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('IstiN/dmtools/dmtools', 'dmtools', 'IstiN', 'dmtools', 'community', 'dmtools IstiN dmtools community dmtools is an AI-powered development toolkit that integrates with multiple platforms, providing 96+ MCP tools for automation. It benefits developers by streamlining their workflow. DMtools 是一个 AI 电子商务自动化工具，提供 96+ 的 MCP 工具，帮助开发者简化工作流程 DMtools は、AI エージェントによる電子商取引自動化ツールで、96 個以上の MCP ツールを提供して開発者のワークフローを簡素化 DMtools 는 AI 도구를 통한 전자상거래 자동화 도구로, 96개 이상의 MCP 도구를 제공하여 개발자의 워크플로우를 단순화합니다 dmtools es un kit de herramientas de desarrollo de AI que integra con múltiples plataformas y ofrece 96+ herramientas MCP para automatización dmtools est un kit de développement d''IA qui s''intègre à plusieurs plateformes et offre 96+ outils MCP pour l''automatisation dmtools ist ein AI-Entwicklungstoolkit, das in mehrere Plattformen integriert ist und 96+ MCP-Tools für die Automatisierung bietet O dmtools é uma ferramenta de desenvolvimento baseada em IA que oferece integração com múltiplas plataformas e mais de 96 ferramentas de automação MCP. dmtools - это набор инструментов разработки на основе ИИ, который предлагает интеграцию с несколькими платформами и более 96 инструментов автоматизации MCP. dmtools هو مجموعة أدوات تطوير تعتمد على الذكاء الاصطناعي وتوفر إمكانية التكامل مع منصات متعددة وأكثر من 96 أداة تلقائية MCP. how to use dmtools dmtools setup guide dmtools alternative dmtools vs other toolkits what is dmtools dmtools install dmtools automated setup dmtools MCP tools dmtools integration dmtools bash setup DMtools AI 电子商务自动化 MCP 工具 多平台集成 自动化设置 开发效率 工作流程简化 Runs automated setup helper via curl command Configures everything for first-time setup Provides 96+ MCP tools for automation Integrates with multiple platforms Supports quick automated setup Utilizes bash for setup and configuration dmtools is an AI-powered development toolkit that integrates with multiple platforms to provide automation capabilities.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('wildcard/caro/declutter', 'community', 'wildcard', 'caro', 'wildcard/caro', 'declutter', 26, 2, 70, '2026-02-08T01:22:59Z', '2026-03-06T06:39:52.376Z', '3b0c1d04b2580bababcbb9d1321d163b72dc399ea3401218853072175f444104', '{"id":"wildcard/caro/declutter","name":"declutter","description":{"en":"The declutter skill creates a clean project structure using open-source conventions and established patterns, benefiting developers with a predictable tree and clear intent.","zh":"Declutter Skill是一个基于Rust CLI的工具，用于创建干净、有序的项目结构。它支持vLLM/Ollama/LM Studio和JSON输出","ja":"Declutter SkillはRust CLIベースのツールで、クリーンで構造化されたプロジェクトを作成します。vLLM/Ollama/LM StudioとJSON出力をサポート","ko":"Declutter Skill은 Rust CLI 기반 도구로, 깨끗하고 구조화된 프로젝트를 생성합니다. vLLM/Ollama/LM Studio와 JSON 출력을 지원","es":"Declutter es una herramienta de línea de comandos de Rust que crea una estructura de proyecto organizada y segura, con soporte para vLLM y Ollama","fr":"Declutter est un outil de ligne de commande Rust qui crée une structure de projet organisée et sécurisée, avec prise en charge de vLLM et Ollama","de":"Declutter ist ein Rust-CLI-Tool, das eine organisierte und sichere Projektstruktur erstellt, mit Unterstützung für vLLM und Ollama","pt":"O Declutter é uma ferramenta CLI em Rust que ajuda a organizar projetos, transformando tarefas em comandos POSIX seguros","ru":"Declutter - это инструмент CLI на Rust, который помогает организовать проекты, преобразуя задачи в безопасные команды POSIX","ar":"Declutter هو أداة سطر أوامر الرست التي تساعد في تنظيم المشاريع، وتحول المهام إلى أوامر POSIX آمنة"},"seo":{"title":{"en":"Declutter: Setup Guide for AI Agents | Rust CLI","zh":"Declutter Setup Guide: 使用Rust CLI优化项目结构","ja":"Declutter セットアップガイド: Rust CLI でプロジェクト構造を最適化","ko":"Declutter 설정 가이드: Rust CLI로 프로젝트 구조 최적화","es":"Guía de configuración de Declutter: Organización de proye...","fr":"Guide de configuration de Declutter: Organisation de proj...","de":"Einrichtungsleitfaden für Declutter: Projektorganisation ...","pt":"Declutter: Guia de Configuração para Organização de Proje...","ru":"Declutter: Настройка для организации проектов с помощью И...","ar":"Declutter: دليل الإعداد لتنظيم المشاريع باستخدام واجهة سط..."},"description":{"en":"Discover how to use declutter, a fast Rust CLI, to turn natural-language tasks into safe POSIX commands and organize your project structure with ease. Learn ...","zh":"使用Declutter Skill创建干净、有序的项目结构，遵循开源规范和项目模式，支持vLLM/Ollama/LM Studio","ja":"Declutter Skillを使用してクリーンで構造化されたプロジェクトを作成し、オープンソースの規範とプロジェクトのパターンに従います。vLLM/Ollama/LM Studioをサポート","ko":"Declutter Skill을 사용하여 깨끗하고 구조화된 프로젝트를 생성하고, 오픈소스 규약과 프로젝트 패턴을 따릅니다. vLLM/Ollama/LM Studio 지원","es":"Descubre cómo Declutter utiliza Rust y CLI para crear una estructura de proyecto limpia y organizada, siguiendo convenciones de código abierto","fr":"Découvrez comment Declutter utilise Rust et CLI pour créer une structure de projet propre et organisée, suivant les conventions de code ouvert","de":"Erfahren Sie, wie Declutter mit Rust und CLI eine saubere und organisierte Projektstruktur erstellt, die Open-Source-Konventionen folgt","pt":"Aprenda a organizar seus projetos com o Declutter, uma ferramenta CLI em Rust que transforma tarefas em comandos POSIX seguros","ru":"Узнайте, как организовать свои проекты с помощью Declutter, инструмента CLI на Rust, который преобразует задачи в безопасные команды POSIX","ar":"تعلم كيفية تنظيم مشاريعك باستخدام Declutter، أداة سطر أوامر الرست التي تحول المهام إلى أوامر POSIX آمنة"},"definition":{"en":"Declutter is a Rust CLI that turns natural-language tasks into safe POSIX commands, built for macOS with a built-in model and JSON-only output.","zh":"Declutter Skill是一种AI工具，用于优化项目结构和组织","ja":"Declutter SkillはAIエージェントの一種で、プロジェクト構造と組織を最適化する","ko":"Declutter Skill은 프로젝트 구조와 구성 최적화를 위한 AI 도구","es":"Declutter es una herramienta de organización de proyectos que utiliza Rust y CLI para crear una estructura de proyecto limpia y segura","fr":"Declutter est un outil d''organisation de projets qui utilise Rust et CLI pour créer une structure de projet propre et sécurisée","de":"Declutter ist ein Projektorganisations-Tool, das Rust und CLI verwendet, um eine saubere und sichere Projektstruktur zu erstellen","pt":"Declutter é uma ferramenta que organiza projetos em uma estrutura limpa e previsível","ru":"Declutter - это инструмент, который организует проекты в чистую и предсказуемую структуру","ar":"Declutter هو أداة تنظم المشاريع في هيكل نظيف وقابل للتنبؤ"},"features":{"en":["Generates safe POSIX commands from natural-language tasks","Supports vLLM, Ollama, and LM Studio models","Includes a devcontainer for easy setup and development","Produces JSON-only output for easy parsing and integration","Performs safety checks and confirmation for secure command execution","Enables multi-step goals for complex task automation"],"zh":["支持vLLM/Ollama/LM Studio","JSON输出","安全检查和确认","多步骤目标支持","devcontainer包含"],"ja":["vLLM/Ollama/LM Studioをサポート","JSON出力","安全性チェックと確認","マルチステップ目標のサポート","devcontainerを含む"],"ko":["vLLM/Ollama/LM Studio 지원","JSON 출력","안전성 검사 및 확인","다단계 목표 지원","devcontainer 포함"],"es":["Soporte para vLLM y Ollama","Salida de JSON solo","Comprobaciones de seguridad","Confirmación de comandos","Compatibilidad con devcontainer"],"fr":["Prise en charge de vLLM et Ollama","Sortie JSON uniquement","Vérifications de sécurité","Confirmation de commandes","Compatibilité avec devcontainer"],"de":["Unterstützung für vLLM und Ollama","Nur JSON-Ausgabe","Sicherheitsüberprüfungen","Befehlsbestätigung","Kompatibilität mit devcontainer"],"pt":["Transforma tarefas em comandos POSIX seguros","Suporte a vLLM, Ollama e LM Studio","Saída em JSON apenas","Verificações de segurança e confirmação","Metas multi-etapa"],"ru":["Преобразует задачи в безопасные команды POSIX","Поддержка vLLM, Ollama и LM Studio","Выходные данные только в JSON","Проверки безопасности и подтверждение","Многоэтапные цели"],"ar":["تحويل المهام إلى أوامر POSIX آمنة","دعم vLLM و Ollama و LM Studio","إخراج JSON فقط","فحوصات أمان وتأكيد","أهداف متعددة المراحل"]},"keywords":{"en":["how to use declutter","declutter alternative","declutter setup guide","what is declutter","declutter vs rust cli","declutter install","rust cli for macos","posix command generator","natural language task automation"],"zh":["Declutter Skill","Rust CLI","项目结构优化","AI工具","vLLM/Ollama/LM Studio","JSON输出","安全检查","devcontainer"],"ja":["Declutter Skill","Rust CLI","プロジェクト構造最適化","AIエージェント","vLLM/Ollama/LM Studio","JSON出力","安全性チェック","devcontainer"],"ko":["Declutter Skill","Rust CLI","프로젝트 구조 최적화","AI 도구","vLLM/Ollama/LM Studio","JSON 출력","안전성 검사","devcontainer"],"es":["herramientas de organización de proyectos","Rust CLI","vLLM","Ollama","devcontainer","seguridad de proyectos","estructura de proyecto limpia"],"fr":["outils d''organisation de projets","Rust CLI","vLLM","Ollama","devcontainer","sécurité de projets","structure de projet propre"],"de":["Projektorganisations-Tools","Rust CLI","vLLM","Ollama","devcontainer","Projektsicherheit","saubere Projektstruktur"],"pt":["organização de projetos","CLI em Rust","comandos POSIX","vLLM","Ollama","LM Studio","segurança em projetos","devops"],"ru":["организация проектов","ИИ Агенты","CLI на Rust","команды POSIX","vLLM","Ollama","LM Studio","безопасность в проектах","devops"],"ar":["تنظيم المشاريع","واجهة سطر الأوامر الرست","أوامر POSIX","vLLM","Ollama","LM Studio","أمان المشاريع","devops"]}},"owner":"wildcard","repo":"caro","repoPath":"wildcard/caro","stars":26,"forks":2,"updatedAt":"2026-02-08T01:22:59Z","topics":["ai","cmd","command-line","devops","local-llm","posix","runbook","rust","unix"],"category":"community","skillMd":{"name":"declutter","description":"Identify misplaced files and organize project structure following open-source best practices, while delegating refactoring to specialized skills","version":"1.0.0","bodyPreview":"# Declutter Skill\n\n**Purpose**: Create a clean, welcoming project structure where every file has its proper place, following open-source conventions and the project''s established patterns.\n\n**Philosophy**: A well-organized project should produce a hand-sized, predictable tree that immediately communicates what the project does and how it''s structured. The root should be clean and inviting, not overwhelming.\n\n---\n\n## Core Principles\n\n### 1. Clean Root, Clear Intent\n\nThe project root is the first","body":"# Declutter Skill\n\n**Purpose**: Create a clean, welcoming project structure where every file has its proper place, following open-source conventions and the project''s established patterns.\n\n**Philosophy**: A well-organized project should produce a hand-sized, predictable tree that immediately communicates what the project does and how it''s structured. The root should be clean and inviting, not overwhelming.\n\n---\n\n## Core Principles\n\n### 1. Clean Root, Clear Intent\n\nThe project root is the first impression. It should contain only:\n- Essential entry files (README, LICENSE, main config)\n- Standard directories that communicate purpose\n- No orphaned files, experiments, or ambiguous content\n\n### 2. Correlation Preservation\n\nFiles that belong together stay together:\n- Module-related files remain in module context\n- Development stage files stay with their stage\n- App-specific files stay with their app\n- Build artifacts stay with build configuration\n\n### 3. Skill Delegation\n\nDeclutter **identifies and recommends** but does not refactor alone:\n- For code restructuring → delegate to `refactor` skill\n- For documentation moves → delegate to `technical-writer` agent\n- For build pipeline changes → delegate to `devops` skill\n- If skill doesn''t exist → recommend installation/configuration\n\n### 4. Query Before Move\n\nWhen placement is ambiguous:\n1. First, check for relevant specialized skills/agents\n2. Consult with appropriate skill for research\n3. Only ask user when no skill can help\n4. Always explain the reasoning\n\n---\n\n## When to Use This Skill\n\n**Trigger Phrases**:\n- \"Declutter this project\"\n- \"Organize the file structure\"\n- \"Clean up the root directory\"\n- \"This project is messy, help me organize it\"\n- \"Where should this file go?\"\n\n**Automatic Contexts**:\n- After initial project setup\n- Before open-sourcing a project\n- When onboarding feels overwhelming\n- After feature sprawl or rapid prototyping\n\n---\n\n## The Declutter Workflow\n\n```\nPhase 1: Assessment (Survey)\n   ↓\nPhase 2: Classification (Categorize)\n   ↓\nPhase 3: Research (Consult Skills)\n   ↓\nPhase 4: Proposal (Plan Moves)\n   ↓\nPhase 5: Execution (Delegate Actions)\n```\n\n---\n\n## Phase 1: Assessment (Survey the Landscape)\n\n**Goal**: Understand current state without judgment.\n\n### Actions:\n\n1. **Capture the current tree**:\n   ```bash\n   tree -L 2 -a --dirsfirst -I ''.git|node_modules|target|__pycache__|.venv''\n   ```\n\n2. **Identify technology stack**:\n   - Check for `package.json`, `Cargo.toml`, `pyproject.toml`, `go.mod`, etc.\n   - Note frameworks (React, Astro, Django, etc.)\n   - Identify build systems (webpack, vite, cargo, etc.)\n\n3. **Count root-level items**:\n   ```bash\n   ls -la | wc -l\n   ```\n\n   **Healthy root**: 10-20 items (dirs + essential files)\n   **Needs attention**: 20-30 items\n   **Critical**: 30+ items\n\n4. **Identify outliers**:\n   - Files that don''t match project type\n   - Duplicate or similar-named files\n   - Dated/versioned files (backup.old, file_v2.txt)\n   - Orphaned configuration files\n\n### Output:\n- [ ] Tree captured\n- [ ] Tech stack identified\n- [ ] Root item count logged\n- [ ] Outliers list created\n\n---\n\n## Phase 2: Classification (Categorize Everything)\n\n**Goal**: Assign each item to a category for action.\n\n### File Categories:\n\n| Category | Examples | Action |\n|----------|----------|--------|\n| **Essential Root** | README, LICENSE, main config | Keep in root |\n| **Documentation** | *.md guides, ADRs, specs | Move to `/docs` |\n| **Configuration** | dotfiles, *.config.js | Consider `/config` or keep root |\n| **Scripts** | Shell scripts, automation | Move to `/scripts` |\n| **DevOps** | CI/CD, Docker, k8s | Move to `.github/`, `/deploy` |\n| **Source Code** | Application code | Move to `/src`, `/lib`, `/app` |\n| **Tests** | Test files | Move to `/tests` or colocate |\n| **Build Artifacts** | Generated files | Add to `.gitignore` |\n| **Experiments** | POCs, spikes | Move to `/sandbox` or delete |\n| **Orphaned** | No clear purpose | Ask user or delete |\n\n### Classification Rules:\n\n**For Markdown Files**:\n```\nREADME.md, CONTRIBUTING.md, CHANGELOG.md → Root (OSS standard)\nCODE_OF_CONDUCT.md, SECURITY.md → Root (GitHub special files)\n*.md (other) → /docs\n```\n\n**For Configuration**:\n```\nSingle dotfile → Root acceptable\nMultiple similar configs → /config directory\nBuild tool config → Usually root (webpack.config.js, etc.)\nEditor config → Root (.editorconfig, .prettierrc)\n```\n\n**For Scripts**:\n```\n1-2 scripts → /scripts or root acceptable\n3+ scripts → Must move to /scripts\nShell scripts → /scripts\nBuild scripts → /scripts/build or npm scripts\n```\n\n### Output:\n- [ ] Each file/directory categorized\n- [ ] Action type assigned (keep/move/delete/ask)\n- [ ] Ambiguous items flagged for consultation\n\n---\n\n## Phase 3: Research (Consult Specialized Skills)\n\n**Goal**: Get expert guidance before making moves.\n\n### Skill Consultation Matrix:\n\n| Question Type | Consult |\n|--------------|---------|\n| \"Where should docs go?\" | `technical-writer` agent |\n| \"How to structure Rust project?\" | `rust-cli-architect` agent |\n| \"Best practices for this framework?\" | `Explore` agent with framework focus |\n| \"Is this safe to delete?\" | `safety-pattern-auditor` skill |\n| \"How to reorganize build pipeline?\" | `devops` skill (if exists) |\n| \"Cultural/locale files placement?\" | `multicultural-holidays` skill |\n\n### Consultation Protocol:\n\n1. **Check if skill exists**:\n   ```\n   Glob: .claude/skills/*/SKILL.md\n   ```\n\n2. **Check if agent can help**:\n   - Review Task tool agent descriptions\n   - Match to categorization need\n\n3. **If skill/agent available**:\n   ```\n   Task: [appropriate-agent]\n   Prompt: \"I''m decluttering this project and need guidance on\n   [specific question]. What''s the best practice for [specific situation]?\"\n   ```\n\n4. **If skill/agent not available**:\n   ```\n   Report to user:\n   \"I''d like to consult a [skill-type] skill for [reason], but it''s\n   not installed. Would you like to:\n   a) Configure/install the skill\n   b) Proceed with my best judgment\n   c) Skip this category for now\"\n   ```\n\n### OSS Convention Research:\n\nWhen framework-specific guidance isn''t available, research:\n- GitHub trending repos in same tech stack\n- Official framework documentation\n- Community-accepted patterns\n\nUse the `Explore` agent:\n```\nTask: Explore\nPrompt: \"Find the standard directory structure for [technology] projects.\nFocus on: root organization, docs placement, scripts location, config handling.\"\n```\n\n### Output:\n- [ ] Skills/agents consulted\n- [ ] Best practices documented\n- [ ] User decisions recorded (if any)\n\n---\n\n## Phase 4: Proposal (Create the Move Plan)\n\n**Goal**: Present a clear, actionable reorganization plan.\n\n### Proposal Format:\n\n```markdown\n## Declutter Proposal - [Project Name]\n\n### Current State\n- Root items: 42 (Critical - needs attention)\n- Tech stack: Rust CLI with Astro website\n- Primary issues: Documentation scattered, scripts mixed\n\n### Proposed Structure\n\n```\nproject-root/\n├── .claude/                 # Claude configuration (keep)\n├── .github/                 # GitHub workflows (keep)\n├── docs/                    # Documentation (create)\n│   ├── architecture/        # ADRs and design docs\n│   ├── guides/              # User guides\n│   └── api/                 # API documentation\n├── scripts/                 # Automation (organize)\n│   ├── build/               # Build scripts\n│   ├── dev/                 # Development helpers\n│   └── release/             # Release automation\n├── src/                     # Source code (keep)\n├── tests/                   # Test files (keep)\n├── website/                 # Astro site (keep)\n├── Cargo.toml               # Main config (keep)\n├── README.md                # Entry point (keep)\n├── LICENSE                  # Legal (keep)\n└── CHANGELOG.md             # History (keep)\n```\n\n### Proposed Moves\n\n| File | From | To | Reason |\n|------|------|-----|--------|\n| ARCHITECTURE.md | / | /docs/architecture/ | Standard docs location |\n| setup.sh | / | /scripts/ | OSS convention |\n| dev-notes.md | / | /docs/guides/ | Internal documentation |\n\n### Files to Delete\n| File | Reason |\n|------|--------|\n| backup.old | Obsolete backup |\n| test_experiment.rs | Superseded by /tests |\n\n### Files Requiring Decision\n| File | Options |\n|------|---------|\n| random_script.py | A) Delete B) Move to /scripts C) Keep |\n\n### Skills to Engage\n\n1. `technical-writer` - Restructure /docs hierarchy\n2. `refactor` - Update import paths after moves (NOT AVAILABLE - recommend install)\n```\n\n### Output:\n- [ ] Proposal document created\n- [ ] All moves justified\n- [ ] User decisions requested\n- [ ] Skills identified for delegation\n\n---\n\n## Phase 5: Execution (Delegate and Move)\n\n**Goal**: Execute the plan with proper delegation.\n\n### Execution Rules:\n\n1. **Never refactor code directly** - delegate to `refactor` skill\n2. **Never update imports alone** - delegate to appropriate skill\n3. **Document all moves** in commit message\n4. **Preserve git history** where possible (git mv)\n\n### Move Protocol:\n\n```bash\n# Always use git mv for tracked files\ngit mv old/path new/path\n\n# Create directories first\nmkdir -p new/directory\n\n# Batch related moves\ngit mv docs/*.md docs/guides/\n```\n\n### Post-Move Validation:\n\n1. **Check for broken links**:\n   ```bash\n   grep -rn \"old/path\" --include=\"*.md\" --include=\"*.rs\"\n   ```\n\n2. **Verify imports still work**:\n   ```bash\n   cargo check  # For Rust\n   npm run build  # For JS\n   ```\n\n3. **Update any absolute references**\n\n### Commit Strategy:\n\n```bash\n# Single logical commit for declutter\ngit add -A\ngit commit -m \"$(cat <<''EOF''\nrefactor: Declutter project structure\n\nMoves:\n- ARCHITECTURE.md → docs/architecture/\n- setup.sh → scripts/\n- dev-notes.md → docs/guides/\n\nDeletes:\n- backup.old (obsolete)\n- test_experiment.rs (superseded)\n\nCreated:\n- docs/architecture/ directory\n- scripts/build/ directory\n\nConsulted: technical-writer agent, OSS conventions\nEOF\n)\"\n```\n\n### Output:\n- [ ] All moves executed\n- [ ] Broken references fixed\n- [ ] Commit created\n- [ ] Post-move validation passed\n\n---\n\n## Mono-Repo Strategy\n\nFor mono-repos, declutter level by level:\n\n### Level 1: Root\n- Focus on top-level organization\n- Ensure clear separation between projects\n- Shared configs at root or `/config`\n\n### Level 2: Individual Projects\n- Apply same principles to each sub-project\n- Respect sub-project conventions\n- Don''t cross-contaminate\n\n### Level 3: Scripts/DevOps\n- Centralize shared scripts\n- Per-project scripts stay in project\n- CI/CD in `.github/` or `/ci`\n\n### Mono-Repo Structure Template:\n\n```\nmonorepo/\n├── .github/               # Shared CI/CD\n├── docs/                  # Shared documentation\n├── packages/              # Sub-projects\n│   ├── app-a/\n│   │   ├── src/\n│   │   ├── tests/\n│   │   └── package.json\n│   └── app-b/\n├── scripts/               # Shared automation\n├── config/                # Shared configuration\n├── package.json           # Root workspace\n└── README.md\n```\n\n---\n\n## Technology-Specific Conventions\n\n### Rust Projects\n```\nproject/\n├── src/\n│   ├── lib.rs             # Library entry\n│   └── main.rs            # Binary entry\n├── tests/                 # Integration tests\n├── benches/               # Benchmarks\n├── examples/              # Example usage\n├── Cargo.toml\n└── README.md\n```\n\n### JavaScript/Node Projects\n```\nproject/\n├── src/                   # Source code\n├── dist/                  # Build output (gitignored)\n├── tests/ or __tests__/   # Tests\n├── scripts/               # Build/dev scripts\n├── package.json\n└── README.md\n```\n\n### Python Projects\n```\nproject/\n├── src/project_name/      # Package code\n├── tests/                 # Tests\n├── docs/                  # Documentation\n├── scripts/               # Automation\n├── pyproject.toml\n└── README.md\n```\n\nSee `references/oss-conventions.md` for comprehensive patterns.\n\n---\n\n## Quick Reference Checklist\n\n```\n┌─────────────────────────────────────────────────────────┐\n│  DECLUTTER CHECKLIST                                    │\n├─────────────────────────────────────────────────────────┤\n│                                                         │\n│  Assessment:                                            │\n│  ☐ Tree captured (depth 2)                             │\n│  ☐ Tech stack identified                               │\n│  ☐ Root item count: _____ (target: <20)               │\n│  ☐ Outliers identified                                 │\n│                                                         │\n│  Classification:                                        │\n│  ☐ Each item categorized                               │\n│  ☐ Actions assigned (keep/move/delete/ask)            │\n│                                                         │\n│  Research:                                              │\n│  ☐ Relevant skills consulted                           │\n│  ☐ Missing skills reported                             │\n│  ☐ OSS conventions checked                             │\n│                                                         │\n│  Proposal:                                              │\n│  ☐ Target structure documented                         │\n│  ☐ Move plan created                                   │\n│  ☐ User decisions collected                            │\n│                                                         │\n│  Execution:                                             │\n│  ☐ Moves delegated to skills where needed              │\n│  ☐ git mv used for tracked files                       │\n│  ☐ Broken references fixed                             │\n│  ☐ Commit created with full context                    │\n│                                                         │\n└─────────────────────────────────────────────────────────┘\n```\n\n---\n\n## What Declutter Does NOT Do\n\n- **Does not refactor code** - delegates to `refactor` skill\n- **Does not update imports** - delegates to appropriate skill\n- **Does not delete without confirmation** - always asks\n- **Does not override project conventions** - respects existing patterns\n- **Does not move without explanation** - documents all decisions\n\n---\n\n## Skill Dependencies\n\n### Required:\n- None (can run standalone with manual moves)\n\n### Recommended:\n- `refactor` - For updating imports after moves\n- `technical-writer` - For documentation restructuring\n- `Explore` agent - For OSS convention research\n\n### Optional:\n- `devops` - For pipeline reorganization\n- `validate-constitution` - For checking project rules\n\n---\n\n## Example Invocation\n\nUsing the Task tool:\n\n```\nTask: general-purpose\nPrompt: \"Run the declutter skill on this project.\n\nFollow the workflow in .claude/skills/declutter/SKILL.md:\n1. Assess the current structure\n2. Classify all files/directories\n3. Consult relevant skills for guidance\n4. Create a proposal document\n5. Present it for user approval before execution\n\nFocus on making the root clean and welcoming.\nRespect existing conventions and correlations.\nDelegate refactoring to appropriate skills.\"\n```\n\n---\n\n## Success Criteria\n\nDeclutter is complete when:\n\n- ✅ Root contains ≤20 items\n- ✅ All files are in logical locations\n- ✅ Structure follows tech-stack conventions\n- ✅ Orphaned files addressed\n- ✅ Proposal approved by user\n- ✅ All moves executed or delegated\n- ✅ No broken references remain\n- ✅ Commit documents all changes\n\n---\n\n*A decluttered project is a welcoming project. Every file in its place, every place with purpose.*\n"},"lastSynced":"2026-03-06T06:39:52.376Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Refactoring Agents needing a clean and organized project structure.","zh":"非常适合需要干净和有组织的项目结构的代码重构代理。","ja":"コードリファクタリングエージェントがクリーンで整理されたプロジェクト構造を必要とする場合に最適です。","ko":"클린하고 조직화된 프로젝트 구조가 필요한 코드 리팩토링 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Refactorización de Código que necesitan una estructura de proyecto limpia y organizada.","fr":"Parfait pour les Agents de Réorganisation de Code ayant besoin d''une structure de projet propre et organisée.","de":"Perfekt für Code-Refactoring-Agents, die eine saubere und organisierte Projektstruktur benötigen.","pt":"Perfeito para agentes de Refatoração de Código que necessitam de uma estrutura de projeto limpa e organizada.","ru":"Идеально подходит для агентов рефакторинга кода, которым требуется чистая и организованная структура проекта.","ar":"مثالي لعميل إعادة هيكلة الشفرة الذي يحتاج إلى هيكل مشروع منظم ونظيف."},"recommendation":{"en":"Empowers agents to create a predictable tree structure following open-source conventions, providing clear intent and a welcoming project root, utilizing established patterns and file organization protocols.","zh":"赋予代理创建遵循开源约定的可预测树结构的能力，提供清晰的意图和欢迎的项目根目录，利用既定的模式和文件组织协议。","ja":"オープンソースの規約に従った予測可能なツリー構造を作成するエージェントをEmpowerし、明確な意図と歓迎的なプロジェクトルートを提供し、確立されたパターンとファイルの組織化プロトコルを利用します。","ko":"오픈소스 규약을 따르는 예측 가능한 트리 구조를 생성하는 에이전트를赋能하여, 명확한 의도와 환영하는 프로젝트 루트를 제공하며, 확립된 패턴과 파일 조직화 프로토콜을 활용합니다.","es":"Habilita a los agentes a crear una estructura de árbol predecible siguiendo convenciones de código abierto, proporcionando una intención clara y una raíz de proyecto acogedora, utilizando patrones establecidos y protocolos de organización de archivos.","fr":"Permet aux agents de créer une structure d''arbre prévisible en suivant les conventions de code open-source, offrant une intention claire et une racine de projet accueillante, en utilisant des modèles établis et des protocoles d''organisation de fichiers.","de":"Ermächtigt die Agents, eine vorhersehbare Baumstruktur nach Open-Source-Konventionen zu erstellen, wodurch eine klare Absicht und eine einladende Projektwurzel bereitgestellt werden, unter Verwendung etablierter Muster und Dateiorganisationsprotokolle.","pt":"Permite que os agentes criem uma estrutura de árvore previsível seguindo convenções de código aberto, fornecendo intenção clara e uma raiz de projeto acolhedora, utilizando padrões estabelecidos e protocolos de organização de arquivos.","ru":"Позволяет агентам создавать предсказуемую структуру дерева, следуя открытым конвенциям, обеспечивая четкий замысел и гостеприимный корень проекта, используя устоявшиеся закономерности и протоколы организации файлов.","ar":"يمكن للعميل إنشاء هيكل شجري قابل للتنبؤ به اتباعًا لاتفاقيات الشفرة المفتوحة، وتوفير نوايا واضحة وجذور مشروع مرحبة، باستخدام أنماط متعارف عليها وبروتوكولات تنظيم الملفات."},"useCases":{"en":["Organizing project directories","Establishing consistent naming conventions","Improving code readability through structured file placement"],"zh":["组织项目目录","建立一致的命名约定","通过结构化文件放置提高代码可读性"],"ja":["プロジェクトディレクトリの組織化","一貫した命名規約の確立","構造化されたファイル配置を通じてコードの可読性の向上"],"ko":["프로젝트 디렉토리 조직화","일관된命名 규약의 설정","구조화된 파일 배치 통해 코드 가독성 향상"],"es":["Organizar directorios de proyecto","Establecer convenciones de nomenclatura consistentes","Mejorar la legibilidad del código a través de la colocación estructurada de archivos"],"fr":["Organiser les répertoires de projet","Établir des conventions de dénomination cohérentes","Améliorer la lisibilité du code grâce à un placement structuré de fichiers"],"de":["Projektverzeichnisse organisieren","Konsistente Benennungskonventionen etablieren","Code-Lesbarkeit durch strukturierte Dateiplatzierung verbessern"],"pt":["Organizar diretórios de projeto","Estabelecer convenções de nomenclatura consistentes","Melhorar a legibilidade do código por meio da colocação estruturada de arquivos"],"ru":["Организация директорий проекта","Установление последовательных конвенций именования","Улучшение читаемости кода за счет структурированного размещения файлов"],"ar":["تنظيم دليل المشروع","إ制ام اتفاقيات تسمية متسقة","تحسين قراءة الشفرة من خلال وضع الملفات المنظّمة"]},"limitations":{"en":["Requires understanding of open-source conventions","Limited to project structure organization"],"zh":["需要了解开源约定","仅限于项目结构组织"],"ja":["オープンソース規約の理解が必要","プロジェクト構造の組織化に限定される"],"ko":["오픈소스 규약의 이해가 필요","프로젝트 구조 조직화에만 제한"],"es":["Requiere comprensión de las convenciones de código abierto","Limitado a la organización de la estructura del proyecto"],"fr":["Nécessite une compréhension des conventions de code open-source","Limité à l''organisation de la structure du projet"],"de":["Erfordert das Verständnis von Open-Source-Konventionen","Begrenzt auf die Organisation der Projektstruktur"],"pt":["Requer entendimento das convenções de código aberto","Limitado à organização da estrutura do projeto"],"ru":["Требует понимания открытых конвенций","Ограничен организацией структуры проекта"],"ar":["يتطلب فهم الاتفاقيات للشفرة المفتوحة","محدود بتنظيم هيكل المشروع"]},"version":4},"contentHash":"3b0c1d04b2580bababcbb9d1321d163b72dc399ea3401218853072175f444104","qualityScore":70}');
