INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('wildcard/caro/declutter', 'declutter', 'wildcard', 'caro', 'community', 'declutter wildcard caro community ai cmd command-line devops local-llm posix runbook rust unix The declutter skill creates a clean project structure using open-source conventions and established patterns, benefiting developers with a predictable tree and clear intent. Declutter Skill是一个基于Rust CLI的工具，用于创建干净、有序的项目结构。它支持vLLM/Ollama/LM Studio和JSON输出 Declutter SkillはRust CLIベースのツールで、クリーンで構造化されたプロジェクトを作成します。vLLM/Ollama/LM StudioとJSON出力をサポート Declutter Skill은 Rust CLI 기반 도구로, 깨끗하고 구조화된 프로젝트를 생성합니다. vLLM/Ollama/LM Studio와 JSON 출력을 지원 Declutter es una herramienta de línea de comandos de Rust que crea una estructura de proyecto organizada y segura, con soporte para vLLM y Ollama Declutter est un outil de ligne de commande Rust qui crée une structure de projet organisée et sécurisée, avec prise en charge de vLLM et Ollama Declutter ist ein Rust-CLI-Tool, das eine organisierte und sichere Projektstruktur erstellt, mit Unterstützung für vLLM und Ollama O Declutter é uma ferramenta CLI em Rust que ajuda a organizar projetos, transformando tarefas em comandos POSIX seguros Declutter - это инструмент CLI на Rust, который помогает организовать проекты, преобразуя задачи в безопасные команды POSIX Declutter هو أداة سطر أوامر الرست التي تساعد في تنظيم المشاريع، وتحول المهام إلى أوامر POSIX آمنة how to use declutter declutter alternative declutter setup guide what is declutter declutter vs rust cli declutter install rust cli for macos posix command generator natural language task automation Declutter Skill Rust CLI 项目结构优化 AI工具 vLLM/Ollama/LM Studio JSON输出 安全检查 devcontainer Generates safe POSIX commands from natural-language tasks Supports vLLM, Ollama, and LM Studio models Includes a devcontainer for easy setup and development Produces JSON-only output for easy parsing and integration Performs safety checks and confirmation for secure command execution Enables multi-step goals for complex task automation Declutter is a Rust CLI that turns natural-language tasks into safe POSIX commands, built for macOS with a built-in model and JSON-only output.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ihmorol/unsw-nb15-handling-binary-multiclass-ids/convex-component-authoring', 'community', 'ihmorol', 'unsw-nb15-handling-binary-multiclass-ids', 'ihmorol/unsw-nb15-handling-binary-multiclass-ids', 'convex-component-authoring', 1, 0, 70, '2026-02-28T10:16:01Z', '2026-03-06T13:08:45.480Z', '561346aded0969635fc3f32ae6d465f882266b6be20b4038c7a55645ff6db7c2', '{"id":"ihmorol/unsw-nb15-handling-binary-multiclass-ids/convex-component-authoring","name":"convex-component-authoring","description":{"en":"Convex-component-authoring enables developers to create reusable Convex components for class-imbalanced intrusion detection, comparing techniques like SMOTE and class weighting.","zh":"Convex 组件创建是开发可重用的 Convex 组件的过程，通过正确的隔离、导出和依赖管理","ja":"Convex コンポーネントの作成は、再利用可能な Convex コンポーネントを開発するプロセスです","ko":"Convex 컴포넌트 작성은 재사용 가능한 Convex 컴포넌트를 개발하는 과정입니다","es":"La habilidad convex-component-authoring permite la creación de componentes Convex reutilizables con aislamiento, exportación y gestión de dependencias adecuados.","fr":"La compétence convex-component-authoring permet la création de composants Convex réutilisables avec une isolation, une exportation et une gestion des dépendances appropriées.","de":"Die Fähigkeit convex-component-authoring ermöglicht die Erstellung wiederverwendbarer Convex-Komponenten mit geeigneter Isolation, Export und Abhängigkeitsverwaltung.","pt":"O Convex Component Authoring permite criar componentes reutilizáveis com isolamento adequado, exportações e gerenciamento de dependências","ru":"Convex Component Authoring позволяет создавать自одостаточные компоненты с правильной изоляцией, экспортами и управлением зависимостями","ar":"يسمح Convex Component Authoring بإنشاء مكونات قابلة لإعادة الاستخدام مع عزل مناسب وتصدير وإدارة التبعيات"},"seo":{"title":{"en":"Convex-Component-Authoring: Setup Guide for AI Agents","zh":"Convex 组件创建最佳实践","ja":"Convex コンポーネントの作成ガイド - AIエージェント","ko":"Convex 컴포넌트 작성 가이드 - AI 도구","es":"Guía de configuración para convex-component-authoring: Cr...","fr":"Guide de mise en place pour convex-component-authoring: C...","de":"Einrichtungsleitfaden für convex-component-authoring: Ers...","pt":"Guia de Configuração do Convex Component Authoring","ru":"ИИ Агенты: Руководство по настройке Convex Component Auth...","ar":"دليل إعداد Convex Component Authoring للأدوات الذكية"},"description":{"en":"Unlock the full potential of convex-component-authoring with our expert guide. Learn how to create self-contained components with proper isolation and exports.","zh":"学习如何创建自包含、可重用的 Convex 组件，了解 Convex 组件的创建和依赖管理","ja":"Convex コンポーネントの作成方法を学び、プロジェクト間での共有を実現する - AIエージェント","ko":"Convex 컴포넌트 작성 방법을 배우고 프로젝트 간에 공유하는 방법을 알아보세요 - AI 도구","es":"Aprende a crear componentes Convex reutilizables con la habilidad convex-component-authoring. Mejora tus proyectos con componentes aislados y bien documentados.","fr":"Découvrez comment créer des composants Convex réutilisables avec la compétence convex-component-authoring. Améliorez vos projets avec des composants isolés e...","de":"Erfahren Sie, wie Sie wiederverwendbare Convex-Komponenten mit der Fähigkeit convex-component-authoring erstellen. Verbessern Sie Ihre Projekte mit isolierte...","pt":"Aprenda a criar componentes Convex reutilizáveis com isolamento adequado, exportações e gerenciamento de dependências para compartilhar em projetos","ru":"Создавайте自одостаточные компоненты Convex с правильной изоляцией, экспортами и управлением зависимостями для обмена между проектами","ar":"تعلم كيفية إنشاء مكونات Convex قابلة لإعادة الاستخدام مع عزل مناسب وتصدير وإدارة التبعيات للمشاركة عبر المشاريع"},"definition":{"en":"Convex-component-authoring is a technique for creating self-contained, reusable Convex components with proper isolation, exports, and dependency management.","zh":"Convex 组件创建是指创建自包含、可重用的 Convex 组件","ja":"Convex コンポーネントの作成とは、再利用可能な Convex コンポーネントを作成すること","ko":"Convex 컴포넌트 작성은 재사용 가능한 Convex 컴포넌트를 생성하는 것을 의미합니다","es":"Convex-component-authoring es una habilidad que permite crear componentes reutilizables y aislados para proyectos Convex.","fr":"Convex-component-authoring est une compétence qui permet de créer des composants réutilisables et isolés pour les projets Convex.","de":"Convex-component-authoring ist eine Fähigkeit, die die Erstellung wiederverwendbarer und isolierter Komponenten für Convex-Projekte ermöglicht.","pt":"O Convex Component Authoring é uma técnica para criar componentes reutilizáveis com isolamento adequado","ru":"Convex Component Authoring - это техника для создания自одостаточных компонентов с правильной изоляцией","ar":"Convex Component Authoring هو تقنية لإنشاء مكونات قابلة لإعادة الاستخدام مع عزل مناسب"},"features":{"en":["Creates self-contained Convex components with proper isolation and exports","Supports class-imbalanced intrusion detection on UNSW-NB15 dataset","Compares techniques like no balancing, class weighting, and SMOTE","Evaluates performance using macro-F1, ROC-AUC, G-Mean, and per-class metrics","Follows documentation guidelines from https://docs.convex.dev/components"],"zh":["创建自包含、可重用的 Convex 组件","正确的隔离、导出和依赖管理","支持多种指标，包括 macro-F1、ROC-AUC、G-Mean 和 per-class metrics","可用于类不平衡的入侵检测","支持 SMOTE 和类权重"],"ja":["再利用可能な Convex コンポーネントの作成","適切な隔離、エクスポート、依存関係管理","マクロ F1、ROC-AUC、G-Mean、クラスごとのメトリクスなどの複数のメトリクスのサポート","クラス不均衡の侵入検出に使用可能","SMOTE とクラス重みのサポート"],"ko":["재사용 가능한 Convex 컴포넌트 생성","적절한 격리, 내보내기, 의존성 관리","매크로 F1, ROC-AUC, G-Mean, 클래스별 메트릭스 등의 여러 메트릭스 지원","클래스 불균형의 침입 탐지에 사용 가능","SMOTE 및 클래스 가중치 지원"],"es":["Creación de componentes reutilizables con aislamiento y exportación adecuados","Gestión de dependencias para proyectos Convex","Documentación y recursos para la creación de componentes","Compatibilidad con la documentación oficial de Convex","Soporte para la creación de componentes con macro-F1, ROC-AUC y G-Mean"],"fr":["Création de composants réutilisables avec une isolation et une exportation appropriées","Gestion des dépendances pour les projets Convex","Documentation et ressources pour la création de composants","Compatibilité avec la documentation officielle de Convex","Prise en charge de la création de composants avec macro-F1, ROC-AUC et G-Mean"],"de":["Erstellung wiederverwendbarer Komponenten mit geeigneter Isolation und Export","Abhängigkeitsverwaltung für Convex-Projekte","Dokumentation und Ressourcen für die Erstellung von Komponenten","Kompatibilität mit der offiziellen Convex-Dokumentation","Unterstützung für die Erstellung von Komponenten mit macro-F1, ROC-AUC und G-Mean"],"pt":["Criação de componentes reutilizáveis com isolamento adequado","Exportações e gerenciamento de dependências","Compartilhamento de componentes entre projetos","Utilização de macro-F1, ROC-AUC, G-Mean e métricas por classe","Comparação de técnicas de balanceamento de classes, incluindo SMOTE"],"ru":["Создание自одостаточных компонентов с правильной изоляцией","Экспорт и управление зависимостями","Обмен компонентами между проектами","Использование макро-F1, ROC-AUC, G-Mean и метрик по классам","Сравнение техник балансировки классов, включая SMOTE"],"ar":["إنشاء مكونات قابلة لإعادة الاستخدام مع عزل مناسب","تصدير وإدارة التبعيات","مشاركة المكونات بين المشاريع","استخدام макرو-F1، ROC-AUC، G-Mean وقياسات الفئة","مقارنة تقنيات توازن الفئات، بما في ذلك SMOTE"]},"keywords":{"en":["convex-component-authoring setup guide","how to use convex-component-authoring","convex-component-authoring vs traditional ML","convex-component-authoring install","class-imbalanced intrusion detection techniques","UNSW-NB15 dataset tutorial","what is convex-component-authoring","convex-component-authoring alternative","convex-component-authoring documentation"],"zh":["Convex 组件创建","Convex 组件开发","可重用的 Convex 组件","Convex 依赖管理","类不平衡的入侵检测","SMOTE","类权重","Convex 文档"],"ja":["Convex コンポーネントの作成","Convex コンポーネントの開発","再利用可能な Convex コンポーネント","Convex 依存関係管理","クラス不均衡の侵入検出","SMOTE","クラス重み","Convex ドキュメント","AIエージェント"],"ko":["Convex 컴포넌트 작성","Convex 컴포넌트 개발","재사용 가능한 Convex 컴포넌트","Convex 의존성 관리","클래스 불균형의 침입 탐지","SMOTE","클래스 가중치","Convex 문서","AI 도구"],"es":["convex-component-authoring","componentes reutilizables","Convex","documentación oficial","macro-F1","ROC-AUC","G-Mean","Herramientas de AI","Agentes de inteligencia artificial"],"fr":["convex-component-authoring","composants réutilisables","Convex","documentation officielle","macro-F1","ROC-AUC","G-Mean","Outils d''IA","Agents d''intelligence artificielle"],"de":["convex-component-authoring","wiederverwendbare Komponenten","Convex","offizielle Dokumentation","macro-F1","ROC-AUC","G-Mean","KI-Tools","Künstliche Intelligenz Agenten"],"pt":["Convex Component Authoring","componentes reutilizáveis","isolamento adequado","exportações","gerenciamento de dependências","macro-F1","ROC-AUC","G-Mean","métricas por classe","balanceamento de classes","SMOTE"],"ru":["Convex Component Authoring","ИИ Агенты","создание自одостаточных компонентов","правильная изоляция","экспорт","управление зависимостями","макро-F1","ROC-AUC","G-Mean","метрики по классам","балансировка классов","SMOTE"],"ar":["Convex Component Authoring","أدوات ذكية","إنشاء مكونات قابلة لإعادة الاستخدام","عزل مناسب","تصدير","إدارة التبعيات","مакرو-F1","ROC-AUC","G-Mean","قياسات الفئة","توازن الفئات","SMOTE"]}},"owner":"ihmorol","repo":"unsw-nb15-handling-binary-multiclass-ids","repoPath":"ihmorol/unsw-nb15-handling-binary-multiclass-ids","stars":1,"forks":0,"updatedAt":"2026-02-28T10:16:01Z","topics":[],"category":"community","skillMd":{"name":"convex-component-authoring","description":"How to create, structure, and publish self-contained Convex components with proper isolation, exports, and dependency management","version":"1.0.0","tags":["convex","components","reusable","packages","npm"],"bodyPreview":"# Convex Component Authoring\n\nCreate self-contained, reusable Convex components with proper isolation, exports, and dependency management for sharing across projects.\n\n## Documentation Sources\n\nBefore implementing, do not assume; fetch the latest documentation:\n\n- Primary: https://docs.convex.dev/components\n- Component Authoring: https://docs.convex.dev/components/authoring\n- For broader context: https://docs.convex.dev/llms.txt\n\n## Instructions\n\n### What Are Convex Components?\n\nConvex component","body":"# Convex Component Authoring\n\nCreate self-contained, reusable Convex components with proper isolation, exports, and dependency management for sharing across projects.\n\n## Documentation Sources\n\nBefore implementing, do not assume; fetch the latest documentation:\n\n- Primary: https://docs.convex.dev/components\n- Component Authoring: https://docs.convex.dev/components/authoring\n- For broader context: https://docs.convex.dev/llms.txt\n\n## Instructions\n\n### What Are Convex Components?\n\nConvex components are self-contained packages that include:\n- Database tables (isolated from the main app)\n- Functions (queries, mutations, actions)\n- TypeScript types and validators\n- Optional frontend hooks\n\n### Component Structure\n\n```\nmy-convex-component/\n├── package.json\n├── tsconfig.json\n├── README.md\n├── src/\n│   ├── index.ts           # Main exports\n│   ├── component.ts       # Component definition\n│   ├── schema.ts          # Component schema\n│   └── functions/\n│       ├── queries.ts\n│       ├── mutations.ts\n│       └── actions.ts\n└── convex.config.ts       # Component configuration\n```\n\n### Creating a Component\n\n#### 1. Component Configuration\n\n```typescript\n// convex.config.ts\nimport { defineComponent } from \"convex/server\";\n\nexport default defineComponent(\"myComponent\");\n```\n\n#### 2. Component Schema\n\n```typescript\n// src/schema.ts\nimport { defineSchema, defineTable } from \"convex/server\";\nimport { v } from \"convex/values\";\n\nexport default defineSchema({\n  // Tables are isolated to this component\n  items: defineTable({\n    name: v.string(),\n    data: v.any(),\n    createdAt: v.number(),\n  }).index(\"by_name\", [\"name\"]),\n  \n  config: defineTable({\n    key: v.string(),\n    value: v.any(),\n  }).index(\"by_key\", [\"key\"]),\n});\n```\n\n#### 3. Component Definition\n\n```typescript\n// src/component.ts\nimport { defineComponent, ComponentDefinition } from \"convex/server\";\nimport schema from \"./schema\";\nimport * as queries from \"./functions/queries\";\nimport * as mutations from \"./functions/mutations\";\n\nconst component = defineComponent(\"myComponent\", {\n  schema,\n  functions: {\n    ...queries,\n    ...mutations,\n  },\n});\n\nexport default component;\n```\n\n#### 4. Component Functions\n\n```typescript\n// src/functions/queries.ts\nimport { query } from \"../_generated/server\";\nimport { v } from \"convex/values\";\n\nexport const list = query({\n  args: {\n    limit: v.optional(v.number()),\n  },\n  returns: v.array(v.object({\n    _id: v.id(\"items\"),\n    name: v.string(),\n    data: v.any(),\n    createdAt: v.number(),\n  })),\n  handler: async (ctx, args) => {\n    return await ctx.db\n      .query(\"items\")\n      .order(\"desc\")\n      .take(args.limit ?? 10);\n  },\n});\n\nexport const get = query({\n  args: { name: v.string() },\n  returns: v.union(v.object({\n    _id: v.id(\"items\"),\n    name: v.string(),\n    data: v.any(),\n  }), v.null()),\n  handler: async (ctx, args) => {\n    return await ctx.db\n      .query(\"items\")\n      .withIndex(\"by_name\", (q) => q.eq(\"name\", args.name))\n      .unique();\n  },\n});\n```\n\n```typescript\n// src/functions/mutations.ts\nimport { mutation } from \"../_generated/server\";\nimport { v } from \"convex/values\";\n\nexport const create = mutation({\n  args: {\n    name: v.string(),\n    data: v.any(),\n  },\n  returns: v.id(\"items\"),\n  handler: async (ctx, args) => {\n    return await ctx.db.insert(\"items\", {\n      name: args.name,\n      data: args.data,\n      createdAt: Date.now(),\n    });\n  },\n});\n\nexport const update = mutation({\n  args: {\n    id: v.id(\"items\"),\n    data: v.any(),\n  },\n  returns: v.null(),\n  handler: async (ctx, args) => {\n    await ctx.db.patch(args.id, { data: args.data });\n    return null;\n  },\n});\n\nexport const remove = mutation({\n  args: { id: v.id(\"items\") },\n  returns: v.null(),\n  handler: async (ctx, args) => {\n    await ctx.db.delete(args.id);\n    return null;\n  },\n});\n```\n\n#### 5. Main Exports\n\n```typescript\n// src/index.ts\nexport { default as component } from \"./component\";\nexport * from \"./functions/queries\";\nexport * from \"./functions/mutations\";\n\n// Export types for consumers\nexport type { Id } from \"./_generated/dataModel\";\n```\n\n### Using a Component\n\n```typescript\n// In the consuming app''s convex/convex.config.ts\nimport { defineApp } from \"convex/server\";\nimport myComponent from \"my-convex-component\";\n\nconst app = defineApp();\n\napp.use(myComponent, { name: \"myComponent\" });\n\nexport default app;\n```\n\n```typescript\n// In the consuming app''s code\nimport { useQuery, useMutation } from \"convex/react\";\nimport { api } from \"../convex/_generated/api\";\n\nfunction MyApp() {\n  // Access component functions through the app''s API\n  const items = useQuery(api.myComponent.list, { limit: 10 });\n  const createItem = useMutation(api.myComponent.create);\n  \n  return (\n    <div>\n      {items?.map((item) => (\n        <div key={item._id}>{item.name}</div>\n      ))}\n      <button onClick={() => createItem({ name: \"New\", data: {} })}>\n        Add Item\n      </button>\n    </div>\n  );\n}\n```\n\n### Component Configuration Options\n\n```typescript\n// convex/convex.config.ts\nimport { defineApp } from \"convex/server\";\nimport myComponent from \"my-convex-component\";\n\nconst app = defineApp();\n\n// Basic usage\napp.use(myComponent);\n\n// With custom name\napp.use(myComponent, { name: \"customName\" });\n\n// Multiple instances\napp.use(myComponent, { name: \"instance1\" });\napp.use(myComponent, { name: \"instance2\" });\n\nexport default app;\n```\n\n### Providing Component Hooks\n\n```typescript\n// src/hooks.ts\nimport { useQuery, useMutation } from \"convex/react\";\nimport { FunctionReference } from \"convex/server\";\n\n// Type-safe hooks for component consumers\nexport function useMyComponent(api: {\n  list: FunctionReference<\"query\">;\n  create: FunctionReference<\"mutation\">;\n}) {\n  const items = useQuery(api.list, {});\n  const createItem = useMutation(api.create);\n  \n  return {\n    items,\n    createItem,\n    isLoading: items === undefined,\n  };\n}\n```\n\n### Publishing a Component\n\n#### package.json\n\n```json\n{\n  \"name\": \"my-convex-component\",\n  \"version\": \"1.0.0\",\n  \"description\": \"A reusable Convex component\",\n  \"main\": \"dist/index.js\",\n  \"types\": \"dist/index.d.ts\",\n  \"files\": [\n    \"dist\",\n    \"convex.config.ts\"\n  ],\n  \"scripts\": {\n    \"build\": \"tsc\",\n    \"prepublishOnly\": \"npm run build\"\n  },\n  \"peerDependencies\": {\n    \"convex\": \"^1.0.0\"\n  },\n  \"devDependencies\": {\n    \"convex\": \"^1.17.0\",\n    \"typescript\": \"^5.0.0\"\n  },\n  \"keywords\": [\n    \"convex\",\n    \"component\"\n  ]\n}\n```\n\n#### tsconfig.json\n\n```json\n{\n  \"compilerOptions\": {\n    \"target\": \"ES2020\",\n    \"module\": \"ESNext\",\n    \"moduleResolution\": \"bundler\",\n    \"declaration\": true,\n    \"outDir\": \"dist\",\n    \"strict\": true,\n    \"esModuleInterop\": true,\n    \"skipLibCheck\": true\n  },\n  \"include\": [\"src/**/*\"],\n  \"exclude\": [\"node_modules\", \"dist\"]\n}\n```\n\n## Examples\n\n### Rate Limiter Component\n\n```typescript\n// rate-limiter/src/schema.ts\nimport { defineSchema, defineTable } from \"convex/server\";\nimport { v } from \"convex/values\";\n\nexport default defineSchema({\n  requests: defineTable({\n    key: v.string(),\n    timestamp: v.number(),\n  })\n    .index(\"by_key\", [\"key\"])\n    .index(\"by_key_and_time\", [\"key\", \"timestamp\"]),\n});\n```\n\n```typescript\n// rate-limiter/src/functions/mutations.ts\nimport { mutation } from \"../_generated/server\";\nimport { v } from \"convex/values\";\n\nexport const checkLimit = mutation({\n  args: {\n    key: v.string(),\n    limit: v.number(),\n    windowMs: v.number(),\n  },\n  returns: v.object({\n    allowed: v.boolean(),\n    remaining: v.number(),\n    resetAt: v.number(),\n  }),\n  handler: async (ctx, args) => {\n    const now = Date.now();\n    const windowStart = now - args.windowMs;\n    \n    // Clean old entries\n    const oldEntries = await ctx.db\n      .query(\"requests\")\n      .withIndex(\"by_key_and_time\", (q) => \n        q.eq(\"key\", args.key).lt(\"timestamp\", windowStart)\n      )\n      .collect();\n    \n    for (const entry of oldEntries) {\n      await ctx.db.delete(entry._id);\n    }\n    \n    // Count current window\n    const currentRequests = await ctx.db\n      .query(\"requests\")\n      .withIndex(\"by_key\", (q) => q.eq(\"key\", args.key))\n      .collect();\n    \n    const remaining = Math.max(0, args.limit - currentRequests.length);\n    const allowed = remaining > 0;\n    \n    if (allowed) {\n      await ctx.db.insert(\"requests\", {\n        key: args.key,\n        timestamp: now,\n      });\n    }\n    \n    const oldestRequest = currentRequests[0];\n    const resetAt = oldestRequest \n      ? oldestRequest.timestamp + args.windowMs \n      : now + args.windowMs;\n    \n    return { allowed, remaining: remaining - (allowed ? 1 : 0), resetAt };\n  },\n});\n```\n\n```typescript\n// Usage in consuming app\nimport { useMutation } from \"convex/react\";\nimport { api } from \"../convex/_generated/api\";\n\nfunction useRateLimitedAction() {\n  const checkLimit = useMutation(api.rateLimiter.checkLimit);\n  \n  return async (action: () => Promise<void>) => {\n    const result = await checkLimit({\n      key: \"user-action\",\n      limit: 10,\n      windowMs: 60000,\n    });\n    \n    if (!result.allowed) {\n      throw new Error(`Rate limited. Try again at ${new Date(result.resetAt)}`);\n    }\n    \n    await action();\n  };\n}\n```\n\n## Best Practices\n\n- Never run `npx convex deploy` unless explicitly instructed\n- Never run any git commands unless explicitly instructed\n- Keep component tables isolated (don''t reference main app tables)\n- Export clear TypeScript types for consumers\n- Document all public functions and their arguments\n- Use semantic versioning for component releases\n- Include comprehensive README with examples\n- Test components in isolation before publishing\n\n## Common Pitfalls\n\n1. **Cross-referencing tables** - Component tables should be self-contained\n2. **Missing type exports** - Export all necessary types\n3. **Hardcoded configuration** - Use component options for customization\n4. **No versioning** - Follow semantic versioning\n5. **Poor documentation** - Document all public APIs\n\n## References\n\n- Convex Documentation: https://docs.convex.dev/\n- Convex LLMs.txt: https://docs.convex.dev/llms.txt\n- Components: https://docs.convex.dev/components\n- Component Authoring: https://docs.convex.dev/components/authoring\n"},"lastSynced":"2026-03-06T13:08:45.480Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents specializing in backend development and database optimization for class-imbalanced intrusion detection systems.","zh":"适合专门从事后端开发和针对类不平衡入侵检测系统的数据库优化的AI代理。","ja":"バックエンド開発とクラス不均衡な侵入検出システムのデータベース最適化を専門とするAIエージェントに最適です。","ko":"백엔드 개발 및 클래스 불균형 침입 감지 시스템의 데이터베이스 최적화를 전문으로 하는 AI 에이전트에 적합합니다.","es":"Ideal para agentes de IA que se especializan en desarrollo de backend y optimización de bases de datos para sistemas de detección de intrusiones con clases desequilibradas.","fr":"Idéal pour les agents IA spécialisés dans le développement backend et l''optimisation de bases de données pour les systèmes de détection d''intrusion à classes déséquilibrées.","de":"Ideal für KI-Agents, die sich auf die Entwicklung von Backends und die Optimierung von Datenbanken für Systeme zur Erkennung von Eindringversuchen mit unbalancierten Klassen spezialisieren.","pt":"Ideal para agentes de IA especializados em desenvolvimento backend e otimização de banco de dados para sistemas de detecção de intrusão com classes desequilibradas.","ru":"Идеально подходит для агентов ИИ, специализирующихся на разработке backend и оптимизации баз данных для систем обнаружения вторжений с несбалансированными классами.","ar":"مثالي للوكلاء الذكية المتخصصة في تطوير الخلفية وتحسين قواعد البيانات لأنظمة الكشف عن الغزوات ذات الفئات غير المتوازنة."},"recommendation":{"en":"Enables agents to create reusable Convex components with proper isolation and dependency management, specifically comparing techniques like SMOTE and class weighting for intrusion detection. Provides structured component authoring capabilities for sharing across multiple projects.","zh":"使代理能够创建具有适当隔离和依赖管理的可重用Convex组件，特别是比较SMOTE和类权重等技术以进行入侵检测。提供结构化组件创作能力以便在多个项目之间共享。","ja":"エージェントが適切な分離と依存関係管理を備えた再利用可能なConvexコンポーネントを作成できるようにし、侵入検出のためにSMOTEやクラス重み付けなどの技術を比較します。複数のプロジェクトで共有するための構造化コンポーネントの作成機能を提供します。","ko":"에이전트가 적절한 분리 및 의존성 관리를 갖춘 재사용 가능한 Convex 컴포넌트를 생성할 수 있도록 하며, 침입 감지를 위해 SMOTE 및 클래스 가중치와 같은 기술을 비교합니다. 여러 프로젝트에서 공유할 수 있는 구조화된 컴포넌트 작성 기능을 제공합니다.","es":"Permite a los agentes crear componentes reutilizables de Convex con aislamiento y gestión de dependencias adecuados, comparando específicamente técnicas como SMOTE y ponderación de clases para la detección de intrusiones. Proporciona capacidades de creación de componentes estructurados para compartir entre múltiples proyectos.","fr":"Permet aux agents de créer des composants Convex réutilisables avec une isolation et une gestion des dépendances appropriées, en comparant spécifiquement des techniques comme SMOTE et le poids des classes pour la détection d''intrusion. Fournit des capacités de création de composants structurés pour les partager entre plusieurs projets.","de":"Ermöglicht es Agents, wiederverwendbare Convex-Komponenten mit ordnungsgemäßer Isolation und Abhängigkeitsverwaltung zu erstellen, indem speziell Techniken wie SMOTE und Klassen-Gewichtung für die Erkennung von Eindringversuchen verglichen werden. Bietet strukturierte Komponenten-Erstellungsfunktionen zum Teilen zwischen mehreren Projekten.","pt":"Permite que os agentes criem componentes Convex reutilizáveis com isolamento e gerenciamento de dependências adequados, comparando especificamente técnicas como SMOTE e ponderação de classes para detecção de intrusão. Fornece capacidades de autorização de componentes estruturados para compartilhamento em vários projetos.","ru":"Позволяет агентам создавать многократно используемые компоненты Convex с правильной изоляцией и управлением зависимостями, сравнивая специально такие методы, как SMOTE и взвешивание классов для обнаружения вторжений. Предоставляет структурированные возможности создания компонентов для обмена между несколькими проектами.","ar":"يمكن للوكلاء إنشاء مكونات Convex قابلة لإعادة الاستخدام مع العزل والإدارة المناسبة لل依赖ات، ومقارنة تقنيات محددة مثل SMOTE ووزن الفئات للكشف عن الغزوات. يوفر khảيات مؤلفة للمكونات الهيكلية لمشاركتها عبر مشاريع متعددة."},"useCases":{"en":["Creating reusable intrusion detection components","Comparing SMOTE vs class weighting techniques","Managing Convex component dependencies","Sharing components across multiple security projects"],"zh":["创建可重用入侵检测组件","比较SMOTE与类权重技术","管理Convex组件依赖","跨多个安全项目共享组件"],"ja":["再利用可能な侵入検出コンポーネントの作成","SMOTEとクラス重み付け技術の比較","Convexコンポーネントの依存関係の管理","複数のセキュリティプロジェクトでコンポーネントを共有"],"ko":["재사용 가능한 침입 감지 컴포넌트 생성","SMOTE 및 클래스 가중치 기술 비교","Convex 컴포넌트 종속성 관리","여러 보안 프로젝트에서 컴포넌트 공유"],"es":["Creación de componentes de detección de intrusiones reutilizables","Comparación de técnicas SMOTE frente a ponderación de clases","Gestión de dependencias de componentes Convex","Compartir componentes en varios proyectos de seguridad"],"fr":["Création de composants de détection d''intrusion réutilisables","Comparaison des techniques SMOTE et de pondération de classes","Gestion des dépendances de composants Convex","Partage de composants entre plusieurs projets de sécurité"],"de":["Erstellung wiederverwendbarer Komponenten zur Erkennung von Eindringversuchen","Vergleich von SMOTE- und Klassen-Gewichtungstechniken","Verwaltung von Abhängigkeiten von Convex-Komponenten","Teilen von Komponenten zwischen mehreren Sicherheitsprojekten"],"pt":["Criação de componentes de detecção de intrusão reutilizáveis","Comparação de técnicas SMOTE vs ponderação de classes","Gerenciamento de dependências de componentes Convex","Compartilhamento de componentes em vários projetos de segurança"],"ru":["Создание многократно используемых компонентов обнаружения вторжений","Сравнение методов SMOTE и взвешивания классов","Управление зависимостями компонентов Convex","Обмен компонентами между несколькими проектами безопасности"],"ar":["إنشاء مكونات الكشف عن الغزوات قابلة لإعادة الاستخدام","مقارنة تقنيات SMOTE ووزن الفئات","إدارة зависимости مكونات Convex","مشاركة المكونات عبر مشاريع أمنية متعددة"]},"limitations":{"en":["Requires Convex platform knowledge","Limited to class-imbalanced intrusion detection use cases","Needs latest Convex documentation access"],"zh":["需要Convex平台知识","仅限于类不平衡入侵检测用例","需要访问最新的Convex文档"],"ja":["Convexプラットフォームの知識が必要","クラス不均衡な侵入検出用ケースに限定","最新のConvexドキュメントへのアクセスが必要"],"ko":["Convex 플랫폼 지식이 필요","클래스 불균형 침입 감지 사용 사례에만 제한","최신 Convex 문서에 액세스해야 함"],"es":["Requiere conocimiento de la plataforma Convex","Limitado a casos de uso de detección de intrusiones con clases desequilibradas","Necesita acceso a la documentación más reciente de Convex"],"fr":["Nécessite des connaissances sur la plateforme Convex","Limité aux cas d''utilisation de la détection d''intrusion à classes déséquilibrées","Nécessite un accès à la documentation la plus récente de Convex"],"de":["Benötigt Kenntnisse der Convex-Plattform","Begrenzt auf Anwendungsfälle zur Erkennung von Eindringversuchen mit unbalancierten Klassen","Benötigt Zugriff auf die aktuellste Convex-Dokumentation"],"pt":["Exige conhecimento da plataforma Convex","Limitado a casos de uso de detecção de intrusão com classes desequilibradas","Necessita acesso à documentação mais recente do Convex"],"ru":["Требует знания платформы Convex","Ограничен для случаев использования обнаружения вторжений с несбалансированными классами","Требует доступа к последней документации Convex"],"ar":["يتطلب معرفة منصة Convex","محدود لاستخدامات الكشف عن الغزوات ذات الفئات غير المتوازنة","يحتاج إلى وصول إلى آخر وثائق Convex"]},"version":4},"contentHash":"561346aded0969635fc3f32ae6d465f882266b6be20b4038c7a55645ff6db7c2","qualityScore":70}');
