INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ihmorol/unsw-nb15-handling-binary-multiclass-ids/convex-component-authoring', 'convex-component-authoring', 'ihmorol', 'unsw-nb15-handling-binary-multiclass-ids', 'community', 'convex-component-authoring ihmorol unsw-nb15-handling-binary-multiclass-ids community Convex-component-authoring enables developers to create reusable Convex components for class-imbalanced intrusion detection, comparing techniques like SMOTE and class weighting. Convex 组件创建是开发可重用的 Convex 组件的过程，通过正确的隔离、导出和依赖管理 Convex コンポーネントの作成は、再利用可能な Convex コンポーネントを開発するプロセスです Convex 컴포넌트 작성은 재사용 가능한 Convex 컴포넌트를 개발하는 과정입니다 La habilidad convex-component-authoring permite la creación de componentes Convex reutilizables con aislamiento, exportación y gestión de dependencias adecuados. La compétence convex-component-authoring permet la création de composants Convex réutilisables avec une isolation, une exportation et une gestion des dépendances appropriées. Die Fähigkeit convex-component-authoring ermöglicht die Erstellung wiederverwendbarer Convex-Komponenten mit geeigneter Isolation, Export und Abhängigkeitsverwaltung. O Convex Component Authoring permite criar componentes reutilizáveis com isolamento adequado, exportações e gerenciamento de dependências Convex Component Authoring позволяет создавать自одостаточные компоненты с правильной изоляцией, экспортами и управлением зависимостями يسمح Convex Component Authoring بإنشاء مكونات قابلة لإعادة الاستخدام مع عزل مناسب وتصدير وإدارة التبعيات convex-component-authoring setup guide how to use convex-component-authoring convex-component-authoring vs traditional ML convex-component-authoring install class-imbalanced intrusion detection techniques UNSW-NB15 dataset tutorial what is convex-component-authoring convex-component-authoring alternative convex-component-authoring documentation Convex 组件创建 Convex 组件开发 可重用的 Convex 组件 Convex 依赖管理 类不平衡的入侵检测 SMOTE 类权重 Convex 文档 Creates self-contained Convex components with proper isolation and exports Supports class-imbalanced intrusion detection on UNSW-NB15 dataset Compares techniques like no balancing, class weighting, and SMOTE Evaluates performance using macro-F1, ROC-AUC, G-Mean, and per-class metrics Follows documentation guidelines from https://docs.convex.dev/components Convex-component-authoring is a technique for creating self-contained, reusable Convex components with proper isolation, exports, and dependency management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('GAURAVSVNIT/Genesis/azure-diagrams', 'community', 'GAURAVSVNIT', 'Genesis', 'GAURAVSVNIT/Genesis', 'azure-diagrams', 1, 0, 70, '2026-02-25T21:16:48Z', '2026-03-06T07:15:44.178Z', '7a2a9640b208428d82d03e5ab5929f26919f68b11996b73fd9c9b5a3b39058b8', '{"id":"GAURAVSVNIT/Genesis/azure-diagrams","name":"azure-diagrams","description":{"en":"The azure-diagrams skill generates architecture diagrams for Azure infrastructure from ARM templates, Azure CLI output, or natural language descriptions, benefiting developers and architects.","zh":"Azure Diagram Generator 是一种生成 Azure 基础设施图表的工具，支持 ARM 模板、Azure CLI 输出和自然语言描述","ja":"Azure Diagram Generator は、ARM テンプレート、Azure CLI 出力、または自然言語の説明から Azure インフラストラクチャの図を生成するツール","ko":"Azure Diagram Generator는 ARM 템플릿, Azure CLI 출력 또는 자연어 설명에서 Azure 인프라의 다이어그램을 생성하는 도구","es":"Azure-diagrams genera diagramas de arquitectura de Azure a partir de plantillas ARM, salida de Azure CLI o descripciones en lenguaje natural. Ideal para visualizar recursos de Azure.","fr":"Azure-diagrams génère des diagrammes d''architecture Azure à partir de modèles ARM, de sortie Azure CLI ou de descriptions en langage naturel. Idéal pour visualiser les ressources Azure.","de":"Azure-diagrams generiert Architekturdiagramme für Azure aus ARM-Vorlagen, Azure-CLI-Ausgabe oder natürlichen Sprachbeschreibungen. Ideal für die Visualisierung von Azure-Ressourcen.","pt":"O Azure Diagrams gera diagramas de arquitetura de infraestrutura Azure a partir de modelos ARM, saída do Azure CLI ou descrições em linguagem natural","ru":"Azure Diagrams генерирует диаграммы архитектуры инфраструктуры Azure из шаблонов ARM, вывода Azure CLI или естественных языковых описаний","ar":"أداة диаграмات Azure تنجز مخططات بنية تحتية Azure من قوالب ARM أو مخرجات Azure CLI أو описات لغة طبيعية"},"seo":{"title":{"en":"azure-diagrams: Architecture Diagram Generation for Azure...","zh":"Azure Diagram Generator 设置指南 - 自动生成 Azure 基础设施图表","ja":"Azure Diagram Generator のベストプラクティス - Azure エージェントを使用してインフ...","ko":"Azure Diagram Generator 설정 가이드 - Azure 인프라를 위한 자동 다이어그램 생성","es":"Guía de configuración de azure-diagrams para arquitectura...","fr":"Configurer azure-diagrams pour les architectures Azure - ...","de":"Einrichtungsleitfaden für azure-diagrams in Azure-Infrast...","pt":"Guia de Configuração do Azure Diagrams: Gerador de Diagra...","ru":"Настройка Azure Diagrams: Генератор диаграмм инфраструкту...","ar":"دليل إعداد диагรมات Azure: أداة إنشاء مخططات البنية التحت..."},"description":{"en":"Discover how to visualize Azure resources with azure-diagrams. Learn to generate architecture diagrams from ARM templates, Azure CLI output, and more. Get st...","zh":"使用 Azure Diagram Generator 自动生成 Azure 基础设施图表，支持 ARM 模板、Azure CLI 输出和自然语言描述","ja":"Azure Diagram Generator を使用して Azure インフラストラクチャを視覚化し、効率的な設計と管理を実現","ko":"Azure Diagram Generator를 사용하여 Azure 인프라를 자동으로 다이어그램화하고, 효율적인 설계와 관리를 실현","es":"Aprende a generar diagramas de arquitectura de Azure con azure-diagrams a partir de plantillas ARM, salida de Azure CLI o descripciones en lenguaje natural","fr":"Découvrez comment générer des diagrammes d''architecture Azure avec azure-diagrams à partir de modèles ARM, de sortie Azure CLI ou de descriptions en langage ...","de":"Erfahren Sie, wie Sie mit azure-diagrams Architekturdiagramme für Azure aus ARM-Vorlagen, Azure-CLI-Ausgabe oder natürlichen Sprachbeschreibungen generieren","pt":"Aprenda a usar o Azure Diagrams para gerar diagramas de arquitetura de infraestrutura Azure a partir de modelos ARM, saída do Azure CLI ou descrições em ling...","ru":"Узнайте, как использовать Azure Diagrams для генерации диаграмм архитектуры инфраструктуры Azure из шаблонов ARM, вывода Azure CLI или естественных языковых ...","ar":"تعرف على كيفية استخدام أداة диагرمات Azure لإنشاء مخططات بنية تحتية Azure من قوالب ARM أو مخرجات Azure CLI أو описات لغة طبيعية مع أداة الوكلاء الذكاء الاصطناعي"},"definition":{"en":"azure-diagrams is a skill that generates visual representations of Azure infrastructure, supporting ARM templates, Azure CLI output, and natural language descriptions.","zh":"Azure Diagram Generator 是一种用于生成 Azure 基础设施图表的 AI 工具","ja":"Azure Diagram Generator は、Azure インフラストラクチャの図を生成する AI エージェント","ko":"Azure Diagram Generator는 Azure 인프라의 다이어그램을 생성하는 AI 도구","es":"Azure-diagrams es una herramienta de inteligencia artificial que genera diagramas de arquitectura de Azure","fr":"Azure-diagrams est un outil d''intelligence artificielle qui génère des diagrammes d''architecture Azure","de":"Azure-diagrams ist ein KI-Tool, das Architekturdiagramme für Azure generiert","pt":"O que é Azure Diagrams? É uma ferramenta que gera diagramas de arquitetura de infraestrutura Azure","ru":"Что такое Azure Diagrams? Это инструмент, генерирующий диаграммы архитектуры инфраструктуры Azure","ar":"ما هي أداة диагرمات Azure? هي أداة تنجز مخططات بنية تحتية Azure"},"features":{"en":["Generates architecture diagrams from ARM templates (JSON)","Supports Azure CLI output, such as `az vm list`","Visualizes Azure resources, including Virtual Machines and Storage Accounts","Creates diagrams from natural language descriptions","Activates when users mention Azure services, like VNets"],"zh":["支持 ARM 模板（JSON）","支持 Azure CLI 输出（例如 `az vm list`）","支持自然语言描述","可视化 Azure 资源","支持 Azure 服务（虚拟机、存储账户、VNet 等）"],"ja":["ARM テンプレート（JSON）をサポート","Azure CLI 出力（例：`az vm list`）をサポート","自然言語の説明をサポート","Azure リソースを視覚化","Azure サービス（仮想マシン、ストレージ アカウント、VNet など）をサポート"],"ko":["ARM 템플릿（JSON） 지원","Azure CLI 출력（예：`az vm list`） 지원","자연어 설명 지원","Azure 리소스 시각화","Azure 서비스（가상 머신, 저장소 계정, VNet 등） 지원"],"es":["Generación de diagramas de arquitectura de Azure a partir de plantillas ARM","Soporte para salida de Azure CLI","Compatibilidad con descripciones en lenguaje natural","Visualización de recursos de Azure como máquinas virtuales y cuentas de almacenamiento","Generación de diagramas a partir de comandos de Azure CLI como ''az vm list''","Integración con servicios de Azure como Virtual Machines, Storage Accounts y VNets"],"fr":["Génération de diagrammes d''architecture Azure à partir de modèles ARM","Prise en charge de la sortie Azure CLI","Compatibilité avec les descriptions en langage naturel","Visualisation des ressources Azure telles que les machines virtuelles et les comptes de stockage","Génération de diagrammes à partir de commandes Azure CLI comme ''az vm list''","Intégration avec les services Azure tels que Virtual Machines, Storage Accounts et VNets"],"de":["Generierung von Architekturdiagrammen für Azure aus ARM-Vorlagen","Unterstützung für Azure-CLI-Ausgabe","Kompatibilität mit natürlichen Sprachbeschreibungen","Visualisierung von Azure-Ressourcen wie virtuellen Maschinen und Speicherkonten","Generierung von Diagrammen aus Azure-CLI-Befehlen wie ''az vm list''","Integration mit Azure-Diensten wie Virtual Machines, Storage Accounts und VNets"],"pt":["Geração de diagramas de arquitetura de infraestrutura Azure a partir de modelos ARM","Suporte à saída do Azure CLI","Geração de diagramas a partir de descrições em linguagem natural","Visualização de recursos Azure","Suporte a serviços Azure, como Máquinas Virtuais, Contas de Armazenamento e VNets"],"ru":["Генерация диаграмм архитектуры инфраструктуры Azure из шаблонов ARM","Поддержка вывода Azure CLI","Генерация диаграмм из естественных языковых описаний","Визуализация ресурсов Azure","Поддержка сервисов Azure, таких как Виртуальные Машины, Учетные записи хранения и VNets"],"ar":["إنشاء مخططات بنية تحتية Azure من قوالب ARM","دعم مخرجات Azure CLI","إنشاء مخططات منوصات لغة طبيعية","تصوير الموارد Azure","دعم خدمات Azure، مثل الماكينات الافتراضية و حسابات التخزين و VNets"]},"keywords":{"en":["how to use azure-diagrams","azure-diagrams setup guide","azure-diagrams alternative","azure-diagrams vs Lucidchart","generate azure architecture diagram","visualize azure infrastructure","azure-diagrams install","azure-diagrams tutorial"],"zh":["Azure Diagram Generator","ARM 模板","Azure CLI","自然语言描述","Azure 资源","Azure 服务","AI 工具","Azure 基础设施图表"],"ja":["Azure Diagram Generator","ARM テンプレート","Azure CLI","自然言語の説明","Azure リソース","Azure サービス","AI エージェント","Azure インフラストラクチャの図"],"ko":["Azure Diagram Generator","ARM 템플릿","Azure CLI","자연어 설명","Azure 리소스","Azure 서비스","AI 도구","Azure 인프라 다이어그램"],"es":["azure-diagrams","herramientas de inteligencia artificial para Azure","generación de diagramas de arquitectura de Azure","plantillas ARM","Azure CLI","descripciones en lenguaje natural","visualización de recursos de Azure","máquinas virtuales Azure","cuentas de almacenamiento Azure"],"fr":["azure-diagrams","outils d''intelligence artificielle pour Azure","génération de diagrammes d''architecture Azure","modèles ARM","Azure CLI","descriptions en langage naturel","visualisation des ressources Azure","machines virtuelles Azure","comptes de stockage Azure"],"de":["azure-diagrams","KI-Tools für Azure","Generierung von Architekturdiagrammen für Azure","ARM-Vorlagen","Azure-CLI","natürliche Sprachbeschreibungen","Visualisierung von Azure-Ressourcen","virtuelle Maschinen Azure","Speicherkonten Azure"],"pt":["Azure Diagrams","Gerador de diagramas de infraestrutura","Modelos ARM","Azure CLI","Descrições em linguagem natural","Recursos Azure","Serviços Azure"],"ru":["Azure Diagrams","Генератор диаграмм инфраструктуры","Шаблоны ARM","Azure CLI","Естественные языковые описания","Ресурсы Azure","Сервисы Azure","ИИ Агенты"],"ar":["أداة диаграмات Azure","أداة إنشاء مخططات البنية التحتية","قوالب ARM","Azure CLI","وصفات لغة طبيعية","الموارد Azure","خدمات Azure","الوكلاء الذكاء الاصطناعي"]}},"owner":"GAURAVSVNIT","repo":"Genesis","repoPath":"GAURAVSVNIT/Genesis","stars":1,"forks":0,"updatedAt":"2026-02-25T21:16:48Z","topics":[],"category":"community","skillMd":{"name":"azure-diagrams","description":"Visualizes Azure infrastructure from ARM templates, Azure CLI, or descriptions. Use when user has Azure resources to diagram.","version":"1.0.0","tags":"azure, diagram, arm, resource-group, vnet, vm, storage, infrastructure","bodyPreview":"# Azure Diagram Generator\n\nGenerates architecture diagrams for Azure infrastructure from ARM templates, Azure CLI output, or natural language descriptions.\n\n## When to Use\n\nActivate this skill when:\n\n- User has ARM (Azure Resource Manager) templates (JSON)\n- User provides Azure CLI output (e.g., `az vm list`)\n- User wants to visualize Azure resources\n- User mentions Azure services (Virtual Machines, Storage Accounts, VNets, etc.)\n- User asks to \"diagram my Azure infrastructure\"\n\n## How It Works","body":"# Azure Diagram Generator\n\nGenerates architecture diagrams for Azure infrastructure from ARM templates, Azure CLI output, or natural language descriptions.\n\n## When to Use\n\nActivate this skill when:\n\n- User has ARM (Azure Resource Manager) templates (JSON)\n- User provides Azure CLI output (e.g., `az vm list`)\n- User wants to visualize Azure resources\n- User mentions Azure services (Virtual Machines, Storage Accounts, VNets, etc.)\n- User asks to \"diagram my Azure infrastructure\"\n\n## How It Works\n\nThis skill generates Azure-specific diagrams by parsing Azure resources and calling the Eraser API directly:\n\n1. **Parse Azure Resources**: Extract resources from ARM templates, CLI output, or descriptions\n2. **Map Azure Relationships**: Identify Resource Groups, VNets, subnets, and service connections\n3. **Generate Eraser DSL**: Create Eraser DSL code from Azure resources\n4. **Call Eraser API**: Use `/api/render/elements` with `diagramType: \"cloud-architecture-diagram\"`\n\n## Instructions\n\nWhen the user provides Azure infrastructure information:\n\n1. **Parse the Source**\n\n   - **ARM Templates**: Extract `resources` array, identify types (Microsoft.Compute/virtualMachines, etc.)\n   - **CLI Output**: Parse JSON output from `az` commands\n   - **Description**: Identify Azure service names and relationships\n\n2. **Identify Azure Components**\n\n   - **Networking**: Virtual Networks (VNets), Subnets, Network Security Groups, Load Balancers\n   - **Compute**: Virtual Machines, Virtual Machine Scale Sets, App Services, Functions\n   - **Storage**: Storage Accounts, Blob Storage, File Shares\n   - **Databases**: SQL Databases, Cosmos DB, Redis Cache\n   - **Security**: Network Security Groups, Azure AD, Key Vault\n   - **Load Balancing**: Application Gateway, Load Balancer, Traffic Manager\n   - **Other**: Service Bus, Event Hubs, API Management\n\n3. **Map Relationships**\n\n   - VMs in subnets\n   - Subnets in VNets\n   - VNets in Resource Groups\n   - Storage accounts accessed by VMs\n   - Databases accessed by applications\n   - Network Security Groups attached to subnets\n\n4. **Generate Eraser DSL** Convert Azure resources to Eraser DSL:\n\n   - **CRITICAL: Label Formatting Rules**\n     - Labels MUST be on a single line - NEVER use newlines inside label attributes\n     - Keep labels simple and readable - prefer separate labels over concatenating too much metadata\n     - Format DSL with proper line breaks (one node/group per line, but labels stay on single lines)\n     - If including metadata like CIDR blocks or instance types, include them in the same quoted label string: `[label: \"VNet 10.0.0.0/16\"]`\n\n   Example:\n\n   ```\n   myVNet [label: \"VNet 10.0.0.0/16\"] {\n     subnet1 [label: \"Subnet 1\"] {\n       myVM [icon: azure-vm, label: \"Virtual Machine\"]\n       gateway [icon: azure-app-gateway]\n     }\n     subnet2 [label: \"Subnet 2\"] {\n       database [icon: azure-sql]\n     }\n   }\n   storage [icon: azure-storage]\n   myVNet -> myVM\n   myVM -> database\n   ```\n\n5. **Make the HTTP Request**\n\n   **IMPORTANT**: You MUST execute this curl command after generating the DSL. Never stop after generating DSL without making the API call.\n\n   **CRITICAL**: In the `X-Skill-Source` header below, you MUST replace the value with your AI agent name:\n   - If you are Claude (Anthropic), use: `claude`\n   - If you are running in Cursor, use: `cursor`\n   - If you are ChatGPT (OpenAI), use: `chatgpt`\n   - If you are Gemini (Google), use: `gemini`\n   - Otherwise, use your model/agent name in lowercase\n\n   ```bash\n   curl -X POST https://app.eraser.io/api/render/elements \\\n     -H \"Content-Type: application/json\" \\\n     -H \"X-Skill-Source: eraser-skill\" \\\n     -H \"Authorization: Bearer ${ERASER_API_KEY}\" \\\n     -d ''{\n       \"elements\": [{\n         \"type\": \"diagram\",\n         \"id\": \"diagram-1\",\n         \"code\": \"<your generated DSL>\",\n         \"diagramType\": \"cloud-architecture-diagram\"\n       }],\n       \"scale\": 2,\n       \"theme\": \"${ERASER_THEME:-dark}\",\n       \"background\": true\n     }''\n   ```\n\n6. **Track Sources During Analysis**\n\n   As you analyze files and resources to generate the diagram, track:\n\n   - **Internal files**: Record each file path you read and what information was extracted (e.g., `infra/main.bicep` - VNet and subnet definitions)\n   - **External references**: Note any documentation, examples, or URLs consulted (e.g., Azure architecture best practices documentation)\n   - **Annotations**: For each source, note what it contributed to the diagram\n\n7. **Handle the Response**\n\n   **CRITICAL: Minimal Output Format**\n\n   Your response MUST always include these elements with clear headers:\n\n   1. **Diagram Preview**: Display with a header\n      ```\n      ## Diagram\n      ![{Title}]({imageUrl})\n      ```\n      Use the ACTUAL `imageUrl` from the API response.\n\n   2. **Editor Link**: Display with a header\n      ```\n      ## Open in Eraser\n      [Edit this diagram in the Eraser editor]({createEraserFileUrl})\n      ```\n      Use the ACTUAL URL from the API response.\n\n   3. **Sources section**: Brief list of files/resources analyzed (if applicable)\n      ```\n      ## Sources\n      - `path/to/file` - What was extracted\n      ```\n\n   4. **Diagram Code section**: The Eraser DSL in a code block with `eraser` language tag\n      ```\n      ## Diagram Code\n      ```eraser\n      {DSL code here}\n      ```\n      ```\n\n   5. **Learn More link**: `You can learn more about Eraser at https://docs.eraser.io/docs/using-ai-agent-integrations`\n\n   **Additional content rules:**\n   - If the user ONLY asked for a diagram, include NOTHING beyond the 5 elements above\n   - If the user explicitly asked for more (e.g., \"explain the architecture\", \"suggest improvements\"), you may include that additional content\n   - Never add unrequested sections like Overview, Security Considerations, Testing, etc.\n\n   The default output should be SHORT. The diagram image speaks for itself.\n\n## Azure-Specific Tips\n\n- **Resource Groups**: Show Resource Groups as logical containers\n- **VNets as Containers**: Always show VNets containing subnets and resources\n- **Network Security Groups**: Include NSG rules and attachments\n- **Subscriptions**: Note subscription context if provided\n- **Data Flow**: Show traffic flow (Internet → Application Gateway → VM → SQL Database)\n- **Use Azure Icons**: Request Azure-specific styling in the description\n\n## Example: ARM Template with Multiple Azure Services\n\n### User Input\n\n```json\n{\n  \"resources\": [\n    {\n      \"type\": \"Microsoft.Resources/resourceGroups\",\n      \"name\": \"rg-main\"\n    },\n    {\n      \"type\": \"Microsoft.Network/virtualNetworks\",\n      \"name\": \"myVNet\",\n      \"properties\": {\n        \"addressSpace\": {\n          \"addressPrefixes\": [\"10.0.0.0/16\"]\n        },\n        \"subnets\": [\n          {\n            \"name\": \"subnet1\",\n            \"properties\": {\n              \"addressPrefix\": \"10.0.1.0/24\"\n            }\n          }\n        ]\n      }\n    },\n    {\n      \"type\": \"Microsoft.Compute/virtualMachines\",\n      \"name\": \"myVM\",\n      \"properties\": {\n        \"hardwareProfile\": {\n          \"vmSize\": \"Standard_B1s\"\n        }\n      }\n    },\n    {\n      \"type\": \"Microsoft.Web/sites\",\n      \"name\": \"myAppService\",\n      \"properties\": {\n        \"serverFarmId\": \"/subscriptions/.../serverfarms/myPlan\"\n      }\n    },\n    {\n      \"type\": \"Microsoft.Storage/storageAccounts\",\n      \"name\": \"mystorageaccount\"\n    },\n    {\n      \"type\": \"Microsoft.Sql/servers\",\n      \"name\": \"mysqlserver\",\n      \"properties\": {\n        \"administratorLogin\": \"admin\"\n      }\n    }\n  ]\n}\n```\n\n### Expected Behavior\n\n1. Parses ARM template:\n\n   - **Resource Group**: rg-main (container)\n   - **Networking**: VNet with subnet\n   - **Compute**: VM, App Service\n   - **Storage**: Storage Account\n   - **Database**: SQL Server\n\n2. Generates DSL showing Azure service diversity:\n\n   ```\n   resource-group [label: \"Resource Group rg-main\"] {\n     myVNet [label: \"VNet 10.0.0.0/16\"] {\n       subnet1 [label: \"Subnet 1 10.0.1.0/24\"] {\n         myVM [icon: azure-vm, label: \"VM Standard_B1s\"]\n       }\n     }\n     myAppService [icon: azure-app-service, label: \"App Service\"]\n     mystorageaccount [icon: azure-storage, label: \"Storage Account\"]\n     mysqlserver [icon: azure-sql, label: \"SQL Server\"]\n   }\n\n   myAppService -> mystorageaccount\n   myVM -> mysqlserver\n   ```\n\n   **Important**: All label text must be on a single line within quotes. Azure-specific: Show Resource Groups as containers, include App Services, Storage Accounts, and SQL databases with proper Azure icons.\n\n3. Calls `/api/render/elements` with `diagramType: \"cloud-architecture-diagram\"`\n\n## Example: Azure CLI Output\n\n### User Input\n\n```\nUser runs: az vm list --output json\nProvides JSON output\n```\n\n### Expected Behavior\n\n1. Parses JSON to extract:\n\n   - VM names, sizes, states\n   - Resource groups\n   - Network interfaces\n   - Storage accounts\n\n2. Formats and calls API\n"},"lastSynced":"2026-03-06T07:15:44.178Z","agentAnalysis":{"suitability":{"en":"Perfect for Cloud Architecture Agents needing advanced Azure infrastructure visualization capabilities from ARM templates or Azure CLI output.","zh":"非常适合需要高级 Azure 基础设施可视化功能的 Cloud Architecture Agents，从 ARM 模板或 Azure CLI 输出中获取。","ja":"Azure インフラストラクチャの高度な可視化機能が必要な Cloud Architecture エージェントに最適です。ARM テンプレートまたは Azure CLI 出力を使用します。","ko":"고급 Azure 인프라 시각화를 위한 기능이 필요한 Cloud Architecture 에이전트에게 적합합니다. ARM 템플릿 또는 Azure CLI 출력에서 가져옵니다.","es":"Perfecto para agentes de Arquitectura en la Nube que necesitan capacidades avanzadas de visualización de infraestructura de Azure a partir de plantillas de ARM o salida de Azure CLI.","fr":"Parfait pour les agents d''architecture cloud nécessitant des fonctionnalités avancées de visualisation d''infrastructure Azure à partir de modèles ARM ou de sortie Azure CLI.","de":"Perfekt für Cloud-Architektur-Agenten, die erweiterte Azure-Infrastruktur-Visualisierungsfunktionen aus ARM-Vorlagen oder Azure-CLI-Ausgaben benötigen.","pt":"Perfeito para Agentes de Arquitetura de Nuvem que necessitam de capacidades avançadas de visualização de infraestrutura do Azure a partir de modelos do ARM ou saída do Azure CLI.","ru":"Идеально подходит для агентов облачной архитектуры, которым необходимы расширенные возможности визуализации инфраструктуры Azure из шаблонов ARM или вывода Azure CLI.","ar":"مثالي لعمليات وكيلات هندسة السحابة التي تحتاج إلى إمكانيات متقدمة لتصور بنية تحتية Azure من قوالب ARM أو إخراج Azure CLI."},"recommendation":{"en":"Empowers agents to generate comprehensive architecture diagrams for Azure infrastructure using ARM templates, Azure CLI output, or natural language descriptions, supporting formats like JSON and leveraging Azure services such as Virtual Machines, Storage Accounts, and VNets.","zh":"赋予代理生成 Azure 基础设施的综合体系结构图，使用 ARM 模板、Azure CLI 输出或自然语言描述，支持 JSON 等格式，并利用 Azure 服务，如 Virtual Machines、Storage Accounts 和 VNets。","ja":"エージェントが ARM テンプレート、Azure CLI 出力、または自然言語の説明を使用して Azure インフラストラクチャの包括的なアーキテクチャ図を生成できるようにします。JSON などの形式をサポートし、Virtual Machines、Storage Accounts、VNets などの Azure サービスを利用します。","ko":"에이전트가 ARM 템플릿, Azure CLI 출력 또는 자연어 설명을 사용하여 Azure 인프라의 포괄적인 아키텍처 다이어그램을 생성하도록 합니다. JSON과 같은 형식을 지원하며 Virtual Machines, Storage Accounts, VNets 등의 Azure 서비스를 활용합니다.","es":"Habilita a los agentes a generar diagramas de arquitectura completos para la infraestructura de Azure utilizando plantillas de ARM, salida de Azure CLI o descripciones de lenguaje natural, admitiendo formatos como JSON y aprovechando los servicios de Azure como Máquinas Virtuales, Cuentas de Almacenamiento y VNets.","fr":"Permet aux agents de générer des diagrammes d''architecture complets pour l''infrastructure Azure en utilisant des modèles ARM, une sortie Azure CLI ou des descriptions de langage naturel, en prenant en charge des formats tels que JSON et en exploitant les services Azure tels que les Machines Virtuelles, les Comptes de Stockage et les VNets.","de":"Ermächtigt Agenten, umfassende Architekturdiagramme für die Azure-Infrastruktur zu erstellen, indem sie ARM-Vorlagen, Azure-CLI-Ausgaben oder natürliche Sprachbeschreibungen verwenden, und unterstützt Formate wie JSON und nutzt Azure-Dienste wie Virtuelle Maschinen, Speicherkonten und VNets.","pt":"Habilita os agentes a gerar diagramas de arquitetura abrangentes para a infraestrutura do Azure usando modelos do ARM, saída do Azure CLI ou descrições em linguagem natural, suportando formatos como JSON e aproveitando os serviços do Azure, como Máquinas Virtuais, Contas de Armazenamento e VNets.","ru":"Позволяет агентам генерировать полные диаграммы архитектуры для инфраструктуры Azure с использованием шаблонов ARM, вывода Azure CLI или естественных языковых описаний, поддерживая форматы, такие как JSON, и используя сервисы Azure, такие как Виртуальные Машины, Учетные записи хранения и VNets.","ar":"تمكّن الوكيلات من توليد رسوم بيانية شاملة لهندسة بنية تحتية Azure باستخدام قوالب ARM أو إخراج Azure CLI أو описات لغة طبيعية، ودعم صيغ مثل JSON واستغلال خدمات Azure مثل أجهزة افتراضية و حسابات تخزين و VNets."},"useCases":{"en":["Visualizing Azure resource configurations from ARM templates","Generating diagrams from Azure CLI output for easier infrastructure understanding","Creating architecture diagrams from natural language descriptions of Azure services"],"zh":["从 ARM 模板中可视化 Azure 资源配置","从 Azure CLI 输出中生成图表以更容易地理解基础设施","从 Azure 服务的自然语言描述中创建体系结构图"],"ja":["ARM テンプレートから Azure リソース構成を視覚化する","Azure CLI 出力から図を生成してインフラストラクチャをより簡単に理解する","Azure サービスの自然言語の説明からアーキテクチャ図を生成する"],"ko":["ARM 템플릿에서 Azure 리소스 구성 시각화","Azure CLI 출력에서 다이어그램 생성하여 인프라를 더 쉽게理解","Azure 서비스의 자연어 설명에서 아키텍처 다이어그램 생성"],"es":["Visualizar configuraciones de recursos de Azure a partir de plantillas de ARM","Generar diagramas a partir de la salida de Azure CLI para una mejor comprensión de la infraestructura","Crear diagramas de arquitectura a partir de descripciones de lenguaje natural de servicios de Azure"],"fr":["Visualiser les configurations de ressources Azure à partir de modèles ARM","Générer des diagrammes à partir de la sortie Azure CLI pour une meilleure compréhension de l''infrastructure","Créer des diagrammes d''architecture à partir de descriptions de langage naturel de services Azure"],"de":["Visualisierung von Azure-Ressourcenkonfigurationen aus ARM-Vorlagen","Erstellung von Diagrammen aus Azure-CLI-Ausgaben für ein besseres Verständnis der Infrastruktur","Erstellung von Architekturdiagrammen aus natürlichen Sprachbeschreibungen von Azure-Diensten"],"pt":["Visualizar configurações de recursos do Azure a partir de modelos do ARM","Gerar diagramas a partir da saída do Azure CLI para uma compreensão mais fácil da infraestrutura","Criar diagramas de arquitetura a partir de descrições em linguagem natural dos serviços do Azure"],"ru":["Визуализировать конфигурации ресурсов Azure из шаблонов ARM","Генерировать диаграммы из вывода Azure CLI для более легкого понимания инфраструктуры","Создавать диаграммы архитектуры из естественных языковых описаний сервисов Azure"],"ar":["تصور تكوينات موارد Azure من قوالب ARM","توليد رسوم بيانية من إخراج Azure CLI لتسهيل فهم البنية التحتية","إنشاء رسوم بيانية للهندسة المعمارية من وصفات لغة طبيعية لخدمات Azure"]},"limitations":{"en":["Requires ARM templates, Azure CLI output, or natural language descriptions as input","Specific to Azure infrastructure, not compatible with other cloud providers"],"zh":["需要 ARM 模板、Azure CLI 输出或自然语言描述作为输入","特定于 Azure 基础设施，不兼容其他云提供商"],"ja":["ARM テンプレート、Azure CLI 出力、または自然言語の説明が入力として必要","Azure インフラストラクチャに特有で、他のクラウド プロバイダーとは互換性がありません"],"ko":["ARM 템플릿, Azure CLI 출력 또는 자연어 설명이 입력으로 필요","Azure 인프라에 특정되어 다른 클라우드 제공업체와 호환되지 않음"],"es":["Requiere plantillas de ARM, salida de Azure CLI o descripciones de lenguaje natural como entrada","Específico para la infraestructura de Azure, no compatible con otros proveedores de nube"],"fr":["Nécessite des modèles ARM, une sortie Azure CLI ou des descriptions de langage naturel comme entrée","Spécifique à l''infrastructure Azure, non compatible avec d''autres fournisseurs de cloud"],"de":["Benötigt ARM-Vorlagen, Azure-CLI-Ausgaben oder natürliche Sprachbeschreibungen als Eingabe","Spezifisch für die Azure-Infrastruktur, nicht kompatibel mit anderen Cloud-Anbietern"],"pt":["Requer modelos do ARM, saída do Azure CLI ou descrições em linguagem natural como entrada","Específico para a infraestrutura do Azure, não é compatível com outros provedores de nuvem"],"ru":["Требует шаблонов ARM, вывода Azure CLI или естественных языковых описаний в качестве входных данных","Специфичен для инфраструктуры Azure, не совместим с другими облачными провайдерами"],"ar":["يتطلب قوالب ARM أو إخراج Azure CLI أو описات لغة طبيعية كمدخلات","محدد لبنية تحتية Azure، غير متوافق مع مقدمي السحابة الآخرين"]},"version":4},"contentHash":"7a2a9640b208428d82d03e5ab5929f26919f68b11996b73fd9c9b5a3b39058b8","qualityScore":70}');
