INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('GAURAVSVNIT/Genesis/azure-diagrams', 'azure-diagrams', 'GAURAVSVNIT', 'Genesis', 'community', 'azure-diagrams GAURAVSVNIT Genesis community The azure-diagrams skill generates architecture diagrams for Azure infrastructure from ARM templates, Azure CLI output, or natural language descriptions, benefiting developers and architects. Azure Diagram Generator 是一种生成 Azure 基础设施图表的工具，支持 ARM 模板、Azure CLI 输出和自然语言描述 Azure Diagram Generator は、ARM テンプレート、Azure CLI 出力、または自然言語の説明から Azure インフラストラクチャの図を生成するツール Azure Diagram Generator는 ARM 템플릿, Azure CLI 출력 또는 자연어 설명에서 Azure 인프라의 다이어그램을 생성하는 도구 Azure-diagrams genera diagramas de arquitectura de Azure a partir de plantillas ARM, salida de Azure CLI o descripciones en lenguaje natural. Ideal para visualizar recursos de Azure. Azure-diagrams génère des diagrammes d''architecture Azure à partir de modèles ARM, de sortie Azure CLI ou de descriptions en langage naturel. Idéal pour visualiser les ressources Azure. Azure-diagrams generiert Architekturdiagramme für Azure aus ARM-Vorlagen, Azure-CLI-Ausgabe oder natürlichen Sprachbeschreibungen. Ideal für die Visualisierung von Azure-Ressourcen. O Azure Diagrams gera diagramas de arquitetura de infraestrutura Azure a partir de modelos ARM, saída do Azure CLI ou descrições em linguagem natural Azure Diagrams генерирует диаграммы архитектуры инфраструктуры Azure из шаблонов ARM, вывода Azure CLI или естественных языковых описаний أداة диаграмات Azure تنجز مخططات بنية تحتية Azure من قوالب ARM أو مخرجات Azure CLI أو описات لغة طبيعية how to use azure-diagrams azure-diagrams setup guide azure-diagrams alternative azure-diagrams vs Lucidchart generate azure architecture diagram visualize azure infrastructure azure-diagrams install azure-diagrams tutorial Azure Diagram Generator ARM 模板 Azure CLI 自然语言描述 Azure 资源 Azure 服务 AI 工具 Azure 基础设施图表 Generates architecture diagrams from ARM templates (JSON) Supports Azure CLI output, such as `az vm list` Visualizes Azure resources, including Virtual Machines and Storage Accounts Creates diagrams from natural language descriptions Activates when users mention Azure services, like VNets azure-diagrams is a skill that generates visual representations of Azure infrastructure, supporting ARM templates, Azure CLI output, and natural language descriptions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('QualityUnit/rendervid/rendervid', 'community', 'QualityUnit', 'rendervid', 'QualityUnit/rendervid', 'rendervid', 0, 0, 70, '2026-03-08T01:57:15.273Z', '2026-03-08T02:00:27.963Z', '8add2b0ffa99f8bfda6cca185b0ac5ec76ce32edcdb0a886e308f1755dd466a1', '{"id":"QualityUnit/rendervid/rendervid","name":"rendervid","description":{"en":"rendervid is a stateless video/image rendering engine that generates professional videos and images from JSON templates using natural language, benefiting AI agents and developers.","zh":"rendervid是一个无状态的视频/图像渲染引擎，支持JSON模板和React组件，用于生成专业视频和图像","ja":"rendervidは状態を保持しないビデオ/画像レンダリングエンジンで、JSONテンプレートとReactコンポーネントをサポートして、プロフェッショナルなビデオと画像を生成","ko":"rendervid는 상태를 유지하지 않는 비디오/이미지 렌더링 엔진으로 JSON 템플릿과 React 컴포넌트를 지원하여 전문가급 비디오와 이미지를 생성","es":"Rendervid es un motor de renderizado de video y imagen con JSON y soporte de componentes React, ideal para crear contenido animado para redes sociales, marketing y visualización de datos","fr":"Rendervid est un moteur de rendu vidéo et image avec JSON et prise en charge de composants React, idéal pour créer du contenu animé pour les réseaux sociaux, le marketing et la visualisation de données","de":"Rendervid ist eine stateless Video-/Bild-Renderings-Engine mit JSON-Vorlagen und React-Komponenten-Unterstützung, ideal für die Erstellung von animierten Inhalten für soziale Medien, Marketing und Datenvisualisierung","pt":"O Rendervid é um servidor MCP que permite a geração de vídeos e imagens profissionais a partir de templates JSON com suporte a componentes React","ru":"Rendervid - это сервер ИИ Агентов, который позволяет создавать профессиональные видео и изображения с помощью JSON шаблонов и поддержкой React компонентов","ar":"rendervid هو خادم MCP يتيح إنشاء فيديوهات وصور احترافية من قوالب JSON مع دعم لمكونات React"},"seo":{"title":{"en":"rendervid: Video Rendering Engine for AI Agents | AI Agen...","zh":"rendervid_setup_guide","ja":"rendervidベストプラクティス","ko":"rendervid_설치_가이드","es":"Guía de configuración de Rendervid: Motor de renderizado ...","fr":"Guide de mise en place de Rendervid : Moteur de rendu vid...","de":"Rendervid Einrichtungsleitfaden: Stateloses Video-/Bild-R...","pt":"Rendervid: Guia de Configuração para Renderização de Víde...","ru":"Rendervid: Настройка Stateless Видео/Изображения Рендерин...","ar":"rendervid: دليل إعداد محرك عرض الفيديو والصورة مع قوالب JSON"},"description":{"en":"Discover how rendervid''s stateless video rendering engine generates professional videos and images from JSON templates. Get started with rendervid today!","zh":"rendervid是一个无状态的视频/图像渲染引擎，支持JSON模板和React组件","ja":"rendervidは状態を保持しないビデオ/画像レンダリングエンジンで、JSONテンプレートとReactコンポーネントをサポート","ko":"rendervid는 상태를 유지하지 않는 비디오/이미지 렌더링 엔진으로 JSON 템플릿과 React 컴포넌트를 지원","es":"Aprende a utilizar Rendervid, un motor de renderizado de video y imagen con JSON y soporte de componentes React, para crear contenido animado","fr":"Découvrez comment utiliser Rendervid, un moteur de rendu vidéo et image avec JSON et prise en charge de composants React, pour créer du contenu animé","de":"Erfahren Sie, wie Sie Rendervid verwenden, einen stateless Video-/Bild-Renderings-Engine mit JSON-Vorlagen und React-Komponenten-Unterstützung, um animierte ...","pt":"Aprenda a utilizar o Rendervid, um motor de renderização de vídeo e imagem stateless com suporte a templates JSON e componentes React","ru":"Узнайте, как использовать Rendervid, сервер ИИ Агентов для создания профессиональных видео и изображений с помощью JSON шаблонов","ar":"تعرف على كيفية استخدام rendervid، محرك عرض فيديو وصور بدون حالة مع دعم قوالب JSON ومكونات React"},"definition":{"en":"rendervid is a Model Context Protocol (MCP) server that enables AI agents to generate animated content for social media, marketing, and data visualization.","zh":"rendervid是一种AIエージェント工具，用于生成视频和图像","ja":"rendervidはAIエージェントツールの一種で、ビデオと画像を生成","ko":"rendervid는 AI 에이전트 도구 중 하나로 비디오와 이미지를 생성","es":"Rendervid es un motor de renderizado de video y imagen que utiliza JSON y soporte de componentes React para crear contenido animado","fr":"Rendervid est un moteur de rendu vidéo et image qui utilise JSON et prise en charge de composants React pour créer du contenu animé","de":"Rendervid ist eine stateless Video-/Bild-Renderings-Engine, die JSON-Vorlagen und React-Komponenten-Unterstützung verwendet, um animierte Inhalte zu erstellen","pt":"O que é Rendervid? Um motor de renderização de vídeo e imagem stateless com suporte a templates JSON e componentes React","ru":"Что такое Rendervid? Сервер ИИ Агентов для создания профессиональных видео и изображений с помощью JSON шаблонов","ar":"ما هو rendervid؟ محرك عرض فيديو وصور بدون حالة مع دعم قوالب JSON ومكونات React"},"features":{"en":["Generates videos in multiple formats (MP4, WebM, MOV, GIF)","Creates static images (PNG, JPEG, WebP)","Accesses 50+ ready-to-use templates","Validates templates before rendering","Supports React component integration","Uses JSON templates for declarative content creation"],"zh":["支持JSON模板","支持React组件","生成多种视频格式（MP4、WebM、MOV、GIF）","生成静态图像（PNG、JPEG、WebP）","提供50+预制模板"],"ja":["JSONテンプレートをサポート","Reactコンポーネントをサポート","複数のビデオ形式（MP4、WebM、MOV、GIF）を生成","静的な画像（PNG、JPEG、WebP）を生成","50以上のテンプレートを提供"],"ko":["JSON 템플릿 지원","React 컴포넌트 지원","여러 비디오 형식（MP4、WebM、MOV、GIF） 생성","정적인 이미지（PNG、JPEG、WebP） 생성","50개 이상의 템플릿 제공"],"es":["Renderizado de video en múltiples formatos (MP4, WebM, MOV, GIF)","Creación de imágenes estáticas (PNG, JPEG, WebP)","Acceso a más de 50 plantillas predefinidas","Validación de plantillas antes de la renderización","Soporte de componentes React"],"fr":["Rendu de vidéo dans plusieurs formats (MP4, WebM, MOV, GIF)","Création d''images statiques (PNG, JPEG, WebP)","Accès à plus de 50 modèles prédéfinis","Validation des modèles avant le rendu","Prise en charge de composants React"],"de":["Renderung von Video in mehreren Formaten (MP4, WebM, MOV, GIF)","Erstellung von statischen Bildern (PNG, JPEG, WebP)","Zugriff auf über 50 vordefinierte Vorlagen","Validierung von Vorlagen vor der Renderung","Unterstützung von React-Komponenten"],"pt":["Geração de vídeos em múltiplos formatos (MP4, WebM, MOV, GIF)","Criação de imagens estáticas (PNG, JPEG, WebP)","Acesso a 50+ templates prontos para uso","Validação de templates antes da renderização","Suporte a componentes React"],"ru":["Генерация видео в нескольких форматах (MP4, WebM, MOV, GIF)","Создание статических изображений (PNG, JPEG, WebP)","Доступ к 50+ готовым шаблонам","Валидация шаблонов перед рендерингом","Поддержка React компонентов"],"ar":["إنشاء فيديوهات في صيغ متعددة (MP4, WebM, MOV, GIF)","إنشاء صور ثابتة (PNG, JPEG, WebP)","الوصول إلى 50+ قوالب جاهزة","التحقق من قوالب قبل العرض","دعم مكونات React"]},"keywords":{"en":["how to use rendervid","rendervid alternative","rendervid setup guide","what is rendervid","rendervid vs ffmpeg","rendervid install","rendervid JSON templates","rendervid React integration","rendervid video rendering engine"],"zh":["rendervid","AIエージェント","视频渲染","图像渲染","JSON模板","React组件","视频生成","图像生成"],"ja":["rendervid","AIエージェント","ビデオレンダリング","画像レンダリング","JSONテンプレート","Reactコンポーネント","ビデオ生成","画像生成"],"ko":["rendervid","AI 에이전트","비디오 렌더링","이미지 렌더링","JSON 템플릿","React 컴포넌트","비디오 생성","이미지 생성"],"es":["Rendervid","motor de renderizado de video","JSON","React","contenido animado","redes sociales","marketing","visualización de datos","herramientas de AI","agentes de AI"],"fr":["Rendervid","moteur de rendu de vidéo","JSON","React","contenu animé","réseaux sociaux","marketing","visualisation de données","outils d''IA","agents d''IA"],"de":["Rendervid","stateless Video-/Bild-Renderings-Engine","JSON","React","animierte Inhalte","soziale Medien","Marketing","Datenvisualisierung","KI-Tools","KI-Agents"],"pt":["rendervid","renderização de vídeo","renderização de imagem","templates JSON","componentes React","servidor MCP","ferramentas de IA","desenvolvimento de vídeo","desenvolvimento de imagem"],"ru":["Rendervid","видео рендеринг","изображение рендеринг","JSON шаблоны","React компоненты","ИИ Агенты","сервер ИИ Агентов","разработка видео","разработка изображений"],"ar":["rendervid","عرض الفيديو","عرض الصورة","قوالب JSON","مكونات React","أدوات الذكاء الاصطناعي","خادم MCP","تطوير الفيديو","تطوير الصورة"]}},"owner":"QualityUnit","repo":"rendervid","repoPath":"QualityUnit/rendervid","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.273Z","topics":[],"category":"community","skillMd":{"name":"rendervid","description":"Generate videos and images from JSON templates using AI-powered video rendering","version":"0.1.0","tags":["video","rendering","animation","templates","social-media","mcp"],"bodyPreview":"# Rendervid MCP Skill\n\nGenerate professional videos and images from JSON templates using natural language. Rendervid provides a declarative, AI-friendly way to create animated content for social media, marketing, data visualization, and more.\n\n## Overview\n\nRendervid is a Model Context Protocol (MCP) server that enables AI agents to:\n- Generate videos in multiple formats (MP4, WebM, MOV, GIF)\n- Create static images (PNG, JPEG, WebP)\n- Access 50+ ready-to-use templates\n- Validate templates before","body":"# Rendervid MCP Skill\n\nGenerate professional videos and images from JSON templates using natural language. Rendervid provides a declarative, AI-friendly way to create animated content for social media, marketing, data visualization, and more.\n\n## Overview\n\nRendervid is a Model Context Protocol (MCP) server that enables AI agents to:\n- Generate videos in multiple formats (MP4, WebM, MOV, GIF)\n- Create static images (PNG, JPEG, WebP)\n- Access 50+ ready-to-use templates\n- Validate templates before rendering\n- Discover all available capabilities\n\n**Key Features:**\n- **Declarative JSON Templates** - Define videos/images as simple JSON structures\n- **40+ Animation Presets** - Entrance, exit, and emphasis animations with easing functions\n- **Rich Layer Types** - Text, images, video, shapes, audio, Lottie, custom React components\n- **50+ Examples** - Ready-to-use templates across 10+ categories\n- **Type-Safe** - Full TypeScript with Zod validation\n- **Cross-Platform** - Works in Node.js and browsers\n\n## When to Use This Skill\n\nUse Rendervid when you need to:\n\n### Content Creation\n- Generate social media content (Instagram stories, TikTok videos, YouTube thumbnails)\n- Create marketing videos (product showcases, sale announcements, testimonials)\n- Build data visualizations (animated charts, graphs, dashboards)\n- Produce educational content (course intros, lesson titles)\n\n### Automation\n- Batch generate videos from data\n- Create personalized video content\n- Generate thumbnails for video content\n- Build video generation workflows\n\n### Prototyping\n- Quickly test video concepts\n- Create animated mockups\n- Generate placeholder content\n- Explore animation styles\n\n### AI-Driven Content\n- Let AI agents create videos from text descriptions\n- Generate videos based on user input\n- Create dynamic content based on data\n- Build video generation chatbots\n\n## Available Tools\n\nThe Rendervid MCP server provides 6 tools:\n\n### 1. render_video\nGenerate video files from JSON templates.\n\n**Common uses:**\n- Social media videos\n- Marketing content\n- Animated explainers\n- Data visualizations\n\n**Example prompt:**\n```\n\"Create a 5-second Instagram story with text ''Summer Sale'' and a blue gradient background\"\n```\n\n### 2. render_image\nGenerate static images or single frames.\n\n**Common uses:**\n- Thumbnails\n- Social media images\n- Preview frames\n- Static graphics\n\n**Example prompt:**\n```\n\"Generate a YouTube thumbnail with title ''Best Practices 2024''\"\n```\n\n### 3. validate_template\nValidate template JSON before rendering.\n\n**Common uses:**\n- Check template syntax\n- Catch errors early\n- Verify AI-generated templates\n- Debug template issues\n\n**Example prompt:**\n```\n\"Validate this template: [paste JSON]\"\n```\n\n### 4. get_capabilities\nDiscover all available features.\n\n**Common uses:**\n- Learn what''s possible\n- Find available animations\n- Check supported formats\n- Understand layer types\n\n**Example prompt:**\n```\n\"What animation presets are available?\"\n```\n\n### 5. list_examples\nBrowse 50+ example templates.\n\n**Common uses:**\n- Find templates by category\n- Discover use cases\n- Get inspiration\n- Learn template structure\n\n**Example prompt:**\n```\n\"Show me all social media templates\"\n```\n\n### 6. get_example\nLoad a specific example template.\n\n**Common uses:**\n- Use ready-made templates\n- Start from examples\n- Learn template patterns\n- Customize existing templates\n\n**Example prompt:**\n```\n\"Load the Instagram story template\"\n```\n\n## Template Structure\n\nRendervid templates are JSON objects with three main sections:\n\n```json\n{\n  \"name\": \"My Video\",\n  \"output\": {\n    \"type\": \"video\",\n    \"width\": 1920,\n    \"height\": 1080,\n    \"fps\": 30,\n    \"duration\": 5\n  },\n  \"inputs\": [\n    {\n      \"key\": \"title\",\n      \"type\": \"string\",\n      \"label\": \"Title\",\n      \"default\": \"Hello\"\n    }\n  ],\n  \"composition\": {\n    \"scenes\": [\n      {\n        \"id\": \"main\",\n        \"startFrame\": 0,\n        \"endFrame\": 150,\n        \"backgroundColor\": \"#1a1a2e\",\n        \"layers\": [\n          {\n            \"id\": \"title\",\n            \"type\": \"text\",\n            \"position\": { \"x\": 960, \"y\": 540 },\n            \"size\": { \"width\": 1600, \"height\": 200 },\n            \"inputKey\": \"title\",\n            \"props\": {\n              \"fontSize\": 120,\n              \"color\": \"#ffffff\",\n              \"textAlign\": \"center\"\n            },\n            \"animations\": [\n              {\n                \"type\": \"entrance\",\n                \"effect\": \"fadeInUp\",\n                \"duration\": 30,\n                \"easing\": \"easeOut\"\n              }\n            ]\n          }\n        ]\n      }\n    ]\n  }\n}\n```\n\n### Key Concepts\n\n**Output Configuration:**\n- Defines video/image dimensions, FPS, duration\n- Supports multiple formats and codecs\n\n**Dynamic Inputs:**\n- Variables that can be customized per render\n- Support strings, numbers, booleans, colors, images, videos\n\n**Composition:**\n- Scenes with frame ranges\n- Layers with types, positions, props\n- Animations with presets and easing\n\n## Common Patterns\n\n### Pattern 1: Text Animation\n```\nUser: \"Create a video with animated text\"\n\nAI flow:\n1. get_capabilities() to understand animations\n2. render_video() with fadeIn animation\n```\n\n### Pattern 2: Social Media Content\n```\nUser: \"Make an Instagram story for a product launch\"\n\nAI flow:\n1. list_examples({ category: \"social-media\" })\n2. get_example({ examplePath: \"social-media/instagram-story\" })\n3. render_video() with custom inputs\n```\n\n### Pattern 3: Data Visualization\n```\nUser: \"Create an animated bar chart showing Q1 sales\"\n\nAI flow:\n1. get_example({ examplePath: \"data-visualization/animated-bar-chart\" })\n2. Modify template with data\n3. render_video()\n```\n\n### Pattern 4: Batch Generation\n```\nUser: \"Create 10 videos with different titles\"\n\nAI flow:\n1. Load template once\n2. Call render_video() 10 times with different inputs\n```\n\n### Pattern 5: Template Validation\n```\nUser: \"Check if my custom template is valid\"\n\nAI flow:\n1. validate_template() to check structure\n2. Fix any errors\n3. render_video() to generate\n```\n\n## Special Topics\n\n### Animations\n\nRendervid supports 40+ animation presets organized by category:\n\n**Entrance Animations:**\n- fadeIn, fadeInUp, fadeInDown, fadeInLeft, fadeInRight\n- slideInUp, slideInDown, slideInLeft, slideInRight\n- scaleIn, zoomIn, rotateIn, bounceIn, flipInX, flipInY\n\n**Exit Animations:**\n- fadeOut, fadeOutUp, fadeOutDown, fadeOutLeft, fadeOutRight\n- slideOutUp, slideOutDown, slideOutLeft, slideOutRight\n- scaleOut, zoomOut, rotateOut, bounceOut\n\n**Emphasis Animations:**\n- pulse, shake, bounce, swing, wobble, flash, rubberBand\n- heartbeat, float, spin, tada, jello, flip\n\n**Easing Functions (30+):**\n- Linear: linear\n- Ease: ease, easeIn, easeOut, easeInOut\n- Cubic: easeInQuad, easeOutQuad, easeInOutQuad\n- And more: Cubic, Quart, Quint, Sine, Expo, Circ, Back, Elastic, Bounce\n\n### Layer Types\n\n**Text Layers:**\n- Typography controls (font, size, weight, style)\n- Alignment and spacing\n- Color and effects\n- Google Fonts support\n\n**Image Layers:**\n- Fit options (cover, contain, fill)\n- Scaling and positioning\n- Filters and blend modes\n\n**Video Layers:**\n- Playback controls\n- Timing and trimming\n- Audio control\n\n**Shape Layers:**\n- Rectangles, ellipses, polygons, stars, paths\n- Fill and stroke\n- Border radius and effects\n\n**Audio Layers:**\n- Background music\n- Sound effects\n- Volume and fade controls\n\n**Lottie Layers:**\n- Animated vector graphics\n- JSON animation files\n\n**Custom Layers:**\n- React components\n- Full CSS/Tailwind support\n- Advanced use cases\n\n### Output Formats\n\n**Video Formats:**\n- MP4 (H.264, H.265)\n- WebM (VP8, VP9, AV1)\n- MOV (ProRes, H.264)\n- GIF\n\n**Image Formats:**\n- PNG (lossless)\n- JPEG (lossy, quality control)\n- WebP (modern, efficient)\n\n**Quality Presets:**\n- draft: Fast rendering, lower quality\n- standard: Balanced quality/speed\n- high: High quality, slower rendering\n- lossless: Maximum quality, large files\n\n### Template Categories\n\n**Getting Started:**\n- Hello World\n- First Video\n- First Image\n\n**Social Media:**\n- Instagram Story (1080x1920)\n- Instagram Post (1080x1080)\n- TikTok Video (1080x1920)\n- YouTube Thumbnail (1280x720)\n- Twitter Card (1200x630)\n- LinkedIn Banner (1584x396)\n\n**Marketing:**\n- Product Showcase\n- Sale Announcement\n- Testimonial Video\n- Before & After\n- Logo Reveal\n\n**Data Visualization:**\n- Animated Bar Chart\n- Line Graph\n- Pie Chart\n- Counter Animation\n- Progress Dashboard\n\n**Business:**\n- Quote Card\n- Stat Highlight\n- Feature Announcement\n- Team Introduction\n- Company Update\n\n**Education:**\n- Lesson Title\n- Quiz Question\n- Course Intro\n- Study Tip\n- Progress Tracker\n\n**Celebrations:**\n- Birthday Card\n- Holiday Greeting\n- Congratulations\n- Thank You\n- Milestone\n\n**E-commerce:**\n- Product Launch\n- Flash Sale\n- New Arrival\n- Customer Review\n- Price Drop\n\n**Event:**\n- Event Announcement\n- Countdown Timer\n- Registration\n- Thank You (Attendees)\n- Highlight Reel\n\n**Podcast:**\n- Episode Intro\n- Quote Card\n- Guest Introduction\n- Coming Soon\n- Subscribe Reminder\n\n**Real Estate:**\n- Property Showcase\n- Open House\n- Sold Announcement\n- Agent Introduction\n- Virtual Tour Intro\n\n## Best Practices\n\n### Template Design\n\n1. **Keep it Simple**\n   - Start with examples\n   - Build complexity gradually\n   - Test frequently\n\n2. **Use Dynamic Inputs**\n   - Make values customizable\n   - Provide sensible defaults\n   - Document input purposes\n\n3. **Optimize Frame Ranges**\n   - Minimize total frames for faster rendering\n   - Use appropriate FPS (24-30 for most content)\n   - Consider file size vs quality tradeoffs\n\n4. **Test Animations**\n   - Preview before full render\n   - Check timing and easing\n   - Verify layer stacking\n\n### Performance\n\n1. **Draft Quality for Iteration**\n   - Use draft quality during development\n   - Switch to high quality for finals\n   - Consider file size requirements\n\n2. **Batch Rendering**\n   - Reuse templates when possible\n   - Queue multiple renders\n   - Monitor resource usage\n\n3. **Asset Optimization**\n   - Compress images before use\n   - Use appropriate video codecs\n   - Optimize Lottie animations\n\n### AI Integration\n\n1. **Clear Descriptions**\n   - Describe intent clearly\n   - Specify dimensions and duration\n   - Mention animation preferences\n\n2. **Validate Templates**\n   - Always validate AI-generated templates\n   - Check for common errors\n   - Test with sample data\n\n3. **Iterate Progressively**\n   - Start simple, add complexity\n   - Test each change\n   - Use examples as starting points\n\n## Example Workflows\n\n### Workflow 1: Quick Social Media Post\n\n```\nUser: \"Create an Instagram story announcing a flash sale\"\n\nAI Agent:\n1. list_examples({ category: \"social-media\" })\n2. get_example({ examplePath: \"social-media/instagram-story\" })\n3. render_video({\n     template: {...},\n     inputs: {\n       title: \"Flash Sale\",\n       subtitle: \"50% Off Everything\",\n       backgroundColor: \"#FF6B6B\"\n     },\n     format: \"mp4\",\n     quality: \"high\"\n   })\n\nResult: Instagram-ready 1080x1920 video\n```\n\n### Workflow 2: Data Visualization\n\n```\nUser: \"Create an animated chart showing Q1 revenue growth\"\n\nAI Agent:\n1. get_example({ examplePath: \"data-visualization/animated-bar-chart\" })\n2. Modify template with revenue data\n3. validate_template({ template })\n4. render_video({\n     template,\n     inputs: { data: [...], title: \"Q1 Revenue\" },\n     format: \"mp4\",\n     quality: \"high\"\n   })\n\nResult: Animated bar chart video\n```\n\n### Workflow 3: Custom Template Creation\n\n```\nUser: \"Create a custom video with my brand colors and logo\"\n\nAI Agent:\n1. get_capabilities() to understand options\n2. Start with example template\n3. Customize colors, fonts, layout\n4. validate_template() to check\n5. render_video() with draft quality\n6. Iterate based on preview\n7. Final render with high quality\n\nResult: Custom branded video\n```\n\n### Workflow 4: Batch Video Generation\n\n```\nUser: \"Create welcome videos for 100 new users\"\n\nAI Agent:\n1. get_example({ examplePath: \"business/team-introduction\" })\n2. Loop through user list:\n   - render_video({\n       template,\n       inputs: { name: user.name },\n       outputPath: `welcome-${user.id}.mp4`\n     })\n\nResult: 100 personalized welcome videos\n```\n\n## Troubleshooting\n\n### Common Issues\n\n**Issue: Server not connecting**\n- Check absolute path in MCP config\n- Verify Node.js version (20+)\n- Check server builds: `pnpm build`\n- Review logs in AI editor\n\n**Issue: FFmpeg not found**\n```bash\n# Install FFmpeg\nbrew install ffmpeg  # macOS\nsudo apt install ffmpeg  # Ubuntu\nchoco install ffmpeg  # Windows\n```\n\n**Issue: Template validation fails**\n- Check JSON syntax\n- Verify required fields\n- Review error messages\n- Use validate_template tool\n\n**Issue: Slow rendering**\n- Use draft quality for iteration\n- Reduce video duration/FPS\n- Optimize asset sizes\n- Check system resources\n\n**Issue: Node version errors**\n- Update to Node.js 20+\n- Use full Node.js path in config\n- Verify with: `node --version`\n\n### Getting Help\n\n- **Documentation**: [MCP Server README](../mcp/README.md)\n- **Examples**: Browse `/examples/` directory\n- **Issues**: [GitHub Issues](https://github.com/QualityUnit/rendervid/issues)\n- **Discussions**: [GitHub Discussions](https://github.com/QualityUnit/rendervid/discussions)\n\n## Resources\n\n### Documentation\n- [MCP Server Documentation](../mcp/README.md)\n- [Installation Guide](../mcp/INSTALL.md)\n- [Quick Start Guide](../mcp/QUICKSTART.md)\n- [API Reference](./README.md)\n\n### Templates\n- [50+ Example Templates](../examples/)\n- [Skills Registry](./skills-registry.json)\n- [Individual Tool Docs](./README.md#available-skills)\n\n### External Links\n- [Model Context Protocol](https://modelcontextprotocol.io)\n- [MCP Specification](https://modelcontextprotocol.io/specification)\n- [Rendervid Repository](https://github.com/QualityUnit/rendervid)\n\n## Version History\n\n### 0.1.0 (Initial Release)\n- 6 MCP tools (render_video, render_image, validate_template, get_capabilities, list_examples, get_example)\n- 50+ example templates across 10 categories\n- 40+ animation presets with 30+ easing functions\n- Support for MP4, WebM, MOV, GIF, PNG, JPEG, WebP\n- Full TypeScript with Zod validation\n- Stdio transport for maximum compatibility\n- Comprehensive documentation\n\n## License\n\nFlowHunt Attribution License - Free for commercial and personal use with attribution\n\n## Contributing\n\nContributions welcome! See [CONTRIBUTING.md](../CONTRIBUTING.md) for guidelines.\n\n## Credits\n\nDeveloped by QualityUnit\n\nBuilt with:\n- TypeScript\n- Model Context Protocol SDK\n- Zod for validation\n- Puppeteer for rendering\n- FFmpeg for video encoding\n"},"lastSynced":"2026-03-08T02:00:27.963Z","agentAnalysis":{"suitability":{"en":"Perfect for Media Creation Agents needing advanced video and image rendering capabilities from JSON templates using natural language.","zh":"非常适合需要使用JSON模板和自然语言进行高级视频和图像渲染的媒体创建代理。","ja":"高度な動画および画像レンダリング機能をJSONテンプレートと自然言語から必要とするメディア作成エージェントに最適です。","ko":"JSON 템플릿과 자연어를 사용하여 고급 비디오 및 이미지 렌더링 기능이 필요한 미디어 생성 에이전트에게 완벽합니다.","es":"Perfecto para agentes de creación de medios que necesitan capacidades avanzadas de renderizado de video e imagen desde plantillas JSON utilizando lenguaje natural.","fr":"Parfait pour les agents de création de médias ayant besoin de fonctionnalités avancées de rendu de vidéo et d''image à partir de modèles JSON en utilisant le langage naturel.","de":"Perfekt für Media Creation Agents, die erweiterte Video- und Bildrendering-Funktionen aus JSON-Vorlagen unter Verwendung von natürlicher Sprache benötigen.","pt":"Perfeito para Agentes de Criação de Mídia que necessitam de capacidades avançadas de renderização de vídeo e imagem a partir de modelos JSON usando linguagem natural.","ru":"Идеально подходит для агентов создания медиа, которым необходимы продвинутые возможности рендеринга видео и изображений из шаблонов JSON с использованием естественного языка.","ar":"مثالي لوسائل الإعلام وكلاء الخلق الذين يحتاجون إلى قدرات متقدمة من العرض والصورة من قوالب JSON باستخدام اللغة الطبيعية."},"recommendation":{"en":"Empowers agents to generate professional videos in multiple formats like MP4, WebM, MOV, GIF, and static images in PNG, JPEG, WebP, leveraging 50+ ready-to-use templates and validating them before use, all through a declarative, AI-friendly Model Context Protocol (MCP) server.","zh":"赋予代理生成多种格式（如MP4、WebM、MOV、GIF）的专业视频和PNG、JPEG、WebP格式的静态图像的能力，利用50多个即用模板，并在使用前验证它们，所有这些都通过声明式的AI友好型模型上下文协议（MCP）服务器实现。","ja":"エージェントがMP4、WebM、MOV、GIFなどの複数形式のプロフェッショナルビデオとPNG、JPEG、WebP形式の静的画像を生成する機能を提供し、50以上の即用テンプレートを利用し、使用前にそれらを検証する。すべてこれらは宣言的なAIフレンドリーモデルコンテキストプロトコル（MCP）サーバーを介して実現されます。","ko":"에이전트가 MP4, WebM, MOV, GIF 등의 여러 형식의 전문가급 비디오와 PNG, JPEG, WebP 형식의 정적 이미지를 생성할 수 있는 기능을 제공하며, 50개 이상의 즉시 사용 가능한 템플릿을 활용하고 사용 전에 검증합니다. 모든 것은 선언적 인 AI 친화적 모델 컨텍스트 프로토콜 (MCP) 서버를 통해 구현됩니다.","es":"Habilita a los agentes a generar videos profesionales en múltiples formatos como MP4, WebM, MOV, GIF y imágenes estáticas en PNG, JPEG, WebP, aprovechando más de 50 plantillas listas para usar y validándolas antes de su uso, todo a través de un servidor de protocolo de contexto de modelo declarativo, AI-friendly Model Context Protocol (MCP).","fr":"Permet aux agents de générer des vidéos professionnelles dans plusieurs formats tels que MP4, WebM, MOV, GIF et des images statiques au format PNG, JPEG, WebP, en exploitant plus de 50 modèles prêts à l''emploi et en les validant avant leur utilisation, le tout via un serveur de protocole de contexte de modèle déclaratif, AI-friendly Model Context Protocol (MCP).","de":"Ermächtigt Agenten, professionelle Videos in mehreren Formaten wie MP4, WebM, MOV, GIF und statische Bilder im PNG-, JPEG-, WebP-Format zu generieren, indem es mehr als 50 sofort verwendbare Vorlagen nutzt und diese vor der Verwendung validiert, all dies über einen deklarativen, AI-freundlichen Model Context Protocol (MCP)-Server.","pt":"Habilita os agentes a gerar vídeos profissionais em vários formatos, como MP4, WebM, MOV, GIF e imagens estáticas em PNG, JPEG, WebP, aproveitando 50+ modelos prontos para uso e validando-os antes do uso, tudo por meio de um servidor de protocolo de contexto de modelo declarativo, AI-friendly Model Context Protocol (MCP).","ru":"Наделяет агентов возможностью генерировать профессиональные видео в различных форматах, таких как MP4, WebM, MOV, GIF, и статические изображения в PNG, JPEG, WebP, используя 50+ готовых к использованию шаблонов и проверяя их перед использованием, все через сервер декларативного, дружественного к ИИ протокола контекста модели (MCP).","ar":"تمكين الوكلاء من生成 فيديوهات احترافية في عدة صيغ مثل MP4 و WebM و MOV و GIF والصور الثابتة في PNG و JPEG و WebP ، واستخدام أكثر من 50 نموذج جاهز للتشغيل والتحقق منها قبل الاستخدام ، كل ذلك من خلال خادم بروتوكول سياق نموذج إعلاني ، AI-friendly Model Context Protocol (MCP)."},"useCases":{"en":["Generating animated content for social media","Creating data visualization videos in various formats","Automating marketing material production using JSON templates","Validating video and image templates before rendering"],"zh":["为社交媒体生成动画内容","在各种格式中创建数据可视化视频","使用JSON模板自动化营销材料的生产","在渲染之前验证视频和图像模板"],"ja":["ソーシャルメディア用のアニメーションコンテンツを生成する","様々な形式でデータビジュアライゼーションビデオを作成する","JSONテンプレートを使用してマーケティング資料の生産を自動化する","レンダリング前にビデオと画像テンプレートを検証する"],"ko":["소셜 미디어용 애니메이션 콘텐츠 생성","다양한 형식으로 데이터 시각화 비디오 생성","JSON 템플릿을 사용하여 마케팅 자료의 생산을 자동화","렌더링 전에 비디오 및 이미지 템플릿을 검증"],"es":["Generación de contenido animado para redes sociales","Creación de videos de visualización de datos en varios formatos","Automatización de la producción de material de marketing utilizando plantillas JSON","Validación de plantillas de video e imagen antes del renderizado"],"fr":["Génération de contenu animé pour les réseaux sociaux","Création de vidéos de visualisation de données dans plusieurs formats","Automatisation de la production de matériel de marketing en utilisant des modèles JSON","Validation des modèles de vidéo et d''image avant le rendu"],"de":["Erzeugung von animiertem Inhalt für soziale Medien","Erstellung von Datenvisualisierungsvideos in verschiedenen Formaten","Automatisierung der Produktion von Marketingmaterial unter Verwendung von JSON-Vorlagen","Validierung von Video- und Bildvorlagen vor dem Rendering"],"pt":["Geração de conteúdo animado para mídias sociais","Criação de vídeos de visualização de dados em vários formatos","Automatização da produção de material de marketing usando modelos JSON","Validação de modelos de vídeo e imagem antes da renderização"],"ru":["Генерация анимированного контента для социальных сетей","Создание видео визуализации данных в различных форматах","Автоматизация производства маркетингового материала с использованием шаблонов JSON","Проверка шаблонов видео и изображений перед рендерингом"],"ar":["генерация محتوى متحرك لوسائل الإعلام الاجتماعية","إنشاء فيديوهات للرسومات البيانية في عدة صيغ","توسيط إنتاج مواد التسويق باستخدام قوالب JSON","التحقق من قوالب الفيديو والصورة قبل العرض"]},"limitations":{"en":["Stateless, requiring template validation before rendering","Dependent on JSON templates for video and image generation"],"zh":["无状态，需要在渲染前验证模板","依赖JSON模板进行视频和图像生成"],"ja":["ステートレスで、レンダリング前にテンプレートを検証する必要がある","ビデオおよび画像生成にJSONテンプレートに依存する"],"ko":["무상태로 렌더링 전에 템플릿을 검증해야 함","비디오 및 이미지 생성에 JSON 템플릿에 의존"],"es":["Sin estado, requiriendo validación de plantilla antes del renderizado","Dependiente de plantillas JSON para la generación de video e imagen"],"fr":["Sans état, nécessitant une validation de modèle avant le rendu","Dépendant des modèles JSON pour la génération de vidéo et d''image"],"de":["Zustandslos, erfordert Vorlagenvalidierung vor dem Rendering","Abhängig von JSON-Vorlagen für die Generierung von Video und Bild"],"pt":["Estadoless, requerendo validação de modelo antes da renderização","Dependente de modelos JSON para geração de vídeo e imagem"],"ru":["Безсостояние, требующее проверки шаблона перед рендерингом","Зависимый от шаблонов JSON для генерации видео и изображений"],"ar":["دون حالة ، يتطلب التحقق من القالب قبل العرض"," معتمد على قوالب JSON لتوليد الفيديو والصورة"]},"version":4},"contentHash":"8add2b0ffa99f8bfda6cca185b0ac5ec76ce32edcdb0a886e308f1755dd466a1","qualityScore":70}');
