INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('QualityUnit/rendervid/rendervid', 'rendervid', 'QualityUnit', 'rendervid', 'community', 'rendervid QualityUnit rendervid community rendervid is a stateless video/image rendering engine that generates professional videos and images from JSON templates using natural language, benefiting AI agents and developers. rendervid是一个无状态的视频/图像渲染引擎，支持JSON模板和React组件，用于生成专业视频和图像 rendervidは状態を保持しないビデオ/画像レンダリングエンジンで、JSONテンプレートとReactコンポーネントをサポートして、プロフェッショナルなビデオと画像を生成 rendervid는 상태를 유지하지 않는 비디오/이미지 렌더링 엔진으로 JSON 템플릿과 React 컴포넌트를 지원하여 전문가급 비디오와 이미지를 생성 Rendervid es un motor de renderizado de video y imagen con JSON y soporte de componentes React, ideal para crear contenido animado para redes sociales, marketing y visualización de datos Rendervid est un moteur de rendu vidéo et image avec JSON et prise en charge de composants React, idéal pour créer du contenu animé pour les réseaux sociaux, le marketing et la visualisation de données Rendervid ist eine stateless Video-/Bild-Renderings-Engine mit JSON-Vorlagen und React-Komponenten-Unterstützung, ideal für die Erstellung von animierten Inhalten für soziale Medien, Marketing und Datenvisualisierung O Rendervid é um servidor MCP que permite a geração de vídeos e imagens profissionais a partir de templates JSON com suporte a componentes React Rendervid - это сервер ИИ Агентов, который позволяет создавать профессиональные видео и изображения с помощью JSON шаблонов и поддержкой React компонентов rendervid هو خادم MCP يتيح إنشاء فيديوهات وصور احترافية من قوالب JSON مع دعم لمكونات React how to use rendervid rendervid alternative rendervid setup guide what is rendervid rendervid vs ffmpeg rendervid install rendervid JSON templates rendervid React integration rendervid video rendering engine rendervid AIエージェント 视频渲染 图像渲染 JSON模板 React组件 视频生成 图像生成 Generates videos in multiple formats (MP4, WebM, MOV, GIF) Creates static images (PNG, JPEG, WebP) Accesses 50+ ready-to-use templates Validates templates before rendering Supports React component integration Uses JSON templates for declarative content creation rendervid is a Model Context Protocol (MCP) server that enables AI agents to generate animated content for social media, marketing, and data visualization.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('agent0ai/agent-zero/create-skill', 'community', 'agent0ai', 'agent-zero', 'agent0ai/agent-zero', 'create-skill', 0, 0, 70, '2026-03-08T01:57:15.274Z', '2026-03-08T02:00:29.891Z', '55f81fc1d57546548d400d6e71470643bc64fc7bbe464ebf40609712bb43bc0c', '{"id":"agent0ai/agent-zero/create-skill","name":"create-skill","description":{"en":"The create-skill helps developers create new Agent Zero skills, guiding them through steps like naming, trigger patterns, and content structure. It benefits AI agent developers.","zh":"Create Skill技能帮助您创建新的AIエージェント，按照SKILL.md标准，包括Name & Purpose、Trigger Patterns、Content Structure和Supporting Files","ja":"Create Skillスキルは、AIエージェントを作成するために、SKILL.md標準に従って、名前と目的、トリガーパターン、コンテンツ構造、サポートファイルを設定します","ko":"Create Skill 스킬은 새로운 AI 에이전트를 생성하기 위해 SKILL.md 표준에 따라 이름 및 목적, 트리거 패턴, 콘텐츠 구조 및 지원 파일을 설정합니다","es":"Create-skill es una habilidad que permite crear nuevas habilidades para Agent Zero según el estándar SKILL.md.","fr":"Create-skill est une compétence qui aide à créer de nouvelles compétences pour les outils d''IA suivant la norme SKILL.md.","de":"Create-skill ist eine Fähigkeit, die das Erstellen neuer Fähigkeiten für KI-Agents nach dem SKILL.md-Standard ermöglicht.","pt":"O Create Skill é uma habilidade que ajuda a criar novas habilidades para o framework Agent Zero, seguindo o padrão SKILL.md","ru":"Create Skill - это навык, который помогает создавать новые навыки для фреймворка Agent Zero, следуя стандарту SKILL.md","ar":"المهارة الإبداعية هي مهارة تساعد على إنشاء مهارات جديدة لإطار العمل Agent Zero، تتبع معيار SKILL.md"},"seo":{"title":{"en":"create-skill: Setup Guide for AI Agents | AI Agent Skill","zh":"AIエージェント创建向导 - Create Skill Setup Guide","ja":"AIエージェントを作成する - Create Skill Best Practices","ko":"AI 에이전트 생성 가이드 - Create Skill Wizard","es":"Guía de Configuración de create-skill para 