INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('agent0ai/agent-zero/create-skill', 'create-skill', 'agent0ai', 'agent-zero', 'community', 'create-skill agent0ai agent-zero community The create-skill helps developers create new Agent Zero skills, guiding them through steps like naming, trigger patterns, and content structure. It benefits AI agent developers. Create Skill技能帮助您创建新的AIエージェント，按照SKILL.md标准，包括Name & Purpose、Trigger Patterns、Content Structure和Supporting Files Create Skillスキルは、AIエージェントを作成するために、SKILL.md標準に従って、名前と目的、トリガーパターン、コンテンツ構造、サポートファイルを設定します Create Skill 스킬은 새로운 AI 에이전트를 생성하기 위해 SKILL.md 표준에 따라 이름 및 목적, 트리거 패턴, 콘텐츠 구조 및 지원 파일을 설정합니다 Create-skill es una habilidad que permite crear nuevas habilidades para Agent Zero según el estándar SKILL.md. Create-skill est une compétence qui aide à créer de nouvelles compétences pour les outils d''IA suivant la norme SKILL.md. Create-skill ist eine Fähigkeit, die das Erstellen neuer Fähigkeiten für KI-Agents nach dem SKILL.md-Standard ermöglicht. O Create Skill é uma habilidade que ajuda a criar novas habilidades para o framework Agent Zero, seguindo o padrão SKILL.md Create Skill - это навык, который помогает создавать новые навыки для фреймворка Agent Zero, следуя стандарту SKILL.md المهارة الإبداعية هي مهارة تساعد على إنشاء مهارات جديدة لإطار العمل Agent Zero، تتبع معيار SKILL.md how to use create-skill create-skill setup guide Agent Zero AI framework SKILL.md standard create-skill alternative create-skill vs Agent Zero create-skill install what is create-skill create-skill for AI agents AIエージェント创建 Create Skill SKILL.md标准 AI工具创建 快速开始 触发模式 内容结构 支持文件 Guides through the creation of new Agent Zero skills Supports the SKILL.md standard with YAML frontmatter Helps define trigger patterns for skill activation Assists in structuring content for the agent to follow Facilitates the inclusion of supporting files like scripts and templates create-skill is a wizard that helps create new Agent Zero skills following the SKILL.md standard, streamlining the development process');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('blocknavi/convex-batch-processor/convex-component-authoring', 'community', 'blocknavi', 'convex-batch-processor', 'blocknavi/convex-batch-processor', 'convex-component-authoring', 0, 0, 70, '2026-03-08T01:57:15.302Z', '2026-03-08T02:01:40.408Z', '561346aded0969635fc3f32ae6d465f882266b6be20b4038c7a55645ff6db7c2', '{"id":"blocknavi/convex-batch-processor/convex-component-authoring","name":"convex-component-authoring","description":{"en":"Convex-component-authoring enables developers to create reusable Convex components with proper isolation, exports, and dependency management. This skill benefits developers working on projects that require sharing components across projects.","zh":"Convex 组件创建允许开发者创建自包含、可重用的组件，实现跨项目的共享和复用","ja":"Convex コンポーネント作成は、開発者が自己完結的で再利用可能なコンポーネントを作成できるようにします","ko":"Convex 컴포넌트 작성은 개발자가 독립적이고 재사용 가능한 컴포넌트를 작성할 수 있게 해줍니다","es":"Convex component authoring permite crear componentes reutilizables con aislamiento y gestión de dependencias","fr":"L''authoring de composants convexes permet de créer des composants réutilisables avec isolation et gestion de dépendances","de":"Convex-Komponentenauthoring ermöglicht die Erstellung von wiederverwendbaren Komponenten mit Isolation und Abhängigkeitsverwaltung","pt":"Convex Component Authoring permite criar componentes reutilizáveis com isolamento e gerenciamento de dependências","ru":"Convex Component Authoring позволяет создавать самодостаточные компоненты с изоляцией и управлением зависимостями","ar":"Convex Component Authoring يسمح بإنشاء مكونات قابلة لإعادة الاستخدام مع العزل وإدارة التبعيات"},"seo":{"title":{"en":"Convex-Component-Authoring: Setup Guide for AI Agents | A...","zh":"Convex 组件创建最佳实践","ja":"Convex コンポーネント作成ガイド - AIエージェント","ko":"Convex 컴포넌트 작성 가이드 - AI 도구","es":"Guía de configuración de componentes convexos","fr":"Guide de mise en place de composants convexes","de":"Einrichtungsleitfaden für Convex-Komponenten","pt":"Guia de Configuração do Convex Component Authoring","ru":"Настройка Convex Component Authoring: ИИ Агенты","ar":"دليل إعداد Convex Component Authoring للأدوات الذكية"},"description":{"en":"Learn how to create self-contained Convex components with proper isolation and dependency management. Get started with Convex component authoring today!","zh":"学习 Convex 组件的创建和管理，实现跨项目的共享和复用","ja":"Convex コンポーネントの作成と管理を学び、プロジェクト間の共有と再利用を実現する - AIエージェント","ko":"Convex 컴포넌트의 작성과 관리를 공부하고 프로젝트 간의 공유와 재사용을 구현하세요 - AI 도구","es":"Aprende a crear componentes convexos reutilizables con aislamiento, exportaciones y gestión de dependencias para compartir entre proyectos","fr":"Découvrez comment créer des composants convexes réutilisables avec isolation, exportations et gestion de dépendances pour les partager entre projets","de":"Erfahren Sie, wie Sie wiederverwendbare Convex-Komponenten mit Isolation, Exporten und Abhängigkeitsverwaltung für den Austausch zwischen Projekten erstellen","pt":"Aprenda a criar componentes Convex reutilizáveis com isolamento, exportação e gerenciamento de dependências adequados","ru":"Создавайте самодостаточные компоненты Convex с правильной изоляцией, экспортом и управлением зависимостями с помощью ИИ Агентов","ar":"تعلم كيفية إنشاء مكونات Convex قابلة لإعادة الاستخدام مع العزل والتصدير وإدارة التبعيات المناسبة للأدوات الذكية"},"definition":{"en":"Convex-component-authoring is a technique for creating self-contained, reusable Convex components with proper isolation, exports, and dependency management for sharing across projects.","zh":"Convex 组件创建是指创建自包含、可重用的 Convex 组件","ja":"Convex コンポーネント作成とは、自己完結的で再利用可能な Convex コンポーネントを作成することです","ko":"Convex 컴포넌트 작성은 독립적이고 재사용 가능한 Convex 컴포넌트를 작성하는 것을 의미합니다","es":"Convex component authoring es una técnica para crear componentes autónomos y reutilizables","fr":"L''authoring de composants convexes est une technique pour créer des composants autonomes et réutilisables","de":"Convex-Komponentenauthoring ist eine Technik zur Erstellung von autarken und wiederverwendbaren Komponenten","pt":"Convex Component Authoring é uma técnica para criar componentes reutilizáveis","ru":"Convex Component Authoring - это метод создания самодостаточных компонентов","ar":"Convex Component Authoring هو تقنية لإنشاء مكونات قابلة لإعادة الاستخدام"},"features":{"en":["Creates self-contained Convex components with proper isolation","Supports exports and dependency management for sharing across projects","Utilizes documentation from https://docs.convex.dev/components for implementation","Follows guidelines from https://docs.convex.dev/components/authoring for authoring","References broader context from https://docs.convex.dev/llms.txt for additional information"],"zh":["支持创建自包含的 Convex 组件","实现跨项目的组件共享和复用","提供依赖管理和导出功能","参考 Convex 官方文档进行实现"],"ja":["自己完結的 Convex コンポーネントを作成可能","プロジェクト間のコンポーネントの共有と再利用を実現","依存関係管理とエクスポート機能を提供","Convex 公式ドキュメントを参考して実装"],"ko":["독립적인 Convex 컴포넌트의 작성이 가능","프로젝트 간의 컴포넌트 공유와 재사용을 구현","의존성 관리와导出 기능을 제공","Convex 공식 문서를 참조하여 구현"],"es":["Creación de componentes reutilizables","Aislamiento de componentes","Gestión de dependencias","Exportaciones de componentes","Compatibilidad con proyectos múltiples","Documentación en línea en https://docs.convex.dev/components"],"fr":["Création de composants réutilisables","Isolation de composants","Gestion de dépendances","Exportations de composants","Compatibilité avec plusieurs projets","Documentation en ligne sur https://docs.convex.dev/components"],"de":["Erstellung von wiederverwendbaren Komponenten","Isolation von Komponenten","Abhängigkeitsverwaltung","Export von Komponenten","Kompatibilität mit mehreren Projekten","Online-Dokumentation auf https://docs.convex.dev/components"],"pt":["Criação de componentes Convex reutilizáveis","Isolamento e exportação de componentes","Gerenciamento de dependências","Integração com a documentação oficial da Convex","Suporte à criação de componentes com exports e dependency management"],"ru":["Создание самодостаточных компонентов Convex","Изоляция и экспорт компонентов","Управление зависимостями","Интеграция с официальной документацией Convex","Поддержка создания компонентов с экспортом и управлением зависимостями"],"ar":["إنشاء مكونات Convex قابلة لإعادة الاستخدام","العزل والتصدير للمكونات","إدارة التبعيات","التكامل مع وثائق Convex الرسمية","دعم إنشاء المكونات مع التصدير وإدارة التبعيات"]},"keywords":{"en":["how to use convex-component-authoring","convex-component-authoring setup guide","convex-component-authoring vs other component authoring tools","convex-component-authoring install","what is convex-component-authoring","convex-component-authoring documentation","convex-component-authoring tutorial","convex-component-authoring best practices"],"zh":["Convex 组件创建","Convex 组件管理","跨项目共享","组件复用","Convex 官方文档","依赖管理","导出功能"],"ja":["Convex コンポーネント作成","Convex コンポーネント管理","プロジェクト間の共有","コンポーネントの再利用","Convex 公式ドキュメント","依存関係管理","エクスポート機能"],"ko":["Convex 컴포넌트 작성","Convex 컴포넌트 관리","프로젝트 간의 공유","컴포넌트의 재사용","Convex 공식 문서","의존성 관리","导出 기능"],"es":["convex component authoring","componentes convexos","Herramientas de AI","desarrollo de componentes","gestión de dependencias","exportaciones de componentes","proyectos de desarrollo","documentación de convex"],"fr":["authoring de composants convexes","composants convexes","Outils d''IA","développement de composants","gestion de dépendances","exportations de composants","projets de développement","documentation de convex"],"de":["Convex-Komponentenauthoring","Convex-Komponenten","KI-Tools","Komponentenentwicklung","Abhängigkeitsverwaltung","Export von Komponenten","Entwicklungsprojekte","Convex-Dokumentation"],"pt":["Convex Component Authoring","componentes reutilizáveis","isolamento de componentes","gerenciamento de dependências","documentação Convex","criação de componentes","exports e dependency management"],"ru":["Convex Component Authoring","ИИ Агенты","самодостаточные компоненты","изоляция компонентов","управление зависимостями","документация Convex","создание компонентов","экспорт и управление зависимостями"],"ar":["Convex Component Authoring","الأدوات الذكية","مكونات قابلة لإعادة الاستخدام","عزل المكونات","إدارة التبعيات","وثائق Convex","إنشاء المكونات","التصدير وإدارة التبعيات"]}},"owner":"blocknavi","repo":"convex-batch-processor","repoPath":"blocknavi/convex-batch-processor","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.302Z","topics":[],"category":"community","skillMd":{"name":"convex-component-authoring","description":"How to create, structure, and publish self-contained Convex components with proper isolation, exports, and dependency management","version":"1.0.0","tags":["convex","components","reusable","packages","npm"],"bodyPreview":"# Convex Component Authoring\n\nCreate self-contained, reusable Convex components with proper isolation, exports, and dependency management for sharing across projects.\n\n## Documentation Sources\n\nBefore implementing, do not assume; fetch the latest documentation:\n\n- Primary: https://docs.convex.dev/components\n- Component Authoring: https://docs.convex.dev/components/authoring\n- For broader context: https://docs.convex.dev/llms.txt\n\n## Instructions\n\n### What Are Convex Components?\n\nConvex component","body":"# Convex Component Authoring\n\nCreate self-contained, reusable Convex components with proper isolation, exports, and dependency management for sharing across projects.\n\n## Documentation Sources\n\nBefore implementing, do not assume; fetch the latest documentation:\n\n- Primary: https://docs.convex.dev/components\n- Component Authoring: https://docs.convex.dev/components/authoring\n- For broader context: https://docs.convex.dev/llms.txt\n\n## Instructions\n\n### What Are Convex Components?\n\nConvex components are self-contained packages that include:\n- Database tables (isolated from the main app)\n- Functions (queries, mutations, actions)\n- TypeScript types and validators\n- Optional frontend hooks\n\n### Component Structure\n\n```\nmy-convex-component/\n├── package.json\n├── tsconfig.json\n├── README.md\n├── src/\n│   ├── index.ts           # Main exports\n│   ├── component.ts       # Component definition\n│   ├── schema.ts          # Component schema\n│   └── functions/\n│       ├── queries.ts\n│       ├── mutations.ts\n│       └── actions.ts\n└── convex.config.ts       # Component configuration\n```\n\n### Creating a Component\n\n#### 1. Component Configuration\n\n```typescript\n// convex.config.ts\nimport { defineComponent } from \"convex/server\";\n\nexport default defineComponent(\"myComponent\");\n```\n\n#### 2. Component Schema\n\n```typescript\n// src/schema.ts\nimport { defineSchema, defineTable } from \"convex/server\";\nimport { v } from \"convex/values\";\n\nexport default defineSchema({\n  // Tables are isolated to this component\n  items: defineTable({\n    name: v.string(),\n    data: v.any(),\n    createdAt: v.number(),\n  }).index(\"by_name\", [\"name\"]),\n  \n  config: defineTable({\n    key: v.string(),\n    value: v.any(),\n  }).index(\"by_key\", [\"key\"]),\n});\n```\n\n#### 3. Component Definition\n\n```typescript\n// src/component.ts\nimport { defineComponent, ComponentDefinition } from \"convex/server\";\nimport schema from \"./schema\";\nimport * as queries from \"./functions/queries\";\nimport * as mutations from \"./functions/mutations\";\n\nconst component = defineComponent(\"myComponent\", {\n  schema,\n  functions: {\n    ...queries,\n    ...mutations,\n  },\n});\n\nexport default component;\n```\n\n#### 4. Component Functions\n\n```typescript\n// src/functions/queries.ts\nimport { query } from \"../_generated/server\";\nimport { v } from \"convex/values\";\n\nexport const list = query({\n  args: {\n    limit: v.optional(v.number()),\n  },\n  returns: v.array(v.object({\n    _id: v.id(\"items\"),\n    name: v.string(),\n    data: v.any(),\n    createdAt: v.number(),\n  })),\n  handler: async (ctx, args) => {\n    return await ctx.db\n      .query(\"items\")\n      .order(\"desc\")\n      .take(args.limit ?? 10);\n  },\n});\n\nexport const get = query({\n  args: { name: v.string() },\n  returns: v.union(v.object({\n    _id: v.id(\"items\"),\n    name: v.string(),\n    data: v.any(),\n  }), v.null()),\n  handler: async (ctx, args) => {\n    return await ctx.db\n      .query(\"items\")\n      .withIndex(\"by_name\", (q) => q.eq(\"name\", args.name))\n      .unique();\n  },\n});\n```\n\n```typescript\n// src/functions/mutations.ts\nimport { mutation } from \"../_generated/server\";\nimport { v } from \"convex/values\";\n\nexport const create = mutation({\n  args: {\n    name: v.string(),\n    data: v.any(),\n  },\n  returns: v.id(\"items\"),\n  handler: async (ctx, args) => {\n    return await ctx.db.insert(\"items\", {\n      name: args.name,\n      data: args.data,\n      createdAt: Date.now(),\n    });\n  },\n});\n\nexport const update = mutation({\n  args: {\n    id: v.id(\"items\"),\n    data: v.any(),\n  },\n  returns: v.null(),\n  handler: async (ctx, args) => {\n    await ctx.db.patch(args.id, { data: args.data });\n    return null;\n  },\n});\n\nexport const remove = mutation({\n  args: { id: v.id(\"items\") },\n  returns: v.null(),\n  handler: async (ctx, args) => {\n    await ctx.db.delete(args.id);\n    return null;\n  },\n});\n```\n\n#### 5. Main Exports\n\n```typescript\n// src/index.ts\nexport { default as component } from \"./component\";\nexport * from \"./functions/queries\";\nexport * from \"./functions/mutations\";\n\n// Export types for consumers\nexport type { Id } from \"./_generated/dataModel\";\n```\n\n### Using a Component\n\n```typescript\n// In the consuming app''s convex/convex.config.ts\nimport { defineApp } from \"convex/server\";\nimport myComponent from \"my-convex-component\";\n\nconst app = defineApp();\n\napp.use(myComponent, { name: \"myComponent\" });\n\nexport default app;\n```\n\n```typescript\n// In the consuming app''s code\nimport { useQuery, useMutation } from \"convex/react\";\nimport { api } from \"../convex/_generated/api\";\n\nfunction MyApp() {\n  // Access component functions through the app''s API\n  const items = useQuery(api.myComponent.list, { limit: 10 });\n  const createItem = useMutation(api.myComponent.create);\n  \n  return (\n    <div>\n      {items?.map((item) => (\n        <div key={item._id}>{item.name}</div>\n      ))}\n      <button onClick={() => createItem({ name: \"New\", data: {} })}>\n        Add Item\n      </button>\n    </div>\n  );\n}\n```\n\n### Component Configuration Options\n\n```typescript\n// convex/convex.config.ts\nimport { defineApp } from \"convex/server\";\nimport myComponent from \"my-convex-component\";\n\nconst app = defineApp();\n\n// Basic usage\napp.use(myComponent);\n\n// With custom name\napp.use(myComponent, { name: \"customName\" });\n\n// Multiple instances\napp.use(myComponent, { name: \"instance1\" });\napp.use(myComponent, { name: \"instance2\" });\n\nexport default app;\n```\n\n### Providing Component Hooks\n\n```typescript\n// src/hooks.ts\nimport { useQuery, useMutation } from \"convex/react\";\nimport { FunctionReference } from \"convex/server\";\n\n// Type-safe hooks for component consumers\nexport function useMyComponent(api: {\n  list: FunctionReference<\"query\">;\n  create: FunctionReference<\"mutation\">;\n}) {\n  const items = useQuery(api.list, {});\n  const createItem = useMutation(api.create);\n  \n  return {\n    items,\n    createItem,\n    isLoading: items === undefined,\n  };\n}\n```\n\n### Publishing a Component\n\n#### package.json\n\n```json\n{\n  \"name\": \"my-convex-component\",\n  \"version\": \"1.0.0\",\n  \"description\": \"A reusable Convex component\",\n  \"main\": \"dist/index.js\",\n  \"types\": \"dist/index.d.ts\",\n  \"files\": [\n    \"dist\",\n    \"convex.config.ts\"\n  ],\n  \"scripts\": {\n    \"build\": \"tsc\",\n    \"prepublishOnly\": \"npm run build\"\n  },\n  \"peerDependencies\": {\n    \"convex\": \"^1.0.0\"\n  },\n  \"devDependencies\": {\n    \"convex\": \"^1.17.0\",\n    \"typescript\": \"^5.0.0\"\n  },\n  \"keywords\": [\n    \"convex\",\n    \"component\"\n  ]\n}\n```\n\n#### tsconfig.json\n\n```json\n{\n  \"compilerOptions\": {\n    \"target\": \"ES2020\",\n    \"module\": \"ESNext\",\n    \"moduleResolution\": \"bundler\",\n    \"declaration\": true,\n    \"outDir\": \"dist\",\n    \"strict\": true,\n    \"esModuleInterop\": true,\n    \"skipLibCheck\": true\n  },\n  \"include\": [\"src/**/*\"],\n  \"exclude\": [\"node_modules\", \"dist\"]\n}\n```\n\n## Examples\n\n### Rate Limiter Component\n\n```typescript\n// rate-limiter/src/schema.ts\nimport { defineSchema, defineTable } from \"convex/server\";\nimport { v } from \"convex/values\";\n\nexport default defineSchema({\n  requests: defineTable({\n    key: v.string(),\n    timestamp: v.number(),\n  })\n    .index(\"by_key\", [\"key\"])\n    .index(\"by_key_and_time\", [\"key\", \"timestamp\"]),\n});\n```\n\n```typescript\n// rate-limiter/src/functions/mutations.ts\nimport { mutation } from \"../_generated/server\";\nimport { v } from \"convex/values\";\n\nexport const checkLimit = mutation({\n  args: {\n    key: v.string(),\n    limit: v.number(),\n    windowMs: v.number(),\n  },\n  returns: v.object({\n    allowed: v.boolean(),\n    remaining: v.number(),\n    resetAt: v.number(),\n  }),\n  handler: async (ctx, args) => {\n    const now = Date.now();\n    const windowStart = now - args.windowMs;\n    \n    // Clean old entries\n    const oldEntries = await ctx.db\n      .query(\"requests\")\n      .withIndex(\"by_key_and_time\", (q) => \n        q.eq(\"key\", args.key).lt(\"timestamp\", windowStart)\n      )\n      .collect();\n    \n    for (const entry of oldEntries) {\n      await ctx.db.delete(entry._id);\n    }\n    \n    // Count current window\n    const currentRequests = await ctx.db\n      .query(\"requests\")\n      .withIndex(\"by_key\", (q) => q.eq(\"key\", args.key))\n      .collect();\n    \n    const remaining = Math.max(0, args.limit - currentRequests.length);\n    const allowed = remaining > 0;\n    \n    if (allowed) {\n      await ctx.db.insert(\"requests\", {\n        key: args.key,\n        timestamp: now,\n      });\n    }\n    \n    const oldestRequest = currentRequests[0];\n    const resetAt = oldestRequest \n      ? oldestRequest.timestamp + args.windowMs \n      : now + args.windowMs;\n    \n    return { allowed, remaining: remaining - (allowed ? 1 : 0), resetAt };\n  },\n});\n```\n\n```typescript\n// Usage in consuming app\nimport { useMutation } from \"convex/react\";\nimport { api } from \"../convex/_generated/api\";\n\nfunction useRateLimitedAction() {\n  const checkLimit = useMutation(api.rateLimiter.checkLimit);\n  \n  return async (action: () => Promise<void>) => {\n    const result = await checkLimit({\n      key: \"user-action\",\n      limit: 10,\n      windowMs: 60000,\n    });\n    \n    if (!result.allowed) {\n      throw new Error(`Rate limited. Try again at ${new Date(result.resetAt)}`);\n    }\n    \n    await action();\n  };\n}\n```\n\n## Best Practices\n\n- Never run `npx convex deploy` unless explicitly instructed\n- Never run any git commands unless explicitly instructed\n- Keep component tables isolated (don''t reference main app tables)\n- Export clear TypeScript types for consumers\n- Document all public functions and their arguments\n- Use semantic versioning for component releases\n- Include comprehensive README with examples\n- Test components in isolation before publishing\n\n## Common Pitfalls\n\n1. **Cross-referencing tables** - Component tables should be self-contained\n2. **Missing type exports** - Export all necessary types\n3. **Hardcoded configuration** - Use component options for customization\n4. **No versioning** - Follow semantic versioning\n5. **Poor documentation** - Document all public APIs\n\n## References\n\n- Convex Documentation: https://docs.convex.dev/\n- Convex LLMs.txt: https://docs.convex.dev/llms.txt\n- Components: https://docs.convex.dev/components\n- Component Authoring: https://docs.convex.dev/components/authoring\n"},"lastSynced":"2026-03-08T02:01:40.408Z","agentAnalysis":{"suitability":{"en":"Perfect for Full Stack Agents needing reusable Convex components with proper isolation and dependency management.","zh":"非常适合需要可重用 Convex 组件的全栈代理，具有适当的隔离和依赖管理。","ja":"再利用可能なConvexコンポーネントを必要とするフルスタックエージェントに最適で、適切な分離と依存関係管理が可能です。","ko":"다시 사용 가능한 Convex 컴포넌트가 필요한 풀 스택 에이전트에게 적합하며, 적절한 분리 및 의존성 관리를 제공합니다.","es":"Perfecto para Agentes de Full Stack que necesitan componentes Convex reutilizables con aislamiento y gestión de dependencias adecuados.","fr":"Parfait pour les agents Full Stack qui ont besoin de composants Convex réutilisables avec une isolation et une gestion des dépendances appropriées.","de":"Perfekt für Full-Stack-Agents, die wiederverwendbare Convex-Komponenten mit ordnungsgemäßer Isolation und Abhängigkeitsverwaltung benötigen.","pt":"Perfeito para Agentes Full Stack que precisam de componentes Convex reutilizáveis com isolamento e gerenciamento de dependências adequados.","ru":"Идеально подходит для полнофункциональных агентов, которым требуются многократно используемые компоненты Convex с правильной изоляцией и управлением зависимостями.","ar":"مثالي للوكلاء الخليويين الكاملين الذين يحتاجون إلى مكونات Convex قابلة لإعادة الاستخدام مع عزل وإدارة التبعيات المناسبة."},"recommendation":{"en":"Empowers agents to create self-contained Convex components with exports and dependency management using the Convex components authoring documentation, enabling efficient sharing across projects with proper isolation.","zh":"使代理能够使用Convex组件编写文档创建自包含的Convex组件，具有导出和依赖管理功能，从而实现跨项目的高效共享和适当的隔离。","ja":"Convexコンポーネントの作成文書を使用して、エージェントがエクスポートと依存関係管理を使用して自己完結型のConvexコンポーネントを作成できるようにし、プロジェクト間で効率的に共有し、適切な分離を実現します。","ko":"에이전트가 Convex 컴포넌트 작성 문서를 사용하여 내보내기 및 의존성 관리를 사용하는 자체 포함 Convex 컴포넌트를 생성할 수 있도록 하여 프로젝트 간에 효율적으로 공유하고 적절한 분리를 구현합니다.","es":"Habilita a los agentes a crear componentes Convex autocontenidos con exportaciones y gestión de dependencias utilizando la documentación de autoría de componentes Convex, lo que permite un intercambio eficiente entre proyectos con un aislamiento adecuado.","fr":"Permet aux agents de créer des composants Convex autocontenus avec des exportations et une gestion des dépendances en utilisant la documentation d''authoring des composants Convex, ce qui permet un partage efficace entre les projets avec une isolation appropriée.","de":"Ermächtigt Agents, selbstenthaltene Convex-Komponenten mit Exporten und Abhängigkeitsverwaltung zu erstellen, indem sie die Convex-Komponenten-Autoren-Dokumentation verwenden, was ein effizientes Teilen zwischen Projekten mit angemessener Isolation ermöglicht.","pt":"Habilita os agentes a criar componentes Convex autocontidos com exports e gerenciamento de dependências usando a documentação de autorização de componentes Convex, permitindo compartilhamento eficiente entre projetos com isolamento adequado.","ru":"Наделяет агентов возможностью создавать самодостаточные компоненты Convex с экспортами и управлением зависимостями с помощью документации по созданию компонентов Convex, обеспечивая эффективное обмен между проектами с правильной изоляцией.","ar":"يمنح الوكلاء القدرة على إنشاء مكونات Convex متكاملة ذاتيا مع تصدير وإدارة التبعيات باستخدام وثائق تأليف مكونات Convex، وتمكين المشاركة الفعالة عبر المشاريع مع عزل مناسب."},"useCases":{"en":["Authoring reusable Convex components for sharing across projects","Managing dependencies for Convex components","Exporting Convex components for use in multiple applications"],"zh":["为跨项目共享而创建可重用的Convex组件","管理Convex组件的依赖关系","导出Convex组件以在多个应用程序中使用"],"ja":["プロジェクト間で共有するための再利用可能なConvexコンポーネントの作成","Convexコンポーネントの依存関係の管理","複数のアプリケーションで使用するためのConvexコンポーネントのエクスポート"],"ko":["프로젝트 간에 공유하기 위한 다시 사용 가능한 Convex 컴포넌트 생성","Convex 컴포넌트의 종속성 관리","다중 응용 프로그램에서 사용하기 위한 Convex 컴포넌트 내보내기"],"es":["Crear componentes Convex reutilizables para compartir entre proyectos","Gestionar dependencias para componentes Convex","Exportar componentes Convex para usar en varias aplicaciones"],"fr":["Créer des composants Convex réutilisables pour les partager entre les projets","Gérer les dépendances pour les composants Convex","Exporter des composants Convex pour les utiliser dans plusieurs applications"],"de":["Erstellen von wiederverwendbaren Convex-Komponenten zum Teilen zwischen Projekten","Verwalten von Abhängigkeiten für Convex-Komponenten","Exportieren von Convex-Komponenten zur Verwendung in mehreren Anwendungen"],"pt":["Criar componentes Convex reutilizáveis para compartilhamento entre projetos","Gerenciar dependências para componentes Convex","Exportar componentes Convex para uso em várias aplicações"],"ru":["Создание многократно используемых компонентов Convex для обмена между проектами","Управление зависимостями для компонентов Convex","Экспорт компонентов Convex для использования в нескольких приложениях"],"ar":["إنشاء مكونات Convex قابلة لإعادة الاستخدام للمشاركة عبر المشاريع","إدارة التبعيات لمكونات Convex","تصدير مكونات Convex لاستخدامها في تطبيقات متعددة"]},"limitations":{"en":["Requires knowledge of Convex component authoring documentation","Dependent on Convex platform"],"zh":["需要Convex组件编写文档的知识","依赖于Convex平台"],"ja":["Convexコンポーネントの作成文書の知識が必要","Convexプラットフォームに依存"],"ko":["Convex 컴포넌트 작성 문서에 대한 지식이 필요","Convex 플랫폼에 의존"],"es":["Requiere conocimiento de la documentación de autoría de componentes Convex","Dependiente de la plataforma Convex"],"fr":["Nécessite une connaissance de la documentation d''authoring des composants Convex","Dépend de la plate-forme Convex"],"de":["Benötigt Kenntnisse der Convex-Komponenten-Autoren-Dokumentation","Abhängig von der Convex-Plattform"],"pt":["Exige conhecimento da documentação de autorização de componentes Convex","Dependente da plataforma Convex"],"ru":["Требует знания документации по созданию компонентов Convex","Зависит от платформы Convex"],"ar":["يتطلب معرفة وثائق تأليف مكونات Convex","يعتمد على منصة Convex"]},"version":4},"contentHash":"561346aded0969635fc3f32ae6d465f882266b6be20b4038c7a55645ff6db7c2","qualityScore":70}');
