INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('blocknavi/convex-batch-processor/convex-component-authoring', 'convex-component-authoring', 'blocknavi', 'convex-batch-processor', 'community', 'convex-component-authoring blocknavi convex-batch-processor community Convex-component-authoring enables developers to create reusable Convex components with proper isolation, exports, and dependency management. This skill benefits developers working on projects that require sharing components across projects. Convex 组件创建允许开发者创建自包含、可重用的组件，实现跨项目的共享和复用 Convex コンポーネント作成は、開発者が自己完結的で再利用可能なコンポーネントを作成できるようにします Convex 컴포넌트 작성은 개발자가 독립적이고 재사용 가능한 컴포넌트를 작성할 수 있게 해줍니다 Convex component authoring permite crear componentes reutilizables con aislamiento y gestión de dependencias L''authoring de composants convexes permet de créer des composants réutilisables avec isolation et gestion de dépendances Convex-Komponentenauthoring ermöglicht die Erstellung von wiederverwendbaren Komponenten mit Isolation und Abhängigkeitsverwaltung Convex Component Authoring permite criar componentes reutilizáveis com isolamento e gerenciamento de dependências Convex Component Authoring позволяет создавать самодостаточные компоненты с изоляцией и управлением зависимостями Convex Component Authoring يسمح بإنشاء مكونات قابلة لإعادة الاستخدام مع العزل وإدارة التبعيات how to use convex-component-authoring convex-component-authoring setup guide convex-component-authoring vs other component authoring tools convex-component-authoring install what is convex-component-authoring convex-component-authoring documentation convex-component-authoring tutorial convex-component-authoring best practices Convex 组件创建 Convex 组件管理 跨项目共享 组件复用 Convex 官方文档 依赖管理 导出功能 Creates self-contained Convex components with proper isolation Supports exports and dependency management for sharing across projects Utilizes documentation from https://docs.convex.dev/components for implementation Follows guidelines from https://docs.convex.dev/components/authoring for authoring References broader context from https://docs.convex.dev/llms.txt for additional information Convex-component-authoring is a technique for creating self-contained, reusable Convex components with proper isolation, exports, and dependency management for sharing across projects.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('gamingopgamingop/sarthak-skill-forge/azure-diagrams', 'community', 'gamingopgamingop', 'sarthak-skill-forge', 'gamingopgamingop/sarthak-skill-forge', 'azure-diagrams', 0, 0, 70, '2026-03-08T01:57:15.332Z', '2026-03-08T02:03:13.933Z', '7a2a9640b208428d82d03e5ab5929f26919f68b11996b73fd9c9b5a3b39058b8', '{"id":"gamingopgamingop/sarthak-skill-forge/azure-diagrams","name":"azure-diagrams","description":{"en":"The azure-diagrams skill generates architecture diagrams for Azure infrastructure from ARM templates, Azure CLI output, or natural language descriptions, benefiting developers and architects. It visualizes Azure resources, including Virtual Machines, Storage Accounts, and VNets.","zh":"Azure Diagram Generator 是一种从 ARM 模板、Azure CLI 输出或自然语言描述生成 Azure 基础设施图的工具。它支持多种输入格式，包括 JSON 和 Azure CLI 输出","ja":"Azure Diagram Generator は、ARM テンプレート、Azure CLI 出力、または自然言語の説明から Azure インフラストラクチャ図を生成するツールです。多くの入力形式をサポートしています","ko":"Azure Diagram Generator는 ARM 템플릿, Azure CLI 출력 또는 자연어 설명에서 Azure 인프라스트럭처 다이어그램을 생성하는 도구입니다. JSON 및 Azure CLI 출력과 같은 여러 입력 형식을 지원합니다","es":"Azure-diagrams es una herramienta que genera diagramas de arquitectura de Azure desde plantillas ARM, salida de Azure CLI o descripciones en lenguaje natural","fr":"Azure-diagrams est un outil qui génère des diagrammes d''architecture Azure à partir de modèles ARM, de sortie Azure CLI ou de descriptions en langage naturel","de":"Azure-diagrams ist ein Tool, das Azure-Architekturdiagramme aus ARM-Vorlagen, Azure-CLI-Ausgaben oder natürlichen Sprachbeschreibungen erstellt","pt":"O Azure Diagrams gera diagramas de arquitetura de infraestrutura do Azure a partir de modelos ARM, saída do Azure CLI ou descrições em linguagem natural","ru":"Azure Diagrams генерирует диаграммы архитектуры инфраструктуры Azure из шаблонов ARM, вывода Azure CLI или описаний на естественном 