INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('chathuraed/existing_project/formik', 'formik', 'chathuraed', 'existing_project', 'community', 'formik chathuraed existing_project community formik is a popular open-source form library for React, helping developers manage form state, validation, and submission. It benefits developers building complex React applications. formik是一种用于构建和管理React表单的库，提供了强大的验证、状态管理和异步提交功能 FormikはReactフォームを構築するためのライブラリで、強力なバリデーション、ステート管理、非同期送信機能を提供します formik은 리액트 폼을 구축하고 관리하는 라이브러리로서 강력한 유효성 검사, 상태 관리, 비동기 제출 기능을 제공합니다 Formik es una biblioteca de formularios para React que simplifica la creación de formularios complejos con validación y gestión de estado Formik est une bibliothèque de formulaires pour React qui simplifie la création de formulaires complexes avec validation et gestion d''état Formik ist eine Formularbibliothek für React, die die Erstellung komplexer Formulare mit Validierung und Zustandsverwaltung vereinfacht O Formik é uma biblioteca de formulários para React que simplifica a criação de formulários complexos Formik - это библиотека форм для React, которая упрощает создание сложных форм .Formik هو مكتبة لإنشاء نماذج React التي تبسط إنشاء النماذج المعقدة how to use formik formik vs react-hook-form formik install formik setup guide what is formik formik alternative formik validation formik react forms formik tutorial formik react表单 表单验证 状态管理 异步提交 formik教程 react表单构建 Handles form validation with or without Yup Manages form state, field values, and errors Supports complex form patterns like arrays and nested objects Enables async form submissions Allows building custom form components with Formik hooks Optimizes form performance formik is an open-source form library for React, used for building, validating, and managing forms in React applications.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('waynesutton/convexskills/convex-http-actions', 'community', 'waynesutton', 'convexskills', 'waynesutton/convexskills', 'convex-http-actions', 0, 0, 70, '2026-03-08T01:57:15.577Z', '2026-03-08T02:11:48.896Z', '8db2fb7582555411c20d89212d5c6ab805fbb2bbeb6e3b713f82befff50436d6', '{"id":"waynesutton/convexskills/convex-http-actions","name":"convex-http-actions","description":{"en":"Convex-http-actions provides AI agent skills and templates for building production-ready apps with Convex, supporting HTTP endpoints, queries, mutations, and more. It benefits developers building custom Convex applications.","zh":"Convex HTTP Actions 提供了构建生产就绪应用的 AI 代理技能和模板，包括 HTTP 端点、Webhook 集成和自定义路由","ja":"Convex HTTP Actions は、プロダクションレディのアプリを作成するための AI エージェントスキルとテンプレートを提供します","ko":"Convex HTTP Actions 는 프로덕션 레디 애플리케이션을 구축하기 위한 AI 에이전트 스킬과 템플릿을 제공합니다","es":"Convex-http-actions es un conjunto de habilidades y plantillas de AI para construir aplicaciones web listas para producción con Convex, incluyendo patrones para consultas, mutaciones, trabajos cron, webhooks y más","fr":"Convex-http-actions est un ensemble de compétences et de modèles d''IA pour construire des applications web prêtes pour la production avec Convex, y compris des modèles pour les requêtes, les mutations, les travaux cron, les webhooks et plus encore","de":"Convex-http-actions ist ein Satz von Fähigkeiten und Vorlagen für künstliche Intelligenz, um Webanwendungen mit Convex bereitzustellen, einschließlich Muster für Abfragen, Mutationen, Cron-Jobs, Webhooks und mehr","pt":"Convex HTTP Actions permite criar endpoints HTTP para webhooks, integrações de API e rotas personalizadas","ru":"Convex HTTP Actions позволяет создавать HTTP-конечные точки для вебхуков, интеграций API и пользовательских маршрутов","ar":"Convex HTTP Actions يسمح بإنشاء نهايات HTTP للويب هوك وتكا