INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('waynesutton/convexskills/convex-http-actions', 'convex-http-actions', 'waynesutton', 'convexskills', 'community', 'convex-http-actions waynesutton convexskills community Convex-http-actions provides AI agent skills and templates for building production-ready apps with Convex, supporting HTTP endpoints, queries, mutations, and more. It benefits developers building custom Convex applications. Convex HTTP Actions 提供了构建生产就绪应用的 AI 代理技能和模板，包括 HTTP 端点、Webhook 集成和自定义路由 Convex HTTP Actions は、プロダクションレディのアプリを作成するための AI エージェントスキルとテンプレートを提供します Convex HTTP Actions 는 프로덕션 레디 애플리케이션을 구축하기 위한 AI 에이전트 스킬과 템플릿을 제공합니다 Convex-http-actions es un conjunto de habilidades y plantillas de AI para construir aplicaciones web listas para producción con Convex, incluyendo patrones para consultas, mutaciones, trabajos cron, webhooks y más Convex-http-actions est un ensemble de compétences et de modèles d''IA pour construire des applications web prêtes pour la production avec Convex, y compris des modèles pour les requêtes, les mutations, les travaux cron, les webhooks et plus encore Convex-http-actions ist ein Satz von Fähigkeiten und Vorlagen für künstliche Intelligenz, um Webanwendungen mit Convex bereitzustellen, einschließlich Muster für Abfragen, Mutationen, Cron-Jobs, Webhooks und mehr Convex HTTP Actions permite criar endpoints HTTP para webhooks, integrações de API e rotas personalizadas Convex HTTP Actions позволяет создавать HTTP-конечные точки для вебхуков, интеграций API и пользовательских маршрутов Convex HTTP Actions يسمح بإنشاء نهايات HTTP للويب هوك وتكاملات API والطرق المخصصة convex-http-actions setup guide how to use convex-http-actions convex-http-actions vs convex-functions convex-http-actions install what is convex-http-actions convex-http-actions alternative convex-http-actions documentation convex-http-actions tutorial convex-http-actions examples convex-http-actions best practices Convex HTTP Actions AI 工具 HTTP 端点 Webhook 集成 自定义路由 cron 作业 迁移 Builds HTTP endpoints for webhooks and external API integrations Supports queries, mutations, cron jobs, and migrations in Convex applications Utilizes Convex functions for custom routes and HTTP actions Follows documentation from https://docs.convex.dev/functions/http-actions Enables authentication via https://docs.convex.dev/auth Provides patterns for production-ready app development convex-http-actions is a set of AI agent skills and templates for building production-ready Convex applications with HTTP endpoints, webhooks, and custom routes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ksmuvva/Multi-Agent--Council/code-generation', 'community', 'ksmuvva', 'Multi-Agent--Council', 'ksmuvva/Multi-Agent--Council', 'code-generation', 0, 0, 70, '2026-03-07T20:32:44Z', '2026-03-08T02:17:43.168Z', 'a1fcaa4d318ef1812a926f0f92d966e4483bcebf23c50e9cb831aa0e204af91c', '{"id":"ksmuvva/Multi-Agent--Council/code-generation","name":"code-generation","description":{"en":"The code-generation skill generates production-quality code that is clean, secure, maintainable, and well-tested, benefiting developers and AI agents alike.","zh":"代码生成工具可以帮助您创建高质量的代码，具有清晰的命名、单一职责和安全性","ja":"コード生成AIエージェントは、クリーンでセキュアなコードを生成するために役立ちます","ko":"코드 생성 도구는 깨끗하고 안전한 코드를 생성하여 개발자에게 도움을 줍니다","pt":"Geração de código de produção de alta qualidade com clean code, segurança e testes","ru":"Создание производственного кодирования с чистым кодом, безопасностью и тестированием","ar":"توليد كود إنتاجي عالي الجودة مع كود نظيف وأمان وتجارب"},"seo":{"title":{"en":"Code-Generation: Best Practices for AI Agents | AI Agent ...","zh":"代码生成工具设置指南","ja":"コード生成AIエージェントのベストプラクティス","ko":"코드 생성 도구 구축 가이드","pt":"Guia de Configuração de Geração de Código com Ferramentas...","ru":"ИИ Агенты: Руководство по Созданию Производственного Коди...","ar":"دليل ضبط توليد الكود باستخدام أدوات الذكاء الاصطناعي"},"description":{"en":"Unlock production-quality code with code-generation skill. Discover how to write clean, secure, and maintainable code with expert tips and tricks. Get starte...","zh":"学习如何使用代码生成工具创建干净、安全、可维护的代码，提升开发效率","ja":"コード生成AIエージェントを使用して、クリーンでセキュアなコードを生成する方法を学びましょう","ko":"코드 생성 도구를 사용하여 깨끗하고 안전하고 유지 보수가 쉬운 코드를 생성하는 방법을 알아보세요","pt":"Aprenda a criar código de produção de alta qualidade com as melhores práticas de geração de código e segurança","ru":"Создавайте производственный код с помощью ИИ Агентов и следуйте лучшим практикам кодирования и безопасности","ar":"تعلم كيفية إنشاء كود إنتاجي عالي الجودة باستخدام أفضل الممارسات لتوليد الكود والأمان"},"definition":{"en":"Code-generation is the process of creating production-quality code that adheres to clean code principles, security best practices, and maintainability standards.","zh":"代码生成是指使用AI工具生成生产级别的代码的过程","ja":"コード生成は、AIエージェントを使用して生産レベルのコードを生成するプロセスです","ko":"코드 생성은 AI 도구를 사용하여 생산 수준의 코드를 생성하는 과정입니다","pt":"Geração de código é a capacidade de criar código de produção de alta qualidade automaticamente","ru":"Генерация кода - это способность создавать производственный код высокого качества автоматически","ar":"توليد الكود هو القدرة على إنشاء كود إنتاجي عالي الجودة تلقائيا"},"features":{"en":["Generates code with meaningful names and single responsibility functions","Applies DRY principle to extract common patterns and reduce repetition","Includes comments that explain ''why'' instead of ''what'' for self-documenting code","Prioritizes security first with robust and secure coding practices","Produces well-tested code with high-quality testing standards"],"zh":["生成干净的代码，具有有意义的命名和单一职责","支持安全性优先的代码生成，防止常见的安全漏洞","遵循DRY原则，减少代码重复","生成自文档代码，减少注释的需要","支持多种编程语言和框架"],"ja":["クリーンなコードを生成し、意味のある名前と単一の責任を持たせる","セキュリティを優先したコード生成をサポートし、一般的なセキュリティの欠陥を防ぐ","DRY原則に従い、コードの重複を減らす","自文書化コードを生成し、コメントの必要性を減らす","複数のプログラミング言語とフレームワークをサポート"],"ko":["깨끗한 코드를 생성하여 의미 있는 이름과 단일 책임을 부여","보안을 우선하는 코드 생성을 지원하여 일반적인 보안 허점을 방지","DRY 원칙을 따르며 코드 중복을 줄임","자체 문서화 코드를 생성하여 주석의 필요성을 줄임","다수의 프로그래밍 언어와 프레임워크를 지원"],"pt":["Clean code com nomes significativos e responsabilidades únicas","Segurança em primeiro lugar com extração de padrões comuns","DRY principle para evitar repetição de código","Comentários que explicam o porquê, não o que","Código auto-documentado para facilitar a manutenção"],"ru":["Чистый код с осмысленными именами и единственной ответственностью","Безопасность на первом месте с извлечением общих шаблонов","Принцип DRY для избежания повторения кода","Комментарии, объясняющие почему, а не что","Самодокументирующийся код для облегчения поддержки"],"ar":["كود نظيف مع أسماء ذات معنى ومسؤوليات فريدة","أولوية الأمان مع استخراج أنماط مشتركة","مبدأ DRY لتجنب تكرار الكود","تعليقات توضح почему، لا ما","كود自ي توثيق للسهولة في الصيانة"]},"keywords":{"en":["how to use code-generation","code-generation best practices","code-generation alternative","code-generation vs manual coding","code-generation setup guide","code-generation for AI agents"],"zh":["代码生成工具","AI代码生成","代码质量","安全性优先","DRY原则","自文档代码","代码生成框架","编程语言支持"],"ja":["コード生成AIエージェント","コード生成ツール","コード品質","セキュリティを優先","DRY原則","自文書化コード","コード生成フレームワーク","プログラミング言語サポート"],"ko":["코드 생성 도구","AI 코드 생성","코드 품질","보안을 우선","DRY 원칙","자체 문서화 코드","코드 생성 프레임워크","프로그래밍 언어 지원"],"pt":["geração de código","ferramentas de ia","clean code","segurança em primeiro lugar","dry principle","comentários de código","código auto-documentado","desenvolvimento de software","engenharia de software"],"ru":["генерация кода","ИИ Агенты","чистый код","безопасность на первом месте","принцип DRY","комментарии кода","самодокументирующийся код","разработка программного обеспечения","инженерия программного обеспечения"],"ar":["توليد الكود","أدوات الذكاء الاصطناعي","كود نظيف","أولوية الأمان","مبدأ DRY","تعليقات الكود","كود自ي توثيق","تطوير البرمجيات","هندسة البرمجيات"]}},"owner":"ksmuvva","repo":"Multi-Agent--Council","repoPath":"ksmuvva/Multi-Agent--Council","stars":0,"forks":0,"updatedAt":"2026-03-07T20:32:44Z","topics":[],"category":"community","skillMd":{"name":"code-generation","description":"Best practices and patterns for generating clean, secure, maintainable code","version":"1.0.0","tags":["code","programming","security","testing","best-practices"],"bodyPreview":"# Code Generation Skill\n\nYou are an expert in **generating production-quality code** that is clean, secure, maintainable, and well-tested.\n\n## Code Quality Principles\n\n### 1. Clean Code\n\n- **Meaningful names**: Variables, functions, classes describe their purpose\n- **Single responsibility**: Each function does one thing well\n- **DRY principle**: Don''t repeat yourself - extract common patterns\n- **Comments**: Explain \"why\", not \"what\" - code should be self-documenting\n\n### 2. Security First\n\n```p","body":"# Code Generation Skill\n\nYou are an expert in **generating production-quality code** that is clean, secure, maintainable, and well-tested.\n\n## Code Quality Principles\n\n### 1. Clean Code\n\n- **Meaningful names**: Variables, functions, classes describe their purpose\n- **Single responsibility**: Each function does one thing well\n- **DRY principle**: Don''t repeat yourself - extract common patterns\n- **Comments**: Explain \"why\", not \"what\" - code should be self-documenting\n\n### 2. Security First\n\n```python\n# ❌ BAD - Hardcoded credentials\npassword = \"admin123\"\n\n# ✅ GOOD - Environment variables\npassword = os.getenv(\"DB_PASSWORD\")\nif not password:\n    raise ValueError(\"DB_PASSWORD not set\")\n```\n\n### 3. Error Handling\n\n```python\n# Specific exceptions, not bare except\ntry:\n    result = risky_operation()\nexcept ValueError as e:\n    logger.error(f\"Invalid input: {e}\")\n    raise\nexcept Exception as e:\n    logger.exception(f\"Unexpected error: {e}\")\n    raise\n```\n\n### 4. Type Hints\n\n```python\nfrom typing import List, Optional\n\ndef process_items(\n    items: List[str],\n    threshold: Optional[int] = None\n) -> dict[str, int]:\n    \"\"\"Process items and return statistics.\"\"\"\n    # Implementation...\n```\n\n## Language-Specific Guidelines\n\n### Python\n\n- Follow PEP 8 style guide\n- Use type hints (Python 3.9+)\n- Prefer dataclasses over classes for data containers\n- Use context managers for resource management\n- Avoid mutable default arguments\n\n### JavaScript/TypeScript\n\n- Use `const` and `let`, never `var`\n- Prefer arrow functions for callbacks\n- Use template literals for string interpolation\n- Async/await over promise chains\n- JSDoc for function documentation\n\n### Go\n\n- Error handling: never ignore errors\n- Use goroutines sparingly\n- Prefer interfaces over concrete types\n- Keep goroutines lightweight\n- Use channels for communication\n\n## Code Structure\n\n### File Organization\n\n```\nsrc/\n├── __init__.py\n├── models.py          # Data models\n├── services.py         # Business logic\n├── repositories.py     # Data access\n├── schemas.py          # Validation schemas\n├── utils.py            # Utilities\n└── config.py           # Configuration\n```\n\n### Function Template\n\n```python\ndef function_name(\n    param1: type,\n    param2: type,\n    optional_param: type = default_value,\n) -> return_type:\n    \"\"\"Brief description of function.\n\n    Args:\n        param1: Description of param1\n        param2: Description of param2\n        optional_param: Description of optional param\n\n    Returns:\n        Description of return value\n\n    Raises:\n        SpecificException: When condition occurs\n\n    Example:\n        >>> result = function_name(\"test\", 42)\n        >>> print(result)\n        ''output''\n    \"\"\"\n    # Implementation\n    pass\n```\n\n## Security Checklist\n\n- [ ] No hardcoded credentials\n- [ ] Input validation on all user inputs\n- [ ] Parameterized queries for database\n- [ ] Output encoding to prevent XSS\n- [ ] Proper error handling (no info leakage)\n- [ ] Principle of least privilege for permissions\n- [ ] Secrets in environment variables\n- [ ] Dependency security scanning\n\n## Testing Guidelines\n\n### Unit Tests\n\n```python\ndef test_function_success_case():\n    \"\"\"Test the happy path.\"\"\"\n    result = function_name(\"valid_input\", 10)\n    assert result.status == \"success\"\n\ndef test_function_edge_case():\n    \"\"\"Test edge conditions.\"\"\"\n    result = function_name(\"\", 0)\n    assert result.status == \"invalid\"\n\ndef test_function_error_handling():\n    \"\"\"Test error cases.\"\"\"\n    with pytest.raises(ValueError):\n        function_name(\"invalid\", -1)\n```\n\n### Test Coverage\n\n- Aim for 80%+ coverage on critical paths\n- Test success cases, edge cases, and error cases\n- Mock external dependencies\n- Use fixtures for common test data\n\n## Performance Considerations\n\n1. **Algorithm choice**: Use appropriate data structures\n2. **Caching**: Cache expensive operations\n3. **Lazy loading**: Load resources only when needed\n4. **Batching**: Group operations to reduce overhead\n5. **Profiling**: Measure before optimizing\n\n## When to Use This Skill\n\nUse **code-generation** when:\n- Writing implementation code\n- Refactoring existing code\n- Adding new features\n- Creating API endpoints\n- Building data pipelines\n\n## Output Format\n\nGenerate code with:\n1. File path as comment header\n2. Imports organized (stdlib, third-party, local)\n3. Type hints throughout\n4. Docstrings for functions/classes\n5. Example usage in comments\n6. Error handling\n7. Logging where appropriate\n8. Test examples\n"},"lastSynced":"2026-03-08T02:17:43.168Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing advanced code-generation capabilities with clean, secure, and maintainable code","zh":"非常适合需要高级代码生成能力的开发者代理，能够生成干净、安全、可维护的代码","ja":"開発者エージェントが高度なコード生成機能を必要とする場合に最適です。クリーンでセキュアで保守可能なコードを生成できます","ko":"개발자 에이전트가 고급 코드 생성 기능을 필요로 하는 경우에 적합합니다. 깨끗하고 안전하고 유지 보수 가능한 코드를 생성 할 수 있습니다","es":"Perfecto para Agentes de Desarrollador que necesitan capacidades avanzadas de generación de código con código limpio, seguro y mantenible","fr":"Idéal pour les Agents de Développeur ayant besoin de capacités de génération de code avancées avec un code propre, sécurisé et maintenable","de":"Perfekt für Entwickleragenten, die erweiterte Code-Generierungsfunktionen mit sauberem, sicheren und wartbarem Code benötigen","pt":"Perfeito para Agentes de Desenvolvedor que necessitam de capacidades avançadas de geração de código com código limpo, seguro e mantido","ru":"Идеально для агентов-разработчиков, которым необходимы продвинутые возможности генерации кода с чистым, безопасным и поддерживаемым кодом","ar":"مثالي لعميل المطور الذي يحتاج إلى إمكانيات تقديم شفرة متقدمة مع شفرة نظيفة وآمنة وقابلة للصيانة"},"recommendation":{"en":"Empowers agents to generate production-quality code following clean code principles, security-first mindset, and DRY principles, utilizing meaningful names, single responsibility functions, and self-documenting code","zh":"赋予代理生成生产质量的代码，遵循干净的代码原则、以安全为第一的思维方式和DRY原则，使用有意义的名称、单一职责函数和自我记录的代码","ja":"エージェントにクリーンなコードの原則、セキュリティ第一の思考方法、DRY原則に従った生産性の高いコードを生成させることができます。有意義な名前、単一責任関数、セルフドキュメント化コードを使用します","ko":"에이전트가 생산성 있는 코드를 생성 할 수 있도록 해줍니다. 깨끗한 코드 원칙, 보안 우선 사고 방식 및 DRY 원칙을 따르는 코드를 생성합니다. 의미 있는 이름, 단일 책임 함수 및 자기 기록 코드를 사용합니다","es":"Habilita a los agentes para generar código de producción de alta calidad siguiendo los principios de código limpio, una mentalidad de seguridad en primer lugar y los principios DRY, utilizando nombres significativos, funciones de responsabilidad única y código auto-documentado","fr":"Permet aux agents de générer du code de production de haute qualité en suivant les principes de code propre, une mentalité de sécurité en premier et les principes DRY, en utilisant des noms significatifs, des fonctions à responsabilité unique et du code auto-documenté","de":"Ermächtigt die Agenten, Produktionscode hoher Qualität zu generieren, der den Grundsätzen sauberen Codes, einer Sicherheits-First-Mentalität und den DRY-Prinzipien folgt, unter Verwendung aussagekräftiger Namen, Funktionen mit einziger Verantwortung und selbst-dokumentierendem Code","pt":"Habilita os agentes a gerar código de produção de alta qualidade seguindo os princípios de código limpo, mentalidade de segurança em primeiro lugar e princípios DRY, utilizando nomes significativos, funções de responsabilidade única e código auto-documentado","ru":"Наделяет агентов возможностью генерировать код высокого качества, следующий принципам чистого кода, безопасности и принципам DRY, используя осмысленные имена, функции с единственной ответственностью и самодокументирующийся код","ar":"يمنح الوكيل القدرة على توليد رمز الإنتاج عالي الجودة اتباعًا لمبادئ الشفرة النظيفة والمنظور الأمني الأول والأسس الجافة، مع استخدام أسماء ذات مغزى ودالات مسؤولية واحدة ورمز خود وثائق"},"useCases":{"en":["Generating well-structured API clients","Creating secure and maintainable backend services","Developing clean and efficient data processing pipelines"],"zh":["生成结构良好的API客户端","创建安全且可维护的后端服务","开发干净且高效的数据处理管道"],"ja":["構造化されたAPIクライアントを生成する","セキュアで保守可能なバックエンドサービスを作成する","クリーンで効率的なデータ処理パイプラインを開発する"],"ko":["잘 구조화된 API 클라이언트를 생성하는 것","보안이 뛰어난 백엔드 서비스를 생성하는 것","깨끗하고 효율적인 데이터 처리 파이프라인을 개발하는 것"],"es":["Generación de clientes de API bien estructurados","Creación de servicios de backend seguros y mantenibles","Desarrollo de tuberías de procesamiento de datos limpias y eficientes"],"fr":["Génération de clients d''API bien structurés","Création de services de backend sécurisés et maintenables","Développement de pipelines de traitement de données propres et efficaces"],"de":["Generierung von gut strukturierten API-Clients","Erstellung von sicheren und wartbaren Backend-Diensten","Entwicklung von sauberen und effizienten Datenverarbeitungspipelines"],"pt":["Geração de clientes API bem estruturados","Criação de serviços de backend seguros e mantidos","Desenvolvimento de pipelines de processamento de dados limpos e eficientes"],"ru":["Генерация хорошо структурированных клиентов API","Создание безопасных и поддерживаемых сервисов бэкэнда","Разработка чистых и эффективных конвейеров обработки данных"],"ar":["توليد عميل واجهة برمجة التطبيقات محسّن الهيكل","إنشاء خدمات الخلفية الآمنة والقابلة للصيانة","تطوير أنابيب معالجة البيانات النظيفة والفعالة"]},"limitations":{"en":["Requires programming language support","Dependent on specific code quality principles and security standards"],"zh":["需要编程语言支持","依赖于特定的代码质量原则和安全标准"],"ja":["プログラミング言語のサポートが必要","特定のコード品質原則とセキュリティ標準に依存する"],"ko":["프로그래밍 언어 지원이 필요하다","특정 코드 품질 원칙 및 보안 표준에 의존한다"],"es":["Requiere soporte de lenguaje de programación","Dependiente de principios de calidad de código y normas de seguridad específicas"],"fr":["Nécessite un support de langage de programmation","Dépendante de principes de qualité de code et de normes de sécurité spécifiques"],"de":["Benötigt Programmiersprachunterstützung","Abhängig von spezifischen Code-Qualitätsprinzipien und Sicherheitsstandards"],"pt":["Exige suporte de linguagem de programação","Dependente de princípios específicos de qualidade de código e padrões de segurança"],"ru":["Требует поддержки языка программирования","Зависит от конкретных принципов качества кода и стандартов безопасности"],"ar":["يتطلب دعم لغة البرمجة","يعتمد على مبادئ محددة لجودة الشفرة ومعايير الأمن"]},"version":4},"contentHash":"a1fcaa4d318ef1812a926f0f92d966e4483bcebf23c50e9cb831aa0e204af91c","qualityScore":70}');
