INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dbjpanda/convex-tenants/convex-component-authoring', 'convex-component-authoring', 'dbjpanda', 'convex-tenants', 'community', 'convex-component-authoring dbjpanda convex-tenants community Convex 组件作者是一个多租户组织和团队管理组件，内置 @djpanda/convex-authz 授权 Convex コンポーネント作成は、マルチテナント組織とチーム管理コンポーネントで、@djpanda/convex-authz を使用した認可が組み込まれています Convex 컴포넌트 작성은 멀티 테넌트 조직 및 팀 관리 컴포넌트로 @djpanda/convex-authz를 사용한 인가 기능이 내장되어 있습니다 El componente de autorización de convex-component-authoring es una herramienta para la gestión de equipos y organizaciones multi-tenant en Convex Le composant d''autorisation de convex-component-authoring est un outil pour la gestion d''équipes et d''organisations multi-tenant dans Convex Das Convex-Komponenten-Autorisierungselement ist ein Werkzeug für das multi-tenant-fähige Team- und Organisationsmanagement in Convex O Convex Component Authoring é um componente de gerenciamento de equipes e organizações multi-tenant com autorização via @djpanda/convex-authz Convex Component Authoring — это компонент управления командами и организациями с поддержкой нескольких арендаторов и встроенной авторизацией через @djpanda/convex-authz مكون Convex Authoring هو مكون لإدارة الفرق والمنظمات متعدد المستأجرين مع نظام تفويض عبر @djpanda/convex-authz A multi-tenant organization and team management component for Convex with built-in authorization via @djpanda/convex-authz Convex 组件作者 AIエージェント 多租户组织管理 团队管理 Convex 组件 如何使用 Convex Convex 介绍 Convex 安装 Convex 教程 A multi-tenant organization and team management component for Convex with built-in authorization via @djpanda/convex-authz');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('anthropics/skills/canvas-design', 'official', 'anthropics', 'skills', 'anthropics/skills', 'canvas-design', 85097, 8974, 70, '2026-03-06T03:11:21Z', '2026-03-06T03:14:04.272Z', 'a1f288079624402f30682753c1d43920b6664785698d21d3e7aa197450a6448b', '{"id":"anthropics/skills/canvas-design","name":"canvas-design","description":{"en":"The canvas-design skill creates beautiful visual art in .png and .pdf documents using design philosophy, benefiting developers and artists alike.","zh":"Canvas-Design AI代理技能通过两步流程创建视觉艺术：首先制定设计哲学，然后将其表达为.png或.pdf文件。它专注于形式、空间、色彩和构图等美学元素，确保输出原创且无版权问题。","ja":"Canvas-Design AIエージェントスキルは、2段階のプロセスでビジュアルアートを作成します：まずデザイン哲学を策定し、次に.pngまたは.pdfファイルとして表現します。形態、空間、色彩、構図などの美的要素に焦点を当て、オリジナルで著作権問題のない出力を保証します。","ko":"Canvas-Design AI 에이전트 스킬은 두 단계 프로세스로 시각 아트를 생성합니다: 먼저 디자인 철학을 수립한 후 .png 또는 .pdf 파일로 표현합니다. 형태, 공간, 색상, 구도 등 미학 요소에 초점을 맞추어 오리지널이고 저작권 문제가 없는 출력을 보장합니다.","es":"La skill canvas-design permite a los desarrolladores integrar la generación de arte visual mediante agentes IA. Crea diseños originales en formatos PNG y PDF basados en filosofías de diseño propias, evitando el uso de obras existentes para prevenir problemas de copyright. Ideal para posters, gráf...","fr":"La compétence canvas-design permet aux développeurs de générer de l''art visuel via des agents IA. Produisez des designs originaux en PNG et PDF en créant des philosophies de design uniques, sans copier des œuvres existantes pour éviter le copyright. Parfait pour les affiches et graphiques.","de":"Die canvas-design-Skill ermöglicht Entwicklern die Generierung von visueller Kunst durch KI-Agenten. Erstellen Sie originale Designs in PNG und PDF basierend auf eigenen Designphilosophien, ohne bestehende Werke zu kopieren. Ideal für Poster und Grafiken.","pt":"A skill canvas-design permite que Agentes de IA criem arte visual programaticamente, gerando arquivos .png e .pdf com base em filosofias de design únicas. Ela opera em um fluxo de duas etapas: criação da filosofia e renderização visual.","ru":"Навык canvas-design позволяет ИИ Агентам программно создавать визуальное искусство, генерируя файлы .png и .pdf на основе уникальных философий дизайна. Он работает в два этапа: создание философии и визуальная реализация.","ar":"تمكن مهارة canvas-design أدوات الذكاء الاصطناعي من إنشاء الفن البصري برمجياً، وتوليد ملفات .png و .pdf بناءً على فلسفات تصميم فريدة. تعمل من خلال مرحلتين: إنشاء الفلسفة والتعبير المرئي."},"owner":"anthropics","repo":"skills","repoPath":"anthropics/skills","stars":85097,"forks":8974,"updatedAt":"2026-03-06T03:11:21Z","topics":["agent-skills"],"skillMd":{"name":"canvas-design","description":"Create beautiful visual art in .png and .pdf documents using design philosophy. You should use this skill when the user asks to create a poster, piece of art, design, or other static piece. Create original visual designs, never copying existing artists work to avoid copyright violations.","bodyPreview":"These are instructions for creating design philosophies - aesthetic movements that are then EXPRESSED VISUALLY. Output only .md files, .pdf files, and .png files.\n\nComplete this in two steps:\n1. Design Philosophy Creation (.md file)\n2. Express by creating it on a canvas (.pdf file or .png file)\n\nFirst, undertake this task:\n\n## DESIGN PHILOSOPHY CREATION\n\nTo begin, create a VISUAL PHILOSOPHY (not layouts or templates) that will be interpreted through:\n- Form, space, color, composition\n- Images, g","body":"These are instructions for creating design philosophies - aesthetic movements that are then EXPRESSED VISUALLY. Output only .md files, .pdf files, and .png files.\n\nComplete this in two steps:\n1. Design Philosophy Creation (.md file)\n2. Express by creating it on a canvas (.pdf file or .png file)\n\nFirst, undertake this task:\n\n## DESIGN PHILOSOPHY CREATION\n\nTo begin, create a VISUAL PHILOSOPHY (not layouts or templates) that will be interpreted through:\n- Form, space, color, composition\n- Images, graphics, shapes, patterns\n- Minimal text as visual accent\n\n### THE CRITICAL UNDERSTANDING\n- What is received: Some subtle input or instructions by the user that should be taken into account, but used as a foundation; it should not constrain creative freedom.\n- What is created: A design philosophy/aesthetic movement.\n- What happens next: Then, the same version receives the philosophy and EXPRESSES IT VISUALLY - creating artifacts that are 90% visual design, 10% essential text.\n\nConsider this approach:\n- Write a manifesto for an art movement\n- The next phase involves making the artwork\n\nThe philosophy must emphasize: Visual expression. Spatial communication. Artistic interpretation. Minimal words.\n\n### HOW TO GENERATE A VISUAL PHILOSOPHY\n\n**Name the movement** (1-2 words): \"Brutalist Joy\" / \"Chromatic Silence\" / \"Metabolist Dreams\"\n\n**Articulate the philosophy** (4-6 paragraphs - concise but complete):\n\nTo capture the VISUAL essence, express how the philosophy manifests through:\n- Space and form\n- Color and material\n- Scale and rhythm\n- Composition and balance\n- Visual hierarchy\n\n**CRITICAL GUIDELINES:**\n- **Avoid redundancy**: Each design aspect should be mentioned once. Avoid repeating points about color theory, spatial relationships, or typographic principles unless adding new depth.\n- **Emphasize craftsmanship REPEATEDLY**: The philosophy MUST stress multiple times that the final work should appear as though it took countless hours to create, was labored over with care, and comes from someone at the absolute top of their field. This framing is essential - repeat phrases like \"meticulously crafted,\" \"the product of deep expertise,\" \"painstaking attention,\" \"master-level execution.\"\n- **Leave creative space**: Remain specific about the aesthetic direction, but concise enough that the next Claude has room to make interpretive choices also at a extremely high level of craftmanship.\n\nThe philosophy must guide the next version to express ideas VISUALLY, not through text. Information lives in design, not paragraphs.\n\n### PHILOSOPHY EXAMPLES\n\n**\"Concrete Poetry\"**\nPhilosophy: Communication through monumental form and bold geometry.\nVisual expression: Massive color blocks, sculptural typography (huge single words, tiny labels), Brutalist spatial divisions, Polish poster energy meets Le Corbusier. Ideas expressed through visual weight and spatial tension, not explanation. Text as rare, powerful gesture - never paragraphs, only essential words integrated into the visual architecture. Every element placed with the precision of a master craftsman.\n\n**\"Chromatic Language\"**\nPhilosophy: Color as the primary information system.\nVisual expression: Geometric precision where color zones create meaning. Typography minimal - small sans-serif labels letting chromatic fields communicate. Think Josef Albers'' interaction meets data visualization. Information encoded spatially and chromatically. Words only to anchor what color already shows. The result of painstaking chromatic calibration.\n\n**\"Analog Meditation\"**\nPhilosophy: Quiet visual contemplation through texture and breathing room.\nVisual expression: Paper grain, ink bleeds, vast negative space. Photography and illustration dominate. Typography whispered (small, restrained, serving the visual). Japanese photobook aesthetic. Images breathe across pages. Text appears sparingly - short phrases, never explanatory blocks. Each composition balanced with the care of a meditation practice.\n\n**\"Organic Systems\"**\nPhilosophy: Natural clustering and modular growth patterns.\nVisual expression: Rounded forms, organic arrangements, color from nature through architecture. Information shown through visual diagrams, spatial relationships, iconography. Text only for key labels floating in space. The composition tells the story through expert spatial orchestration.\n\n**\"Geometric Silence\"**\nPhilosophy: Pure order and restraint.\nVisual expression: Grid-based precision, bold photography or stark graphics, dramatic negative space. Typography precise but minimal - small essential text, large quiet zones. Swiss formalism meets Brutalist material honesty. Structure communicates, not words. Every alignment the work of countless refinements.\n\n*These are condensed examples. The actual design philosophy should be 4-6 substantial paragraphs.*\n\n### ESSENTIAL PRINCIPLES\n- **VISUAL PHILOSOPHY**: Create an aesthetic worldview to be expressed through design\n- **MINIMAL TEXT**: Always emphasize that text is sparse, essential-only, integrated as visual element - never lengthy\n- **SPATIAL EXPRESSION**: Ideas communicate through space, form, color, composition - not paragraphs\n- **ARTISTIC FREEDOM**: The next Claude interprets the philosophy visually - provide creative room\n- **PURE DESIGN**: This is about making ART OBJECTS, not documents with decoration\n- **EXPERT CRAFTSMANSHIP**: Repeatedly emphasize the final work must look meticulously crafted, labored over with care, the product of countless hours by someone at the top of their field\n\n**The design philosophy should be 4-6 paragraphs long.** Fill it with poetic design philosophy that brings together the core vision. Avoid repeating the same points. Keep the design philosophy generic without mentioning the intention of the art, as if it can be used wherever. Output the design philosophy as a .md file.\n\n---\n\n## DEDUCING THE SUBTLE REFERENCE\n\n**CRITICAL STEP**: Before creating the canvas, identify the subtle conceptual thread from the original request.\n\n**THE ESSENTIAL PRINCIPLE**:\nThe topic is a **subtle, niche reference embedded within the art itself** - not always literal, always sophisticated. Someone familiar with the subject should feel it intuitively, while others simply experience a masterful abstract composition. The design philosophy provides the aesthetic language. The deduced topic provides the soul - the quiet conceptual DNA woven invisibly into form, color, and composition.\n\nThis is **VERY IMPORTANT**: The reference must be refined so it enhances the work''s depth without announcing itself. Think like a jazz musician quoting another song - only those who know will catch it, but everyone appreciates the music.\n\n---\n\n## CANVAS CREATION\n\nWith both the philosophy and the conceptual framework established, express it on a canvas. Take a moment to gather thoughts and clear the mind. Use the design philosophy created and the instructions below to craft a masterpiece, embodying all aspects of the philosophy with expert craftsmanship.\n\n**IMPORTANT**: For any type of content, even if the user requests something for a movie/game/book, the approach should still be sophisticated. Never lose sight of the idea that this should be art, not something that''s cartoony or amateur.\n\nTo create museum or magazine quality work, use the design philosophy as the foundation. Create one single page, highly visual, design-forward PDF or PNG output (unless asked for more pages). Generally use repeating patterns and perfect shapes. Treat the abstract philosophical design as if it were a scientific bible, borrowing the visual language of systematic observation—dense accumulation of marks, repeated elements, or layered patterns that build meaning through patient repetition and reward sustained viewing. Add sparse, clinical typography and systematic reference markers that suggest this could be a diagram from an imaginary discipline, treating the invisible subject with the same reverence typically reserved for documenting observable phenomena. Anchor the piece with simple phrase(s) or details positioned subtly, using a limited color palette that feels intentional and cohesive. Embrace the paradox of using analytical visual language to express ideas about human experience: the result should feel like an artifact that proves something ephemeral can be studied, mapped, and understood through careful attention. This is true art. \n\n**Text as a contextual element**: Text is always minimal and visual-first, but let context guide whether that means whisper-quiet labels or bold typographic gestures. A punk venue poster might have larger, more aggressive type than a minimalist ceramics studio identity. Most of the time, font should be thin. All use of fonts must be design-forward and prioritize visual communication. Regardless of text scale, nothing falls off the page and nothing overlaps. Every element must be contained within the canvas boundaries with proper margins. Check carefully that all text, graphics, and visual elements have breathing room and clear separation. This is non-negotiable for professional execution. **IMPORTANT: Use different fonts if writing text. Search the `./canvas-fonts` directory. Regardless of approach, sophistication is non-negotiable.**\n\nDownload and use whatever fonts are needed to make this a reality. Get creative by making the typography actually part of the art itself -- if the art is abstract, bring the font onto the canvas, not typeset digitally.\n\nTo push boundaries, follow design instinct/intuition while using the philosophy as a guiding principle. Embrace ultimate design freedom and choice. Push aesthetics and design to the frontier. \n\n**CRITICAL**: To achieve human-crafted quality (not AI-generated), create work that looks like it took countless hours. Make it appear as though someone at the absolute top of their field labored over every detail with painstaking care. Ensure the composition, spacing, color choices, typography - everything screams expert-level craftsmanship. Double-check that nothing overlaps, formatting is flawless, every detail perfect. Create something that could be shown to people to prove expertise and rank as undeniably impressive.\n\nOutput the final result as a single, downloadable .pdf or .png file, alongside the design philosophy used as a .md file.\n\n---\n\n## FINAL STEP\n\n**IMPORTANT**: The user ALREADY said \"It isn''t perfect enough. It must be pristine, a masterpiece if craftsmanship, as if it were about to be displayed in a museum.\"\n\n**CRITICAL**: To refine the work, avoid adding more graphics; instead refine what has been created and make it extremely crisp, respecting the design philosophy and the principles of minimalism entirely. Rather than adding a fun filter or refactoring a font, consider how to make the existing composition more cohesive with the art. If the instinct is to call a new function or draw a new shape, STOP and instead ask: \"How can I make what''s already here more of a piece of art?\"\n\nTake a second pass. Go back to the code and refine/polish further to make this a philosophically designed masterpiece.\n\n## MULTI-PAGE OPTION\n\nTo create additional pages when requested, create more creative pages along the same lines as the design philosophy but distinctly different as well. Bundle those pages in the same .pdf or many .pngs. Treat the first page as just a single page in a whole coffee table book waiting to be filled. Make the next pages unique twists and memories of the original. Have them almost tell a story in a very tasteful way. Exercise full creative freedom."},"category":"official","lastSynced":"2026-03-06T03:14:04.272Z","seo":{"title":{"en":"canvas-design: Visual Art Creation Setup Guide | AI Agent...","zh":"Canvas-Design AI代理技能：创建原创视觉艺术指南","ja":"Canvas-Design AIエージェントスキル：美的哲学に基づくビジュアル作成","ko":"Canvas-Design AI 에이전트 스킬: 시각적 디자인 철학 구현 가이드","es":"canvas-design: Guía de Implementación para Arte Visual co...","fr":"canvas-design: Guide de Développement pour la Création Ar...","de":"canvas-design: Entwicklerleitfaden für KI-Kunstgenerierung","pt":"canvas-design: Guia de Implementação para Agentes de IA","ru":"canvas-design: Руководство по настройке для ИИ Агентов","ar":"canvas-design: دليل الإعداد لأدوات الذكاء الاصطناعي"},"description":{"en":"Unlock AI-driven visual art creation with canvas-design. Discover how to generate original designs in .png and .pdf formats and learn the design philosophy b...","zh":"Canvas-Design AI代理技能使用设计哲学创建原创.png和.pdf视觉艺术。遵循美学运动原则，通过形式、空间、色彩和构图生成独特设计，避免版权问题。","ja":"Canvas-Design AIエージェントスキルは、デザイン哲学を用いて独自の.pngおよび.pdfビジュアルアートを作成します。美的運動の原則に従い、形態、空間、色彩、構図を通じて独自のデザインを生成し、著作権問題を回避します。","ko":"Canvas-Design AI 에이전트 스킬은 디자인 철학을 사용하여 오리지널 .png 및 .pdf 시각 아트를 생성합니다. 미학 운동 원칙을 따라 형태, 공간, 색상 및 구도를 통해 독특한 디자인을 생성하고 저작권 문제를 방지합니다.","es":"Aprende a usar la skill canvas-design para generar arte visual original en PNG y PDF. Crea filosofías de diseño únicas y evita infracciones de copyright con ...","fr":"Utilisez la compétence canvas-design pour générer des œuvres artistiques originales en PNG et PDF. Créez des philosophies de design uniques avec des agents IA.","de":"Erfahren Sie, wie Sie mit der canvas-design-Skill originale Kunst in PNG und PDF generieren. Erstellen Sie einzigartige Designphilosophien mit KI-Agenten.","pt":"Aprenda a usar a skill canvas-design para seu Agente de IA gerar arte visual original em .png e .pdf. Crie posters e designs com filosofia visual própria, se...","ru":"Узнайте, как использовать навык canvas-design для ИИ Агента для генерации оригинального визуального искусства в .png и .pdf. Создавайте постеры и дизайны с с...","ar":"تعلم كيفية استخدام مهارة canvas-design لأداة الذكاء الاصطناعي لإنشاء فن بصري أصلي بصيغ .png و .pdf. أنشئ ملصقات وتصاميم باستخدام فلسفة بصرية فريدة."},"definition":{"en":"canvas-design is a skill that enables the creation of original visual designs, expressed through form, space, color, and composition, without copying existing artists'' work.","zh":"Canvas-Design是一种AI代理技能，用于基于设计哲学创建原创视觉艺术。它通过分析形式、空间、色彩和构图等美学运动原则，生成.png和.pdf文档，避免复制现有作品以确保版权合规。","ja":"Canvas-Designは、デザイン哲学に基づいてオリジナルのビジュアルアートを作成するAIエージェントスキルです。形態、空間、色彩、構図などの美的運動原則を分析し、.pngおよび.pdf文書を生成し、既存作品の複製を避けて著作権コンプライアンスを確保します。","ko":"Canvas-Design은 디자인 철학을 기반으로 오리지널 시각 아트를 생성하는 AI 에이전트 스킬입니다. 형태, 공간, 색상, 구도 등 미학 운동 원칙을 분석하여 .png 및 .pdf 문서를 생성하고 기존 작품 복제를 피하여 저작권合规성을 보장합니다.","es":"canvas-design es una skill de agente IA que genera arte visual original en formatos PNG y PDF. Utiliza filosofías de diseño propias centradas en forma, color y composición para crear posters y gráficos únicos, evitando infracciones de copyright.","fr":"canvas-design est une compétence d''agent IA qui génère de l''art visuel original en PNG et PDF. Elle utilise des philosophies de design uniques basées sur la forme, la couleur et la composition pour créer des affiches et graphiques sans copyright.","de":"canvas-design ist eine KI-Agenten-Skill zur Generierung von origineller Kunst in PNG und PDF. Sie nutzt eigene Designphilosophien mit Fokus auf Form, Farbe und Komposition zur Erstellung von Postern ohne Urheberrechtsverletzungen.","pt":"canvas-design é uma skill técnica para Agentes de IA que automatiza a criação de arte visual original em documentos .png e .pdf. Ela gera designs baseados em filosofias de design únicas, focando em forma, espaço, cor e composição.","ru":"canvas-design — это технический навык для ИИ Агентов, который автоматизирует создание оригинального визуального искусства в документах .png и .pdf. Он генерирует дизайны на основе уникальных философий дизайна, фокусируясь на форме, пространстве, цвете и композиции.","ar":"canvas-design هي مهارة تقنية لأدوات الذكاء الاصطناعي تُؤتمت إنشاء الفن البصري الأصلي في مستندات .png و .pdf. تولد تصاميمًا تعتمد على فلسفات تصميم فريدة تركز على الشكل والمساحة واللون والتركيب."},"features":{"en":["Creates original visual designs using design philosophy","Generates .png and .pdf files as output","Follows a two-step process: design philosophy creation and visual expression","Utilizes form, space, color, and composition to create unique designs","Avoids copyright violations by not copying existing artists'' work"],"zh":["基于设计哲学生成原创视觉艺术，避免版权问题","支持输出.png和.pdf格式文档","采用两步流程：哲学创建和视觉表达","专注于形式、空间、色彩和构图等美学元素","遵循美学运动原则确保设计独特性","适用于海报、艺术品和其他静态设计创作"],"ja":["デザイン哲学に基づくオリジナルビジュアルアート生成により著作権問題回避",".pngおよび.pdf形式ドキュメントの出力対応","2段階プロセス：哲学作成と視覚的表現","形態、空間、色彩、構図などの美的要素に焦点","美的運動原則に従った独自性の高いデザイン保証","ポスター、アート作品、その他静的デザイン作成に適用"],"ko":["디자인 철학 기반 오리지널 시각 아트 생성으로 저작권 문제 회피",".png 및 .pdf 형식 문서 출력 지원","두 단계 프로세스: 철학 수립과 시각적 표현","형태, 공간, 색상, 구도 등 미학 요소에 초점","미학 운동 원칙 따른 독특한 디자인 보장","포스터, 예술품 및 기타 정적 디자인 제작에 적용"],"es":["Generación de arte visual original en PNG y PDF","Creación de filosofías de diseño únicas con forma, espacio y color","Evita infracciones de copyright al no copiar obras existentes","Flujo de trabajo en dos pasos: filosofía de diseño y expresión visual","Salida en formatos .md, .pdf y .png para desarrolladores","Enfoque en composición y elementos visuales para posters y diseños"],"fr":["Génération d''art visuel original en PNG et PDF","Création de philosophies de design uniques avec forme, espace et couleur","Évite les violations de copyright en ne copiant pas les œuvres existantes","Processus en deux étapes : philosophie de design et expression visuelle","Sortie en formats .md, .pdf et .png pour les développeurs","Concentration sur la composition pour affiches et designs"],"de":["Generierung originaler Kunst in PNG und PDF","Erstellung einzigartiger Designphilosophien mit Form, Raum und Farbe","Vermeidung von Urheberrechtsverletzungen durch keine Kopien bestehender Werke","Zwei-Schritte-Prozess: Designphilosophie und visueller Ausdruck","Ausgabe in .md, .pdf und .png für Entwickler","Fokus auf Komposition für Poster und Designs"],"pt":["Geração de arquivos .png e .pdf para arte visual","Criação de filosofia de design única (não templates)","Processo de duas etapas: filosofia e renderização","Interpretação visual através de forma, espaço, cor e composição","Foco em arte original para evitar violação de copyright","Saída estrita em formatos .md, .pdf e .png"],"ru":["Генерация файлов .png и .pdf для визуального искусства","Создание уникальной философии дизайна (не шаблонов)","Двухэтапный процесс: философия и визуализация","Визуальная интерпретация через форму, пространство, цвет и композицию","Фокус на оригинальном искусстве для избежания нарушения авторских прав","Строгий вывод в форматах .md, .pdf и .png"],"ar":["توليد ملفات .png و .pdf للفن البصري","إنشاء فلسفة تصميم فريدة (ليس قوالب)","عملية من مرحلتين: الفلسفة والتعبير","تفسير بصري melalui الشكل والمساحة واللون والتركيب","التركيز على الفن الأصلي لتجنب انتهاك حقوق النشر","إخراج صارم بصيغ .md و .pdf و .png"]},"keywords":{"en":["how to use canvas-design","what is canvas-design","canvas-design alternative","canvas-design vs graphic design","canvas-design setup guide","canvas-design install","visual art creation with AI","design philosophy in AI","generating original designs with canvas-design"],"zh":["Canvas-Design AI代理","原创视觉艺术生成","设计哲学AI工具","png pdf文档创建","美学运动设计原则","AI代理技能开发","视觉构图AI","静态设计生成"],"ja":["Canvas-Design AIエージェント","オリジナルビジュアルアート生成","デザイン哲学AIツール","png pdfドキュメント作成","美的運動デザイン原則","AIエージェントスキル開発","ビジュアル構図AI","静的デザイン生成"],"ko":["Canvas-Design AI 에이전트","오리지널 시각 아트 생성","디자인 철학 AI 도구","png pdf 문서 생성","미학 운동 디자인 원칙","AI 에이전트 스킬 개발","시각 구도 AI","정적 디자인 생성"],"es":["canvas-design skill","generar arte visual IA","crear posters PNG PDF","filosofía de diseño IA","agentes IA para diseño","evitar copyright arte IA","formato PNG PDF desarrolladores","composición visual agentes IA"],"fr":["compétence canvas-design","générer art visuel IA","créer affiches PNG PDF","philosophie de design IA","agents IA pour design","éviter copyright art IA","format PNG PDF développeurs","composition visuelle agents IA"],"de":["canvas-design skill","visuelle Kunst KI generieren","Poster erstellen PNG PDF","Designphilosophie KI","KI-Agenten für Design","Urheberrecht vermeiden KI Kunst","PNG PDF Format Entwickler","visuelle Komposition KI Agenten"],"pt":["skill canvas-design agente ia","gerar png pdf agente ia","criar arte visual programaticamente","filosofia de design para ia","automatizar design gráfico","agente ia criar poster"],"ru":["навык canvas-design ИИ Агент","генерировать png pdf ИИ Агент","создавать визуальное искусство программно","философия дизайна для ИИ","автоматизировать графический дизайн","ИИ Агент создать постер"],"ar":["مهارة canvas-design أداة ذكاء اصطناعي","إنشاء png pdf أداة ذكاء اصطناعي","إنشاء الفن البصري برمجياً","فلسفة التصميم للذكاء الاصطناعي","أتمتة التصميم الجرافيكي","أداة ذكاء اصطناعي إنشاء ملصق"]}},"agentAnalysis":{"suitability":{"en":"Perfect for Creative AI Agents needing to generate original visual content from abstract design philosophies.","zh":"非常适合需要从抽象设计哲学生成原创视觉内容的创意AI智能体。","ja":"抽象的なデザイン哲学からオリジナルのビジュアルコンテンツを生成する必要があるクリエイティブAIエージェントに最適です。","ko":"추상적인 디자인 철학에서 독창적인 시각적 콘텐츠를 생성해야 하는 창의적인 AI 에이전트에 완벽합니다.","es":"Ideal para agentes de IA creativos que necesitan generar contenido visual original a partir de filosofías de diseño abstractas.","fr":"Parfait pour les agents d''IA créatifs ayant besoin de générer un contenu visuel original à partir de philosophies de design abstraites.","de":"Ideal für kreative KI-Agenten, die originale visuelle Inhalte aus abstrakten Designphilosophien generieren müssen.","pt":"Perfeito para Agentes de IA Criativos que precisam gerar conteúdo visual original a partir de filosofias de design abstratas.","ru":"Идеально подходит для креативных ИИ-агентов, которым необходимо генерировать оригинальный визуальный контент на основе абстрактных философий дизайна.","ar":"مثالي لوكلاء الذكاء الاصطناعي المبدعين الذين يحتاجون إلى إنشاء محتوى مرئي أصلي من فلسفات التصميم المجردة."},"recommendation":{"en":"Empowers agents to create copyright-free visual art by first generating design philosophy .md files, then translating them into .png and .pdf outputs through form, space, color, and composition principles.","zh":"通过首先生成设计哲学.md文件，然后通过形态、空间、色彩和构图原则将其转换为.png和.pdf输出，使智能体能够创建无版权的视觉艺术。","ja":"最初にデザイン哲学の.mdファイルを生成し、その後、形態、空間、色彩、構成の原則を通じてそれらを.pngおよび.pdf出力に変換することで、エージェントが著作権フリーのビジュアルアートを作成できるようにします。","ko":"먼저 디자인 철학 .md 파일을 생성한 다음 형태, 공간, 색상 및 구성 원칙을 통해 .png 및 .pdf 출력으로 변환하여 에이전트가 저작권 없는 시각 예술을 만들 수 있도록 합니다.","es":"Permite a los agentes crear arte visual libre de derechos de autor generando primero archivos .md de filosofía de diseño y luego traduciéndolos a salidas .png y .pdf mediante principios de forma, espacio, color y composición.","fr":"Permet aux agents de créer de l''art visuel libre de droits d''auteur en générant d''abord des fichiers .md de philosophie de design, puis en les traduisant en sorties .png et .pdf grâce aux principes de forme, d''espace, de couleur et de composition.","de":"Ermöglicht es Agenten, urheberrechtsfreie visuelle Kunst zu erstellen, indem zunächst .md-Dateien der Designphilosophie generiert werden, die dann durch Prinzipien von Form, Raum, Farbe und Komposition in .png- und .pdf-Ausgaben übersetzt werden.","pt":"Capacita os agentes a criar arte visual livre de direitos autorais, primeiro gerando arquivos .md de filosofia de design e depois traduzindo-os em saídas .png e .pdf por meio de princípios de forma, espaço, cor e composição.","ru":"Позволяет агентам создавать визуальное искусство, свободное от авторских прав, путем первоначального создания .md-файлов с философией дизайна, а затем преобразования их в выходные данные .png и .pdf с помощью принципов формы, пространства, цвета и композиции.","ar":"يمكن الوكلاء من إنشاء فن مرئي خالٍ من حقوق النشر عن طريق أولاً إنشاء ملفات فلسفة التصميم بصيغة .md، ثم ترجمتها إلى مخرجات بصيغة .png و .pdf من خلال مبادئ الشكل والمساحة واللون والتركيب."},"useCases":{"en":["Generating original marketing posters from aesthetic movements","Creating visual design assets for brand identity packages","Producing abstract art for digital content backgrounds","Designing philosophy-driven presentation materials"],"zh":["从美学运动生成原创营销海报","为品牌标识包创建视觉设计资产","为数字内容背景制作抽象艺术","设计哲学驱动的演示材料"],"ja":["美的運動からオリジナルのマーケティングポスターを生成","ブランドアイデンティティパッケージのためのビジュアルデザインアセットの作成","デジタルコンテンツの背景のための抽象芸術の制作","哲学主導型プレゼンテーション資料のデザイン"],"ko":["미학 운동에서 오리지널 마케팅 포스터 생성","브랜드 아이덴티티 패키지를 위한 시각 디자인 자산 생성","디지털 콘텐츠 배경을 위한 추상 미술 제작","철학 주도 프레젠테이션 자료 디자인"],"es":["Generación de carteles de marketing originales a partir de movimientos estéticos","Creación de recursos de diseño visual para paquetes de identidad de marca","Producción de arte abstracto para fondos de contenido digital","Diseño de materiales de presentación impulsados por la filosofía"],"fr":["Génération d''affiches marketing originales à partir de mouvements esthétiques","Création d''actifs de design visuel pour des packages d''identité de marque","Production d''art abstrait pour les arrière-plans de contenu numérique","Conception de matériel de présentation axé sur la philosophie"],"de":["Generierung originaler Marketing-Poster aus ästhetischen Bewegungen","Erstellung von visuellen Design-Assets für Markenidentitätspakete","Produktion abstrakter Kunst für digitale Inhaltshintergründe","Entwicklung von philosophiegesteuerten Präsentationsmaterialien"],"pt":["Geração de pôsteres de marketing originais a partir de movimentos estéticos","Criação de recursos de design visual para pacotes de identidade de marca","Produção de arte abstrata para fundos de conteúdo digital","Criação de materiais de apresentação orientados por filosofia"],"ru":["Генерация оригинальных маркетинговых постеров на основе эстетических движений","Создание визуальных активов дизайна для пакетов айдентики бренда","Создание абстрактного искусства для фонов цифрового контента","Разработка материалов для презентаций, основанных на философии"],"ar":["إنشاء ملصقات تسويقية أصلية من الحركات الجمالية","إنشاء أصول التصميم المرئي لحزم هوية العلامة التجارية","إنتاج فن تجريدي لخلفيات المحتوى الرقمي","تصميم مواد عرض مدفوعة بالفلسفة"]},"limitations":{"en":["Limited to static .png and .pdf outputs only","Requires design philosophy creation before visual expression","No support for animated or interactive formats"],"zh":["仅限于静态.png和.pdf输出","视觉表达前需要先创建设计哲学","不支持动画或交互式格式"],"ja":["静的な.pngおよび.pdf出力のみに限定","視覚的表現の前にデザイン哲学の作成が必要","アニメーションやインタラクティブ形式には非対応"],"ko":["정적인 .png 및 .pdf 출력으로만 제한됨","시각적 표현 전에 디자인 철학 생성이 필요함","애니메이션 또는 대화형 형식 지원 안 함"],"es":["Limitado únicamente a salidas estáticas .png y .pdf","Requiere la creación de una filosofía de diseño antes de la expresión visual","No hay soporte para formatos animados o interactivos"],"fr":["Limité aux sorties statiques .png et .pdf uniquement","Nécessite la création d''une philosophie de design avant l''expression visuelle","Aucune prise en charge des formats animés ou interactifs"],"de":["Beschränkt auf statische .png- und .pdf-Ausgaben","Erfordert die Erstellung einer Designphilosophie vor dem visuellen Ausdruck","Keine Unterstützung für animierte oder interaktive Formate"],"pt":["Limitado apenas a saídas estáticas .png e .pdf","Requer a criação de uma filosofia de design antes da expressão visual","Sem suporte para formatos animados ou interativos"],"ru":["Ограничено только статическими выходными данными .png и .pdf","Требует создания философии дизайна перед визуальным выражением","Отсутствие поддержки анимированных или интерактивных форматов"],"ar":["يقتصر على مخرجات ثابتة بصيغة .png و .pdf فقط","يتطلب إنشاء فلسفة التصميم قبل التعبير المرئي","لا يدعم التنسيقات المتحركة أو التفاعلية"]},"version":4},"contentHash":"a1f288079624402f30682753c1d43920b6664785698d21d3e7aa197450a6448b","repoEtag":"W/\"7edb6fc0761f3427176a5845d10a3b3b8776acf53d512a10f8fa720076c3c761\"","qualityScore":70}');
