INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('anthropics/skills/canvas-design', 'canvas-design', 'anthropics', 'skills', 'official', 'canvas-design anthropics skills official agent-skills The canvas-design skill creates beautiful visual art in .png and .pdf documents using design philosophy, benefiting developers and artists alike. Canvas-Design AI代理技能通过两步流程创建视觉艺术：首先制定设计哲学，然后将其表达为.png或.pdf文件。它专注于形式、空间、色彩和构图等美学元素，确保输出原创且无版权问题。 Canvas-Design AIエージェントスキルは、2段階のプロセスでビジュアルアートを作成します：まずデザイン哲学を策定し、次に.pngまたは.pdfファイルとして表現します。形態、空間、色彩、構図などの美的要素に焦点を当て、オリジナルで著作権問題のない出力を保証します。 Canvas-Design AI 에이전트 스킬은 두 단계 프로세스로 시각 아트를 생성합니다: 먼저 디자인 철학을 수립한 후 .png 또는 .pdf 파일로 표현합니다. 형태, 공간, 색상, 구도 등 미학 요소에 초점을 맞추어 오리지널이고 저작권 문제가 없는 출력을 보장합니다. La skill canvas-design permite a los desarrolladores integrar la generación de arte visual mediante agentes IA. Crea diseños originales en formatos PNG y PDF basados en filosofías de diseño propias, evitando el uso de obras existentes para prevenir problemas de copyright. Ideal para posters, gráf... La compétence canvas-design permet aux développeurs de générer de l''art visuel via des agents IA. Produisez des designs originaux en PNG et PDF en créant des philosophies de design uniques, sans copier des œuvres existantes pour éviter le copyright. Parfait pour les affiches et graphiques. Die canvas-design-Skill ermöglicht Entwicklern die Generierung von visueller Kunst durch KI-Agenten. Erstellen Sie originale Designs in PNG und PDF basierend auf eigenen Designphilosophien, ohne bestehende Werke zu kopieren. Ideal für Poster und Grafiken. A skill canvas-design permite que Agentes de IA criem arte visual programaticamente, gerando arquivos .png e .pdf com base em filosofias de design únicas. Ela opera em um fluxo de duas etapas: criação da filosofia e renderização visual. Навык canvas-design позволяет ИИ Агентам программно создавать визуальное искусство, генерируя файлы .png и .pdf на основе уникальных философий дизайна. Он работает в два этапа: создание философии и визуальная реализация. تمكن مهارة canvas-design أدوات الذكاء الاصطناعي من إنشاء الفن البصري برمجياً، وتوليد ملفات .png و .pdf بناءً على فلسفات تصميم فريدة. تعمل من خلال مرحلتين: إنشاء الفلسفة والتعبير المرئي. how to use canvas-design what is canvas-design canvas-design alternative canvas-design vs graphic design canvas-design setup guide canvas-design install visual art creation with AI design philosophy in AI generating original designs with canvas-design Canvas-Design AI代理 原创视觉艺术生成 设计哲学AI工具 png pdf文档创建 美学运动设计原则 AI代理技能开发 视觉构图AI 静态设计生成 Creates original visual designs using design philosophy Generates .png and .pdf files as output Follows a two-step process: design philosophy creation and visual expression Utilizes form, space, color, and composition to create unique designs Avoids copyright violations by not copying existing artists'' work canvas-design is a skill that enables the creation of original visual designs, expressed through form, space, color, and composition, without copying existing artists'' work.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('zenobi-us/dotfiles/skill-hunter', 'community', 'zenobi-us', 'dotfiles', 'zenobi-us/dotfiles', 'skill-hunter', 0, 0, 70, '2026-02-24T11:52:28.980Z', '2026-02-24T11:52:35.511Z', '24b17513bfe164e689f2b12b1863513ba0034cd83759e03e323ca92350881ff8', '{"id":"zenobi-us/dotfiles/skill-hunter","name":"skill-hunter","description":{"zh":"Skill Hunter 是一个帮助开发者发现和重用 GitHub 仓库中的 AI 代理技能的工具，支持 Linux、Windows 和 Mac 工作站","ja":"Skill Hunter は、GitHub リポジトリから AI エージェント スキルを検索して再利用するためのツールで、Linux、Windows、Mac のワークステーションをサポートする","ko":"스킬 헌터는 GitHub 저장소에서 AI 에이전트 스킬을 검색하여 재사용할 수 있는 도구로, 리눅스, 윈도우, 맥 작업을 지원한다","es":"Skill Hunter es una herramienta que busca habilidades de AI en GitHub para ayudarte a encontrar patrones y enfoques reutilizables.","fr":"Skill Hunter est un outil qui recherche des compétences d''IA sur GitHub pour vous aider à trouver des modèles et des approches réutilisables.","de":"Skill Hunter ist ein Tool, das KI-Fähigkeiten auf GitHub sucht, um Ihnen zu helfen, wiederverwendbare Muster und Ansätze zu finden.","pt":"O Skill Hunter é uma ferramenta que busca habilidades de IA em repositórios do GitHub, permitindo que você descubra padrões e implementações reutilizáveis.","ru":"Skill Hunter - это инструмент, который ищет навыки ИИ в репозиториях GitHub, позволяя вам обнаружить повторно используемые шаблоны и реализации.","ar":"سكيل هانتر هو أداة تبحث عن مهارات الذكاء الاصطناعي في مستودعات GitHub، مما يسمح لك باكتشاف أنماط وتنفيذ قابلة لإعادة الاستخدام.","en":"my workstation setup for linux, windows and mac"},"seo":{"title":{"zh":"Skill Hunter 技术","ja":"スキルハンターの機能","ko":"스킬 헌터 개발자 도구","es":"Skill Hunter: Descubre patrones de habilidades de AI","fr":"Skill Hunter: Découvrez des modèles de compétences d''IA","de":"Skill Hunter: Entdecken Sie Muster für KI-Fähigkeiten","pt":"Skill Hunter: Descubra Habilidades de IA","ru":"Skill Hunter: поиск навыков ИИ","ar":"سكيل هانتر: اكتشف مهارات الذكاء الاصطناعي","en":"skill-hunter"},"description":{"zh":"Skill Hunter 是一个帮助开发者发现和重用 GitHub 仓库中的 AI 代理技能的工具，支持 Linux、Windows 和 Mac 工作站","ja":"Skill Hunter は、GitHub リポジトリから AI エージェント スキルを検索して再利用するためのツールで、Linux、Windows、Mac のワークステーションをサポートする","ko":"스킬 헌터는 GitHub 저장소에서 AI 에이전트 스킬을 검색하여 재사용할 수 있는 도구로, 리눅스, 윈도우, 맥 작업을 지원한다","es":"Skill Hunter es una herramienta que busca habilidades de AI en GitHub para ayudarte a encontrar patrones y enfoques reutilizables.","fr":"Skill Hunter est un outil qui recherche des compétences d''IA sur GitHub pour vous aider à trouver des modèles et des approches réutilisables.","de":"Skill Hunter ist ein Tool, das KI-Fähigkeiten auf GitHub sucht, um Ihnen zu helfen, wiederverwendbare Muster und Ansätze zu finden.","pt":"O Skill Hunter é uma ferramenta que busca habilidades de IA em repositórios do GitHub, permitindo que você descubra padrões e implementações reutilizáveis.","ru":"Skill Hunter - это инструмент, который ищет навыки ИИ в репозиториях GitHub, позволяя вам обнаружить повторно используемые шаблоны и реализации.","ar":"سكيل هانتر هو أداة تبحث عن مهارات الذكاء الاصطناعي في مستودعات GitHub، مما يسمح لك باكتشاف أنماط وتنفيذ قابلة لإعادة الاستخدام.","en":"my workstation setup for linux, windows and mac"},"definition":{"en":"my workstation setup for linux, windows and mac"},"features":{"zh":["支持 Linux、Windows 和 Mac 工作站","从 GitHub 仓库中搜索 AI 代理技能","发现其他项目中的技能实现","找到常见的模式和方法","重用技能定义","获取最佳实践"],"ja":["Linux、Windows、Mac のワークステーションをサポート","GitHub リポジトリから AI エージェント スキルを検索","他のプロジェクトでのスキル実装を発見","共通のパターンとアプローチを見つける","スキル定義を再利用","ベストプラクティスを取得"],"ko":["리눅스, 윈도우, 맥 작업을 지원","GitHub 저장소에서 AI 에이전트 스킬을 검색","다른 프로젝트의 스킬 구현을 발견","공통의 패턴과 접근 방식을 찾기","스킬 정의를 재사용","최佳实践을 얻기"],"es":["Búsqueda de habilidades de AI en GitHub","Descubre patrones y enfoques reutilizables","Mejora tus proyectos con habilidades de AI existentes","Acceso a una base de datos de habilidades de AI","Búsqueda por ruta para encontrar habilidades específicas"],"fr":["Recherche de compétences d''IA sur GitHub","Découvrez des modèles et des approches réutilisables","Améliorez vos projets avec des compétences d''IA existantes","Accès à une base de données de compétences d''IA","Recherche par chemin pour trouver des compétences spécifiques"],"de":["Suche nach KI-Fähigkeiten auf GitHub","Entdecken Sie wiederverwendbare Muster und Ansätze","Verbessern Sie Ihre Projekte mit bestehenden KI-Fähigkeiten","Zugriff auf eine Datenbank mit KI-Fähigkeiten","Suche nach Pfad, um bestimmte Fähigkeiten zu finden"],"pt":["Busca habilidades de IA em repositórios do GitHub","Descobre padrões e implementações reutilizáveis","Encontra definições de habilidades reutilizáveis","Fornece as melhores práticas para habilidades de IA","Suporta busca baseada em caminho"],"ru":["Поиск навыков ИИ в репозиториях GitHub","Обнаружение повторно используемых шаблонов и реализаций","Находка повторно используемых определений навыков","Предоставление лучших практик для навыков ИИ","Поддержка поиска по пути"],"ar":["بحث عن مهارات الذكاء الاصطناعي في مستودعات GitHub","اكتشاف أنماط وتنفيذ قابلة لإعادة الاستخدام","العثور على تعريفات مهارات قابلة لإعادة الاستخدام","توفير أفضل الممارسات لمهارات الذكاء الاصطناعي","دعم البحث المبني على المسار"]},"keywords":{"zh":["AI 代理技能","GitHub 仓库搜索","技能重用","Linux 工作站","Windows 工作站","Mac 工作站","AI 代理框架","技能搜索工具"],"ja":["AI エージェント スキル","GitHub リポジトリ検索","スキル再利用","Linux ワークステーション","Windows ワークステーション","Mac ワークステーション","AI エージェント フレームワーク","スキル検索ツール"],"ko":["AI 에이전트 스킬","GitHub 저장소 검색","스킬 재사용","리눅스 작업","윈도우 작업","맥 작업","AI 에이전트 프레임워크","스킬 검색 도구"],"es":["habilidades de AI","GitHub","patrones de habilidades","enfoques reutilizables","búsqueda de habilidades","desarrollo de AI","proyectos de AI"," Skills de AI","IA"],"fr":["compétences d''IA","GitHub","modèles de compétences","approches réutilisables","recherche de compétences","développement d''IA","projets d''IA","Compétences d''IA","Intelligence artificielle"],"de":["KI-Fähigkeiten","GitHub","Muster für KI-Fähigkeiten","wiederverwendbare Ansätze","Suche nach KI-Fähigkeiten","Entwicklung von KI","KI-Projekte","KI-Fähigkeiten","Künstliche Intelligenz"],"pt":["habilidades de IA","repositórios do GitHub","busca de habilidades","padrões reutilizáveis","implementações de IA","melhores práticas de IA"],"ru":["навыки ИИ","репозитории GitHub","поиск навыков","повторно используемые шаблоны","реализации ИИ","лучшие практики ИИ"],"ar":["مهارات الذكاء الاصطناعي","مستودعات GitHub","بحث عن مهارات","أنماط قابلة لإعادة الاستخدام","تنفيذ الذكاء الاصطناعي","أفضل الممارسات للذكاء الاصطناعي"]}},"owner":"zenobi-us","repo":"dotfiles","repoPath":"zenobi-us/dotfiles","stars":0,"forks":0,"updatedAt":"2026-02-24T11:52:28.980Z","topics":[],"category":"community","skillMd":{"name":"skill-hunter","description":"Use when you need to discover existing skills from GitHub repositories.","bodyPreview":"# Skill Hunter\n\n**Use when:** You need to discover existing skills from GitHub repositories that use AI agent frameworks (pi, cursor, opencode, etc.) - searches across multiple agent directories to find reusable skill patterns, implementations, and best practices.\n\n## Core Capability\n\nSearch GitHub for skills in AI agent repositories using path-based search to discover:\n\n- Skill implementations from other projects\n- Common patterns and approaches\n- Reusable skill definitions\n- Best practices fro","body":"# Skill Hunter\n\n**Use when:** You need to discover existing skills from GitHub repositories that use AI agent frameworks (pi, cursor, opencode, etc.) - searches across multiple agent directories to find reusable skill patterns, implementations, and best practices.\n\n## Core Capability\n\nSearch GitHub for skills in AI agent repositories using path-based search to discover:\n\n- Skill implementations from other projects\n- Common patterns and approaches\n- Reusable skill definitions\n- Best practices from the community\n\n## Prerequisites\n\n- `gh` CLI installed and authenticated\n- `jq` for JSON processing\n- `$DOTFILES_REPO_ROOT` environment variable set (or will auto-detect)\n- Skills stored in `$DOTFILES_REPO_ROOT/ai/files/skills/`\n\n## GitHub Search Syntax\n\nThe core search pattern targets skill directories in AI agent repos:\n\n```bash\npath:/^./.?(opencode|ai|llm|claude|codex|agents|pi|cursor|factory)\\/skills?\\/.*\\.md$/\n```\n\nThis pattern finds files in paths like:\n\n- `.pi/skills/`\n- `.ai/skills/`\n- `.opencode/skill/`\n- `pi/skills/`\n- `agents/skills/`\n- `cursor/skills/`\n- `factory/skill/`\n\n## Implementation Pattern\n\n### 1. Basic Skill Search\n\nSearch for all skills matching a keyword:\n\n```bash\n# Search for skills related to \"testing\"\ngh search code \"testing path:/^./.?(opencode|ai|llm|claude|codex|agents|pi|cursor|factory)\\/skills?\\/.*\\.md$/\" --limit 20\n\n# Search for zellij skills\ngh search code \"zellij path:/^./.?(opencode|ai|llm|claude|codex|agents|pi|cursor|factory)\\/skills?\\/.*\\.md$/\" --limit 20\n```\n\n### 2. Find Skills by File Type\n\nSearch for specific file types (e.g., all SKILL.md files):\n\n```bash\n# Find SKILL.md files\ngh search code \"SKILL.md path:/^./.?(opencode|ai|llm|claude|codex|agents|pi|cursor|factory)\\/skills?\\/.*\\.md$/\" --limit 50\n\n# Find skill implementations in TypeScript\ngh search code \"extension:ts path:/^./.?(opencode|ai|llm|claude|codex|agents|pi|cursor|factory)\\/skills?\\/.*\\.md$/\" --limit 20\n\n# Find shell script skills\ngh search code \"extension:sh path:/^./.?(opencode|ai|llm|claude|codex|agents|pi|cursor|factory)\\/skills?\\/.*\\.md$/\" --limit 20\n```\n\n### 3. Language-Specific Skills\n\n```bash\n# Find Python skills\ngh search code \"language:python path:/^./.?(opencode|ai|llm|claude|codex|agents|pi|cursor|factory)\\/skills?\\/.*\\.md$/\" --limit 20\n\n# Find JavaScript/TypeScript skills\ngh search code \"language:typescript path:/^./.?(opencode|ai|llm|claude|codex|agents|pi|cursor|factory)\\/skills?\\/.*\\.md$/\" --limit 20\n\n# Find Rust skills\ngh search code \"language:rust path:/^./.?(opencode|ai|llm|claude|codex|agents|pi|cursor|factory)\\/skills?\\/.*\\.md$/\" --limit 20\n```\n\n### 4. Find Skills by Domain\n\n```bash\n# Database skills\ngh search code \"database OR postgres OR mysql path:/^./.?(opencode|ai|llm|claude|codex|agents|pi|cursor|factory)\\/skills?\\/.*\\.md$/\" --limit 20\n\n# DevOps skills\ngh search code \"docker OR kubernetes OR terraform path:/^./.?(opencode|ai|llm|claude|codex|agents|pi|cursor|factory)\\/skills?\\/.*\\.md$/\" --limit 20\n\n# Web development skills\ngh search code \"react OR vue OR angular path:/^./.?(opencode|ai|llm|claude|codex|agents|pi|cursor|factory)\\/skills?\\/.*\\.md$/\" --limit 20\n\n# Testing skills\ngh search code \"playwright OR selenium OR jest path:/^./.?(opencode|ai|llm|claude|codex|agents|pi|cursor|factory)\\/skills?\\/.*\\.md$/\" --limit 20\n```\n\n### 5. Discover Popular Repositories\n\nFind repos with the most skills:\n\n```bash\n# Search and group by repository\ngh search code \"path:/^./.?(opencode|ai|llm|claude|codex|agents|pi|cursor|factory)\\/skills?\\/.*\\.md$/\" --limit 100 --json repository,path | \\\n  jq -r ''.[] | .repository.fullName'' | sort | uniq -c | sort -rn | head -10\n```\n\n### 6. Download and Inspect Skills\n\nOnce you find an interesting skill:\n\n```bash\n# View a specific file directly\ngh browse <owner>/<repo> --branch main <path-to-skill-file>\n\n# Clone the entire repository\ngh repo clone <owner>/<repo>\n\n# Download a specific file\ngh api repos/<owner>/<repo>/contents/<path-to-skill-file> \\\n  --jq ''.content'' | base64 -d > downloaded-skill.md\n```\n\n## Complete Workflow Example\n\n### Scenario: Finding and Adapting a Zellij Skill\n\n```bash\n# 1. Search for zellij skills\necho \"Searching for zellij skills...\"\ngh search code \"zellij path:/^./.?(opencode|ai|llm|claude|codex|agents|pi|cursor|factory)\\/skills?\\/.*\\.md$/\" \\\n  --limit 20 \\\n  --json repository,path,url\n\n# 2. Search more broadly for terminal multiplexer skills\necho \"Searching for terminal/tmux/multiplexer skills...\"\ngh search code \"tmux OR terminal OR multiplexer path:/^./.?(opencode|ai|llm|claude|codex|agents|pi|cursor|factory)\\/skills?\\/.*\\.md$/\" \\\n  --limit 20 \\\n  --json repository,path,url\n\n# 3. Examine a promising result\nREPO=\"username/repo-name\"\nSKILL_PATH=\".pi/skills/terminal-management/SKILL.md\"\n\ngh api \"repos/${REPO}/contents/${SKILL_PATH}\" \\\n  --jq ''.content'' | base64 -d | less\n\n# 4. Download for adaptation\ngh api \"repos/${REPO}/contents/${SKILL_PATH}\" \\\n  --jq ''.content'' | base64 -d > /tmp/reference-skill.md\n\necho \"Downloaded to /tmp/reference-skill.md for review\"\n```\n\n## Advanced Search Patterns\n\n### Find Recently Updated Skills\n\n```bash\n# Skills updated in the last month\ngh search code \"path:/^./.?(opencode|ai|llm|claude|codex|agents|pi|cursor|factory)\\/skills?\\/.*\\.md$/ pushed:>$(date -d ''1 month ago'' +%Y-%m-%d)\" \\\n  --limit 30\n```\n\n### Find Skills by Star Count\n\n```bash\n# Skills from popular repositories (>100 stars)\ngh search code \"path:/^./.?(opencode|ai|llm|claude|codex|agents|pi|cursor|factory)\\/skills?\\/.*\\.md$/ stars:>100\" \\\n  --limit 30\n```\n\n### Find Skills with Specific Patterns\n\n```bash\n# Skills that use subagents\ngh search code \"subagent path:/^./.?(opencode|ai|llm|claude|codex|agents|pi|cursor|factory)\\/skills?\\/.*\\.md$/\" \\\n  --limit 20\n\n# Skills that use MCP (Model Context Protocol)\ngh search code \"MCP OR ''Model Context Protocol'' path:/^./.?(opencode|ai|llm|claude|codex|agents|pi|cursor|factory)\\/skills?\\/.*\\.md$/\" \\\n  --limit 20\n\n# Skills with tool implementations\ngh search code \"tool OR function_call path:/^./.?(opencode|ai|llm|claude|codex|agents|pi|cursor|factory)\\/skills?\\/.*\\.md$/\" \\\n  --limit 20\n```\n\n## Output Processing\n\n### Extract and Format Results\n\n```bash\n# Get a clean list of repositories with skills\ngh search code \"path:/^./.?(opencode|ai|llm|claude|codex|agents|pi|cursor|factory)\\/skills?\\/.*\\.md$/\" \\\n  --limit 100 \\\n  --json repository | \\\n  jq -r ''.[].repository | \"\\(.fullName) - \\(.description // \"No description\")\"'' | \\\n  sort -u\n\n# Create a markdown report of found skills\ngh search code \"SKILL.md path:/^./.?(opencode|ai|llm|claude|codex|agents|pi|cursor|factory)\\/skills?\\/.*\\.md$/\" \\\n  --limit 50 \\\n  --json repository,path,url | \\\n  jq -r ''.[] | \"- [\\(.repository.fullName)](\\(.repository.url)) - [\\(.path)](\\(.url))\"'' > skills-report.md\n```\n\n## Common Use Cases\n\n### 1. Before Writing a New Skill\n\n```bash\n# Check if someone already solved this problem\nSKILL_TOPIC=\"docker\"\ngh search code \"${SKILL_TOPIC} path:/^./.?(opencode|ai|llm|claude|codex|agents|pi|cursor|factory)\\/skills?\\/.*\\.md$/\" \\\n  --limit 20 \\\n  --json repository,path,url | \\\n  jq -r ''.[] | \"[\\(.repository.fullName)] \\(.path)\\n  \\(.url)\\n\"''\n```\n\n### 2. Finding Best Practices\n\n```bash\n# Find skills with comprehensive documentation\ngh search code \"## Prerequisites OR ## Requirements OR ## Installation path:/^./.?(opencode|ai|llm|claude|codex|agents|pi|cursor|factory)\\/skills?\\/.*\\.md$/\" \\\n  --limit 30\n```\n\n### 3. Discovering Skill Patterns\n\n```bash\n# Find skills that use specific frameworks\ngh search code \"playwright OR puppeteer OR selenium path:/^./.?(opencode|ai|llm|claude|codex|agents|pi|cursor|factory)\\/skills?\\/.*\\.md$/\" \\\n  --limit 20\n```\n\n## Integration with Dotfiles\n\n### Save Discovered Skills for Reference\n\nSkills should be stored in your Dotfiles repo under `ai/files/skills/`. When discovering skills, save them to a research directory first:\n\n```bash\n# Use dotfiles environment variable (fallback to detection if not set)\nDOTFILES_ROOT=\"${DOTFILES_REPO_ROOT:-$(git rev-parse --show-toplevel 2>/dev/null || echo \"${HOME}/Projects/dotfiles\")}\"\nSKILLS_ROOT=\"${DOTFILES_ROOT}/ai/files/skills\"\nRESEARCH_DIR=\"${DOTFILES_ROOT}/ai/files/skills-research\"\n\n# Create a skills research directory\nmkdir -p \"${RESEARCH_DIR}\"\n\n# Download and categorize interesting skills\nCATEGORY=\"terminal-management\"\nmkdir -p \"${RESEARCH_DIR}/${CATEGORY}\"\n\n# Save search results\ngh search code \"tmux OR zellij OR screen path:/^./.?(opencode|ai|llm|claude|codex|agents|pi|cursor|factory)\\/skills?\\/.*\\.md$/\" \\\n  --limit 30 \\\n  --json repository,path,url > \"${RESEARCH_DIR}/${CATEGORY}/search-results.json\"\n\n# Extract and download top results\njq -r ''.[] | \"\\(.repository.fullName)|\\(.path)|\\(.url)\"'' \\\n  \"${RESEARCH_DIR}/${CATEGORY}/search-results.json\" | \\\n  head -5 | \\\n  while IFS=''|'' read repo path url; do\n    echo \"Downloading: ${repo} - ${path}\"\n    gh api \"repos/${repo}/contents/${path}\" --jq ''.content'' | base64 -d > \\\n      \"${RESEARCH_DIR}/${CATEGORY}/$(echo ${repo} | tr ''/'' ''-'')-$(basename ${path})\"\n  done\n```\n\n### Suggest Storage Location\n\nAfter downloading and reviewing a skill, suggest appropriate locations within `ai/files/skills/`:\n\n```bash\n# Function to suggest skill locations\nsuggest_skill_location() {\n  local skill_name=\"$1\"\n  local skill_content=\"$2\"\n\n  echo \"📂 Where should ''${skill_name}'' be stored in ai/files/skills/?\"\n  echo \"\"\n\n  # Analyze content to suggest locations\n  if grep -qi \"github\\|gh cli\\|pull request\\|pr\\|issue\" \"${skill_content}\"; then\n    echo \"1. ai/files/skills/github/${skill_name}/\"\n    echo \"   ✓ GitHub-related functionality\"\n  fi\n\n  if grep -qi \"test\\|playwright\\|selenium\\|cypress\" \"${skill_content}\"; then\n    echo \"2. ai/files/skills/devtools/${skill_name}/\"\n    echo \"   ✓ Development and testing tools\"\n  fi\n\n  if grep -qi \"project\\|task\\|planning\\|tracking\" \"${skill_content}\"; then\n    echo \"3. ai/files/skills/projectmanagement/${skill_name}/\"\n    echo \"   ✓ Project management and workflow\"\n  fi\n\n  if grep -qi \"design\\|ui\\|ux\\|figma\" \"${skill_content}\"; then\n    echo \"4. ai/files/skills/design/${skill_name}/\"\n    echo \"   ✓ Design-related skills\"\n  fi\n\n  if grep -qi \"research\\|search\\|discover\" \"${skill_content}\"; then\n    echo \"5. ai/files/skills/research/${skill_name}/\"\n    echo \"   ✓ Research and discovery\"\n  fi\n\n  echo \"\"\n  echo \"Choose a number (1-5), or provide your own path:\"\n  echo \"Example: ai/files/skills/custom-category/${skill_name}/\"\n}\n\n# Usage example\nSKILL_FILE=\"${RESEARCH_DIR}/terminal-management/example-skill.md\"\nSKILL_NAME=\"zellij-manager\"\n\nsuggest_skill_location \"${SKILL_NAME}\" \"${SKILL_FILE}\"\nread -r location_choice\n\ncase $location_choice in\n  1) TARGET_DIR=\"${SKILLS_ROOT}/github/${SKILL_NAME}\" ;;\n  2) TARGET_DIR=\"${SKILLS_ROOT}/devtools/${SKILL_NAME}\" ;;\n  3) TARGET_DIR=\"${SKILLS_ROOT}/projectmanagement/${SKILL_NAME}\" ;;\n  4) TARGET_DIR=\"${SKILLS_ROOT}/design/${SKILL_NAME}\" ;;\n  5) TARGET_DIR=\"${SKILLS_ROOT}/research/${SKILL_NAME}\" ;;\n  *)\n    # User provided custom path\n    if [[ \"$location_choice\" =~ ^ai/files/skills/ ]]; then\n      TARGET_DIR=\"${DOTFILES_ROOT}/${location_choice}\"\n    else\n      TARGET_DIR=\"${SKILLS_ROOT}/${location_choice}\"\n    fi\n    ;;\nesac\n\n# Create target directory and move skill\nmkdir -p \"${TARGET_DIR}\"\ncp \"${SKILL_FILE}\" \"${TARGET_DIR}/SKILL.md\"\necho \"✅ Skill moved to: ${TARGET_DIR}\"\n```\n\n## Tips and Tricks\n\n### 1. Fuzzy Matching with Wildcards\n\nThe regex in the path already handles variations like `skill` vs `skills` with the `?` quantifier.\n\n### 2. Combine with Other Search Terms\n\n```bash\n# Find skills that mention specific tools\ngh search code \"gh cli OR ''github cli'' path:/^./.?(opencode|ai|llm|claude|codex|agents|pi|cursor|factory)\\/skills?\\/.*\\.md$/\" \\\n  --limit 20\n```\n\n### 3. Language-Specific Searches\n\n```bash\n# Find skills written in specific languages with content search\ngh search code \"language:markdown ''use when'' path:/^./.?(opencode|ai|llm|claude|codex|agents|pi|cursor|factory)\\/skills?\\/.*\\.md$/\" \\\n  --limit 30\n```\n\n### 4. Exclude Certain Repos\n\n```bash\n# Search but exclude your own repos\ngh search code \"path:/^./.?(opencode|ai|llm|claude|codex|agents|pi|cursor|factory)\\/skills?\\/.*\\.md$/ -user:yourusername\" \\\n  --limit 30\n```\n\n## Error Handling\n\n```bash\n# Check if gh CLI is installed and authenticated\nif ! command -v gh &> /dev/null; then\n    echo \"Error: GitHub CLI (gh) is not installed\"\n    echo \"Install with: brew install gh (macOS) or apt install gh (Linux)\"\n    exit 1\nfi\n\nif ! gh auth status &> /dev/null; then\n    echo \"Error: Not authenticated with GitHub\"\n    echo \"Run: gh auth login\"\n    exit 1\nfi\n\n# Handle rate limiting\ngh search code \"path:/^./.?(opencode|ai|llm|claude|codex|agents|pi|cursor|factory)\\/skills?\\/.*\\.md$/\" \\\n  --limit 30 || {\n    echo \"Error: GitHub API rate limit exceeded\"\n    echo \"Check status: gh api rate_limit\"\n    exit 1\n}\n```\n\n## Best Practices\n\n1. **Start Broad, Then Narrow**: Begin with general searches, then refine based on results\n2. **Check Multiple Frameworks**: Skills from cursor might work in pi and vice versa\n3. **Look for Patterns**: Similar problems often have similar solutions across repos\n4. **Respect Licenses**: Check repository licenses before adapting code\n5. **Credit Sources**: When adapting skills, note the original source\n6. **Update Your Own Skills**: Share back improved versions to help others\n\n## Example: Complete Skill Discovery Session\n\n```bash\n#!/bin/bash\n# skill-discovery.sh - Discover and analyze skills for a specific topic\n\nTOPIC=\"${1:-testing}\"\n\n# Use dotfiles environment variable\nDOTFILES_ROOT=\"${DOTFILES_REPO_ROOT:-$(git rev-parse --show-toplevel 2>/dev/null || echo \"${HOME}/Projects/dotfiles\")}\"\nSKILLS_ROOT=\"${DOTFILES_ROOT}/ai/files/skills\"\nRESEARCH_DIR=\"${DOTFILES_ROOT}/ai/files/skills-research\"\nOUTPUT_DIR=\"${RESEARCH_DIR}/${TOPIC}\"\n\nmkdir -p \"${OUTPUT_DIR}\"\n\necho \"🔍 Discovering skills related to: ${TOPIC}\"\necho \"📍 Dotfiles: ${DOTFILES_ROOT}\"\necho \"📂 Research output: ${OUTPUT_DIR}\"\necho \"\"\n\n# 1. Initial search\necho \"Step 1: Searching GitHub...\"\ngh search code \"${TOPIC} path:/^./.?(opencode|ai|llm|claude|codex|agents|pi|cursor|factory)\\/skills?\\/.*\\.md$/\" \\\n  --limit 50 \\\n  --json repository,path,url \\\n  > \"${OUTPUT_DIR}/search-results.json\"\n\nRESULT_COUNT=$(jq length \"${OUTPUT_DIR}/search-results.json\")\necho \"Found ${RESULT_COUNT} results\"\n\n# 2. Analyze repositories\necho \"Step 2: Analyzing repositories...\"\njq -r ''.[].repository.fullName'' \"${OUTPUT_DIR}/search-results.json\" | \\\n  sort | uniq -c | sort -rn | \\\n  head -10 > \"${OUTPUT_DIR}/top-repos.txt\"\n\necho \"Top repositories with ${TOPIC} skills:\"\ncat \"${OUTPUT_DIR}/top-repos.txt\"\n\n# 3. Download top 3 skill files\necho \"Step 3: Downloading sample skills...\"\njq -r ''.[0:3] | .[] | \"\\(.repository.fullName)|\\(.path)\"'' \\\n  \"${OUTPUT_DIR}/search-results.json\" | \\\n  while IFS=''|'' read repo path; do\n    filename=$(echo \"${repo}-${path}\" | tr ''/'' ''-'')\n    echo \"  Downloading: ${repo}/${path}\"\n    gh api \"repos/${repo}/contents/${path}\" \\\n      --jq ''.content'' | base64 -d \\\n      > \"${OUTPUT_DIR}/${filename}\" 2>/dev/null || \\\n      echo \"    Failed to download\"\n  done\n\n# 4. Create summary report\necho \"Step 4: Creating summary report...\"\ncat > \"${OUTPUT_DIR}/DISCOVERY-REPORT.md\" << EOF\n# Skill Discovery Report: ${TOPIC}\n\n**Date**: $(date)\n**Total Results**: ${RESULT_COUNT}\n**Dotfiles Root**: ${DOTFILES_ROOT}\n\n## Top Repositories\n\n\\`\\`\\`\n$(cat \"${OUTPUT_DIR}/top-repos.txt\")\n\\`\\`\\`\n\n## All Results\n\n$(jq -r ''.[] | \"- [\\(.repository.fullName)](\\(.repository.url)) - [\\(.path)](\\(.url))\"'' \\\n  \"${OUTPUT_DIR}/search-results.json\")\n\n## Storage Locations\n\nReview downloaded skills and determine appropriate location in:\n\n\\`\\`\\`\n${SKILLS_ROOT}/\n├── github/          # GitHub-related functionality\n├── devtools/        # Development and testing tools\n├── projectmanagement/  # Project and task management\n├── design/          # Design and UI/UX tools\n├── research/        # Research and discovery\n├── superpowers/     # Advanced meta-skills\n├── experts/         # Domain expert personas\n└── [custom]/        # Your custom categories\n\\`\\`\\`\n\n## Next Steps\n\n1. Review downloaded skill files in: ${OUTPUT_DIR}\n2. Identify common patterns and best practices\n3. Choose appropriate location in ai/files/skills/\n4. Adapt for your use case\n5. Consider contributing improvements back\n\n## Move to Skills Directory\n\n\\`\\`\\`bash\n# Example: Move adapted skill to appropriate location\nSKILL_NAME=\"my-new-skill\"\n\n# Option 1: GitHub-related\nmkdir -p \"${SKILLS_ROOT}/github/\\${SKILL_NAME}\"\ncp adapted-skill.md \"${SKILLS_ROOT}/github/\\${SKILL_NAME}/SKILL.md\"\n\n# Option 2: DevTools\nmkdir -p \"${SKILLS_ROOT}/devtools/\\${SKILL_NAME}\"\ncp adapted-skill.md \"${SKILLS_ROOT}/devtools/\\${SKILL_NAME}/SKILL.md\"\n\n# Option 3: Custom location\nmkdir -p \"${SKILLS_ROOT}/custom-category/\\${SKILL_NAME}\"\ncp adapted-skill.md \"${SKILLS_ROOT}/custom-category/\\${SKILL_NAME}/SKILL.md\"\n\\`\\`\\`\n\nEOF\n\necho \"✅ Discovery complete! Report saved to: ${OUTPUT_DIR}/DISCOVERY-REPORT.md\"\necho \"\"\necho \"Next: Review skills and move to ${SKILLS_ROOT}/\"\n```\n\n## Skill Storage Workflow\n\nAfter discovering and adapting a skill, follow this workflow:\n\n### 1. Analyze Skill Content\n\nReview the skill to determine its primary purpose:\n\n```bash\nSKILL_FILE=\"downloaded-skill.md\"\n\necho \"Analyzing skill content...\"\necho \"\"\necho \"Contains GitHub functionality:\" $(grep -qi \"github\\|gh cli\" \"$SKILL_FILE\" && echo \"✓ Yes\" || echo \"✗ No\")\necho \"Contains testing tools:\" $(grep -qi \"test\\|playwright\\|selenium\" \"$SKILL_FILE\" && echo \"✓ Yes\" || echo \"✗ No\")\necho \"Contains project management:\" $(grep -qi \"project\\|task\\|planning\" \"$SKILL_FILE\" && echo \"✓ Yes\" || echo \"✗ No\")\necho \"Contains design tools:\" $(grep -qi \"design\\|ui\\|figma\" \"$SKILL_FILE\" && echo \"✓ Yes\" || echo \"✗ No\")\necho \"Contains research tools:\" $(grep -qi \"research\\|search\\|discover\" \"$SKILL_FILE\" && echo \"✓ Yes\" || echo \"✗ No\")\n```\n\n### 2. Present Storage Options\n\nPresent 1-3 suggested locations based on content analysis:\n\n```\n📂 Where should this skill be stored in ai/files/skills/?\n\nSuggested locations:\n\n1. ai/files/skills/github/skill-name/\n   ✓ Contains GitHub API usage\n   ✓ Uses gh CLI extensively\n\n2. ai/files/skills/research/skill-name/\n   ✓ Primary purpose is discovery/research\n   ✓ Searches external sources\n\n3. ai/files/skills/devtools/skill-name/\n   ✓ Developer tooling functionality\n   ✓ Enhances development workflow\n\nChoose a number (1-3), or provide your own path:\nExample: ai/files/skills/custom-category/skill-name/\n```\n\n### 3. Interactive Selection Script\n\n```bash\n#!/bin/bash\n# store-skill.sh - Interactive skill storage helper\n\nSKILL_FILE=\"$1\"\nSKILL_NAME=\"$2\"\n\nif [[ -z \"$SKILL_FILE\" || -z \"$SKILL_NAME\" ]]; then\n  echo \"Usage: $0 <skill-file> <skill-name>\"\n  exit 1\nfi\n\n# Use dotfiles environment variable\nDOTFILES_ROOT=\"${DOTFILES_REPO_ROOT:-$(git rev-parse --show-toplevel 2>/dev/null || echo \"${HOME}/Projects/dotfiles\")}\"\nSKILLS_ROOT=\"${DOTFILES_ROOT}/ai/files/skills\"\n\n# Analyze content\necho \"🔍 Analyzing skill content...\"\necho \"\"\n\nSUGGESTIONS=()\nCOUNT=1\n\nif grep -qi \"github\\|gh cli\\|pull request\\|issue\" \"$SKILL_FILE\"; then\n  SUGGESTIONS+=(\"${COUNT}:github:GitHub-related functionality\")\n  echo \"${COUNT}. ai/files/skills/github/${SKILL_NAME}/\"\n  echo \"   ✓ GitHub-related functionality\"\n  echo \"\"\n  ((COUNT++))\nfi\n\nif grep -qi \"test\\|playwright\\|selenium\\|cypress\\|jest\" \"$SKILL_FILE\"; then\n  SUGGESTIONS+=(\"${COUNT}:devtools:Testing and development tools\")\n  echo \"${COUNT}. ai/files/skills/devtools/${SKILL_NAME}/\"\n  echo \"   ✓ Testing and development tools\"\n  echo \"\"\n  ((COUNT++))\nfi\n\nif grep -qi \"project\\|task\\|planning\\|tracking\\|workflow\" \"$SKILL_FILE\"; then\n  SUGGESTIONS+=(\"${COUNT}:projectmanagement:Project management\")\n  echo \"${COUNT}. ai/files/skills/projectmanagement/${SKILL_NAME}/\"\n  echo \"   ✓ Project management and workflow\"\n  echo \"\"\n  ((COUNT++))\nfi\n\nif grep -qi \"design\\|ui\\|ux\\|figma\\|sketch\" \"$SKILL_FILE\"; then\n  SUGGESTIONS+=(\"${COUNT}:design:Design tools\")\n  echo \"${COUNT}. ai/files/skills/design/${SKILL_NAME}/\"\n  echo \"   ✓ Design and UI/UX tools\"\n  echo \"\"\n  ((COUNT++))\nfi\n\nif grep -qi \"research\\|search\\|discover\\|analyze\" \"$SKILL_FILE\"; then\n  SUGGESTIONS+=(\"${COUNT}:research:Research and discovery\")\n  echo \"${COUNT}. ai/files/skills/research/${SKILL_NAME}/\"\n  echo \"   ✓ Research and discovery\"\n  echo \"\"\n  ((COUNT++))\nfi\n\n# If no suggestions, show common categories\nif [[ ${#SUGGESTIONS[@]} -eq 0 ]]; then\n  echo \"No specific category detected. Common options:\"\n  echo \"\"\n  echo \"1. ai/files/skills/devtools/${SKILL_NAME}/\"\n  echo \"2. ai/files/skills/superpowers/${SKILL_NAME}/\"\n  echo \"3. ai/files/skills/experts/${SKILL_NAME}/\"\n  echo \"\"\nfi\n\necho \"Choose a number, or provide your own path:\"\necho \"Example: ai/files/skills/my-category/${SKILL_NAME}/\"\necho \"\"\nread -r -p \"Selection: \" choice\n\n# Process choice\nTARGET_DIR=\"\"\nif [[ \"$choice\" =~ ^[0-9]+$ ]] && [[ \"$choice\" -le \"${#SUGGESTIONS[@]}\" ]]; then\n  # Numbered choice\n  CATEGORY=$(echo \"${SUGGESTIONS[$((choice-1))]}\" | cut -d: -f2)\n  TARGET_DIR=\"${SKILLS_ROOT}/${CATEGORY}/${SKILL_NAME}\"\nelif [[ \"$choice\" =~ ^ai/files/skills/ ]]; then\n  # Full path provided\n  TARGET_DIR=\"${DOTFILES_ROOT}/${choice}\"\nelse\n  # Relative path assumed\n  TARGET_DIR=\"${SKILLS_ROOT}/${choice}\"\nfi\n\n# Create and copy\nmkdir -p \"${TARGET_DIR}\"\ncp \"${SKILL_FILE}\" \"${TARGET_DIR}/SKILL.md\"\n\necho \"\"\necho \"✅ Skill stored at: ${TARGET_DIR}/SKILL.md\"\necho \"\"\necho \"Next steps:\"\necho \"1. Review and edit: ${TARGET_DIR}/SKILL.md\"\necho \"2. Add frontmatter if needed (name, description)\"\necho \"3. Commit to dotfiles repo\"\n```\n\n### 4. Commit to Dotfiles\n\nAfter storing the skill:\n\n```bash\ncd \"${DOTFILES_ROOT}\"\ngit add \"ai/files/skills/${CATEGORY}/${SKILL_NAME}/\"\ngit commit -m \"feat(skills): add ${SKILL_NAME} skill\n\nDiscovered from GitHub search, adapted for local use.\nStored in ${CATEGORY} category.\"\ngit push\n```\n\n## See Also\n\n- **github**: Core GitHub CLI skill\n- **writing-skills**: Creating and editing skills\n- **superpowers/brainstorming**: Design before implementation\n"},"lastSynced":"2026-02-24T11:52:35.511Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agent Developers needing to discover and reuse existing skill patterns from GitHub repositories using path-based search across multiple agent directories.","zh":"非常适合需要从GitHub仓库中发现和重用现有技能模式的AI代理开发人员，使用基于路径的搜索跨多个代理目录。","ja":"GitHubリポジトリから既存のスキルパターンを検出して再利用する必要があるAIエージェント開発者に最適です。複数のエージェントディレクトリを横断してパスベースの検索を使用します。","ko":"기존 스킬 패턴을 GitHub 리포지토리에서 발견하여 재사용해야 하는 AI 에이전트 개발자를 위한 완벽한 솔루션으로, 여러 에이전트 디렉토리를跨越하여 경로 기반 검색을 사용합니다.","es":"Perfecto para desarrolladores de agentes de IA que necesitan descubrir y reutilizar patrones de habilidades existentes desde repositorios de GitHub utilizando búsquedas basadas en rutas en múltiples directorios de agentes.","fr":"Parfait pour les développeurs d''agents IA ayant besoin de découvrir et de réutiliser des modèles de compétences existants à partir de référentiels GitHub en utilisant une recherche basée sur les chemins dans plusieurs répertoires d''agents.","de":"Perfekt für Entwickler von KI-Agents, die bestehende Fähigkeitsmuster aus GitHub-Repositorys mithilfe von pfadbasierter Suche in mehreren Agentenverzeichnissen entdecken und wiederverwenden müssen.","pt":"Perfeito para desenvolvedores de Agentes de IA que precisam descobrir e reutilizar padrões de habilidades existentes de repositórios do GitHub usando busca baseada em caminho em vários diretórios de agentes.","ru":"Идеально для разработчиков агентов ИИ, которым необходимо обнаружить и повторно использовать существующие шаблоны навыков из репозиториев GitHub, используя поисковую систему на основе пути в нескольких агентских директориях.","ar":"مثالي لمطوري وكلاء الذكاء الاصطناعي الذين يحتاجون إلى اكتشاف وإعادة استخدام أنماط المهارات الحالية من مستودعات جيت هاب باستخدام بحث مبني على المسار عبر أدلة وكلاء متعددة."},"recommendation":{"en":"Empowers agents to search GitHub for skill implementations, common patterns, and reusable skill definitions using AI agent frameworks like pi, cursor, and opencode, while applying best practices for skill development and integration.","zh":"赋予代理搜索GitHub的技能实现、常见模式和可重用的技能定义的能力，使用像pi、cursor和opencode这样的AI代理框架，同时应用技能开发和集成的最佳实践。","ja":"pi、cursor、opencodeなどのAIエージェントフレームワークを使用して、GitHubのスキル実装、一般的なパターン、再利用可能なスキル定義を検索するエージェントの機能を強化します。また、スキル開発および統合のベストプラクティスも適用します。","ko":"에이전트가 pi, 커서, 오픈코드와 같은 AI 에이전트 프레임워크를 사용하여 GitHub의 스킬 구현, 일반적인 패턴 및 재사용 가능한 스킬 정의를 검색할 수 있도록 하는 동시에 스킬 개발 및 통합의 모범 사례를 적용합니다.","es":"Habilita a los agentes a buscar en GitHub implementaciones de habilidades, patrones comunes y definiciones de habilidades reutilizables utilizando marcos de agentes de IA como pi, cursor y opencode, aplicando al mismo tiempo las mejores prácticas para el desarrollo y la integración de habilidades.","fr":"Permet aux agents de rechercher sur GitHub des implémentations de compétences, des modèles courants et des définitions de compétences réutilisables en utilisant des cadres d''agents IA tels que pi, cursor et opencode, tout en appliquant les meilleures pratiques pour le développement et l''intégration de compétences.","de":"Ermächtigt Agenten, auf GitHub nach Fähigkeitsimplementierungen, gängigen Mustern und wiederverwendbaren Fähigkeitsdefinitionen zu suchen, indem sie KI-Agenten-Frameworks wie pi, cursor und opencode verwenden und gleichzeitig die besten Praktiken für die Fähigkeitsentwicklung und -integration anwenden.","pt":"Habilita os agentes a procurar no GitHub implementações de habilidades, padrões comuns e definições de habilidades reutilizáveis usando estruturas de agente de IA como pi, cursor e opencode, aplicando as melhores práticas para desenvolvimento e integração de habilidades.","ru":"Наделяет агентов возможностью искать в GitHub реализации навыков, общие шаблоны и повторно используемые определения навыков, используя фреймворки агентов ИИ, такие как pi, cursor и opencode, применяя лучшие практики для разработки и интеграции навыков.","ar":"تمكّن الوكلاء من البحث في جيت هاب عن تنفيذ المهارات وأنماط شائعة وتعريفات المهارات القابلة لإعادة الاستخدام باستخدام إطارات وكلاء الذكاء الاصطناعي مثل pi و cursor و opencode، مع تطبيق أفضل الممارسات لتطوير المهارات وتكاملها."},"useCases":{"en":["Discovering existing skill implementations from open-source projects","Identifying common patterns and approaches in AI agent skill development","Finding reusable skill definitions for rapid agent development and deployment"],"zh":["从开源项目中发现现有的技能实现","确定AI代理技能开发中的常见模式和方法","找到可重用的技能定义以实现快速代理开发和部署"],"ja":["オープンソースプロジェクトから既存のスキル実装を検出する","AIエージェントスキル開発における一般的なパターンとアプローチを特定する","迅速なエージェント開発および展開のための再利用可能なスキル定義を見つける"],"ko":["오픈소스 프로젝트에서 기존의 스킬 구현을 발견하는 것","AI 에이전트 스킬 개발에서 일반적인 패턴과 접근 방식을 식별하는 것","신속한 에이전트 개발 및 배포를 위한 재사용 가능한 스킬 정의를 찾는 것"],"es":["Descubrir implementaciones de habilidades existentes de proyectos de código abierto","Identificar patrones y enfoques comunes en el desarrollo de habilidades de agentes de IA","Encontrar definiciones de habilidades reutilizables para un desarrollo y despliegue de agentes rápido"],"fr":["Découvrir des implémentations de compétences existantes de projets open source","Identifier des modèles et des approches courants dans le développement de compétences d''agents IA","Trouver des définitions de compétences réutilisables pour un développement et un déploiement d''agents rapides"],"de":["Vorhandene Fähigkeitsimplementierungen aus Open-Source-Projekten entdecken","Gängige Muster und Ansätze in der Fähigkeitsentwicklung von KI-Agents identifizieren","Wiederverwendbare Fähigkeitsdefinitionen für eine schnelle Entwicklung und Bereitstellung von Agents finden"],"pt":["Descobrindo implementações de habilidades existentes de projetos de código aberto","Identificando padrões e abordagens comuns no desenvolvimento de habilidades de agente de IA","Encontrando definições de habilidades reutilizáveis para desenvolvimento e implantação rápida de agentes"],"ru":["Обнаружение существующих реализаций навыков из открытых проектов","Определение общих шаблонов и подходов в разработке навыков агентов ИИ","Поиск повторно используемых определений навыков для быстрой разработки и развертывания агентов"],"ar":["اكتشاف تنفيذ المهارات الحالية من المشاريع مفتوحة المصدر","تحديد الأنماط والمنهجيات الشائعة في تطوير مهارات وكلاء الذكاء الاصطناعي","العثور على تعريفات المهارات القابلة لإعادة الاستخدام من أجل التطوير السريع وتحديث الوكلاء"]},"limitations":{"en":["Requires GitHub access and repository permissions","Limited to searching repositories using specific AI agent frameworks","Path-based search may require adjustments for optimal results"],"zh":["需要GitHub访问和仓库权限","仅限使用特定的AI代理框架搜索仓库","基于路径的搜索可能需要调整以获得最佳结果"],"ja":["GitHubへのアクセスおよびリポジトリの権限が必要","特定のAIエージェントフレームワークを使用してリポジトリを検索することのみ","パスベースの検索では、最適な結果を得るために調整が必要になる場合がある"],"ko":["GitHub 액세스 및 리포지토리 권한이 필요","특정 AI 에이전트 프레임워크를 사용하여 리포지토리를 검색하는 것만 가능","경로 기반 검색은 최적의 결과를 얻으려면 조정이 필요할 수 있음"],"es":["Requiere acceso a GitHub y permisos de repositorio","Limitado a la búsqueda de repositorios que utilizan marcos de agentes de IA específicos","La búsqueda basada en rutas puede requerir ajustes para obtener resultados óptimos"],"fr":["Nécessite un accès à GitHub et des autorisations de référentiel","Limité à la recherche de référentiels utilisant des cadres d''agents IA spécifiques","La recherche basée sur les chemins peut nécessiter des ajustements pour obtenir des résultats optimaux"],"de":["Benötigt Zugriff auf GitHub und Repository-Berechtigungen","Begrenzt auf die Suche in Repositorys, die spezifische KI-Agenten-Frameworks verwenden","Die pfadbasierte Suche kann Anpassungen erfordern, um optimale Ergebnisse zu erzielen"],"pt":["Requer acesso ao GitHub e permissões de repositório","Limitado à busca em repositórios que usam estruturas de agente de IA específicas","A busca baseada em caminho pode requerer ajustes para resultados ótimos"],"ru":["Требует доступа к GitHub и разрешений репозитория","Ограничен поиском в репозиториях, использующих конкретные фреймворки агентов ИИ","Поиск на основе пути может требовать корректировки для оптимальных результатов"],"ar":["يتطلب الوصول إلى جيت هاب والصلاحيات المستودعية","محدود بالبحث في المستودعات التي تستخدم إطارات وكلاء الذكاء الاصطناعي المحددة","البحث المبني على المسار قد يتطلب تعديلات للحصول على نتائج مثالية"]},"version":3},"contentHash":"24b17513bfe164e689f2b12b1863513ba0034cd83759e03e323ca92350881ff8","qualityScore":70}');
